          <TextBlock x:Name="Gesture" Grid.Column="1" Text="{TemplateBinding InputGestureText}" Margin="28,0,0,0" Foreground="{StaticResource Muted}" VerticalAlignment="Center"/>
          <Popup x:Name="PART_Popup" Placement="Bottom" VerticalOffset="4" AllowsTransparency="True" Focusable="False" PopupAnimation="Fade"
                 IsOpen="{Binding IsSubmenuOpen, RelativeSource={RelativeSource TemplatedParent}}">
            <Border Background="{StaticResource Surface}" BorderBrush="{StaticResource Border}" BorderThickness="1" CornerRadius="6" Padding="4" MinWidth="240">
              <StackPanel IsItemsHost="True" KeyboardNavigation.DirectionalNavigation="Cycle"/>
            </Border>
          </Popup>
        </Grid>
      </Border>
      <ControlTemplate.Triggers>
        <Trigger Property="IsHighlighted" Value="True"><Setter TargetName="Bd" Property="Background" Value="{StaticResource Soft}"/></Trigger>
        <Trigger Property="IsSubmenuOpen" Value="True"><Setter TargetName="Bd" Property="Background" Value="{StaticResource Soft}"/></Trigger>
        <Trigger Property="Role" Value="TopLevelHeader"><Setter TargetName="Gesture" Property="Visibility" Value="Collapsed"/><Setter TargetName="Bd" Property="Padding" Value="12,6"/></Trigger>
        <Trigger Property="IsEnabled" Value="False"><Setter TargetName="Bd" Property="Opacity" Value="0.45"/></Trigger>
      </ControlTemplate.Triggers>
    </ControlTemplate>
  </Setter.Value></Setter>
</Style>
<Style TargetType="ContextMenu">
  <Setter Property="Template"><Setter.Value>
    <ControlTemplate TargetType="ContextMenu">
      <Border Background="{StaticResource Surface}" BorderBrush="{StaticResource Border}" BorderThickness="1" CornerRadius="6" Padding="4" MinWidth="200">
        <StackPanel IsItemsHost="True" KeyboardNavigation.DirectionalNavigation="Cycle"/>
      </Border>
    </ControlTemplate>
  </Setter.Value></Setter>
</Style>
<Style TargetType="DataGridCell">
  <Setter Property="BorderThickness" Value="0"/><Setter Property="Padding" Value="6,3"/><Setter Property="FocusVisualStyle" Value="{x:Null}"/>
  <Setter Property="Template"><Setter.Value>
    <ControlTemplate TargetType="DataGridCell">
      <Border Background="{TemplateBinding Background}" BorderBrush="{TemplateBinding BorderBrush}" BorderThickness="{TemplateBinding BorderThickness}" Padding="{TemplateBinding Padding}" SnapsToDevicePixels="True">
        <ContentPresenter VerticalAlignment="Center" SnapsToDevicePixels="{TemplateBinding SnapsToDevicePixels}"/>
      </Border>
    </ControlTemplate>
  </Setter.Value></Setter>
  <Style.Triggers>
    <Trigger Property="IsSelected" Value="True"><Setter Property="Background" Value="{DynamicResource Soft}"/><Setter Property="Foreground" Value="{DynamicResource Text}"/></Trigger>
  </Style.Triggers>
</Style>
<Style TargetType="DataGridColumnHeader">
  <Setter Property="Background" Value="{StaticResource Surface}"/><Setter Property="Foreground" Value="{StaticResource Muted}"/>
  <Setter Property="FontWeight" Value="SemiBold"/><Setter Property="Padding" Value="8,6"/><Setter Property="BorderBrush" Value="{StaticResource Border}"/><Setter Property="BorderThickness" Value="0,0,1,1"/>
</Style>
<Style x:Key="ScrollThumbStyle" TargetType="Thumb">
  <Setter Property="Template"><Setter.Value>
    <ControlTemplate TargetType="Thumb">
      <Border x:Name="Bd" CornerRadius="4" Background="{DynamicResource ScrollThumb}"/>
      <ControlTemplate.Triggers>
        <Trigger Property="IsMouseOver" Value="True"><Setter TargetName="Bd" Property="Background" Value="{DynamicResource Muted}"/></Trigger>
        <Trigger Property="IsDragging" Value="True"><Setter TargetName="Bd" Property="Background" Value="{DynamicResource Primary}"/></Trigger>
      </ControlTemplate.Triggers>
    </ControlTemplate>
  </Setter.Value></Setter>
</Style>
<Style x:Key="ScrollPageButton" TargetType="RepeatButton">
  <Setter Property="Focusable" Value="False"/><Setter Property="IsTabStop" Value="False"/>
  <Setter Property="Template"><Setter.Value><ControlTemplate TargetType="RepeatButton"><Border Background="Transparent"/></ControlTemplate></Setter.Value></Setter>
</Style>
<Style TargetType="ScrollBar">
  <Setter Property="Background" Value="Transparent"/><Setter Property="Width" Value="10"/><Setter Property="MinWidth" Value="10"/>
  <Setter Property="Template"><Setter.Value>
    <ControlTemplate TargetType="ScrollBar">
      <Grid Background="{TemplateBinding Background}">
        <Track x:Name="PART_Track" IsDirectionReversed="True">
          <Track.DecreaseRepeatButton><RepeatButton Style="{StaticResource ScrollPageButton}" Command="ScrollBar.PageUpCommand"/></Track.DecreaseRepeatButton>
          <Track.Thumb><Thumb Style="{StaticResource ScrollThumbStyle}" Margin="2"/></Track.Thumb>
          <Track.IncreaseRepeatButton><RepeatButton Style="{StaticResource ScrollPageButton}" Command="ScrollBar.PageDownCommand"/></Track.IncreaseRepeatButton>
        </Track>
      </Grid>
    </ControlTemplate>
  </Setter.Value></Setter>
  <Style.Triggers>
    <Trigger Property="Orientation" Value="Horizontal">
      <Setter Property="Width" Value="Auto"/><Setter Property="MinWidth" Value="0"/><Setter Property="Height" Value="10"/><Setter Property="MinHeight" Value="10"/>
      <Setter Property="Template"><Setter.Value>
        <ControlTemplate TargetType="ScrollBar">
          <Grid Background="{TemplateBinding Background}">
            <Track x:Name="PART_Track" IsDirectionReversed="False">
              <Track.DecreaseRepeatButton><RepeatButton Style="{StaticResource ScrollPageButton}" Command="ScrollBar.PageLeftCommand"/></Track.DecreaseRepeatButton>
              <Track.Thumb><Thumb Style="{StaticResource ScrollThumbStyle}" Margin="2"/></Track.Thumb>
              <Track.IncreaseRepeatButton><RepeatButton Style="{StaticResource ScrollPageButton}" Command="ScrollBar.PageRightCommand"/></Track.IncreaseRepeatButton>
            </Track>
          </Grid>
        </ControlTemplate>
      </Setter.Value></Setter>
    </Trigger>
  </Style.Triggers>
</Style>
<Style x:Key="SectionLabel" TargetType="TextBlock">
  <Setter Property="FontSize" Value="11"/><Setter Property="FontWeight" Value="SemiBold"/><Setter Property="Foreground" Value="{StaticResource Muted}"/>
</Style>
'@
    foreach ($token in $tokens.Keys) { $xaml = $xaml.Replace($token, $tokens[$token]) }
    return $xaml
}

# Loads a XAML window. Put <!--APP_RESOURCES--> inside <Window.Resources> to pull in the shared styles and
# use @FORM@ / @TEXT@ for the theme's window background and text colors.
# Returns @{ Window = <Window>; Controls = <x:Name -> element> }.
# Brush resource key -> colour for the active theme. Every colour in the XAML is a DynamicResource on one of these
# keys, so a theme change only has to replace the brushes (Set-WpfThemeResources) for every open window to repaint.
$script:ThemeBrushKeys = @('Primary', 'PrimaryText', 'Soft', 'SoftText', 'Surface', 'Border', 'Muted', 'Text', 'Form', 'Input', 'ScrollThumb')

function Get-ThemeBrushColors {
    return @{
        Primary = ConvertTo-HexColor $script:Theme.PrimaryButton; PrimaryText = ConvertTo-HexColor $script:Theme.PrimaryButtonText
        Soft = ConvertTo-HexColor $script:Theme.SecondaryButton; SoftText = ConvertTo-HexColor $script:Theme.SecondaryButtonText
        Surface = ConvertTo-HexColor $script:Theme.GroupBackground; Border = ConvertTo-HexColor $script:Theme.BorderColor
        Muted = ConvertTo-HexColor $script:Theme.MutedText; Text = ConvertTo-HexColor $script:Theme.TextColor
        Form = ConvertTo-HexColor $script:Theme.FormBackground; Input = ConvertTo-HexColor $script:Theme.TextBoxBackground
        ScrollThumb = $(if ($script:settings.AppTheme -eq 'Dark') { '#3A4A6B' } else { '#C3CCDA' })
    }
}

function Set-WpfThemeResources {
    param([Parameter(Mandatory = $true)]$Window)
    $colors = Get-ThemeBrushColors
    foreach ($key in $script:ThemeBrushKeys) {
        $brush = New-Object System.Windows.Media.SolidColorBrush ([System.Windows.Media.ColorConverter]::ConvertFromString($colors[$key]))
        $Window.Resources[$key] = $brush
    }
}

$script:openWpfWindows = New-Object System.Collections.ArrayList

function Register-WpfWindow {
    param($Window)
    [void]$script:openWpfWindows.Add($Window)
    $Window.Add_Closed({ param($sender) [void]$script:openWpfWindows.Remove($sender) })
}

# Loads a XAML window. Put <!--APP_RESOURCES--> inside <Window.Resources> to pull in the shared styles; @FORM@ and
# @TEXT@ (window background / text) and {StaticResource <brush>} become theme-aware dynamic resources.
# Returns @{ Window = <Window>; Controls = <x:Name -> element> }.
function New-WpfWindowFromXaml {
    param([Parameter(Mandatory = $true)][string]$Xaml, [string[]]$ControlNames = @())

    Initialize-WpfSupport
    $Xaml = $Xaml.Replace('<!--APP_RESOURCES-->', (Get-WpfResourcesXaml))
    $Xaml = $Xaml.Replace('"@FORM@"', '"{DynamicResource Form}"').Replace('"@TEXT@"', '"{DynamicResource Text}"')
    $Xaml = [regex]::Replace($Xaml, '\{StaticResource (' + ($script:ThemeBrushKeys -join '|') + ')\}', '{DynamicResource $1}')
    $window = [Windows.Markup.XamlReader]::Load((New-Object System.Xml.XmlNodeReader ([xml]$Xaml)))
    Register-WpfWindow -Window $window
    $controls = @{}
    foreach ($name in $ControlNames) { $controls[$name] = $window.FindName($name) }
    return @{ Window = $window; Controls = $controls }
}

# ---- Screen fitting ---------------------------------------------------------------------------------------------
# Returns the work area (WPF device-independent units) of the monitor showing $Reference, or the primary monitor.
function Get-WindowWorkArea {
    param($Reference = $null)
    try {
        if ($Reference -is [System.Windows.Window] -and $Reference.IsLoaded) {
            $handle = (New-Object System.Windows.Interop.WindowInteropHelper($Reference)).Handle
            $source = [System.Windows.PresentationSource]::FromVisual($Reference)
            if ($handle -ne [IntPtr]::Zero -and $source) {
                $working = [System.Windows.Forms.Screen]::FromHandle($handle).WorkingArea
                $toDips = $source.CompositionTarget.TransformFromDevice
                $topLeft = $toDips.Transform([System.Windows.Point]::new($working.Left, $working.Top))
                $bottomRight = $toDips.Transform([System.Windows.Point]::new($working.Right, $working.Bottom))
                return [System.Windows.Rect]::new($topLeft, $bottomRight)
            }
        }
    } catch { }
    return [System.Windows.SystemParameters]::WorkArea
}

# Moves a shown window so that it lies completely inside the work area of its monitor.
function Move-WindowIntoWorkArea {
    param($Window)
    try {
        if ($Window.WindowState -ne [System.Windows.WindowState]::Normal) { return }
        $area = Get-WindowWorkArea -Reference $Window
        $width = [Math]::Min($Window.ActualWidth, $area.Width); $height = [Math]::Min($Window.ActualHeight, $area.Height)
        if ($Window.ActualWidth -gt $area.Width) { $Window.Width = $area.Width }
        if ($Window.ActualHeight -gt $area.Height) { $Window.Height = $area.Height }
        $Window.Left = [Math]::Max($area.Left, [Math]::Min($Window.Left, $area.Right - $width))
        $Window.Top = [Math]::Max($area.Top, [Math]::Min($Window.Top, $area.Bottom - $height))
    } catch { }
}

# Caps a window (and its minimum size) to the screen before it is shown, and pulls it back on screen once loaded.
# Fixed-size dialogs shrink to fit (their content scrolls); size-to-content dialogs get a maximum size.
function Set-WindowFitToScreen {
    param([Parameter(Mandatory = $true)]$Window, $Reference = $null)
    $area = Get-WindowWorkArea -Reference $(if ($Reference) { $Reference } else { $Window.Owner })
    $maxWidth = [Math]::Max(320, $area.Width - 32)
    $maxHeight = [Math]::Max(240, $area.Height - 32)
    if ($Window.MinWidth -gt $maxWidth) { $Window.MinWidth = $maxWidth }
    if ($Window.MinHeight -gt $maxHeight) { $Window.MinHeight = $maxHeight }
    if ($Window.SizeToContent -ne [System.Windows.SizeToContent]::Manual) { $Window.MaxWidth = $maxWidth; $Window.MaxHeight = $maxHeight }
    if (-not [double]::IsNaN($Window.Width) -and $Window.Width -gt $maxWidth) { $Window.Width = $maxWidth }
    if (-not [double]::IsNaN($Window.Height) -and $Window.Height -gt $maxHeight) { $Window.Height = $maxHeight }
    $hasInteropOwner = $false
    try { $hasInteropOwner = (New-Object System.Windows.Interop.WindowInteropHelper($Window)).Owner -ne [IntPtr]::Zero } catch { }
    if (-not $Window.Owner -and -not $hasInteropOwner) { $Window.WindowStartupLocation = [System.Windows.WindowStartupLocation]::CenterScreen }
    $Window.Add_Loaded({ param($sender) Move-WindowIntoWorkArea -Window $sender })
}

# Shows a WPF window modally. OwnerForm may be a WPF Window, a WinForms Form, or omitted.
# Returns the DialogResult ($true/$false/$null).
function Show-WpfDialog {
    param([Parameter(Mandatory = $true)]$Window, $OwnerForm)

    if ($OwnerForm -is [System.Windows.Window]) {
        $Window.Owner = $OwnerForm
        $Window.WindowStartupLocation = [System.Windows.WindowStartupLocation]::CenterOwner
    } elseif ($OwnerForm -is [System.Windows.Forms.Form]) {
        $interopHelper = New-Object System.Windows.Interop.WindowInteropHelper($Window)
        $interopHelper.Owner = $OwnerForm.Handle
        $Window.WindowStartupLocation = [System.Windows.WindowStartupLocation]::CenterOwner
    }
    Set-WindowFitToScreen -Window $Window -Reference $(if ($OwnerForm -is [System.Windows.Window]) { $OwnerForm } else { $null })
    return $Window.ShowDialog()
}

#endregion

#region Themed Menus
# Menus, context menus and the status bar use a custom renderer so they follow the active theme
# (flat Litera-style look, readable in Dark mode). If the helper type cannot be compiled the app simply
# keeps the default renderer.

function Initialize-ThemedRenderer {
    if ($script:ThemedRendererReady) { return $true }
    try {
        Add-Type -ReferencedAssemblies 'System.Windows.Forms', 'System.Drawing' -TypeDefinition @'
using System.Drawing;
using System.Windows.Forms;

public class AppThemeColorTable : ProfessionalColorTable
{
    public Color Surface = Color.White;
    public Color Hover = Color.LightGray;
    public Color Border = Color.Gray;
    public AppThemeColorTable() { UseSystemColors = false; }
    public override Color ToolStripDropDownBackground { get { return Surface; } }
    public override Color MenuStripGradientBegin { get { return Surface; } }
    public override Color MenuStripGradientEnd { get { return Surface; } }
    public override Color MenuItemSelected { get { return Hover; } }
    public override Color MenuItemSelectedGradientBegin { get { return Hover; } }
    public override Color MenuItemSelectedGradientEnd { get { return Hover; } }
    public override Color MenuItemPressedGradientBegin { get { return Hover; } }
    public override Color MenuItemPressedGradientMiddle { get { return Hover; } }
    public override Color MenuItemPressedGradientEnd { get { return Hover; } }
    public override Color MenuItemBorder { get { return Hover; } }
    public override Color MenuBorder { get { return Border; } }
    public override Color ImageMarginGradientBegin { get { return Surface; } }
    public override Color ImageMarginGradientMiddle { get { return Surface; } }
    public override Color ImageMarginGradientEnd { get { return Surface; } }
    public override Color SeparatorDark { get { return Border; } }
    public override Color SeparatorLight { get { return Surface; } }
    public override Color ToolStripBorder { get { return Border; } }
}

public class AppThemeRenderer : ToolStripProfessionalRenderer
{
    public Color TextColor = Color.Black;
    public AppThemeRenderer(AppThemeColorTable table) : base(table) { RoundedEdges = false; }
    protected override void OnRenderItemText(ToolStripItemTextRenderEventArgs e)
    {
        // Keep the white-on-blue status bar text; everything else follows the theme text color.
        if (!(e.ToolStrip is StatusStrip)) { e.TextColor = TextColor; }
        base.OnRenderItemText(e);
    }
}
'@
        $script:ThemedRendererReady = $true
    } catch {
        Write-Log "Themed menu renderer unavailable: $($_.Exception.Message)" -Level Info
        $script:ThemedRendererReady = $false
    }
    return $script:ThemedRendererReady
}

# Applies the current $script:Theme to every ToolStrip (menus, context menus, status bar) in the app.
function Set-ThemedToolStripRenderer {
    if (-not (Initialize-ThemedRenderer)) { return }
    try {
        $colorTable = New-Object AppThemeColorTable
        $colorTable.Surface = $script:Theme.GroupBackground
        $colorTable.Hover   = $script:Theme.SecondaryButton
        $colorTable.Border  = $script:Theme.BorderColor
        $renderer = New-Object AppThemeRenderer($colorTable)
        $renderer.TextColor = $script:Theme.TextColor
        [System.Windows.Forms.ToolStripManager]::Renderer = $renderer
    } catch {
        Write-Log "Could not apply themed renderer: $($_.Exception.Message)" -Level Info
    }
}
#endregion

function Import-History {
    if (Test-Path $historyFilePath) {
        try {
            $jsonContent = Get-Content -Path $historyFilePath -Raw
            # Filter out any null entries that might be in the JSON array
            $script:history = ($jsonContent | ConvertFrom-Json -ErrorAction SilentlyContinue) | Where-Object { $_ -ne $null }
            Write-Log "History loaded from $historyFilePath"
        } catch { # Catch block for Import-History
            Write-Log "Could not load or parse history file: $($_.Exception.Message)" -Level Info
            $script:history = @()
        }
    }
}

function Save-History {
    try { # Try block for Save-History
        $script:history | ConvertTo-Json -Depth 5 | Set-Content -Path $historyFilePath
    } catch {
        Write-Log "Failed to save history: $($_.Exception.Message)" -Level Debug
    }
}

function Save-Globals {
    try {
        ConvertTo-ProtectedVariables -Variables $script:globals -SecretNames @($script:settings.SecretGlobalNames) | ConvertTo-Json -Depth 10 | Out-File -FilePath $globalsFilePath -Encoding utf8 -NoNewline -ErrorAction Stop
    } catch {
        Write-Log "Failed to save globals: $($_.Exception.Message)" -Level Debug
    }
}

$script:globals = @{}

function Import-Globals {
    if (Test-Path $globalsFilePath) {
        try {
            $json = Get-Content -Path $globalsFilePath -Raw
            $script:globals = ConvertFrom-JsonToHashtable -Json $json
            if (-not $script:globals) { $script:globals = @{} }
            Unprotect-SecretVariables -Variables $script:globals -SecretNames @($script:settings.SecretGlobalNames)
            Write-Log "Globals loaded from $globalsFilePath" -Level Debug
        } catch {
            Write-Log "Could not load or parse globals file: $($_.Exception.Message)" -Level Info
            $script:globals = @{}
        }
    }
}

$script:environments = @{}
$script:activeEnvironment = "No Environment"

function Import-Environments {
    if (Test-Path $environmentsFilePath) {
        try {
            $json = Get-Content -Path $environmentsFilePath -Raw
            $script:environments = ConvertFrom-JsonToHashtable -Json $json
            if (-not $script:environments) { $script:environments = @{} }
            # Decrypt sensitive fields
            foreach ($env in $script:environments.Values) {
                if ($env.Variables) { Unprotect-SecretVariables -Variables $env.Variables -SecretNames (Get-SecretNames $env) }
                if ($env.Authentication) {
                    foreach ($k in @('Value','Token','Password','ClientSecret','AccessToken','RefreshToken')) {
                        if ($env.Authentication[$k]) { $env.Authentication[$k] = Unprotect-String $env.Authentication[$k] }
                    }
                }
            }
            Write-Log "Environments loaded from $environmentsFilePath" -Level Debug
        } catch { # Catch block for Import-Environments
            Write-Log "Could not load or parse environments file: $($_.Exception.Message)" -Level Info
            $script:environments = @{}
        }
    }
}

function Save-Environments {
    try {
        # Clone and Encrypt
        $jsonRaw = $script:environments | ConvertTo-Json -Depth 10
        $envCopy = ConvertFrom-JsonToHashtable -Json $jsonRaw
        if (-not $envCopy) { $envCopy = @{} }
        foreach ($env in $envCopy.Values) {
            if ($env.Variables) { $env.Variables = ConvertTo-ProtectedVariables -Variables $env.Variables -SecretNames (Get-SecretNames $env) }
            if ($env.Authentication) {
                foreach ($k in @('Value','Token','Password','ClientSecret','AccessToken','RefreshToken')) {
                    if ($env.Authentication[$k]) { $env.Authentication[$k] = Protect-String $env.Authentication[$k] }
                }
            }
        }
        $json = $envCopy | ConvertTo-Json -Depth 10
        # Use Out-File with a specific encoding to prevent BOM (Byte Order Mark) issues.
        $json | Out-File -FilePath $environmentsFilePath -Encoding utf8 -NoNewline -ErrorAction Stop
    } catch { # Catch block for Save-Environments
        Write-Log "Failed to save environments: $($_.Exception.Message)" -Level Debug
    }
}

$script:collections = @()
$script:activeCollectionName = $null
$script:activeCollectionNode = $null
$script:activeCollectionVariables = @{}
$script:requestTabs = @()
$script:requestTemplates = @()
$script:activeRequestTabId = $null
$script:isSwitchingRequestTab = $false

function Initialize-CollectionVariables {
    param([array]$Items)
    foreach ($item in ($Items | Where-Object { $_ -ne $null })) {
        if ($item.Type -eq "Collection") {
            if (-not ($item.PSObject.Properties.Name -contains 'Variables')) {
                $item | Add-Member -MemberType NoteProperty -Name 'Variables' -Value @{}
            } elseif ($null -eq $item.Variables) {
                $item.Variables = @{}
            }
        }
        if ($item.Items) { Initialize-CollectionVariables -Items $item.Items }
    }
}

function Import-Collections {
    if (Test-Path $collectionsFilePath) {
        try {
            $jsonContent = Get-Content -Path $collectionsFilePath -Raw
            if (-not [string]::IsNullOrWhiteSpace($jsonContent)) {
                $script:collections = $jsonContent | ConvertFrom-Json -ErrorAction SilentlyContinue
            }
            if ($script:collections -and $script:collections -isnot [array]) { $script:collections = @($script:collections) }
            foreach ($collection in @($script:collections | Where-Object { $_ })) { if ($collection.Variables) { Unprotect-SecretVariables -Variables $collection.Variables -SecretNames (Get-SecretNames $collection) } }
            Initialize-CollectionVariables -Items $script:collections
            Write-Log "Collections loaded from $collectionsFilePath" -Level Debug
        } catch { # Catch block for Import-Collections
            Write-Log "Could not load or parse collections file: $($_.Exception.Message)" -Level Info
            $script:collections = @()
        }
    }
}

function Save-Collections {
    try {
        # Depth 50: nested folders deeper than a few levels were silently truncated at depth 10.
        $json = ConvertTo-Json -InputObject (Get-CollectionsForStorage -Collections $script:collections) -Depth 50
        $json | Out-File -FilePath $collectionsFilePath -Encoding utf8 -NoNewline -ErrorAction Stop
    } catch {
        Write-Log "Failed to save collections: $($_.Exception.Message)" -Level Info
    }
}

function Copy-RequestData {
    param([object]$Data)
    if ($null -eq $Data) { return $null }
    return (($Data | ConvertTo-Json -Depth 20) | ConvertFrom-Json)
}

function New-RequestTabState {
    param(
        [string]$Name = "Request",
        [string]$Method = "POST",
        [string]$Url = "",
        [string]$Headers = "",
        [string]$Body = "",
        [string]$BodyType = "multipart/form-data",
        [string]$OutputFormat = "",
        [string]$Tests = "",
        [string]$PreRequestScript = "",
        [string]$Environment = "No Environment",
        [object]$Authentication = $null,
        [string]$GqlQuery = "",
        [string]$GqlVars = "",
        [bool]$IncludeFilename = $true,
        [bool]$IncludeContentType = $true
    )

    [PSCustomObject]@{
        Id = [guid]::NewGuid().ToString()
        Name = $Name
        Method = $Method
        Url = $Url
        Headers = $Headers
        Body = $Body
        BodyType = $BodyType
        OutputFormat = $OutputFormat
        Tests = $Tests
        PreRequestScript = $PreRequestScript
        Environment = $Environment
        Authentication = if ($Authentication) { Copy-RequestData $Authentication } else { @{ Type = "No Auth" } }
        GqlQuery = $GqlQuery
        GqlVars = $GqlVars
        IncludeFilename = $IncludeFilename
        IncludeContentType = $IncludeContentType
    }
}

function Initialize-RequestTabDefaults {
    param([object]$TabState)
    if (-not $TabState) { return }
    if (-not ($TabState.PSObject.Properties.Name -contains 'Id') -or [string]::IsNullOrWhiteSpace($TabState.Id)) {
        $TabState | Add-Member -MemberType NoteProperty -Name 'Id' -Value ([guid]::NewGuid().ToString()) -Force
    }
    foreach ($pair in @(
        @{ Name='Name'; Value='Request' },
        @{ Name='Method'; Value='POST' },
        @{ Name='Url'; Value='' },
        @{ Name='Headers'; Value='' },
        @{ Name='Body'; Value='' },
        @{ Name='BodyType'; Value='multipart/form-data' },
        @{ Name='OutputFormat'; Value='' },
        @{ Name='Tests'; Value='' },
        @{ Name='PreRequestScript'; Value='' },
        @{ Name='Environment'; Value='No Environment' },
        @{ Name='Authentication'; Value=@{ Type = "No Auth" } },
        @{ Name='GqlQuery'; Value='' },
        @{ Name='GqlVars'; Value='' },
        @{ Name='IncludeFilename'; Value=$true },
        @{ Name='IncludeContentType'; Value=$true }
    )) {
        if (-not ($TabState.PSObject.Properties.Name -contains $pair.Name)) {
            $TabState | Add-Member -MemberType NoteProperty -Name $pair.Name -Value $pair.Value -Force
        }
    }
}

function Import-RequestTabs {
    $script:requestTabs = @()
    if (Test-Path $requestTabsFilePath) {
        try {
            $json = Get-Content -Path $requestTabsFilePath -Raw
            if (-not [string]::IsNullOrWhiteSpace($json)) {
                $loadedTabs = $json | ConvertFrom-Json -ErrorAction SilentlyContinue
                if ($loadedTabs -and $loadedTabs -isnot [array]) { $loadedTabs = @($loadedTabs) }
                foreach ($tabState in @($loadedTabs)) {
                    if (-not $tabState) { continue }
                    Initialize-RequestTabDefaults -TabState $tabState
                    $script:requestTabs += $tabState
                }
            }
            Write-Log "Request tabs loaded from $requestTabsFilePath" -Level Debug
        } catch {
            Write-Log "Could not load request tabs: $($_.Exception.Message)" -Level Info
            $script:requestTabs = @()
        }
    }
    if (-not $script:requestTabs -or $script:requestTabs.Count -eq 0) {
        $script:requestTabs = @(New-RequestTabState -Name "Request 1" -IncludeFilename $script:settings.IncludeFilename -IncludeContentType $script:settings.IncludeContentType)
    }
    $script:activeRequestTabId = $script:requestTabs[0].Id
}

function Save-RequestTabs {
    if ($script:isSecondaryWindow) { return }
    try {
        if (-not $script:requestTabs) { return }
        $script:requestTabs | ConvertTo-Json -Depth 20 | Out-File -FilePath $requestTabsFilePath -Encoding utf8 -NoNewline -ErrorAction Stop
    } catch {
        Write-Log "Failed to save request tabs: $($_.Exception.Message)" -Level Debug
    }
}

function Import-RequestTemplates {
    $script:requestTemplates = @()
    if (Test-Path $requestTemplatesFilePath) {
        try {
            $json = Get-Content -Path $requestTemplatesFilePath -Raw
            if (-not [string]::IsNullOrWhiteSpace($json)) {
                $loadedTemplates = $json | ConvertFrom-Json -ErrorAction SilentlyContinue
                if ($loadedTemplates -and $loadedTemplates -isnot [array]) { $loadedTemplates = @($loadedTemplates) }
                foreach ($template in @($loadedTemplates)) {
                    if (-not $template) { continue }
                    Initialize-RequestTabDefaults -TabState $template
                    $script:requestTemplates += $template
                }
            }
            Write-Log "Request templates loaded from $requestTemplatesFilePath" -Level Debug
        } catch {
            Write-Log "Could not load request templates: $($_.Exception.Message)" -Level Info
            $script:requestTemplates = @()
        }
    }
}

function Save-RequestTemplates {
    try {
        $script:requestTemplates | ConvertTo-Json -Depth 20 | Out-File -FilePath $requestTemplatesFilePath -Encoding utf8 -NoNewline -ErrorAction Stop
    } catch {
        Write-Log "Failed to save request templates: $($_.Exception.Message)" -Level Debug
    }
}

$script:monitors = @()

function Import-Monitors {
    if (Test-Path $monitorsFilePath) {
        try {
            $json = Get-Content -Path $monitorsFilePath -Raw
            $script:monitors = $json | ConvertFrom-Json
            if ($script:monitors -isnot [array]) { $script:monitors = @($script:monitors) }
            # Migration for monitors saved without BodyType or RequestTimeoutSeconds
            foreach ($monitor in ($script:monitors | Where-Object { $_ -ne $null })) {
                if ($monitor.Request) {
                    if (-not ($monitor.Request.PSObject.Properties.Name -contains 'BodyType')) {
                        $monitor.Request | Add-Member -MemberType NoteProperty -Name 'BodyType' -Value 'multipart/form-data'
                    }
                    if (-not ($monitor.Request.PSObject.Properties.Name -contains 'RequestTimeoutSeconds')) {
                        $monitor.Request | Add-Member -MemberType NoteProperty -Name 'RequestTimeoutSeconds' -Value 30
                    }
                    if (-not ($monitor.Request.PSObject.Properties.Name -contains 'Authentication')) {
                        $monitor.Request | Add-Member -MemberType NoteProperty -Name 'Authentication' -Value @{ Type = "No Auth" }
                    }
                }
                # Migration for monitors missing the Alerts object or its properties
                if (-not ($monitor.PSObject.Properties.Name -contains 'Alerts')) {
                    $monitor | Add-Member -MemberType NoteProperty -Name 'Alerts' -Value @{ OnFailure=$true; OnSlow=$false; ThresholdMs=1000; SendEmail=$false; EmailTo="" }
                } else {
                    # Ensure all sub-properties exist
                    if (-not ($monitor.Alerts.PSObject.Properties.Name -contains 'OnFailure'))   { $monitor.Alerts | Add-Member -MemberType NoteProperty -Name 'OnFailure' -Value $true }
                    if (-not ($monitor.Alerts.PSObject.Properties.Name -contains 'OnSlow'))      { $monitor.Alerts | Add-Member -MemberType NoteProperty -Name 'OnSlow' -Value $false }
                    if (-not ($monitor.Alerts.PSObject.Properties.Name -contains 'ThresholdMs')) { $monitor.Alerts | Add-Member -MemberType NoteProperty -Name 'ThresholdMs' -Value 1000 }
                    if (-not ($monitor.Alerts.PSObject.Properties.Name -contains 'SendEmail'))   { $monitor.Alerts | Add-Member -MemberType NoteProperty -Name 'SendEmail' -Value $false }
                    if (-not ($monitor.Alerts.PSObject.Properties.Name -contains 'EmailTo'))     { $monitor.Alerts | Add-Member -MemberType NoteProperty -Name 'EmailTo' -Value "" }
                }
            }
        } catch {
            $script:monitors = @()
        }
    }
}

function Save-Monitors {
    $script:monitors | ConvertTo-Json -Depth 10 | Set-Content -Path $monitorsFilePath
}

