        Dock          = 'Fill'
        FlowDirection = 'TopDown'
        AutoSize      = $true
        AutoSizeMode  = 'GrowAndShrink'
        WrapContents  = $false
        Margin        = [System.Windows.Forms.Padding]::new(0)
