function Add-CollectionTreeNode {
    param($ParentItems, $Item, $ParentItem, $Root, [string]$Filter)
    if (-not $Item) { return $false }
    $type = [string]$Item.Type
    $name = [string]$Item.Name
    $node = New-Object System.Windows.Controls.TreeViewItem
    $node.Tag = @{ Item = $Item; Parent = $ParentItem; Root = $Root }

    if ($type -eq 'Request') {
        $requestData = Get-RequestObjectFromItem -Item $Item
        $url = [string](Get-ObjectProperty $requestData 'Url' '')
        if ($Filter -and $name.IndexOf($Filter, [System.StringComparison]::OrdinalIgnoreCase) -lt 0 -and $url.IndexOf($Filter, [System.StringComparison]::OrdinalIgnoreCase) -lt 0) { return $false }
        $method = [string](Get-ObjectProperty $requestData 'Method' 'GET')
        $panel = New-Object System.Windows.Controls.StackPanel
        $panel.Orientation = 'Horizontal'
        $methodText = New-Object System.Windows.Controls.TextBlock
        $methodText.Text = $method.ToUpperInvariant(); $methodText.FontSize = 10; $methodText.FontWeight = 'Bold'; $methodText.Width = 46
        $methodText.VerticalAlignment = 'Center'; $methodText.Foreground = Get-MethodBrush -Method $method
        $nameText = New-Object System.Windows.Controls.TextBlock
        $nameText.Text = $name; $nameText.VerticalAlignment = 'Center'
        [void]$panel.Children.Add($methodText); [void]$panel.Children.Add($nameText)
        $node.Header = $panel
        $node.ToolTip = $url
        [void]$ParentItems.Add($node)
        return $true
    }

    $icon = if ($type -eq 'Collection') { [char]::ConvertFromUtf32(0x1F4DA) } else { [char]::ConvertFromUtf32(0x1F4C1) }
    $node.Header = "$icon  $name"
    $node.FontWeight = if ($type -eq 'Collection') { 'SemiBold' } else { 'Normal' }
    $anyChild = $false
    foreach ($child in @($Item.Items)) {
        if (Add-CollectionTreeNode -ParentItems $node.Items -Item $child -ParentItem $Item -Root $Root -Filter $Filter) { $anyChild = $true }
    }
    $nameMatches = (-not $Filter) -or ($name.IndexOf($Filter, [System.StringComparison]::OrdinalIgnoreCase) -ge 0)
    if ($Filter -and -not $anyChild -and -not $nameMatches) { return $false }
    if ($Filter) { $node.IsExpanded = $true }
    [void]$ParentItems.Add($node)
    return $true
}

function Update-CollectionsTree {
    $tree = $script:ui.CollectionsTree
    $filter = $script:ui.CollectionFilterBox.Text.Trim()
    $expanded = @{}
    foreach ($node in $tree.Items) { if ($node.IsExpanded -and $node.Tag) { $expanded[[string]$node.Tag.Item.Name] = $true } }
    $tree.Items.Clear()
    foreach ($collection in @($script:collections)) {
        if (-not $collection) { continue }
        [void](Add-CollectionTreeNode -ParentItems $tree.Items -Item $collection -ParentItem $null -Root $collection -Filter $filter)
    }
    foreach ($node in $tree.Items) { if ($expanded[[string]$node.Tag.Item.Name]) { $node.IsExpanded = $true } }
}

function Get-SelectedTreeInfo {
    $selected = $script:ui.CollectionsTree.SelectedItem
    if ($selected -and $selected.Tag) { return $selected.Tag }
    return $null
}

function Update-TreeMenuState {
    $info = Get-SelectedTreeInfo
    $type = if ($info) { [string]$info.Item.Type } else { '' }
    $isContainer = $type -in @('Collection', 'Folder')
    $items = $script:treeMenuItems
    $items['Open'].IsEnabled = ($type -eq 'Request')
    $items['Open in new tab'].IsEnabled = ($type -eq 'Request')
    $items['New Collection'].IsEnabled = $true
    $items['New Folder'].IsEnabled = $isContainer
    $items['Save Current Request'].IsEnabled = $isContainer
    $items['Edit Variables...'].IsEnabled = ($type -eq 'Collection')
    $items['Run...'].IsEnabled = $isContainer
    $items['Load Test...'].IsEnabled = ($type -eq 'Request')
    $items['Import OpenAPI Spec...'].IsEnabled = $true
    $items['Rename'].IsEnabled = ($null -ne $info)
    $items['Delete'].IsEnabled = ($null -ne $info)
    $items['Export...'].IsEnabled = $isContainer
    $items['Export as Postman collection...'].IsEnabled = $isContainer
    $items['Settings (auth, headers, scripts)...'].IsEnabled = $isContainer
}

function Save-CollectionsAndRefresh {
    Save-Collections
    Update-CollectionsTree
}

function Add-ItemToContainer {
    param($Container, $NewItem)
    if (-not ($Container.PSObject.Properties.Name -contains 'Items')) { $Container | Add-Member -MemberType NoteProperty -Name 'Items' -Value @() -Force }
    $Container.Items = @($Container.Items) + $NewItem
}

function New-CollectionFromPrompt {
    $name = Show-InputBox -Prompt 'Collection name:' -Title 'New Collection' -DefaultText 'New Collection'
    if ([string]::IsNullOrWhiteSpace($name)) { return }
    $script:collections = @($script:collections) + [PSCustomObject]@{ Name = $name.Trim(); Type = 'Collection'; Items = @(); Variables = @{} }
    Save-CollectionsAndRefresh
    Set-UiStatus "Created collection '$name'."
}

function New-FolderFromPrompt {
    $info = Get-SelectedTreeInfo
    if (-not $info -or $info.Item.Type -notin @('Collection', 'Folder')) { Set-UiStatus 'Select a collection or folder first.'; return }
    $name = Show-InputBox -Prompt 'Folder name:' -Title 'New Folder' -DefaultText 'New Folder'
    if ([string]::IsNullOrWhiteSpace($name)) { return }
    Add-ItemToContainer -Container $info.Item -NewItem ([PSCustomObject]@{ Name = $name.Trim(); Type = 'Folder'; Items = @() })
    Save-CollectionsAndRefresh
}

# Saves the current request. If the tab was opened from a collection it is updated in place; otherwise it is added to
# the selected collection/folder (or one chosen in a dialog).
function Save-CurrentRequest {
    param([switch]$IntoSelection)
    Save-ActiveRequestTab
    $state = Get-EditorState
    $source = $script:tabSources[[string]$state.Id]
    if ($source -and $source.Item -and -not $IntoSelection) {
        $source.Item.RequestData = New-RequestDataFromState -State $state
        Save-CollectionsAndRefresh
        Set-UiStatus "Updated '$($source.Item.Name)' in the collection."
        return
    }

    $container = $null; $root = $null
    $info = Get-SelectedTreeInfo
    if ($info) {
        if ($info.Item.Type -in @('Collection', 'Folder')) { $container = $info.Item; $root = $info.Root }
        elseif ($info.Item.Type -eq 'Request' -and $info.Parent) { $container = $info.Parent; $root = $info.Root }
    }
    if (-not $container) {
        $choice = Show-ChooseContainerDialog
        if (-not $choice) { return }
        $container = $choice.Container; $root = $choice.Root
    }
    $name = Show-InputBox -Prompt 'Request name:' -Title 'Save Request' -DefaultText "$($state.Method) $($state.Url)"
    if ([string]::IsNullOrWhiteSpace($name)) { return }
    $newItem = [PSCustomObject]@{ Name = $name.Trim(); Type = 'Request'; RequestData = (New-RequestDataFromState -State $state) }
    Add-ItemToContainer -Container $container -NewItem $newItem
    $script:tabSources[[string]$state.Id] = @{ Item = $newItem; Root = $root }
    Set-ActiveCollectionContext -Root $root
    Save-CollectionsAndRefresh
    Set-UiStatus "Saved '$($name.Trim())' to '$($container.Name)'."
}

function Set-ActiveCollectionContext {
    param($Root)
    $script:activeCollection = $Root
    $script:activeCollectionVariables = if ($Root -and $Root.Variables) { $Root.Variables } else { @{} }
    Update-ExtractVariableChoices
}

# Loads a collection request (or a history entry) into the active tab, or into a new tab.
function Open-RequestState {
    param($Data, [string]$Name, $Source = $null, [switch]$NewTab)
    if (-not $Data) { return }
    $state = Copy-RequestData $Data
    Initialize-RequestTabDefaults -TabState $state
    $state.Name = if ($Name) { $Name } else { "$($state.Method) $($state.Url)" }
    if ($NewTab) {
        [void](Add-RequestTab -InitialState $state)
        $tabId = $script:activeRequestTabId
    } else {
        $tabId = $script:activeRequestTabId
        $state.Id = $tabId
        for ($index = 0; $index -lt $script:requestTabs.Count; $index++) { if ($script:requestTabs[$index].Id -eq $tabId) { $script:requestTabs[$index] = $state; break } }
        $script:tabResults.Remove($tabId)
        Set-EditorState -State $state
        Update-RequestTabsStrip
        Save-RequestTabs
    }
    if ($Source) { $script:tabSources[$tabId] = $Source; Set-ActiveCollectionContext -Root $Source.Root }
    else { $script:tabSources.Remove($tabId); Set-ActiveCollectionContext -Root $null }
    Set-UiStatus "Loaded '$($state.Name)'."
}

function Open-SelectedTreeRequest {
    param([switch]$NewTab)
    $info = Get-SelectedTreeInfo
    if (-not $info -or $info.Item.Type -ne 'Request') { return }
    $data = Get-RequestObjectFromItem -Item $info.Item
    Open-RequestState -Data $data -Name ([string]$info.Item.Name) -Source @{ Item = $info.Item; Root = $info.Root } -NewTab:$NewTab
}

function Rename-SelectedTreeItem {
    $info = Get-SelectedTreeInfo
    if (-not $info) { return }
    $newName = Show-InputBox -Prompt 'New name:' -Title 'Rename' -DefaultText ([string]$info.Item.Name)
    if ([string]::IsNullOrWhiteSpace($newName)) { return }
    $info.Item.Name = $newName.Trim()
    Save-CollectionsAndRefresh
}

function Remove-SelectedTreeItem {
    $info = Get-SelectedTreeInfo
    if (-not $info) { return }
    $answer = [System.Windows.MessageBox]::Show((Get-MainWindow), "Delete '$($info.Item.Name)'? This cannot be undone.", 'Confirm delete', 'YesNo', 'Warning')
    if ($answer -ne 'Yes') { return }
    $target = $info.Item
    if ($info.Parent) { $info.Parent.Items = @($info.Parent.Items | Where-Object { $_ -ne $target }) }
    else { $script:collections = @($script:collections | Where-Object { $_ -ne $target }) }
    foreach ($tabId in @($script:tabSources.Keys)) { if ($script:tabSources[$tabId].Item -eq $target) { $script:tabSources.Remove($tabId) } }
    Save-CollectionsAndRefresh
}

function Export-SelectedTreeItem {
    param([switch]$Postman)
    $info = Get-SelectedTreeInfo
    if (-not $info) { return }
    if ($Postman) {
        $picker = New-Object Microsoft.Win32.SaveFileDialog
        $picker.Title = 'Export as Postman collection (v2.1)'
        $picker.Filter = 'Postman collection (*.json)|*.json'
        $picker.FileName = (([string]$info.Item.Name) -replace '[\\/:*?"<>|]', '_') + '.postman_collection.json'
        if ($picker.ShowDialog((Get-MainWindow)) -ne $true) { return }
        ConvertTo-PostmanCollectionJson -Item $info.Item | Set-Content -Path $picker.FileName -Encoding UTF8
        Set-UiStatus "Exported '$($info.Item.Name)' as a Postman collection (secret variables and PowerShell scripts are not included)."
        return
    }
    $dialog = New-Object Microsoft.Win32.SaveFileDialog
    $dialog.Title = 'Export'
    $dialog.Filter = 'JSON files (*.json)|*.json'
    $dialog.FileName = (([string]$info.Item.Name) -replace '[\\/:*?"<>|]', '_') + '.json'
    if ($dialog.ShowDialog((Get-MainWindow)) -ne $true) { return }
    $exportItem = if ($info.Item.Type -eq 'Collection') { $safe = Get-CollectionsForStorage -Collections @($info.Item) -ForExport; $safe[0] } else { $info.Item }
    ConvertTo-Json -InputObject @($exportItem) -Depth 50 | Set-Content -Path $dialog.FileName -Encoding UTF8
    Set-UiStatus "Exported to $($dialog.FileName)"
}

function Export-AllCollections {
    if (@($script:collections).Count -eq 0) { Set-UiStatus 'There are no collections to export.'; return }
    $dialog = New-Object Microsoft.Win32.SaveFileDialog
    $dialog.Title = 'Export all collections'
    $dialog.Filter = 'JSON files (*.json)|*.json'
    $dialog.FileName = 'api_tester_collections.json'
    if ($dialog.ShowDialog((Get-MainWindow)) -ne $true) { return }
    ConvertTo-Json -InputObject (Get-CollectionsForStorage -Collections $script:collections -ForExport) -Depth 50 | Set-Content -Path $dialog.FileName -Encoding UTF8
    Set-UiStatus "Exported collections to $($dialog.FileName)"
}

function Edit-CollectionVariables {
    $info = Get-SelectedTreeInfo
    if (-not $info -or $info.Item.Type -ne 'Collection') { return }
    $collection = $info.Item
    $current = @{}
    if ($collection.Variables -is [hashtable]) { $current = $collection.Variables }
    elseif ($collection.Variables) { foreach ($property in $collection.Variables.PSObject.Properties) { $current[$property.Name] = $property.Value } }
    $edited = Show-VariablesDialog -Title "Variables - $($collection.Name)" -Variables $current -SecretNames (Get-SecretNames $collection)
    if ($null -eq $edited) { return }
    Set-ObjectProperty -Object $collection -Name 'Variables' -Value $edited.Variables
    Set-ObjectProperty -Object $collection -Name 'SecretVariables' -Value @($edited.SecretNames)
    Save-Collections
    if ($script:activeCollection -eq $collection) { Set-ActiveCollectionContext -Root $collection }
    Update-AllCodeHighlights
    Set-UiStatus 'Collection variables saved.'
}

function Edit-ContainerSettings {
    $info = Get-SelectedTreeInfo
    if (-not $info -or $info.Item.Type -notin @('Collection', 'Folder')) { return }
    if (Show-ContainerSettingsDialog -Item $info.Item) { Save-Collections; Set-UiStatus "Saved settings for '$($info.Item.Name)'." }
}

function Start-SelectedCollectionRun {
    $info = Get-SelectedTreeInfo
    if (-not $info -or $info.Item.Type -notin @('Collection', 'Folder')) { return }
    Show-CollectionRunner -Item $info.Item -Root $info.Root
}

function Start-SelectedLoadTest {
    $info = Get-SelectedTreeInfo
    if (-not $info -or $info.Item.Type -ne 'Request') { return }
    $data = Get-RequestObjectFromItem -Item $info.Item
    $headerTable = @{}
    foreach ($entry in (ConvertFrom-HeaderText -HeaderText (Expand-Variables -InputString ([string]$data.Headers)))) { $headerTable[$entry.Name] = $entry.Value }
    $loadRequest = [PSCustomObject]@{ Url = (Expand-Variables -InputString ([string]$data.Url)); Method = [string]$data.Method; Headers = $headerTable; Body = (Expand-Variables -InputString ([string]$data.Body)) }
    Show-LoadTestDialog -RequestObject $loadRequest
}

function Import-OpenApiIntoTree {
    $dialog = New-Object Microsoft.Win32.OpenFileDialog
    $dialog.Title = 'Import OpenAPI specification'
    $dialog.Filter = 'JSON/YAML files (*.json;*.yaml;*.yml)|*.json;*.yaml;*.yml|All files (*.*)|*.*'
    if ($dialog.ShowDialog((Get-MainWindow)) -ne $true) { return }
    try {
        $imported = ConvertFrom-OpenApiSpec -FilePath $dialog.FileName
        $script:collections = @($script:collections) + $imported
        Save-CollectionsAndRefresh
        [void][System.Windows.MessageBox]::Show((Get-MainWindow), 'OpenAPI specification imported successfully.', 'Import', 'OK', 'Information')
    } catch {
        [void][System.Windows.MessageBox]::Show((Get-MainWindow), "Failed to import the OpenAPI spec: $($_.Exception.Message)", 'Import error', 'OK', 'Error')
    }
}

# =================================================================================================
# History
# =================================================================================================

function Add-HistoryEntry {
    param($State)
    if (-not $script:settings.EnableHistory) { return }
    $entry = New-RequestDataFromState -State $State
    $script:history = @($entry) + @($script:history | Where-Object { $_ })
    if ($script:history.Count -gt 50) { $script:history = @($script:history[0..49]) }
    Save-History
    Update-HistoryList
    return $entry
}

# Stores the response with its history entry (status, headers and - unless switched off or too large - the body).
function Set-HistoryResponse {
    param($Entry, $Result)
    if (-not $Entry -or $script:settings.HistorySaveResponses -eq $false) { return }
    $limitBytes = [int]$(if ($script:settings.HistoryResponseBodyLimitKB -gt 0) { $script:settings.HistoryResponseBodyLimitKB } else { 256 }) * 1024
    $saved = [ordered]@{ Timestamp = (Get-Date).ToString('o'); Success = [bool]$Result.Success; ElapsedMs = [int]$Result.ElapsedMs }
    if ($Result.Success) {
        $saved.StatusCode = [int]$Result.StatusCode; $saved.ReasonPhrase = [string]$Result.ReasonPhrase; $saved.SizeBytes = [int]$Result.SizeBytes
        $saved.ContentType = [string]$Result.ContentType; $saved.Headers = (@($Result.HeaderLines) -join "`r`n")
        $saved.Body = if (-not $Result.IsBinary -and ([string]$Result.Body).Length -le $limitBytes) { [string]$Result.Body } else { $null }
        $saved.BodyOmitted = ($null -eq $saved.Body)
    } else { $saved.ErrorMessage = [string]$Result.ErrorMessage }
    $Entry | Add-Member -MemberType NoteProperty -Name 'Response' -Value ([PSCustomObject]$saved) -Force
    Save-History
    Update-HistoryList
}

function ConvertFrom-SavedResponse {
    param($Saved)
    if (-not $Saved) { return $null }
    if (-not $Saved.Success) { return @{ Success = $false; ErrorMessage = [string]$Saved.ErrorMessage; ElapsedMs = [int]$Saved.ElapsedMs } }
    $body = if ($null -ne $Saved.Body) { [string]$Saved.Body } else { '[The body was not saved - it was binary or larger than the history limit.]' }
    return @{ Success = $true; StatusCode = [int]$Saved.StatusCode; ReasonPhrase = [string]$Saved.ReasonPhrase; ElapsedMs = [int]$Saved.ElapsedMs; SizeBytes = [int]$Saved.SizeBytes
        Body = $body; BodyBytes = [System.Text.Encoding]::UTF8.GetBytes($body); IsBinary = $false; HeaderLines = @(([string]$Saved.Headers) -split "`r?`n" | Where-Object { $_ }); ContentType = [string]$Saved.ContentType; ContentDispositionName = '' }
}

function Show-SavedHistoryResponse {
    $entries = Get-SelectedHistoryEntries
    if ($entries.Count -ne 1 -or -not $entries[0].Response) { return }
    $entry = $entries[0]
    Open-RequestState -Data $entry -Name "$($entry.Method) $($entry.Url)" -NewTab
    $result = ConvertFrom-SavedResponse -Saved $entry.Response
    $script:tabResults[[string]$script:activeRequestTabId] = $result
    Show-ResponseResult -Result $result
    Set-UiStatus "Showing the response saved on $(([datetime]$entry.Response.Timestamp).ToString()) (offline)."
}

function ConvertTo-HistoryTime {
    param($Timestamp)
    $text = if ($Timestamp -is [PSCustomObject] -and $Timestamp.PSObject.Properties.Name -contains 'DateTime') { $Timestamp.DateTime } else { $Timestamp }
    $parsed = [datetime]::MinValue
    if ($text -is [datetime]) { return $text }
    if ([datetime]::TryParse([string]$text, [ref]$parsed)) { return $parsed }
    if ([datetime]::TryParse([string]$text, [System.Globalization.CultureInfo]::InvariantCulture, [System.Globalization.DateTimeStyles]::None, [ref]$parsed)) { return $parsed }
    return $null
}

function Update-HistoryEnvironmentChoices {
    $box = $script:ui.HistoryEnvironmentBox
    $current = [string]$box.SelectedItem
    $script:isRefreshingHistoryFilter = $true
    try {
        $box.Items.Clear()
        [void]$box.Items.Add('All Environments')
        foreach ($name in @($script:environments.Keys | Sort-Object)) { [void]$box.Items.Add($name) }
        $box.SelectedItem = if ($current -and $box.Items.Contains($current)) { $current } else { 'All Environments' }
    } finally { $script:isRefreshingHistoryFilter = $false }
}

function Update-HistoryList {
    $controls = $script:ui
    if (-not $controls -or $script:isRefreshingHistoryFilter) { return }
    if ($controls.HistoryEnvironmentBox.Items.Count -eq 0) { Update-HistoryEnvironmentChoices }
    $textFilter = $controls.HistoryFilterBox.Text.Trim()
    $environmentFilter = [string]$controls.HistoryEnvironmentBox.SelectedItem
    $entries = @($script:history | Where-Object { $_ })
    if ($textFilter) { $entries = @($entries | Where-Object { $_.Method -like "*$textFilter*" -or $_.Url -like "*$textFilter*" }) }
    if ($environmentFilter -and $environmentFilter -ne 'All Environments') { $entries = @($entries | Where-Object { $_.Environment -eq $environmentFilter }) }
    $controls.HistoryList.Items.Clear()
    foreach ($entry in $entries) {
        if (-not ($entry.Method -and $entry.Url)) { continue }
        $time = ConvertTo-HistoryTime -Timestamp $entry.Timestamp
        $item = New-Object System.Windows.Controls.ListBoxItem
        $statusText = if ($entry.Response) { if ($entry.Response.Success) { [string]$entry.Response.StatusCode } else { 'ERR' } } else { '...' }
        $item.Content = "$(if ($time) { $time.ToString('HH:mm:ss') } else { '??:??:??' }) | $statusText | $($entry.Method) | $($entry.Url)"
        $item.ToolTip = [string]$entry.Url
        $item.Tag = $entry
        [void]$controls.HistoryList.Items.Add($item)
    }
}

function Get-SelectedHistoryEntries {
    return @($script:ui.HistoryList.SelectedItems | ForEach-Object { $_.Tag })
}

function Open-SelectedHistoryEntry {
    param([switch]$NewTab, [switch]$RunIfEnabled)
    $entries = Get-SelectedHistoryEntries
    if ($entries.Count -ne 1) { return }
    $entry = $entries[0]
    Open-RequestState -Data $entry -Name "$($entry.Method) $($entry.Url)" -NewTab:$NewTab
    # Settings > "Auto-run on history double-click"
    if ($RunIfEnabled -and $script:settings.AutoRunHistory) { Invoke-SendRequest }
}

function Remove-SelectedHistoryEntries {
    $entries = Get-SelectedHistoryEntries
    if ($entries.Count -eq 0) { return }
    $script:history = @($script:history | Where-Object { $_ -and ($entries -notcontains $_) })
    Save-History
    Update-HistoryList
}

function Clear-HistoryWithConfirm {
    $answer = [System.Windows.MessageBox]::Show((Get-MainWindow), 'Clear all history? This cannot be undone.', 'Confirm clear', 'YesNo', 'Warning')
    if ($answer -ne 'Yes') { return }
    $script:history = @()
    Save-History
    Update-HistoryList
}

function Export-HistoryToFile {
    $dialog = New-Object Microsoft.Win32.SaveFileDialog
    $dialog.Title = 'Export history'
    $dialog.Filter = 'JSON files (*.json)|*.json'
    $dialog.FileName = 'api_tester_history_export.json'
    if ($dialog.ShowDialog((Get-MainWindow)) -ne $true) { return }
    @($script:history | Where-Object { $_ }) | ConvertTo-Json -Depth 20 | Set-Content -Path $dialog.FileName -Encoding UTF8
    Set-UiStatus "Exported history to $($dialog.FileName)"
}

function Copy-HistoryAsCode {
    param([string]$Language)
    $entries = Get-SelectedHistoryEntries
    if ($entries.Count -ne 1) { return }
    [System.Windows.Clipboard]::SetText((New-CodeSnippet -RequestItem $entries[0] -Language $Language))
    Set-UiStatus "Copied history item as $Language."
}

function Compare-SelectedHistoryEntries {
    $entries = Get-SelectedHistoryEntries
    if ($entries.Count -ne 2) { return }
    $first = $entries[0]; $second = $entries[1]
    # Both responses saved: compare them offline. Otherwise both requests are sent again.
    if ($first.Response -and $second.Response -and $null -ne $first.Response.Body -and $null -ne $second.Response.Body) {
        Show-DiffDialog -Request1 $first -Request2 $second -SavedBody1 ([string]$first.Response.Body) -SavedBody2 ([string]$second.Response.Body)
    } else { Show-DiffDialog -Request1 $first -Request2 $second }
}
#endregion

#region XAML Main Window - dialogs (variables, environments, templates, save-to-collection, collection runner)

# Shows a small modal XAML dialog built from a header, a body element and OK/Cancel buttons.
# $ControlNames are resolved with FindName; returns @{ Window; Controls }.
function New-DialogWindow {
    param([string]$BodyXaml, [string[]]$ControlNames, [string]$Title, [int]$Width = 520, [int]$Height = 0)
    $heightAttribute = if ($Height -gt 0) { "Height=`"$Height`"" } else { 'SizeToContent="Height"' }
    $xaml = @"
<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation" xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
        Title="Dialog" Width="$Width" $heightAttribute ShowInTaskbar="False" WindowStartupLocation="CenterOwner"
        Background="@FORM@" Foreground="@TEXT@" FontFamily="Segoe UI">
  <Window.Resources><!--APP_RESOURCES--></Window.Resources>
  $BodyXaml
</Window>
"@
    $bundle = New-WpfWindowFromXaml -Xaml $xaml -ControlNames $ControlNames
    $bundle.Window.Title = $Title
    return $bundle
}

# ------------------------------------------------------------------------------------------------
# Variables (name / value / secret grid)
# ------------------------------------------------------------------------------------------------

# XAML for a variables grid; values of secret rows are masked until "Show secret values" is ticked.
function Get-VariablesGridXaml {
    param([string]$Prefix)
    return @"
<DockPanel>
  <WrapPanel DockPanel.Dock="Top" Margin="0,0,0,6">
    <Button x:Name="${Prefix}AddButton" Style="{StaticResource SmallButton}" Content="+ Add variable"/>
    <Button x:Name="${Prefix}RemoveButton" Style="{StaticResource SmallButton}" Content="Remove selected"/>
    <CheckBox x:Name="${Prefix}RevealBox" Content="Show secret values" VerticalAlignment="Center" Margin="8,0,0,0"/>
  </WrapPanel>
  <DataGrid x:Name="${Prefix}Grid" AutoGenerateColumns="False" CanUserAddRows="False" HeadersVisibility="Column" GridLinesVisibility="Horizontal" Background="Transparent" RowBackground="Transparent" SelectionMode="Extended" MinHeight="120">
    <DataGrid.Columns>
      <DataGridTextColumn Header="Name" Binding="{Binding Name, UpdateSourceTrigger=PropertyChanged}" Width="200"/>
      <DataGridTemplateColumn Header="Value" Width="*">
        <DataGridTemplateColumn.CellTemplate><DataTemplate><TextBlock Text="{Binding DisplayValue}" Margin="4,0" VerticalAlignment="Center" TextTrimming="CharacterEllipsis"/></DataTemplate></DataGridTemplateColumn.CellTemplate>
        <DataGridTemplateColumn.CellEditingTemplate><DataTemplate><TextBox Text="{Binding Value, UpdateSourceTrigger=PropertyChanged}" BorderThickness="0" Padding="2,0"/></DataTemplate></DataGridTemplateColumn.CellEditingTemplate>
      </DataGridTemplateColumn>
      <DataGridCheckBoxColumn Header="Secret" Binding="{Binding IsSecret, UpdateSourceTrigger=PropertyChanged}" Width="70"/>
    </DataGrid.Columns>
  </DataGrid>
</DockPanel>
"@
}

function New-VariableRows {
    param($Variables, [string[]]$SecretNames = @())
    $rows = New-Object 'System.Collections.ObjectModel.ObservableCollection[VariableRow]'
    $pairs = if ($Variables -is [System.Collections.IDictionary]) { @($Variables.GetEnumerator() | Sort-Object Name | ForEach-Object { @{ Name = [string]$_.Name; Value = [string]$_.Value } }) }
             elseif ($Variables) { @($Variables.PSObject.Properties | ForEach-Object { @{ Name = $_.Name; Value = [string]$_.Value } }) } else { @() }
    foreach ($pair in $pairs) {
        $row = New-Object VariableRow
        $row.Name = $pair.Name; $row.Value = $pair.Value; $row.IsSecret = (@($SecretNames) -contains $pair.Name)
        $rows.Add($row)
    }
    return ,$rows
}

function ConvertFrom-VariableRows {
    param($Rows)
    $variables = @{}; $secretNames = New-Object System.Collections.Generic.List[string]
    foreach ($row in @($Rows)) {
        if ([string]::IsNullOrWhiteSpace($row.Name)) { continue }
        $variables[$row.Name.Trim()] = [string]$row.Value
        if ($row.IsSecret) { $secretNames.Add($row.Name.Trim()) }
    }
    return @{ Variables = $variables; SecretNames = @($secretNames) }
}

# Wires the add / remove / reveal buttons of a variables grid.
function Register-VariablesGrid {
    param($Controls, [string]$Prefix)
    $grid = $Controls["${Prefix}Grid"]
    $Controls["${Prefix}AddButton"].Tag = $grid
    $Controls["${Prefix}AddButton"].Add_Click({ param($sender) $row = New-Object VariableRow; $row.Name = 'name'; $row.Value = ''; $sender.Tag.ItemsSource.Add($row); $sender.Tag.SelectedItem = $row })
    $Controls["${Prefix}RemoveButton"].Tag = $grid
    $Controls["${Prefix}RemoveButton"].Add_Click({ param($sender) foreach ($row in @($sender.Tag.SelectedItems)) { [void]$sender.Tag.ItemsSource.Remove($row) } })
    $Controls["${Prefix}RevealBox"].Tag = $grid
    $Controls["${Prefix}RevealBox"].Add_Click({ param($sender) foreach ($row in @($sender.Tag.ItemsSource)) { $row.Reveal = [bool]$sender.IsChecked } })
}

# Edits a table of variables with optional secret flags. Returns @{ Variables; SecretNames } or $null when cancelled.
function Show-VariablesDialog {
    param([string]$Title = 'Variables', $Variables = @{}, [string[]]$SecretNames = @())
    $body = @"
  <Grid Margin="22,18,22,18">
    <Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="*"/><RowDefinition Height="Auto"/><RowDefinition Height="Auto"/></Grid.RowDefinitions>
    <TextBlock x:Name="TitleText" FontSize="20" FontWeight="SemiBold" Foreground="{StaticResource Primary}" Margin="0,0,0,10"/>
    <Grid Grid.Row="1">$(Get-VariablesGridXaml -Prefix 'Vars')</Grid>
    <TextBlock Grid.Row="2" Margin="0,8,0,0" Foreground="{StaticResource Muted}" TextWrapping="Wrap" Text="Use a variable as {{name}}. Secret values are masked here, encrypted on disk and left out of exports."/>
    <StackPanel Grid.Row="3" Orientation="Horizontal" HorizontalAlignment="Right" Margin="0,14,0,0">
      <Button x:Name="OkButton" Style="{StaticResource PrimaryButton}" IsDefault="True" Width="90" Content="Save"/>
      <Button x:Name="CancelButton" IsCancel="True" Width="90" Margin="10,0,0,0" Content="Cancel"/>
    </StackPanel>
  </Grid>
"@
    $dialog = New-DialogWindow -BodyXaml $body -ControlNames 'TitleText', 'VarsAddButton', 'VarsRemoveButton', 'VarsRevealBox', 'VarsGrid', 'OkButton', 'CancelButton' -Title $Title -Width 720 -Height 520
    $controls = $dialog.Controls; $window = $dialog.Window
    $controls['TitleText'].Text = $Title
    $controls['VarsGrid'].ItemsSource = New-VariableRows -Variables $Variables -SecretNames $SecretNames
    Register-VariablesGrid -Controls $controls -Prefix 'Vars'
    $script:variablesDialogResult = $null
    $controls['OkButton'].Add_Click({
        [void]$controls['VarsGrid'].CommitEdit([System.Windows.Controls.DataGridEditingUnit]::Row, $true)
        $script:variablesDialogResult = ConvertFrom-VariableRows -Rows $controls['VarsGrid'].ItemsSource
        $window.DialogResult = $true
    })
    [void](Show-WpfDialog -Window $window -OwnerForm (Get-MainWindow))
    return $script:variablesDialogResult
}

# ------------------------------------------------------------------------------------------------
# Folder / collection settings: auth, headers and scripts inherited by the requests inside
# ------------------------------------------------------------------------------------------------

function Show-ContainerSettingsDialog {
    param($Item)
    $body = @'
  <Grid Margin="20,16,20,16">
    <Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="Auto"/><RowDefinition Height="*"/><RowDefinition Height="Auto"/></Grid.RowDefinitions>
    <TextBlock x:Name="TitleText" FontSize="20" FontWeight="SemiBold" Foreground="{StaticResource Primary}"/>
    <TextBlock Grid.Row="1" Margin="0,2,0,10" Foreground="{StaticResource Muted}" TextWrapping="Wrap" Text="Requests inside inherit these settings: auth when their Auth type is 'Inherit', headers are added (the request wins on the same name), and scripts run collection -> folder -> request."/>
    <TabControl Grid.Row="2" Background="{StaticResource Surface}" BorderBrush="{StaticResource Border}">
      <TabItem Header="Auth"><StackPanel Margin="12">
        <ComboBox x:Name="CsAuthTypeBox" Width="220" Height="30" HorizontalAlignment="Left" VerticalContentAlignment="Center" Margin="0,0,0,10"/>
        <WrapPanel>
          <StackPanel x:Name="CsField1Panel" Margin="0,0,12,8"><TextBlock x:Name="CsLabel1" Style="{StaticResource SectionLabel}"/><TextBox x:Name="CsField1Box" Width="280" Height="28" Margin="0,4,0,0" VerticalContentAlignment="Center"/></StackPanel>
          <StackPanel x:Name="CsField2Panel" Margin="0,0,12,8"><TextBlock x:Name="CsLabel2" Style="{StaticResource SectionLabel}"/><TextBox x:Name="CsField2Box" Width="280" Height="28" Margin="0,4,0,0" VerticalContentAlignment="Center"/></StackPanel>
          <StackPanel x:Name="CsField3Panel" Margin="0,0,12,8"><TextBlock x:Name="CsLabel3" Style="{StaticResource SectionLabel}"/><ComboBox x:Name="CsAddToBox" Width="170" Height="28" Margin="0,4,0,0" VerticalContentAlignment="Center"/></StackPanel>
        </WrapPanel>
      </StackPanel></TabItem>
      <TabItem Header="Headers"><TextBox x:Name="CsHeadersBox" Margin="10" AcceptsReturn="True" FontFamily="Consolas" VerticalScrollBarVisibility="Auto" ToolTip="Name: value, one per line"/></TabItem>
      <TabItem Header="Pre-request"><TextBox x:Name="CsPreRequestBox" Margin="10" AcceptsReturn="True" AcceptsTab="True" FontFamily="Consolas" VerticalScrollBarVisibility="Auto"/></TabItem>
      <TabItem Header="Tests"><TextBox x:Name="CsTestsBox" Margin="10" AcceptsReturn="True" AcceptsTab="True" FontFamily="Consolas" VerticalScrollBarVisibility="Auto"/></TabItem>
    </TabControl>
    <StackPanel Grid.Row="3" Orientation="Horizontal" HorizontalAlignment="Right" Margin="0,14,0,0">
      <Button x:Name="OkButton" Style="{StaticResource PrimaryButton}" Width="90" Content="Save"/>
      <Button x:Name="CancelButton" IsCancel="True" Width="90" Margin="10,0,0,0" Content="Cancel"/>
    </StackPanel>
  </Grid>
'@
    $names = 'TitleText', 'CsAuthTypeBox', 'CsField1Panel', 'CsLabel1', 'CsField1Box', 'CsField2Panel', 'CsLabel2', 'CsField2Box', 'CsField3Panel', 'CsLabel3', 'CsAddToBox', 'CsHeadersBox', 'CsPreRequestBox', 'CsTestsBox', 'OkButton', 'CancelButton'
    $dialog = New-DialogWindow -BodyXaml $body -ControlNames $names -Title "Settings - $($Item.Name)" -Width 760 -Height 600
    $controls = $dialog.Controls; $window = $dialog.Window
    $controls['TitleText'].Text = "$($Item.Type) settings - $($Item.Name)"
    foreach ($type in @('Inherit', 'No Auth', 'API Key', 'Bearer Token', 'Basic Auth')) { [void]$controls['CsAuthTypeBox'].Items.Add($type) }
    foreach ($location in @('Header', 'Query Parameter')) { [void]$controls['CsAddToBox'].Items.Add($location) }
    $auth = Get-ObjectProperty $Item 'Auth' $null
    $authType = [string](Get-ObjectProperty $auth 'Type' 'Inherit')
    $controls['CsAuthTypeBox'].SelectedItem = if ($controls['CsAuthTypeBox'].Items.Contains($authType)) { $authType } else { 'Inherit' }
    $updateFields = {
        $labels = switch ([string]$controls['CsAuthTypeBox'].SelectedItem) { 'API Key' { @('KEY NAME', 'VALUE', 'ADD TO') } 'Bearer Token' { @('TOKEN', '', '') } 'Basic Auth' { @('USERNAME', 'PASSWORD', '') } default { @('', '', '') } }
        $controls['CsLabel1'].Text = $labels[0]; $controls['CsLabel2'].Text = $labels[1]; $controls['CsLabel3'].Text = $labels[2]
        $controls['CsField1Panel'].Visibility = if ($labels[0]) { 'Visible' } else { 'Collapsed' }
        $controls['CsField2Panel'].Visibility = if ($labels[1]) { 'Visible' } else { 'Collapsed' }
        $controls['CsField3Panel'].Visibility = if ($labels[2]) { 'Visible' } else { 'Collapsed' }
    }
    $controls['CsAuthTypeBox'].Add_SelectionChanged($updateFields)
    & $updateFields
    switch ($authType) {
        'API Key'      { $controls['CsField1Box'].Text = [string](Get-ObjectProperty $auth 'Key' ''); $controls['CsField2Box'].Text = [string](Get-ObjectProperty $auth 'Value' ''); $controls['CsAddToBox'].SelectedItem = [string](Get-ObjectProperty $auth 'AddTo' 'Header') }
        'Bearer Token' { $controls['CsField1Box'].Text = [string](Get-ObjectProperty $auth 'Token' '') }
        'Basic Auth'   { $controls['CsField1Box'].Text = [string](Get-ObjectProperty $auth 'Username' ''); $controls['CsField2Box'].Text = [string](Get-ObjectProperty $auth 'Password' '') }
    }
    if (-not $controls['CsAddToBox'].SelectedItem) { $controls['CsAddToBox'].SelectedIndex = 0 }
    $controls['CsHeadersBox'].Text = [string](Get-ObjectProperty $Item 'Headers' '')
    $controls['CsPreRequestBox'].Text = [string](Get-ObjectProperty $Item 'PreRequestScript' '')
    $controls['CsTestsBox'].Text = [string](Get-ObjectProperty $Item 'Tests' '')
    $script:containerSettingsSaved = $false
    $controls['OkButton'].Add_Click({
        $type = [string]$controls['CsAuthTypeBox'].SelectedItem
        $newAuth = @{ Type = $type }
        switch ($type) {
            'API Key'      { $newAuth.Key = $controls['CsField1Box'].Text; $newAuth.Value = $controls['CsField2Box'].Text; $newAuth.AddTo = [string]$controls['CsAddToBox'].SelectedItem }
            'Bearer Token' { $newAuth.Token = $controls['CsField1Box'].Text }
            'Basic Auth'   { $newAuth.Username = $controls['CsField1Box'].Text; $newAuth.Password = $controls['CsField2Box'].Text }
        }
        Set-ObjectProperty -Object $Item -Name 'Auth' -Value $(if ($type -eq 'Inherit') { $null } else { $newAuth })
        Set-ObjectProperty -Object $Item -Name 'Headers' -Value $controls['CsHeadersBox'].Text
        Set-ObjectProperty -Object $Item -Name 'PreRequestScript' -Value $controls['CsPreRequestBox'].Text
        Set-ObjectProperty -Object $Item -Name 'Tests' -Value $controls['CsTestsBox'].Text
        $script:containerSettingsSaved = $true
        $window.DialogResult = $true
    })
    [void](Show-WpfDialog -Window $window -OwnerForm (Get-MainWindow))
    return $script:containerSettingsSaved
}

# ------------------------------------------------------------------------------------------------
# Choose a collection / folder to save into
# ------------------------------------------------------------------------------------------------

function Get-ContainerChoices {
    param($Items, $Root, [string]$Prefix = '')
    foreach ($item in @($Items)) {
        if (-not $item -or $item.Type -notin @('Collection', 'Folder')) { continue }
        $rootItem = if ($Root) { $Root } else { $item }
        [PSCustomObject]@{ Label = "$Prefix$($item.Name)"; Container = $item; Root = $rootItem }
        Get-ContainerChoices -Items $item.Items -Root $rootItem -Prefix "$Prefix    "
    }
}

# Returns @{ Container; Root } for the chosen destination (creating a new collection if asked), or $null.
function Show-ChooseContainerDialog {
    $choices = @(Get-ContainerChoices -Items $script:collections -Root $null)
    if ($choices.Count -eq 0) {
        $name = Show-InputBox -Prompt 'There are no collections yet. Name for a new collection:' -Title 'Save Request' -DefaultText 'My Collection'
        if ([string]::IsNullOrWhiteSpace($name)) { return $null }
        $collection = [PSCustomObject]@{ Name = $name.Trim(); Type = 'Collection'; Items = @(); Variables = @{} }
        $script:collections = @($script:collections) + $collection
        return @{ Container = $collection; Root = $collection }
    }
    $body = @'
  <Grid Margin="22,18,22,18">
    <Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="*"/><RowDefinition Height="Auto"/></Grid.RowDefinitions>
    <TextBlock Text="Save to..." FontSize="20" FontWeight="SemiBold" Foreground="{StaticResource Primary}"/>
    <ListBox x:Name="ChoiceList" Grid.Row="1" Margin="0,12,0,0"/>
    <StackPanel Grid.Row="2" Orientation="Horizontal" HorizontalAlignment="Right" Margin="0,14,0,0">
      <Button x:Name="OkButton" Style="{StaticResource PrimaryButton}" IsDefault="True" Width="90" Content="Select"/>
      <Button x:Name="CancelButton" IsCancel="True" Width="90" Margin="10,0,0,0" Content="Cancel"/>
    </StackPanel>
  </Grid>
'@
    $dialog = New-DialogWindow -BodyXaml $body -ControlNames 'ChoiceList', 'OkButton', 'CancelButton' -Title 'Save Request' -Width 460 -Height 420
    $window = $dialog.Window; $controls = $dialog.Controls
    foreach ($choice in $choices) {
        $listItem = New-Object System.Windows.Controls.ListBoxItem
        $listItem.Content = $choice.Label; $listItem.Tag = $choice
        [void]$controls['ChoiceList'].Items.Add($listItem)
    }
    $controls['ChoiceList'].SelectedIndex = 0
    $script:chooseContainerResult = $null
    $accept = { if ($controls['ChoiceList'].SelectedItem) { $script:chooseContainerResult = $controls['ChoiceList'].SelectedItem.Tag; $window.DialogResult = $true } }
    $controls['OkButton'].Add_Click($accept)
    $controls['ChoiceList'].Add_MouseDoubleClick($accept)
    [void](Show-WpfDialog -Window $window -OwnerForm (Get-MainWindow))
    return $script:chooseContainerResult
}

# ------------------------------------------------------------------------------------------------
# Request templates
# ------------------------------------------------------------------------------------------------

function Show-RequestTemplatesDialog {
    $body = @'
  <Grid Margin="22,18,22,18">
    <Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="*"/><RowDefinition Height="Auto"/></Grid.RowDefinitions>
    <TextBlock Text="Request Templates" FontSize="20" FontWeight="SemiBold" Foreground="{StaticResource Primary}"/>
    <ListBox x:Name="TemplateList" Grid.Row="1" Margin="0,12,0,0"/>
    <WrapPanel Grid.Row="2" Margin="0,14,0,0">
      <Button x:Name="SaveTemplateButton" Style="{StaticResource PrimaryButton}" Margin="0,0,8,0" Content="Save current as template..."/>
      <Button x:Name="LoadTemplateButton" Margin="0,0,8,0" Content="Load"/>
      <Button x:Name="NewTabTemplateButton" Margin="0,0,8,0" Content="Open in new tab"/>
      <Button x:Name="DeleteTemplateButton" Margin="0,0,8,0" Content="Delete"/>
      <Button x:Name="CloseButton" IsCancel="True" Content="Close"/>
    </WrapPanel>
  </Grid>
'@
    $dialog = New-DialogWindow -BodyXaml $body -ControlNames 'TemplateList', 'SaveTemplateButton', 'LoadTemplateButton', 'NewTabTemplateButton', 'DeleteTemplateButton', 'CloseButton' -Title 'Request Templates' -Width 620 -Height 460
    $window = $dialog.Window; $controls = $dialog.Controls
    $refresh = {
        $controls['TemplateList'].Items.Clear()
        foreach ($template in @($script:requestTemplates)) {
            $item = New-Object System.Windows.Controls.ListBoxItem
            $item.Content = "$($template.Name)    -    $($template.Method) $($template.Url)"
            $item.Tag = $template
            [void]$controls['TemplateList'].Items.Add($item)
        }
    }
    & $refresh
    $controls['SaveTemplateButton'].Add_Click({
        $name = Show-InputBox -Prompt 'Template name:' -Title 'Save template' -DefaultText 'My template'
        if ([string]::IsNullOrWhiteSpace($name)) { return }
        $template = Get-EditorState
        $template.Id = [guid]::NewGuid().ToString()
        $template.Name = $name.Trim()
        $script:requestTemplates = @($script:requestTemplates) + $template
        Save-RequestTemplates
        & $refresh
    })
    $controls['LoadTemplateButton'].Add_Click({
        $selected = $controls['TemplateList'].SelectedItem
        if ($selected) { Open-RequestState -Data $selected.Tag -Name ([string]$selected.Tag.Name); $window.Close() }
    })
    $controls['NewTabTemplateButton'].Add_Click({
        $selected = $controls['TemplateList'].SelectedItem
        if ($selected) { Open-RequestState -Data $selected.Tag -Name ([string]$selected.Tag.Name) -NewTab; $window.Close() }
    })
    $controls['DeleteTemplateButton'].Add_Click({
        $selected = $controls['TemplateList'].SelectedItem
        if (-not $selected) { return }
        $target = $selected.Tag
        $script:requestTemplates = @($script:requestTemplates | Where-Object { $_ -ne $target })
        Save-RequestTemplates
        & $refresh
    })
    [void](Show-WpfDialog -Window $window -OwnerForm (Get-MainWindow))
}

# ------------------------------------------------------------------------------------------------
# Environment manager
# ------------------------------------------------------------------------------------------------

function Show-EnvironmentManager {
    $body = @'
  <Grid Margin="22,18,22,18">
    <Grid.ColumnDefinitions><ColumnDefinition Width="210"/><ColumnDefinition Width="16"/><ColumnDefinition Width="*"/></Grid.ColumnDefinitions>
    <Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="*"/><RowDefinition Height="Auto"/></Grid.RowDefinitions>
    <TextBlock Grid.ColumnSpan="3" Text="Manage Environments" FontSize="20" FontWeight="SemiBold" Foreground="{StaticResource Primary}" Margin="0,0,0,12"/>
    <Grid Grid.Row="1">
      <Grid.RowDefinitions><RowDefinition Height="*"/><RowDefinition Height="Auto"/></Grid.RowDefinitions>
      <ListBox x:Name="EnvironmentList"/>
      <WrapPanel Grid.Row="1" Margin="0,8,0,0">
        <Button x:Name="AddEnvironmentButton" Style="{StaticResource SmallButton}" Content="Add..."/>
        <Button x:Name="SaveCurrentButton" Style="{StaticResource SmallButton}" Content="Save current..." ToolTip="Create an environment from the request in the editor"/>
        <Button x:Name="RemoveEnvironmentButton" Style="{StaticResource SmallButton}" Content="Remove"/>
      </WrapPanel>
    </Grid>
    <ScrollViewer Grid.Row="1" Grid.Column="2" VerticalScrollBarVisibility="Auto">
      <StackPanel x:Name="EditorPanel" IsEnabled="False">
        <TextBlock Style="{StaticResource SectionLabel}" Text="URL"/>
        <TextBox x:Name="EnvUrlBox" Margin="0,4,0,10" Height="28" VerticalContentAlignment="Center"/>
        <TextBlock Style="{StaticResource SectionLabel}" Text="HEADERS (Name: value, one per line)"/>
        <TextBox x:Name="EnvHeadersBox" Margin="0,4,0,10" Height="70" AcceptsReturn="True" FontFamily="Consolas" VerticalScrollBarVisibility="Auto"/>
        <TextBlock Style="{StaticResource SectionLabel}" Text="VARIABLES"/>
        <Grid Margin="0,4,0,10" Height="190">@@ENVVARS@@</Grid>
        <TextBlock Style="{StaticResource SectionLabel}" Text="AUTHENTICATION"/>
        <ComboBox x:Name="EnvAuthTypeBox" Margin="0,4,0,8" Width="200" HorizontalAlignment="Left" Height="28" VerticalContentAlignment="Center"/>
        <Grid x:Name="EnvAuthFields">
          <Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="10"/><ColumnDefinition Width="*"/></Grid.ColumnDefinitions>
          <Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="Auto"/></Grid.RowDefinitions>
          <StackPanel x:Name="EnvAuthField1Panel"><TextBlock x:Name="EnvAuthLabel1" Style="{StaticResource SectionLabel}"/><TextBox x:Name="EnvAuthField1Box" Margin="0,4,0,8" Height="28" VerticalContentAlignment="Center"/></StackPanel>
          <StackPanel x:Name="EnvAuthField2Panel" Grid.Column="2"><TextBlock x:Name="EnvAuthLabel2" Style="{StaticResource SectionLabel}"/><TextBox x:Name="EnvAuthField2Box" Margin="0,4,0,8" Height="28" VerticalContentAlignment="Center"/></StackPanel>
          <StackPanel x:Name="EnvAuthField3Panel" Grid.Row="1"><TextBlock x:Name="EnvAuthLabel3" Style="{StaticResource SectionLabel}"/><ComboBox x:Name="EnvAuthAddToBox" Margin="0,4,0,8" Height="28" VerticalContentAlignment="Center"/></StackPanel>
        </Grid>
        <TextBlock x:Name="EnvAuthNote" Foreground="{StaticResource Muted}" TextWrapping="Wrap"/>
      </StackPanel>
    </ScrollViewer>
    <StackPanel Grid.Row="2" Grid.ColumnSpan="3" Orientation="Horizontal" HorizontalAlignment="Right" Margin="0,14,0,0">
      <TextBlock x:Name="EnvStatusText" VerticalAlignment="Center" Margin="0,0,14,0" Foreground="{StaticResource Muted}"/>
      <Button x:Name="ApplyButton" Style="{StaticResource PrimaryButton}" Width="100" Content="Save"/>
      <Button x:Name="CloseButton" IsCancel="True" Width="90" Margin="10,0,0,0" Content="Close"/>
    </StackPanel>
  </Grid>
'@
    $names = 'EnvironmentList', 'AddEnvironmentButton', 'SaveCurrentButton', 'RemoveEnvironmentButton', 'EditorPanel', 'EnvUrlBox', 'EnvHeadersBox', 'EnvVarsAddButton', 'EnvVarsRemoveButton', 'EnvVarsRevealBox', 'EnvVarsGrid', 'EnvAuthTypeBox',
        'EnvAuthFields', 'EnvAuthField1Panel', 'EnvAuthLabel1', 'EnvAuthField1Box', 'EnvAuthField2Panel', 'EnvAuthLabel2', 'EnvAuthField2Box', 'EnvAuthField3Panel', 'EnvAuthLabel3', 'EnvAuthAddToBox',
        'EnvAuthNote', 'EnvStatusText', 'ApplyButton', 'CloseButton'
    $body = $body.Replace('@@ENVVARS@@', (Get-VariablesGridXaml -Prefix 'EnvVars'))
    $dialog = New-DialogWindow -BodyXaml $body -ControlNames $names -Title 'Manage Environments' -Width 900 -Height 720
    $window = $dialog.Window; $controls = $dialog.Controls

    foreach ($authType in @('No Auth', 'API Key', 'Bearer Token', 'Basic Auth', 'Auth2', 'Client Certificate')) { [void]$controls['EnvAuthTypeBox'].Items.Add($authType) }
    foreach ($location in @('Header', 'Query Parameter')) { [void]$controls['EnvAuthAddToBox'].Items.Add($location) }
    $script:envEditing = $null     # name of the environment shown in the editor
    $script:envAuthExtras = @{}    # auth values this simple editor does not expose (OAuth / certificate fields) are preserved

    $refreshList = {
        $controls['EnvironmentList'].Items.Clear()
        foreach ($name in @($script:environments.Keys | Sort-Object)) { [void]$controls['EnvironmentList'].Items.Add($name) }
    }
    $updateAuthFields = {
        $type = [string]$controls['EnvAuthTypeBox'].SelectedItem
        $labels = switch ($type) {
            'API Key'      { @('KEY NAME', 'VALUE', 'ADD TO') }
            'Bearer Token' { @('TOKEN', '', '') }
            'Basic Auth'   { @('USERNAME', 'PASSWORD', '') }
            default        { @('', '', '') }
        }
        $controls['EnvAuthLabel1'].Text = $labels[0]; $controls['EnvAuthLabel2'].Text = $labels[1]; $controls['EnvAuthLabel3'].Text = $labels[2]
        $controls['EnvAuthField1Panel'].Visibility = if ($labels[0]) { 'Visible' } else { 'Collapsed' }
        $controls['EnvAuthField2Panel'].Visibility = if ($labels[1]) { 'Visible' } else { 'Collapsed' }
        $controls['EnvAuthField3Panel'].Visibility = if ($labels[2]) { 'Visible' } else { 'Collapsed' }
        $controls['EnvAuthNote'].Text = if ($type -in @('Auth2', 'Client Certificate')) { "$type settings are kept as they are. Edit them on the request's Auth tab and use 'Save current...'." } else { '' }
    }
    $controls['EnvAuthTypeBox'].Add_SelectionChanged($updateAuthFields)

    $loadIntoEditor = {
        param([string]$Name)
        $script:envEditing = $Name
        if (-not $Name -or -not $script:environments.ContainsKey($Name)) { $controls['EditorPanel'].IsEnabled = $false; return }
        $data = $script:environments[$Name]
        $controls['EditorPanel'].IsEnabled = $true
        $controls['EnvUrlBox'].Text = [string](Get-ObjectProperty $data 'Url' '')
        $controls['EnvHeadersBox'].Text = [string](Get-ObjectProperty $data 'Headers' '')
        $controls['EnvVarsGrid'].ItemsSource = New-VariableRows -Variables (Get-ObjectProperty $data 'Variables' @{}) -SecretNames (Get-SecretNames $data)
        $controls['EnvVarsRevealBox'].IsChecked = $false
        $auth = Get-ObjectProperty $data 'Authentication' @{ Type = 'No Auth' }
        $type = [string](Get-ObjectProperty $auth 'Type' 'No Auth')
        if (-not $controls['EnvAuthTypeBox'].Items.Contains($type)) { $type = 'No Auth' }
        $script:envAuthExtras = @{}
        if ($auth -is [hashtable]) { foreach ($key in $auth.Keys) { $script:envAuthExtras[$key] = $auth[$key] } } elseif ($auth) { foreach ($property in $auth.PSObject.Properties) { $script:envAuthExtras[$property.Name] = $property.Value } }
        $controls['EnvAuthTypeBox'].SelectedItem = $type
        & $updateAuthFields
        switch ($type) {
            'API Key'      { $controls['EnvAuthField1Box'].Text = [string]$script:envAuthExtras['Key']; $controls['EnvAuthField2Box'].Text = [string]$script:envAuthExtras['Value']; $controls['EnvAuthAddToBox'].SelectedItem = if ($script:envAuthExtras['AddTo']) { [string]$script:envAuthExtras['AddTo'] } else { 'Header' } }
            'Bearer Token' { $controls['EnvAuthField1Box'].Text = [string]$script:envAuthExtras['Token']; $controls['EnvAuthField2Box'].Text = '' }
            'Basic Auth'   { $controls['EnvAuthField1Box'].Text = [string]$script:envAuthExtras['Username']; $controls['EnvAuthField2Box'].Text = [string]$script:envAuthExtras['Password'] }
            default        { $controls['EnvAuthField1Box'].Text = ''; $controls['EnvAuthField2Box'].Text = '' }
        }
        $controls['EnvStatusText'].Text = ''
    }

    $collectFromEditor = {
        [void]$controls['EnvVarsGrid'].CommitEdit([System.Windows.Controls.DataGridEditingUnit]::Row, $true)
        $variableData = ConvertFrom-VariableRows -Rows $controls['EnvVarsGrid'].ItemsSource
        $variables = $variableData.Variables
        $type = [string]$controls['EnvAuthTypeBox'].SelectedItem
        $auth = @{ Type = $type }
        switch ($type) {
            'API Key'      { $auth.Key = $controls['EnvAuthField1Box'].Text; $auth.Value = $controls['EnvAuthField2Box'].Text; $auth.AddTo = [string]$controls['EnvAuthAddToBox'].SelectedItem }
            'Bearer Token' { $auth.Token = $controls['EnvAuthField1Box'].Text }
            'Basic Auth'   { $auth.Username = $controls['EnvAuthField1Box'].Text; $auth.Password = $controls['EnvAuthField2Box'].Text }
            { $_ -in @('Auth2', 'Client Certificate') } { foreach ($key in $script:envAuthExtras.Keys) { $auth[$key] = $script:envAuthExtras[$key] }; $auth.Type = $type }
        }
        return @{ Url = $controls['EnvUrlBox'].Text; Headers = $controls['EnvHeadersBox'].Text; Authentication = $auth; Variables = $variables; SecretVariables = @($variableData.SecretNames) }
    }

    Register-VariablesGrid -Controls $controls -Prefix 'EnvVars'
    & $refreshList
    $controls['EnvironmentList'].Add_SelectionChanged({ & $loadIntoEditor ([string]$controls['EnvironmentList'].SelectedItem) })

    $controls['AddEnvironmentButton'].Add_Click({
        $name = Show-InputBox -Prompt 'Environment name:' -Title 'Add environment' -DefaultText 'New Environment'
        if ([string]::IsNullOrWhiteSpace($name)) { return }
        $name = $name.Trim()
        if ($script:environments.ContainsKey($name)) { $controls['EnvStatusText'].Text = "'$name' already exists."; return }
        $script:environments[$name] = @{ Url = ''; Headers = ''; Authentication = @{ Type = 'No Auth' }; Variables = @{} }
        Save-Environments; & $refreshList; Update-EnvironmentChoices; Update-HistoryEnvironmentChoices
        $controls['EnvironmentList'].SelectedItem = $name
    })
    $controls['SaveCurrentButton'].Add_Click({
        $name = Show-InputBox -Prompt 'Name for the new environment:' -Title 'Save current request as environment' -DefaultText 'My Environment'
        if ([string]::IsNullOrWhiteSpace($name)) { return }
        $name = $name.Trim()
        if ($script:environments.ContainsKey($name)) { $controls['EnvStatusText'].Text = "'$name' already exists."; return }
        $state = Get-EditorState
        $authCopy = @{}
        foreach ($property in (Copy-RequestData $state.Authentication).PSObject.Properties) { $authCopy[$property.Name] = $property.Value }
        $script:environments[$name] = @{ Url = $state.Url; Headers = $state.Headers; Authentication = $authCopy; Variables = @{} }
        Save-Environments; & $refreshList; Update-EnvironmentChoices; Update-HistoryEnvironmentChoices
        $controls['EnvironmentList'].SelectedItem = $name
    })
    $controls['RemoveEnvironmentButton'].Add_Click({
        $name = [string]$controls['EnvironmentList'].SelectedItem
        if (-not $name) { return }
        $answer = [System.Windows.MessageBox]::Show($window, "Remove the '$name' environment?", 'Confirm removal', 'YesNo', 'Warning')
        if ($answer -ne 'Yes') { return }
        $script:environments.Remove($name)
        if ($script:activeEnvironment -eq $name) { $script:activeEnvironment = 'No Environment' }
        Save-Environments; & $refreshList; & $loadIntoEditor ''; Update-EnvironmentChoices; Update-HistoryEnvironmentChoices
    })
    $controls['ApplyButton'].Add_Click({
        if (-not $script:envEditing) { return }
        $script:environments[$script:envEditing] = & $collectFromEditor
        Save-Environments
        $controls['EnvStatusText'].Text = "Saved '$($script:envEditing)'."
        Update-ExtractVariableChoices
    })
    [void](Show-WpfDialog -Window $window -OwnerForm (Get-MainWindow))
    Update-EnvironmentChoices
}

# ------------------------------------------------------------------------------------------------
# Collection runner
# ------------------------------------------------------------------------------------------------

function Get-RequestsFromItem {
    param($Item, [string]$Path = '')
    foreach ($child in @($Item.Items)) {
        if (-not $child) { continue }
        if ($child.Type -eq 'Request') { [PSCustomObject]@{ Item = $child; Path = $Path } }
        elseif ($child.Type -eq 'Folder') { Get-RequestsFromItem -Item $child -Path "$Path$($child.Name) / " }
    }
}

function Import-RunnerDataFile {
    param([string]$Path)
    if ($Path -match '\.csv$') { return @(Import-Csv -Path $Path) }
    $json = Get-Content -Path $Path -Raw | ConvertFrom-Json
    return @($json)
}

function Show-CollectionRunner {
    param($Item, $Root)

    $body = @'
  <Grid Margin="18,14,18,14">
    <Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="Auto"/><RowDefinition Height="Auto"/><RowDefinition Height="*"/><RowDefinition Height="Auto"/></Grid.RowDefinitions>
    <TextBlock x:Name="RunnerTitle" FontSize="20" FontWeight="SemiBold" Foreground="{StaticResource Primary}"/>
    <WrapPanel Grid.Row="1" Margin="0,10,0,0">
      <TextBlock Text="Delay (ms)" VerticalAlignment="Center" Margin="0,0,6,0"/>
      <TextBox x:Name="DelayBox" Width="70" Height="26" VerticalContentAlignment="Center" Text="0"/>
      <TextBlock Text="Parallel" VerticalAlignment="Center" Margin="16,0,6,0"/>
      <TextBox x:Name="ParallelBox" Width="44" Height="26" VerticalContentAlignment="Center" ToolTip="How many requests run at the same time (1-10)"/>
      <TextBlock Text="Retries" VerticalAlignment="Center" Margin="16,0,6,0"/>
      <TextBox x:Name="RetriesBox" Width="44" Height="26" VerticalContentAlignment="Center" ToolTip="How many times a failing request is retried before it counts as failed (0-5)"/>
      <CheckBox x:Name="StopOnFailBox" Content="Stop on failure" VerticalAlignment="Center" Margin="16,0,0,0"/>
      <CheckBox x:Name="SelectAllBox" Content="Select all" IsChecked="True" VerticalAlignment="Center" Margin="16,0,0,0"/>
      <Button x:Name="DataFileButton" Style="{StaticResource SmallButton}" Margin="16,0,6,0" Content="Data file..."/>
      <TextBox x:Name="DataFileBox" Width="220" Height="26" IsReadOnly="True" VerticalContentAlignment="Center" ToolTip="CSV or JSON. Each row is one iteration; use {{column}} in your requests."/>
      <Button x:Name="ClearDataFileButton" Style="{StaticResource SmallButton}" Margin="6,0,0,0" Content="Clear"/>
    </WrapPanel>
    <StackPanel Grid.Row="2" Margin="0,10,0,8">
      <TextBlock x:Name="SummaryText" Text="Ready to run." Margin="0,0,0,4"/>
      <ProgressBar x:Name="RunProgress" Height="10" Minimum="0" Maximum="1" Value="0"/>
    </StackPanel>
    <DataGrid x:Name="RunnerGrid" Grid.Row="3" AutoGenerateColumns="False" CanUserAddRows="False" HeadersVisibility="Column" SelectionMode="Extended" GridLinesVisibility="Horizontal" Background="Transparent" RowBackground="Transparent" IsReadOnly="False">
      <DataGrid.RowStyle>
        <Style TargetType="DataGridRow">
          <Style.Triggers>
            <DataTrigger Binding="{Binding Status}" Value="PASS"><Setter Property="Background" Value="#DDF3E4"/><Setter Property="Foreground" Value="#14532D"/></DataTrigger>
            <DataTrigger Binding="{Binding Status}" Value="FAIL"><Setter Property="Background" Value="#F8D7DA"/><Setter Property="Foreground" Value="#7F1D1D"/></DataTrigger>
            <DataTrigger Binding="{Binding Status}" Value="ERROR"><Setter Property="Background" Value="#F8D7DA"/><Setter Property="Foreground" Value="#7F1D1D"/></DataTrigger>
            <DataTrigger Binding="{Binding Status}" Value="Running..."><Setter Property="Background" Value="#FFF3CD"/><Setter Property="Foreground" Value="#7A5B00"/></DataTrigger>
          </Style.Triggers>
        </Style>
      </DataGrid.RowStyle>
      <DataGrid.Columns>
        <DataGridCheckBoxColumn Header="Run" Binding="{Binding Run}" Width="46"/>
        <DataGridTextColumn Header="Request" Binding="{Binding Name}" IsReadOnly="True" Width="*"/>
        <DataGridTextColumn Header="Method" Binding="{Binding Method}" IsReadOnly="True" Width="70"/>
        <DataGridTextColumn Header="Status" Binding="{Binding Status}" IsReadOnly="True" Width="80"/>
        <DataGridTextColumn Header="Result" Binding="{Binding Result}" IsReadOnly="True" Width="190"/>
        <DataGridTextColumn Header="Time (ms)" Binding="{Binding TimeMs}" IsReadOnly="True" Width="80"/>
        <DataGridTextColumn Header="Tests" Binding="{Binding Tests}" IsReadOnly="True" Width="110"/>
      </DataGrid.Columns>
    </DataGrid>
    <StackPanel Grid.Row="4" Orientation="Horizontal" HorizontalAlignment="Right" Margin="0,12,0,0">
      <Button x:Name="HtmlReportButton" Margin="0,0,8,0" Padding="14,6" Content="HTML report..."/>
      <Button x:Name="ExportCsvButton" Margin="0,0,8,0" Padding="14,6" Content="Export CSV..."/>
      <Button x:Name="RetryButton" Margin="0,0,8,0" Padding="14,6" Content="Retry failed" IsEnabled="False"/>
      <Button x:Name="StopRunButton" Margin="0,0,8,0" Padding="14,6" Content="Stop run" IsEnabled="False"/>
      <Button x:Name="StartRunButton" Style="{StaticResource PrimaryButton}" Margin="0,0,8,0" Padding="18,6" Content="Start run"/>
      <Button x:Name="CloseButton" IsCancel="True" Padding="14,6" Content="Close"/>
    </StackPanel>
  </Grid>
'@
    $names = 'RunnerTitle', 'DelayBox', 'ParallelBox', 'RetriesBox', 'StopOnFailBox', 'SelectAllBox', 'DataFileButton', 'DataFileBox', 'ClearDataFileButton', 'SummaryText', 'RunProgress', 'RunnerGrid',
        'HtmlReportButton', 'ExportCsvButton', 'RetryButton', 'StopRunButton', 'StartRunButton', 'CloseButton'
    $dialog = New-DialogWindow -BodyXaml $body -ControlNames $names -Title "Collection Runner: $($Item.Name)" -Width 1000 -Height 700
    $window = $dialog.Window; $controls = $dialog.Controls
    $controls['RunnerTitle'].Text = "Collection Runner: $($Item.Name)"
    $controls['DelayBox'].Text = [string]$(if ($script:settings.CollectionRunnerDelay) { $script:settings.CollectionRunnerDelay } else { 0 })
    $controls['StopOnFailBox'].IsChecked = [bool]$script:settings.CollectionRunnerStopOnFail
    $controls['ParallelBox'].Text = [string]$(if ([int]$script:settings.CollectionRunnerParallel -gt 0) { $script:settings.CollectionRunnerParallel } else { 1 })
    $controls['RetriesBox'].Text = [string][int]$script:settings.CollectionRunnerRetries

    $script:runnerRows = New-Object 'System.Collections.ObjectModel.ObservableCollection[RunnerRow]'
    $controls['RunnerGrid'].ItemsSource = $script:runnerRows
    $script:runner = @{ Controls = $controls; Window = $window; Root = $Root; Queue = (New-Object System.Collections.Queue); Running = $false; Stop = $false; Current = $null
        Pending = $null; Expanded = $false; CurrentRequest = $null; Total = 0; Done = 0; Passed = 0; Failed = 0; DelayUntil = [datetime]::MinValue; Delay = 0; StopOnFail = $false; Item = $Item }

    Initialize-RunnerRows
    $controls['SummaryText'].Text = "$($script:runnerRows.Count) request(s) ready to run."

    $controls['SelectAllBox'].Add_Click({ foreach ($row in $script:runnerRows) { $row.Run = [bool]$script:runner.Controls['SelectAllBox'].IsChecked } })
    $controls['DataFileButton'].Add_Click({
        $picker = New-Object Microsoft.Win32.OpenFileDialog
        $picker.Filter = 'Data files (*.csv;*.json)|*.csv;*.json|All files (*.*)|*.*'
        if ($picker.ShowDialog($script:runner.Window) -eq $true) { $script:runner.Controls['DataFileBox'].Text = $picker.FileName }
    })
    $controls['ClearDataFileButton'].Add_Click({ $script:runner.Controls['DataFileBox'].Text = '' })
    $controls['StartRunButton'].Add_Click({ Invoke-UiGuard { Start-CollectionRun } 'Start run' })
    $controls['RetryButton'].Add_Click({ Invoke-UiGuard { Start-CollectionRun -RetryFailed } 'Retry' })
    $controls['StopRunButton'].Add_Click({ $script:runner.Stop = $true; $script:runner.Controls['SummaryText'].Text = 'Stopping after the current request...' })
    $controls['ExportCsvButton'].Add_Click({ Invoke-UiGuard { Export-RunnerResults } 'Export' })
    $controls['HtmlReportButton'].Add_Click({ Invoke-UiGuard { Export-RunnerHtmlReport } 'HTML report' })

    $script:runnerTimer = New-Object System.Windows.Threading.DispatcherTimer
    $script:runnerTimer.Interval = [TimeSpan]::FromMilliseconds(100)
    $script:runnerTimer.Add_Tick({ Invoke-UiGuard { Step-CollectionRun } 'Collection run' })
    $window.Add_Closing({
        try { $script:runnerTimer.Stop() } catch { }
        foreach ($flight in @($script:runner.InFlight)) { try { $flight.State.Cancellation.Cancel() } catch { } }
        $script:iterationVariables = $null
    })
    [void](Show-WpfDialog -Window $window -OwnerForm (Get-MainWindow))
    $script:runner = $null
}

# (Re)creates one grid row per request in the collection/folder being run.
function Initialize-RunnerRows {
    $script:runnerRows.Clear()
    foreach ($entry in @(Get-RequestsFromItem -Item $script:runner.Item)) {
        $data = Get-RequestObjectFromItem -Item $entry.Item
        $row = New-Object RunnerRow
        $row.Run = $true; $row.Name = "$($entry.Path)$($entry.Item.Name)"; $row.Method = [string](Get-ObjectProperty $data 'Method' ''); $row.Url = [string](Get-ObjectProperty $data 'Url' '')
        $row.Status = ''; $row.Result = ''; $row.TimeMs = ''; $row.Tests = ''; $row.Item = $entry.Item
        $script:runnerRows.Add($row)
    }
}

function Start-CollectionRun {
    param([switch]$RetryFailed)
    $runner = $script:runner
    $controls = $runner.Controls
    if ($runner.Running) { return }

    $delay = 0; $parallel = 1; $retries = 0
    [void][int]::TryParse($controls['DelayBox'].Text, [ref]$delay)
    if (-not [int]::TryParse($controls['ParallelBox'].Text, [ref]$parallel) -or $parallel -lt 1) { $parallel = 1 }
    if (-not [int]::TryParse($controls['RetriesBox'].Text, [ref]$retries) -or $retries -lt 0) { $retries = 0 }
    $parallel = [Math]::Min($parallel, 10); $retries = [Math]::Min($retries, 5)
    $script:settings.CollectionRunnerDelay = $delay
    $script:settings.CollectionRunnerStopOnFail = [bool]$controls['StopOnFailBox'].IsChecked
    $script:settings.CollectionRunnerParallel = $parallel
    $script:settings.CollectionRunnerRetries = $retries
    Save-Settings
    $runner.Delay = $delay; $runner.Parallel = $parallel; $runner.Retries = $retries
    $runner.StopOnFail = [bool]$controls['StopOnFailBox'].IsChecked
    $runner.Queue = New-Object System.Collections.ArrayList
    $runner.InFlight = New-Object System.Collections.ArrayList
    $runner.Attempts = @{}
    $runner.Stop = $false

    if ($RetryFailed) {
        $failed = @($script:runnerRows | Where-Object { $_.Status -in @('FAIL', 'ERROR') })
        if ($failed.Count -eq 0) { $controls['SummaryText'].Text = 'No failed requests to retry.'; return }
        foreach ($row in $failed) { $row.Status = 'Queued'; $row.Result = ''; $row.TimeMs = ''; $row.Tests = ''; [void]$runner.Queue.Add($row) }
    } else {
        if ($runner.Expanded) { Initialize-RunnerRows; $runner.Expanded = $false }
        $selected = @($script:runnerRows | Where-Object { $_.Run })
        if ($selected.Count -eq 0) { $controls['SummaryText'].Text = 'Select at least one request.'; return }
        $iterations = @(@{})
        if ($controls['DataFileBox'].Text) {
            try { $dataRows = @(Import-RunnerDataFile -Path $controls['DataFileBox'].Text) } catch { $controls['SummaryText'].Text = "Could not read the data file: $($_.Exception.Message)"; return }
            if ($dataRows.Count -gt 0) { $iterations = @(foreach ($dataRow in $dataRows) { $variables = @{}; foreach ($property in $dataRow.PSObject.Properties) { $variables[$property.Name] = [string]$property.Value }; $variables }) }
        }
        $baseRows = @($selected)
        $script:runnerRows.Clear()
        $runner.Expanded = $true
        foreach ($iterationIndex in 0..($iterations.Count - 1)) {
            foreach ($baseRow in $baseRows) {
                $row = New-Object RunnerRow
                $row.Run = $true
                $row.Name = if ($iterations.Count -gt 1) { "$($baseRow.Name)  [#$($iterationIndex + 1)]" } else { $baseRow.Name }
                $row.Method = $baseRow.Method; $row.Url = $baseRow.Url; $row.Item = $baseRow.Item; $row.Variables = $iterations[$iterationIndex]
                $row.Status = 'Queued'; $row.Result = ''; $row.TimeMs = ''; $row.Tests = ''
                $script:runnerRows.Add($row)
                [void]$runner.Queue.Add($row)
            }
        }
    }

    $runner.Total = $runner.Queue.Count; $runner.Done = 0; $runner.Passed = 0; $runner.Failed = 0
    $controls['RunProgress'].Maximum = [Math]::Max(1, $runner.Total); $controls['RunProgress'].Value = 0
    $controls['SummaryText'].Text = "Running $($runner.Total) request(s)$(if ($parallel -gt 1) { ", $parallel at a time" })..."
    $controls['StartRunButton'].IsEnabled = $false; $controls['RetryButton'].IsEnabled = $false; $controls['StopRunButton'].IsEnabled = $true
    $runner.Running = $true; $runner.NextStartAt = [datetime]::MinValue
    $script:runnerTimer.Start()
}

# One tick: finish completed requests (retrying flaky ones), then start new ones up to the parallel limit.
function Step-CollectionRun {
    $runner = $script:runner
    if (-not $runner -or -not $runner.Running) { return }

    foreach ($flight in @($runner.InFlight)) {
        if (-not $flight.State.Task.IsCompleted) { continue }
        [void]$runner.InFlight.Remove($flight)
        $script:iterationVariables = $flight.Row.Variables
        $result = Get-HttpRequestResult -RequestState $flight.State
        Complete-RunnerRequest -Flight $flight -Result $result
    }

    $stopStarting = $runner.Stop -or ($runner.StopOnFail -and $runner.Failed -gt 0)
    while (-not $stopStarting -and $runner.Queue.Count -gt 0 -and $runner.InFlight.Count -lt $runner.Parallel -and [datetime]::Now -ge $runner.NextStartAt) {
        $row = $runner.Queue[0]
        $runner.Queue.RemoveAt(0)
        Start-RunnerRequest -Row $row
        if ($runner.Delay -gt 0) { $runner.NextStartAt = [datetime]::Now.AddMilliseconds($runner.Delay); break }
    }

    if ($runner.InFlight.Count -eq 0 -and ($runner.Queue.Count -eq 0 -or $stopStarting)) { Complete-CollectionRun }
}

function Start-RunnerRequest {
    param($Row)
    $runner = $script:runner
    $attempt = [int]$runner.Attempts[$Row] + 1
    $runner.Attempts[$Row] = $attempt
    $Row.Status = if ($attempt -gt 1) { "Retry $($attempt - 1)..." } else { 'Running...' }
    $script:iterationVariables = $Row.Variables
    try {
        $data = Get-RequestObjectFromItem -Item $Row.Item
        if (-not $data) { throw 'Missing request data.' }
        $request = Copy-RequestData $data
        Initialize-RequestTabDefaults -TabState $request
        $request = Resolve-InheritedRequest -Request $request -Root $runner.Root -Item $Row.Item
        if ($request.PreRequestScript -match '\S') {
            $modified = Invoke-PreRequestScript -ScriptText $request.PreRequestScript -Request $request
            $request.Method = [string]$modified.Method; $request.Url = [string]$modified.Url; $request.Headers = [string]$modified.Headers; $request.Body = [string]$modified.Body
        }
        $timeout = if ($script:settings.RequestTimeoutSeconds -gt 0) { [int]$script:settings.RequestTimeoutSeconds } else { 60 }
        $state = Start-HttpRequestFromObject -Request $request -TimeoutSeconds $timeout
        [void]$runner.InFlight.Add(@{ Row = $Row; State = $state; Request = $request })
    } catch {
        Complete-RunnerRequest -Flight @{ Row = $Row; Request = $null } -Result @{ Success = $false; ErrorMessage = $_.Exception.Message; ElapsedMs = 0 }
    }
}

function Complete-RunnerRequest {
    param($Flight, $Result)
    $runner = $script:runner
    $row = $Flight.Row
    $row.TimeMs = [string]$Result.ElapsedMs
    $status = 'PASS'
    if (-not $Result.Success) { $status = 'ERROR'; $row.Result = [string]$Result.ErrorMessage }
    else {
        $row.Result = "$($Result.StatusCode) $($Result.ReasonPhrase)".Trim()
        $testScript = if ($Flight.Request) { [string]$Flight.Request.Tests } else { '' }
        $testsPassed = $true
        if ($testScript -match '\S') {
            $testResults = @(Invoke-TestScript -ScriptText $testScript -Result $Result)
            $failedTests = @($testResults | Where-Object { $_.Status -ne 'PASS' })
            $row.Tests = "$($testResults.Count - $failedTests.Count)/$($testResults.Count) passed"
            $testsPassed = ($failedTests.Count -eq 0)
        }
        if ($Result.StatusCode -ge 400 -or -not $testsPassed) { $status = 'FAIL' }
    }
    # Flaky requests: try again (up to the Retries setting) before counting a failure.
    if ($status -ne 'PASS' -and [int]$runner.Attempts[$row] -le $runner.Retries -and -not $runner.Stop) {
        $row.Status = "Retrying ($([int]$runner.Attempts[$row])/$($runner.Retries))"
        $runner.Queue.Insert(0, $row)
        return
    }
    if ([int]$runner.Attempts[$row] -gt 1) { $row.Result = "$($row.Result)  (after $([int]$runner.Attempts[$row] - 1) retr$(if ([int]$runner.Attempts[$row] -eq 2) { 'y' } else { 'ies' }))" }
    $row.Status = $status
    $runner.Done++
    if ($status -eq 'PASS') { $runner.Passed++ } else { $runner.Failed++ }
    $runner.Controls['RunProgress'].Value = $runner.Done
}

function Complete-CollectionRun {
    $runner = $script:runner
    $script:runnerTimer.Stop()
    $runner.Running = $false
    $script:iterationVariables = $null
    foreach ($row in $script:runnerRows) { if ($row.Status -eq 'Queued' -or $row.Status -like 'Retrying*') { $row.Status = 'Skipped' } }
    $controls = $runner.Controls
    $controls['StartRunButton'].IsEnabled = $true; $controls['StopRunButton'].IsEnabled = $false
    $controls['RetryButton'].IsEnabled = ($runner.Failed -gt 0)
    $controls['SummaryText'].Text = "Finished: $($runner.Passed) passed, $($runner.Failed) failed of $($runner.Total)."
    Set-UiStatus "Collection run finished: $($runner.Passed) passed, $($runner.Failed) failed."
}

function Export-RunnerHtmlReport {
    $picker = New-Object Microsoft.Win32.SaveFileDialog
    $picker.Title = 'Save HTML report'; $picker.Filter = 'HTML report (*.html)|*.html'; $picker.FileName = "collection_run_$((Get-Date).ToString('yyyyMMdd_HHmmss')).html"
    if ($picker.ShowDialog($script:runner.Window) -ne $true) { return }
    New-RunnerReportHtml -Title "Collection run: $($script:runner.Item.Name)" -Rows @($script:runnerRows) | Set-Content -Path $picker.FileName -Encoding UTF8
    Start-Process $picker.FileName
}

function Export-RunnerResults {
    $dialog = New-Object Microsoft.Win32.SaveFileDialog
    $dialog.Title = 'Export run results'
    $dialog.Filter = 'CSV files (*.csv)|*.csv'
    $dialog.FileName = 'collection_run_results.csv'
    if ($dialog.ShowDialog($script:runner.Window) -ne $true) { return }
    $script:runnerRows | ForEach-Object { [PSCustomObject]@{ Request = $_.Name; Method = $_.Method; Url = $_.Url; Status = $_.Status; Result = $_.Result; TimeMs = $_.TimeMs; Tests = $_.Tests } } |
        Export-Csv -Path $dialog.FileName -NoTypeInformation -Encoding UTF8
    $script:runner.Controls['SummaryText'].Text = "Results exported to $($dialog.FileName)"
}
#endregion

#region XAML tool dialogs (Settings, Log viewer, Cookie jar, JWT, About, Diff viewer, Report)

# ------------------------------------------------------------------------------------------------
# Settings
# ------------------------------------------------------------------------------------------------

function Show-SettingsDialog {
    $checkGroups = @(
        @{ Title = 'UI & panel visibility'; Items = @(
            @('ShowEnvironmentPanel', 'Environment panel'), @('ShowHistory', 'History panel'), @('ShowRequestHeadersTab', 'Request headers tab'),
            @('ShowAuthTab', 'Authentication tab'), @('ShowPreRequestTab', 'Pre-request script tab'), @('ShowTestsTab', 'Tests tab'),
            @('ShowTestResultsTab', 'Test results tab'), @('ShowResponse', 'Response panel'), @('ShowJsonTreeTab', 'JSON tree tab'),
            @('ShowResponseHeaders', 'Response headers tab'), @('ShowCurl', 'Code snippets tab'), @('ShowConsoleTab', 'Console tab')) },
        @{ Title = 'Configuration'; Items = @(
            @('EnableLogs', 'Enable logging'), @('EnableHistory', 'Enable history tracking'), @('AutoRunHistory', 'Auto-run on history double-click'),
            @('EnableAllMethods', 'Allow all request methods'), @('IgnoreSslErrors', 'Ignore SSL errors'), @('EnablePostmanImport', 'Enable Postman import'),
            @('EnableCurlImport', 'Enable cURL import'), @('EnableRepeatRequest', 'Enable repeat request'), @('RestoreRequestTabs', 'Restore request tabs from the last session'),
            @('HistorySaveResponses', 'Save responses in history'), @('CheckForUpdatesOnStartup', 'Check for updates at start-up')) }
    )
    $checkKeys = @($checkGroups | ForEach-Object { $_.Items } | ForEach-Object { $_[0] }) + @('AutoSaveToFile', 'AutoRenameFile', 'EnableAutoRenamePrefix')

    $groupXaml = foreach ($group in $checkGroups) {
        # Text is XML-escaped: a raw '&' (as in "UI & panel visibility") makes the XAML invalid.
        $boxes = foreach ($item in $group.Items) { "<CheckBox x:Name=`"Chk$($item[0])`" Content=`"$([System.Security.SecurityElement]::Escape($item[1]))`" Width=`"235`" Margin=`"0,4,8,4`"/>" }
        "<Border Background=`"{StaticResource Surface}`" BorderBrush=`"{StaticResource Border}`" BorderThickness=`"1`" CornerRadius=`"8`" Padding=`"14,10`" Margin=`"0,0,0,12`"><StackPanel><TextBlock Style=`"{StaticResource SectionLabel}`" Text=`"$([System.Security.SecurityElement]::Escape($group.Title.ToUpper()))`"/><WrapPanel Margin=`"0,6,0,0`">$($boxes -join '')</WrapPanel></StackPanel></Border>"
    }
    $body = @"
  <Grid Margin="22,16,22,16">
    <Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="*"/><RowDefinition Height="Auto"/></Grid.RowDefinitions>
    <TextBlock Text="Settings" FontSize="22" FontWeight="SemiBold" Foreground="{StaticResource Primary}" Margin="0,0,0,10"/>
    <ScrollViewer Grid.Row="1" VerticalScrollBarVisibility="Auto">
      <StackPanel Margin="0,0,10,0">
        $($groupXaml -join "`n")
        <Border Background="{StaticResource Surface}" BorderBrush="{StaticResource Border}" BorderThickness="1" CornerRadius="8" Padding="14,10" Margin="0,0,0,12">
          <WrapPanel>
            <StackPanel Margin="0,0,24,8"><TextBlock Style="{StaticResource SectionLabel}" Text="APP THEME"/><ComboBox x:Name="CmbAppTheme" Width="170" Height="28" Margin="0,4,0,0" VerticalContentAlignment="Center"/></StackPanel>
            <StackPanel Margin="0,0,24,8"><TextBlock Style="{StaticResource SectionLabel}" Text="LOG LEVEL"/><ComboBox x:Name="CmbLogLevel" Width="120" Height="28" Margin="0,4,0,0" VerticalContentAlignment="Center"/></StackPanel>
            <StackPanel Margin="0,0,24,8"><TextBlock Style="{StaticResource SectionLabel}" Text="DEFAULT CONSOLE LANGUAGE"/><ComboBox x:Name="CmbDefaultConsoleLanguage" Width="200" Height="28" Margin="0,4,0,0" VerticalContentAlignment="Center"/></StackPanel>
            <StackPanel Margin="0,0,24,8"><TextBlock Style="{StaticResource SectionLabel}" Text="TIMEOUT (SECONDS)"/><TextBox x:Name="TxtRequestTimeoutSeconds" Width="90" Height="28" Margin="0,4,0,0" VerticalContentAlignment="Center"/></StackPanel>
            <StackPanel Margin="0,0,24,8"><TextBlock Style="{StaticResource SectionLabel}" Text="RESPONSE FONT SIZE (8-72)"/><TextBox x:Name="TxtResponseFontSize" Width="90" Height="28" Margin="0,4,0,0" VerticalContentAlignment="Center"/></StackPanel>
            <StackPanel Margin="0,0,24,8"><TextBlock Style="{StaticResource SectionLabel}" Text="MAX REPEATS (1-100)"/><TextBox x:Name="TxtMaxRepeatCount" Width="90" Height="28" Margin="0,4,0,0" VerticalContentAlignment="Center"/></StackPanel>
          </WrapPanel>
        </Border>
        <Border Background="{StaticResource Surface}" BorderBrush="{StaticResource Border}" BorderThickness="1" CornerRadius="8" Padding="14,10">
          <StackPanel>
            <TextBlock Style="{StaticResource SectionLabel}" Text="AUTO-SAVE &amp; RENAMING"/>
            <CheckBox x:Name="ChkAutoSaveToFile" Content="Auto-save downloaded files (binary or attachment responses) to a folder" Margin="0,8,0,6"/>
            <DockPanel Margin="0,0,0,6"><Button x:Name="BrowseAutoSaveButton" DockPanel.Dock="Right" Margin="8,0,0,0" Padding="14,3" Content="Browse..."/><TextBox x:Name="TxtAutoSavePath" Height="28" VerticalContentAlignment="Center"/></DockPanel>
            <CheckBox x:Name="ChkAutoRenameFile" Content="Name saved files after the uploaded file(s)" Margin="0,4,0,6"/>
            <DockPanel><CheckBox x:Name="ChkEnableAutoRenamePrefix" Content="Prefix:" VerticalAlignment="Center" Margin="0,0,8,0"/><TextBox x:Name="TxtAutoRenamePrefix" Height="28" Width="240" HorizontalAlignment="Left" VerticalContentAlignment="Center"/></DockPanel>
          </StackPanel>
        </Border>
      </StackPanel>
    </ScrollViewer>
    <DockPanel Grid.Row="2" Margin="0,14,0,0">
      <StackPanel DockPanel.Dock="Left" Orientation="Horizontal">
        <Button x:Name="RestoreButton" Padding="14,6" Margin="0,0,8,0" Content="Restore defaults"/>
        <Button x:Name="ViewLogsButton" Padding="14,6" Margin="0,0,8,0" Content="View logs"/>
        <Button x:Name="OpenLogsButton" Padding="14,6" Margin="0,0,8,0" Content="Open logs folder"/>
        <Button x:Name="ClearLogsButton" Padding="14,6" Content="Clear logs"/>
      </StackPanel>
      <StackPanel Orientation="Horizontal" HorizontalAlignment="Right">
        <TextBlock x:Name="SettingsStatus" VerticalAlignment="Center" Margin="0,0,12,0" Foreground="#D93025"/>
        <Button x:Name="SaveButton" Style="{StaticResource PrimaryButton}" Width="100" Content="Save"/>
        <Button x:Name="CancelButton" IsCancel="True" Width="90" Margin="10,0,0,0" Content="Cancel"/>
      </StackPanel>
    </DockPanel>
  </Grid>
"@
    $names = @($checkKeys | ForEach-Object { "Chk$_" }) + @('CmbAppTheme', 'CmbLogLevel', 'CmbDefaultConsoleLanguage', 'TxtRequestTimeoutSeconds', 'TxtResponseFontSize', 'TxtMaxRepeatCount', 'TxtAutoSavePath', 'TxtAutoRenamePrefix',
        'BrowseAutoSaveButton', 'RestoreButton', 'ViewLogsButton', 'OpenLogsButton', 'ClearLogsButton', 'SettingsStatus', 'SaveButton', 'CancelButton')
    $dialog = New-DialogWindow -BodyXaml $body -ControlNames $names -Title 'Settings' -Width 940 -Height 820
    $window = $dialog.Window; $controls = $dialog.Controls
    $script:settingsDialogSaved = $false

    foreach ($theme in @($script:Themes.Keys | Sort-Object)) { [void]$controls['CmbAppTheme'].Items.Add($theme) }
    foreach ($level in @('Info', 'Debug')) { [void]$controls['CmbLogLevel'].Items.Add($level) }
    foreach ($language in @('PowerShell', 'JavaScript (Node.js)', 'Python', 'PHP', 'Ruby', 'Go', 'Batch', 'Bash')) { [void]$controls['CmbDefaultConsoleLanguage'].Items.Add($language) }

    $loadFrom = {
        param($Source)
        foreach ($key in $checkKeys) { $controls["Chk$key"].IsChecked = [bool]$Source[$key] }
        $controls['CmbAppTheme'].SelectedItem = if ($Source['AppTheme'] -and $controls['CmbAppTheme'].Items.Contains($Source['AppTheme'])) { $Source['AppTheme'] } else { 'Light' }
        $controls['CmbLogLevel'].SelectedItem = if ($Source['LogLevel']) { $Source['LogLevel'] } else { 'Info' }
        $controls['CmbDefaultConsoleLanguage'].SelectedItem = if ($Source['DefaultConsoleLanguage']) { $Source['DefaultConsoleLanguage'] } else { 'PowerShell' }
        $controls['TxtRequestTimeoutSeconds'].Text = [string]$Source['RequestTimeoutSeconds']
        $controls['TxtResponseFontSize'].Text = [string]$Source['ResponseFontSize']
        $controls['TxtMaxRepeatCount'].Text = [string]$Source['MaxRepeatCount']
        $controls['TxtAutoSavePath'].Text = [string]$Source['AutoSavePath']
        $controls['TxtAutoRenamePrefix'].Text = [string]$Source['AutoRenamePrefix']
    }
    & $loadFrom $script:settings

    # Dependent controls
    $updateDependencies = {
        $historyOn = [bool]$controls['ChkEnableHistory'].IsChecked
        $controls['ChkShowHistory'].IsEnabled = $historyOn; $controls['ChkAutoRunHistory'].IsEnabled = $historyOn
        $controls['CmbLogLevel'].IsEnabled = [bool]$controls['ChkEnableLogs'].IsChecked
        $controls['TxtAutoSavePath'].IsEnabled = [bool]$controls['ChkAutoSaveToFile'].IsChecked; $controls['BrowseAutoSaveButton'].IsEnabled = [bool]$controls['ChkAutoSaveToFile'].IsChecked
        $controls['TxtAutoRenamePrefix'].IsEnabled = [bool]$controls['ChkEnableAutoRenamePrefix'].IsChecked
        $controls['TxtMaxRepeatCount'].IsEnabled = [bool]$controls['ChkEnableRepeatRequest'].IsChecked
    }
    foreach ($key in @('EnableHistory', 'EnableLogs', 'AutoSaveToFile', 'EnableAutoRenamePrefix', 'EnableRepeatRequest')) { $controls["Chk$key"].Add_Click($updateDependencies) }
    & $updateDependencies

    $controls['BrowseAutoSaveButton'].Add_Click({
        $picker = New-Object System.Windows.Forms.FolderBrowserDialog
        if ($controls['TxtAutoSavePath'].Text -and (Test-Path $controls['TxtAutoSavePath'].Text)) { $picker.SelectedPath = $controls['TxtAutoSavePath'].Text }
        if ($picker.ShowDialog() -eq [System.Windows.Forms.DialogResult]::OK) { $controls['TxtAutoSavePath'].Text = $picker.SelectedPath }
    })
    $controls['RestoreButton'].Add_Click({
        $answer = [System.Windows.MessageBox]::Show($window, 'Restore all settings to their defaults?', 'Restore defaults', 'YesNo', 'Warning')
        if ($answer -eq 'Yes') { & $loadFrom $script:defaultSettings; & $updateDependencies }
    })
    $controls['ViewLogsButton'].Add_Click({ Show-LogViewerDialog -Owner $window })
    $controls['OpenLogsButton'].Add_Click({
        if (Test-Path $logsDir) { Invoke-Item $logsDir } else { [void][System.Windows.MessageBox]::Show($window, 'Logs folder not found.', 'Open logs', 'OK', 'Information') }
    })
    $controls['ClearLogsButton'].Add_Click({
        if ([System.Windows.MessageBox]::Show($window, 'Clear the log file?', 'Clear logs', 'YesNo', 'Warning') -ne 'Yes') { return }
        try { Set-Content -Path $logFilePath -Value 'Timestamp,Level,Message' -ErrorAction Stop; $controls['SettingsStatus'].Text = '' } catch { $controls['SettingsStatus'].Text = "Could not clear logs: $($_.Exception.Message)" }
    })
    $controls['SaveButton'].Add_Click({
        $timeout = 0; $fontSize = 0; $repeats = 0
        if ([bool]$controls['ChkEnableAutoRenamePrefix'].IsChecked -and [string]::IsNullOrWhiteSpace($controls['TxtAutoRenamePrefix'].Text)) { $controls['SettingsStatus'].Text = 'Prefix cannot be blank.'; return }
        if ([bool]$controls['ChkAutoSaveToFile'].IsChecked) {
            if ([string]::IsNullOrWhiteSpace($controls['TxtAutoSavePath'].Text)) { $controls['SettingsStatus'].Text = 'Auto-save path cannot be blank.'; return }
            if (-not (Test-Path -Path $controls['TxtAutoSavePath'].Text -PathType Container)) { $controls['SettingsStatus'].Text = 'Auto-save path does not exist.'; return }
        }
        if (-not [int]::TryParse($controls['TxtRequestTimeoutSeconds'].Text, [ref]$timeout) -or $timeout -le 0) { $controls['SettingsStatus'].Text = 'Invalid timeout.'; return }
        if (-not [int]::TryParse($controls['TxtResponseFontSize'].Text, [ref]$fontSize) -or $fontSize -lt 8 -or $fontSize -gt 72) { $controls['SettingsStatus'].Text = 'Font size must be 8-72.'; return }
        if (-not [int]::TryParse($controls['TxtMaxRepeatCount'].Text, [ref]$repeats) -or $repeats -lt 1 -or $repeats -gt 100) { $controls['SettingsStatus'].Text = 'Max repeats must be 1-100.'; return }
        foreach ($key in $checkKeys) { $script:settings[$key] = [bool]$controls["Chk$key"].IsChecked }
        $previousTheme = [string]$script:settings.AppTheme
        $script:settings.AppTheme = [string]$controls['CmbAppTheme'].SelectedItem
        if ($script:settings.AppTheme -ne $previousTheme) { Set-AppThemeLive -ThemeName $script:settings.AppTheme }
        $script:settings.LogLevel = [string]$controls['CmbLogLevel'].SelectedItem
        $script:settings.DefaultConsoleLanguage = [string]$controls['CmbDefaultConsoleLanguage'].SelectedItem
        $script:settings.RequestTimeoutSeconds = $timeout; $script:settings.ResponseFontSize = $fontSize; $script:settings.MaxRepeatCount = $repeats
        $script:settings.AutoSavePath = $controls['TxtAutoSavePath'].Text; $script:settings.AutoRenamePrefix = $controls['TxtAutoRenamePrefix'].Text
        Save-Settings
        $script:settingsDialogSaved = $true
        $window.DialogResult = $true
    })
    [void](Show-WpfDialog -Window $window -OwnerForm (Get-MainWindow))
    return $script:settingsDialogSaved
}

# ------------------------------------------------------------------------------------------------
# Log viewer
# ------------------------------------------------------------------------------------------------

function Show-LogViewerDialog {
    param($Owner)
    if (-not (Test-Path $logFilePath)) { [void][System.Windows.MessageBox]::Show($Owner, 'No log file found yet.', 'Log viewer', 'OK', 'Information'); return }
    $body = @'
  <Grid Margin="18,14,18,14">
    <Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="Auto"/><RowDefinition Height="*"/><RowDefinition Height="Auto"/></Grid.RowDefinitions>
    <TextBlock Text="Application log" FontSize="20" FontWeight="SemiBold" Foreground="{StaticResource Primary}"/>
    <WrapPanel Grid.Row="1" Margin="0,10,0,8">
      <TextBox x:Name="FilterBox" Width="300" Height="28" VerticalContentAlignment="Center" Margin="0,0,8,0" ToolTip="Filter by message text"/>
      <ComboBox x:Name="LevelBox" Width="120" Height="28" VerticalContentAlignment="Center" Margin="0,0,8,0"/>
      <Button x:Name="RefreshButton" Style="{StaticResource SmallButton}" Content="Refresh"/>
      <TextBlock x:Name="CountText" VerticalAlignment="Center" Foreground="{StaticResource Muted}"/>
    </WrapPanel>
    <DataGrid x:Name="LogGrid" Grid.Row="2" AutoGenerateColumns="False" IsReadOnly="True" HeadersVisibility="Column" GridLinesVisibility="Horizontal" Background="Transparent" RowBackground="Transparent">
      <DataGrid.Columns>
        <DataGridTextColumn Header="Time" Binding="{Binding C1}" Width="160"/>
        <DataGridTextColumn Header="Level" Binding="{Binding C2}" Width="70"/>
        <DataGridTextColumn Header="Message" Binding="{Binding C3}" Width="*"/>
      </DataGrid.Columns>
    </DataGrid>
    <Button x:Name="CloseButton" Grid.Row="3" HorizontalAlignment="Right" IsCancel="True" Width="90" Margin="0,12,0,0" Content="Close"/>
  </Grid>
'@
    $dialog = New-DialogWindow -BodyXaml $body -ControlNames 'FilterBox', 'LevelBox', 'RefreshButton', 'CountText', 'LogGrid', 'CloseButton' -Title 'Log viewer' -Width 960 -Height 640
    $window = $dialog.Window; $controls = $dialog.Controls
    foreach ($level in @('All levels', 'Info', 'Debug', 'Error')) { [void]$controls['LevelBox'].Items.Add($level) }
    $controls['LevelBox'].SelectedIndex = 0
    $script:logRowsAll = @()
    $load = {
        try { $script:logRowsAll = @(Import-Csv -Path $logFilePath | Select-Object -Last 5000) } catch { $script:logRowsAll = @() }
        & $apply
    }
    $apply = {
        $level = [string]$controls['LevelBox'].SelectedItem; $text = $controls['FilterBox'].Text
        $rows = @($script:logRowsAll)
        if ($level -and $level -ne 'All levels') { $rows = @($rows | Where-Object { $_.Level -eq $level }) }
        if ($text) { $rows = @($rows | Where-Object { $_.Message -like "*$text*" -or $_.Level -like "*$text*" }) }
        $display = New-Object 'System.Collections.ObjectModel.ObservableCollection[SimpleRow]'
        foreach ($row in $rows) { $item = New-Object SimpleRow; $item.C1 = [string]$row.Timestamp; $item.C2 = [string]$row.Level; $item.C3 = [string]$row.Message; $display.Add($item) }
        $controls['LogGrid'].ItemsSource = $display
        $controls['CountText'].Text = "   $($display.Count) of $($script:logRowsAll.Count) entries"
    }
    $controls['FilterBox'].Add_TextChanged({ & $apply })
    $controls['LevelBox'].Add_SelectionChanged({ & $apply })
    $controls['RefreshButton'].Add_Click({ & $load })
    & $load
    [void](Show-WpfDialog -Window $window -OwnerForm $Owner)
}

# ------------------------------------------------------------------------------------------------
# Cookie jar
# ------------------------------------------------------------------------------------------------

function Show-CookieJarDialog {
    $body = @'
  <Grid Margin="18,14,18,14">
    <Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="*"/><RowDefinition Height="Auto"/></Grid.RowDefinitions>
    <TextBlock Text="Cookie jar" FontSize="20" FontWeight="SemiBold" Foreground="{StaticResource Primary}" Margin="0,0,0,10"/>
    <DataGrid x:Name="CookieGrid" Grid.Row="1" AutoGenerateColumns="False" IsReadOnly="True" HeadersVisibility="Column" SelectionMode="Extended" GridLinesVisibility="Horizontal" Background="Transparent" RowBackground="Transparent">
      <DataGrid.Columns>
        <DataGridTextColumn Header="Domain" Binding="{Binding C1}" Width="160"/><DataGridTextColumn Header="Name" Binding="{Binding C2}" Width="140"/>
        <DataGridTextColumn Header="Value" Binding="{Binding C3}" Width="*"/><DataGridTextColumn Header="Path" Binding="{Binding C4}" Width="80"/>
        <DataGridTextColumn Header="Expires" Binding="{Binding C5}" Width="150"/>
      </DataGrid.Columns>
    </DataGrid>
    <WrapPanel Grid.Row="2" Margin="0,12,0,0" HorizontalAlignment="Right">
      <Button x:Name="ImportButton" Margin="0,0,8,0" Padding="14,6" Content="Import..."/>
      <Button x:Name="ExportButton" Margin="0,0,8,0" Padding="14,6" Content="Export..."/>
      <Button x:Name="DeleteSelectedButton" Margin="0,0,8,0" Padding="14,6" Content="Delete selected"/>
      <Button x:Name="ClearAllButton" Margin="0,0,8,0" Padding="14,6" Content="Clear all"/>
      <Button x:Name="CloseButton" IsCancel="True" Padding="14,6" Content="Close"/>
    </WrapPanel>
  </Grid>
'@
    $dialog = New-DialogWindow -BodyXaml $body -ControlNames 'CookieGrid', 'ImportButton', 'ExportButton', 'DeleteSelectedButton', 'ClearAllButton', 'CloseButton' -Title 'Cookie jar' -Width 880 -Height 520
    $window = $dialog.Window; $controls = $dialog.Controls
    if (-not $script:cookieJar) { $script:cookieJar = New-Object System.Collections.ArrayList }
    $refresh = {
        $rows = New-Object 'System.Collections.ObjectModel.ObservableCollection[SimpleRow]'
        foreach ($cookie in $script:cookieJar) {
            $row = New-Object SimpleRow
            $row.C1 = [string]$cookie.Domain; $row.C2 = [string]$cookie.Name; $row.C3 = [string]$cookie.Value; $row.C4 = [string]$cookie.Path; $row.C5 = [string]$cookie.Expires; $row.Item = $cookie
            $rows.Add($row)
        }
        $controls['CookieGrid'].ItemsSource = $rows
    }
    & $refresh
    $controls['ClearAllButton'].Add_Click({ $script:cookieJar.Clear(); & $refresh })
    $controls['DeleteSelectedButton'].Add_Click({ foreach ($row in @($controls['CookieGrid'].SelectedItems)) { $script:cookieJar.Remove($row.Item) }; & $refresh })
    $controls['ExportButton'].Add_Click({
        $picker = New-Object Microsoft.Win32.SaveFileDialog; $picker.Filter = 'JSON files (*.json)|*.json'; $picker.FileName = 'cookies.json'
        if ($picker.ShowDialog($window) -ne $true) { return }
        try { @($script:cookieJar) | ConvertTo-Json -Depth 5 | Set-Content -Path $picker.FileName; [void][System.Windows.MessageBox]::Show($window, 'Cookies exported.', 'Cookie jar', 'OK', 'Information') }
        catch { [void][System.Windows.MessageBox]::Show($window, "Failed to export cookies: $($_.Exception.Message)", 'Cookie jar', 'OK', 'Error') }
    })
    $controls['ImportButton'].Add_Click({
        $picker = New-Object Microsoft.Win32.OpenFileDialog; $picker.Filter = 'JSON files (*.json)|*.json'
        if ($picker.ShowDialog($window) -ne $true) { return }
        try {
            $imported = @(Get-Content -Path $picker.FileName -Raw | ConvertFrom-Json)
            $script:cookieJar.Clear()
            foreach ($entry in $imported) {
                if (-not $entry.Name) { continue }
                [void]$script:cookieJar.Add([PSCustomObject]@{ Name = $entry.Name; Value = $entry.Value; Domain = $entry.Domain; Path = $(if ($entry.Path) { $entry.Path } else { '/' }); Expires = [string]$entry.Expires })
            }
            & $refresh
        } catch { [void][System.Windows.MessageBox]::Show($window, "Failed to import cookies: $($_.Exception.Message)", 'Cookie jar', 'OK', 'Error') }
    })
    [void](Show-WpfDialog -Window $window -OwnerForm (Get-MainWindow))
}

# ------------------------------------------------------------------------------------------------
# JWT utility
# ------------------------------------------------------------------------------------------------

function ConvertFrom-Base64UrlText {
    param([string]$Text)
    $padded = $Text.Replace('-', '+').Replace('_', '/')
    switch ($padded.Length % 4) { 2 { $padded += '==' } 3 { $padded += '=' } }
    return [System.Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($padded))
}

function ConvertTo-Base64UrlText {
    param([byte[]]$Bytes)
    return [Convert]::ToBase64String($Bytes).Replace('+', '-').Replace('/', '_').TrimEnd('=')
}

function Show-JwtDialog {
    $body = @'
  <TabControl Margin="14" Background="{StaticResource Surface}" BorderBrush="{StaticResource Border}">
    <TabItem Header="Decoder">
      <Grid Margin="12">
        <Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="1*"/><RowDefinition Height="Auto"/><RowDefinition Height="Auto"/><RowDefinition Height="1.4*"/></Grid.RowDefinitions>
        <TextBlock Style="{StaticResource SectionLabel}" Text="JWT"/>
        <TextBox x:Name="JwtInputBox" Grid.Row="1" Margin="0,6,0,8" TextWrapping="Wrap" AcceptsReturn="True" FontFamily="Consolas" VerticalScrollBarVisibility="Auto"/>
        <DockPanel Grid.Row="2" Margin="0,0,0,8">
          <StackPanel DockPanel.Dock="Right" Orientation="Horizontal" Margin="8,0,0,0">
            <Button x:Name="VerifyButton" Margin="0,0,6,0" Padding="14,5" Content="Verify signature"/>
            <Button x:Name="DecodeButton" Style="{StaticResource PrimaryButton}" Margin="0,0,6,0" Padding="14,5" Content="Decode"/>
            <Button x:Name="ClearJwtButton" Padding="14,5" Content="Clear"/>
          </StackPanel>
          <TextBlock Text="Secret" VerticalAlignment="Center" Margin="0,0,8,0"/>
          <PasswordBox x:Name="VerifySecretBox" Height="28" VerticalContentAlignment="Center"/>
        </DockPanel>
        <TextBlock x:Name="VerifyResultText" Grid.Row="3" Margin="0,0,0,6" FontWeight="SemiBold"/>
        <TextBox x:Name="JwtOutputBox" Grid.Row="4" IsReadOnly="True" FontFamily="Consolas" VerticalScrollBarVisibility="Auto" HorizontalScrollBarVisibility="Auto"/>
      </Grid>
    </TabItem>
    <TabItem Header="Generator (HS256)">
      <Grid Margin="12">
        <Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="1.2*"/><RowDefinition Height="Auto"/><RowDefinition Height="Auto"/><RowDefinition Height="1*"/></Grid.RowDefinitions>
        <TextBlock Style="{StaticResource SectionLabel}" Text="PAYLOAD (JSON)"/>
        <TextBox x:Name="PayloadBox" Grid.Row="1" Margin="0,6,0,8" AcceptsReturn="True" FontFamily="Consolas" VerticalScrollBarVisibility="Auto"/>
        <DockPanel Grid.Row="2" Margin="0,0,0,8"><TextBlock Text="Secret" VerticalAlignment="Center" Margin="0,0,8,0"/><TextBox x:Name="GenSecretBox" Height="28" VerticalContentAlignment="Center"/></DockPanel>
        <StackPanel Grid.Row="3" Orientation="Horizontal" Margin="0,0,0,8">
          <Button x:Name="GenerateButton" Style="{StaticResource PrimaryButton}" Padding="16,6" Margin="0,0,8,0" Content="Generate JWT"/>
          <Button x:Name="CopyJwtButton" Padding="16,6" Content="Copy"/>
        </StackPanel>
        <TextBox x:Name="GeneratedBox" Grid.Row="4" IsReadOnly="True" TextWrapping="Wrap" FontFamily="Consolas" VerticalScrollBarVisibility="Auto"/>
      </Grid>
    </TabItem>
  </TabControl>
'@
    $names = 'JwtInputBox', 'VerifyButton', 'DecodeButton', 'ClearJwtButton', 'VerifySecretBox', 'VerifyResultText', 'JwtOutputBox', 'PayloadBox', 'GenSecretBox', 'GenerateButton', 'CopyJwtButton', 'GeneratedBox'
    $dialog = New-DialogWindow -BodyXaml $body -ControlNames $names -Title 'JWT utility' -Width 900 -Height 680
    $window = $dialog.Window; $controls = $dialog.Controls
    $controls['PayloadBox'].Text = '{ "sub": "1234567890", "name": "John Doe", "iat": 1516239022 }'
    $controls['GenSecretBox'].Text = 'secret'
    $jwtPattern = '^[A-Za-z0-9\-_]+\.[A-Za-z0-9\-_]+\.[A-Za-z0-9\-_]+$'

    $controls['DecodeButton'].Add_Click({
        $token = $controls['JwtInputBox'].Text.Trim()
        $controls['VerifyResultText'].Text = ''
        if ($token -notmatch $jwtPattern) { $controls['JwtOutputBox'].Text = 'Invalid JWT format.'; return }
        $parts = $token.Split('.')
        try {
            $header = ConvertFrom-Base64UrlText $parts[0] | ConvertFrom-Json | ConvertTo-Json
            $payload = ConvertFrom-Base64UrlText $parts[1] | ConvertFrom-Json | ConvertTo-Json
            $controls['JwtOutputBox'].Text = "HEADER:`r`n$header`r`n`r`nPAYLOAD:`r`n$payload`r`n`r`nSIGNATURE:`r`n$($parts[2])"
        } catch { $controls['JwtOutputBox'].Text = "Error decoding JWT: $($_.Exception.Message)" }
    })
    $controls['VerifyButton'].Add_Click({
        $token = $controls['JwtInputBox'].Text.Trim(); $secret = $controls['VerifySecretBox'].Password
        $brushes = [System.Windows.Media.Brushes]
        if (-not $token -or -not $secret) { $controls['VerifyResultText'].Text = 'Enter the JWT and the secret.'; $controls['VerifyResultText'].Foreground = $brushes::DarkOrange; return }
        if ($token -notmatch $jwtPattern) { $controls['VerifyResultText'].Text = 'Invalid JWT format.'; $controls['VerifyResultText'].Foreground = $brushes::Firebrick; return }
        $parts = $token.Split('.')
        try {
            $algorithm = (ConvertFrom-Base64UrlText $parts[0] | ConvertFrom-Json).alg
            if ($algorithm -ne 'HS256') { $controls['VerifyResultText'].Text = "Only HS256 is supported (token uses $algorithm)."; $controls['VerifyResultText'].Foreground = $brushes::DarkOrange; return }
            $hmac = New-Object System.Security.Cryptography.HMACSHA256(, [System.Text.Encoding]::UTF8.GetBytes($secret))
            $calculated = ConvertTo-Base64UrlText $hmac.ComputeHash([System.Text.Encoding]::UTF8.GetBytes("$($parts[0]).$($parts[1])"))
            if ($calculated -eq $parts[2]) { $controls['VerifyResultText'].Text = 'Signature verified.'; $controls['VerifyResultText'].Foreground = $brushes::SeaGreen }
            else { $controls['VerifyResultText'].Text = 'Signature does NOT match.'; $controls['VerifyResultText'].Foreground = $brushes::Firebrick }
        } catch { $controls['VerifyResultText'].Text = "Error: $($_.Exception.Message)"; $controls['VerifyResultText'].Foreground = $brushes::Firebrick }
    })
    $controls['ClearJwtButton'].Add_Click({ $controls['JwtInputBox'].Clear(); $controls['JwtOutputBox'].Clear(); $controls['VerifyResultText'].Text = '' })
    $controls['GenerateButton'].Add_Click({
        try {
            $payloadJson = $controls['PayloadBox'].Text; $null = $payloadJson | ConvertFrom-Json
            $header = ConvertTo-Base64UrlText ([System.Text.Encoding]::UTF8.GetBytes('{"alg":"HS256","typ":"JWT"}'))
            $payload = ConvertTo-Base64UrlText ([System.Text.Encoding]::UTF8.GetBytes($payloadJson))
            $hmac = New-Object System.Security.Cryptography.HMACSHA256(, [System.Text.Encoding]::UTF8.GetBytes($controls['GenSecretBox'].Text))
            $signature = ConvertTo-Base64UrlText $hmac.ComputeHash([System.Text.Encoding]::UTF8.GetBytes("$header.$payload"))
            $controls['GeneratedBox'].Text = "$header.$payload.$signature"
        } catch { $controls['GeneratedBox'].Text = "Error: $($_.Exception.Message)" }
    })
    $controls['CopyJwtButton'].Add_Click({ if ($controls['GeneratedBox'].Text) { [System.Windows.Clipboard]::SetText($controls['GeneratedBox'].Text) } })
    [void](Show-WpfDialog -Window $window -OwnerForm (Get-MainWindow))
}

# ------------------------------------------------------------------------------------------------
# About + update check
# ------------------------------------------------------------------------------------------------

function Show-AboutWindow {
    $body = @'
  <StackPanel>
    <Border Padding="22,18">
      <Border.Background><LinearGradientBrush StartPoint="0,0" EndPoint="1,0"><GradientStop Color="#3659C9" Offset="0"/><GradientStop Color="#243E9E" Offset="1"/></LinearGradientBrush></Border.Background>
      <StackPanel><TextBlock Text="PowerShell API Tester" FontSize="24" FontWeight="SemiBold" Foreground="White"/>
        <TextBlock Text="Feature-rich REST / gRPC API testing tool for Windows" Foreground="#DCE7FF" Margin="0,2,0,0"/></StackPanel>
    </Border>
    <Grid Margin="22,16,22,8">
      <Grid.ColumnDefinitions><ColumnDefinition Width="90"/><ColumnDefinition Width="*"/></Grid.ColumnDefinitions>
      <Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="Auto"/><RowDefinition Height="Auto"/><RowDefinition Height="Auto"/><RowDefinition Height="Auto"/></Grid.RowDefinitions>
      <TextBlock Text="Version" FontWeight="SemiBold" Margin="0,3"/><TextBlock x:Name="VersionText" Grid.Column="1" Margin="0,3"/>
      <TextBlock Grid.Row="1" Text="Author" FontWeight="SemiBold" Margin="0,3"/><TextBlock Grid.Row="1" Grid.Column="1" Text="Umesh Kashyap" Margin="0,3"/>
      <TextBlock Grid.Row="2" Text="License" FontWeight="SemiBold" Margin="0,3"/><TextBlock Grid.Row="2" Grid.Column="1" Text="MIT" Margin="0,3"/>
      <TextBlock Grid.Row="3" Text="GitHub" FontWeight="SemiBold" Margin="0,3"/>
      <TextBlock Grid.Row="3" Grid.Column="1" Margin="0,3"><Hyperlink x:Name="RepoLink"><TextBlock x:Name="RepoText"/></Hyperlink></TextBlock>
      <TextBlock Grid.Row="4" Grid.ColumnSpan="2" Margin="0,10,0,0" TextWrapping="Wrap" Foreground="{StaticResource Muted}" Text="A feature-rich API testing tool built entirely in PowerShell, with a WPF interface."/>
    </Grid>
    <Border BorderBrush="{StaticResource Border}" BorderThickness="0,1,0,0" Margin="22,8,22,0" Padding="0,14,0,0">
      <StackPanel>
        <TextBlock Text="Updates" FontWeight="SemiBold" FontSize="14"/>
        <TextBlock x:Name="UpdateStatusText" Margin="0,6,0,8" TextWrapping="Wrap" Text="Not checked yet."/>
        <StackPanel Orientation="Horizontal">
          <Button x:Name="CheckUpdateButton" Margin="0,0,8,0" Padding="14,5" Content="Check for updates"/>
          <Button x:Name="DownloadUpdateButton" Style="{StaticResource PrimaryButton}" Padding="14,5" Content="Download &amp; update" Visibility="Collapsed"/>
        </StackPanel>
      </StackPanel>
    </Border>
    <Button x:Name="CloseButton" HorizontalAlignment="Right" IsCancel="True" Width="90" Margin="22,14,22,18" Content="Close"/>
  </StackPanel>
'@
    $dialog = New-DialogWindow -BodyXaml $body -ControlNames 'VersionText', 'RepoLink', 'RepoText', 'UpdateStatusText', 'CheckUpdateButton', 'DownloadUpdateButton', 'CloseButton' -Title 'About PowerShell API Tester' -Width 560
    $window = $dialog.Window; $controls = $dialog.Controls
    $controls['VersionText'].Text = "v$($script:AppVersion)"
    $controls['RepoText'].Text = "github.com/$($script:AppGitHubRepo)"
    $controls['RepoLink'].Add_Click({ try { Start-Process "https://github.com/$($script:AppGitHubRepo)" } catch { } })
    $script:aboutRelease = $null
    $controls['CheckUpdateButton'].Add_Click({
        $controls['UpdateStatusText'].Text = 'Checking for updates...'; $controls['DownloadUpdateButton'].Visibility = 'Collapsed'
        Update-UiNow
        $status = Get-UpdateStatus
        $controls['UpdateStatusText'].Text = $status.Message
        $controls['UpdateStatusText'].Foreground = switch ($status.State) { 'Current' { [System.Windows.Media.Brushes]::SeaGreen } 'Available' { [System.Windows.Media.Brushes]::RoyalBlue } default { [System.Windows.Media.Brushes]::Firebrick } }
        if ($status.State -eq 'Available') { $script:aboutRelease = $status.Release; $controls['DownloadUpdateButton'].Visibility = 'Visible' }
    })
    $controls['DownloadUpdateButton'].Add_Click({
        if (-not $script:aboutRelease) { return }
        $controls['UpdateStatusText'].Text = 'Downloading update...'
        Update-UiNow
        $installed = Install-UpdateRelease -Release $script:aboutRelease
        $controls['UpdateStatusText'].Text = $installed.Message
        $controls['UpdateStatusText'].Foreground = if ($installed.Success) { [System.Windows.Media.Brushes]::SeaGreen } else { [System.Windows.Media.Brushes]::Firebrick }
    })
    [void](Show-WpfDialog -Window $window -OwnerForm (Get-MainWindow))
}

# ------------------------------------------------------------------------------------------------
# Diff viewer (sends both history requests and compares the live responses)
# ------------------------------------------------------------------------------------------------

function Format-ForDiff {
    param([string]$Text)
    if ([string]::IsNullOrEmpty($Text)) { return @() }
    try { if ($Text.TrimStart() -match '^[\{\[]') { return @((Format-JsonText -Text $Text) -split "`r?`n") } } catch { }
    return @($Text -split "`r?`n")
}

function Show-DiffDialog {
    param($Request1, $Request2, $SavedBody1 = $null, $SavedBody2 = $null)
    $body = @'
  <Grid Margin="18,14,18,14">
    <Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="Auto"/><RowDefinition Height="*"/><RowDefinition Height="Auto"/></Grid.RowDefinitions>
    <TextBlock Text="Compare responses" FontSize="20" FontWeight="SemiBold" Foreground="{StaticResource Primary}"/>
    <Grid Grid.Row="1" Margin="0,8,0,8"><Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="*"/></Grid.ColumnDefinitions>
      <TextBlock x:Name="OldText" TextTrimming="CharacterEllipsis" FontWeight="SemiBold"/><TextBlock x:Name="NewText" Grid.Column="1" TextTrimming="CharacterEllipsis" FontWeight="SemiBold"/></Grid>
    <ScrollViewer Grid.Row="2" HorizontalScrollBarVisibility="Auto" VerticalScrollBarVisibility="Auto" Background="{StaticResource Surface}">
      <TextBlock x:Name="DiffText" FontFamily="Consolas" FontSize="13" Margin="8"/>
    </ScrollViewer>
    <StackPanel Grid.Row="3" Orientation="Horizontal" HorizontalAlignment="Right" Margin="0,12,0,0">
      <TextBlock x:Name="DiffSummary" VerticalAlignment="Center" Margin="0,0,14,0" Foreground="{StaticResource Muted}"/>
      <Button x:Name="CloseButton" IsCancel="True" Width="90" Content="Close"/>
    </StackPanel>
  </Grid>
'@
    $dialog = New-DialogWindow -BodyXaml $body -ControlNames 'OldText', 'NewText', 'DiffText', 'DiffSummary', 'CloseButton' -Title 'Diff viewer - compare responses' -Width 1000 -Height 700
    $window = $dialog.Window; $controls = $dialog.Controls
    $controls['OldText'].Text = "Old: [$($Request1.Method)] $($Request1.Url)"
    $controls['NewText'].Text = "New: [$($Request2.Method)] $($Request2.Url)"
    $controls['DiffSummary'].Text = 'Sending both requests...'
    $window.Add_ContentRendered({
        $timeout = if ($script:settings.RequestTimeoutSeconds -gt 0) { [int]$script:settings.RequestTimeoutSeconds } else { 60 }
        if ($null -ne $SavedBody1 -and $null -ne $SavedBody2) {
            $first = @{ Success = $true; Body = $SavedBody1 }; $second = @{ Success = $true; Body = $SavedBody2 }
        } else {
            $first = Invoke-HttpRequestSync -Request $Request1 -TimeoutSeconds $timeout
            $second = Invoke-HttpRequestSync -Request $Request2 -TimeoutSeconds $timeout
        }
        $lines1 = Format-ForDiff $(if ($first.Success) { $first.Body } else { "[ERROR] $($first.ErrorMessage)" })
        $lines2 = Format-ForDiff $(if ($second.Success) { $second.Body } else { "[ERROR] $($second.ErrorMessage)" })
        $added = 0; $removed = 0
        foreach ($entry in (Compare-Object -ReferenceObject $lines1 -DifferenceObject $lines2 -IncludeEqual)) {
            $run = New-Object System.Windows.Documents.Run
            switch ($entry.SideIndicator) {
                '==' { $run.Text = "  $($entry.InputObject)`r`n" }
                '<=' { $run.Text = "- $($entry.InputObject)`r`n"; $run.Foreground = [System.Windows.Media.Brushes]::IndianRed; $removed++ }
                '=>' { $run.Text = "+ $($entry.InputObject)`r`n"; $run.Foreground = [System.Windows.Media.Brushes]::MediumSeaGreen; $added++ }
            }
            [void]$controls['DiffText'].Inlines.Add($run)
        }
        $controls['DiffSummary'].Text = "$added added, $removed removed"
    })
    [void](Show-WpfDialog -Window $window -OwnerForm (Get-MainWindow))
}

# ------------------------------------------------------------------------------------------------
# HTML report from the monitor log
# ------------------------------------------------------------------------------------------------

function Show-ReportDialog {
    if (-not (Test-Path $monitorLogFilePath)) { Show-UiMessage 'No monitor log file found to generate a report.' 'Generate report' 'Information'; return }
    $body = @'
  <Grid Margin="22,18,22,18">
    <Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="Auto"/><RowDefinition Height="*"/><RowDefinition Height="Auto"/></Grid.RowDefinitions>
    <TextBlock Text="Customize report" FontSize="20" FontWeight="SemiBold" Foreground="{StaticResource Primary}"/>
    <StackPanel Grid.Row="1" Margin="0,12,0,8">
      <CheckBox x:Name="SummaryCardsBox" Content="Include summary cards" IsChecked="True" Margin="0,3"/>
      <CheckBox x:Name="MonitorStatsBox" Content="Include monitor statistics table" IsChecked="True" Margin="0,3"/>
    </StackPanel>
    <Border Grid.Row="2" Background="{StaticResource Surface}" BorderBrush="{StaticResource Border}" BorderThickness="1" CornerRadius="8" Padding="12,8">
      <StackPanel><TextBlock Style="{StaticResource SectionLabel}" Text="DETAILED LOG COLUMNS"/><StackPanel x:Name="ColumnsPanel" Margin="0,6,0,0"/></StackPanel>
    </Border>
    <StackPanel Grid.Row="3" Orientation="Horizontal" HorizontalAlignment="Right" Margin="0,14,0,0">
      <Button x:Name="GenerateButton" Style="{StaticResource PrimaryButton}" IsDefault="True" Width="110" Content="Generate"/>
      <Button x:Name="CancelButton" IsCancel="True" Width="90" Margin="10,0,0,0" Content="Cancel"/>
    </StackPanel>
  </Grid>
'@
    $dialog = New-DialogWindow -BodyXaml $body -ControlNames 'SummaryCardsBox', 'MonitorStatsBox', 'ColumnsPanel', 'GenerateButton', 'CancelButton' -Title 'Customize report' -Width 440 -Height 520
    $window = $dialog.Window; $controls = $dialog.Controls
    $columnBoxes = @{}
    foreach ($column in @('Timestamp', 'MonitorName', 'URL', 'Success', 'StatusCode', 'TimeMs', 'Message')) {
        $box = New-Object System.Windows.Controls.CheckBox; $box.Content = $column; $box.IsChecked = $true; $box.Margin = [System.Windows.Thickness]::new(0, 3, 0, 3)
        [void]$controls['ColumnsPanel'].Children.Add($box); $columnBoxes[$column] = $box
    }
    $script:reportOptions = $null
    $controls['GenerateButton'].Add_Click({
        $script:reportOptions = [PSCustomObject]@{
            IncludeSummaryCards = [bool]$controls['SummaryCardsBox'].IsChecked; IncludeMonitorStats = [bool]$controls['MonitorStatsBox'].IsChecked
            DetailedLogColumns = @($columnBoxes.Keys | Where-Object { $columnBoxes[$_].IsChecked } | Sort-Object { @('Timestamp', 'MonitorName', 'URL', 'Success', 'StatusCode', 'TimeMs', 'Message').IndexOf($_) })
        }
        $window.DialogResult = $true
    })
    [void](Show-WpfDialog -Window $window -OwnerForm (Get-MainWindow))
    if (-not $script:reportOptions) { return }

    $picker = New-Object Microsoft.Win32.SaveFileDialog
    $picker.Filter = 'HTML report (*.html)|*.html'; $picker.FileName = "API_Test_Report_$((Get-Date).ToString('yyyyMMdd')).html"
    if ($picker.ShowDialog((Get-MainWindow)) -ne $true) { return }
    try {
        $data = @(Import-Csv $monitorLogFilePath)
        if ($data.Count -eq 0) { throw 'The log file is empty.' }
        New-MonitorReportHtml -Data $data -Options $script:reportOptions | Set-Content -Path $picker.FileName -Encoding UTF8
        Start-Process $picker.FileName
    } catch { Show-UiMessage "Failed to generate the report: $($_.Exception.Message)" 'Generate report' 'Error' }
}
#endregion

#region XAML network dialogs (WebSocket, gRPC, Load tester)

function Add-RichTextLine {
    param($Box, [string]$Text, [string]$Color = '')
    $paragraph = New-Object System.Windows.Documents.Paragraph
    $paragraph.Margin = [System.Windows.Thickness]::new(0)
    $run = New-Object System.Windows.Documents.Run($Text)
    if ($Color) { $run.Foreground = ConvertTo-WpfBrush $Color }
    [void]$paragraph.Inlines.Add($run)
    [void]$Box.Document.Blocks.Add($paragraph)
    $Box.ScrollToEnd()
}

function Get-RichTextContent {
    param($Box)
    return (New-Object System.Windows.Documents.TextRange($Box.Document.ContentStart, $Box.Document.ContentEnd)).Text
}

# ------------------------------------------------------------------------------------------------
# WebSocket client
# ------------------------------------------------------------------------------------------------

function Show-WebSocketDialog {
    $body = @'
  <Grid Margin="16,14,16,14">
    <Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="*"/><RowDefinition Height="Auto"/></Grid.RowDefinitions>
    <WrapPanel Margin="0,0,0,8">
      <TextBlock Text="URL" VerticalAlignment="Center" Margin="0,0,8,0"/>
      <TextBox x:Name="WsUrlBox" Width="340" Height="28" VerticalContentAlignment="Center" Text="wss://echo.websocket.org" Margin="0,0,8,0"/>
      <Button x:Name="ConnectButton" Style="{StaticResource PrimaryButton}" Padding="14,5" Margin="0,0,6,0" Content="Connect"/>
      <Button x:Name="DisconnectButton" Padding="14,5" Margin="0,0,14,0" Content="Disconnect" IsEnabled="False"/>
      <Button x:Name="SaveLogButton" Style="{StaticResource SmallButton}" Content="Save log"/>
      <Button x:Name="LoadLogButton" Style="{StaticResource SmallButton}" Content="Load log"/>
      <Button x:Name="ClearLogButton" Style="{StaticResource SmallButton}" Content="Clear log"/>
      <TextBlock x:Name="WsStatusText" VerticalAlignment="Center" Margin="8,0,0,0" Text="Status: Disconnected" Foreground="#B91C1C"/>
    </WrapPanel>
    <RichTextBox x:Name="WsLogBox" Grid.Row="1" IsReadOnly="True" FontFamily="Consolas" FontSize="12" VerticalScrollBarVisibility="Auto"/>
    <DockPanel Grid.Row="2" Margin="0,8,0,0">
      <Button x:Name="SendButton" DockPanel.Dock="Right" Style="{StaticResource PrimaryButton}" Width="90" Margin="8,0,0,0" Content="Send" IsEnabled="False"/>
      <TextBox x:Name="WsMessageBox" Height="30" VerticalContentAlignment="Center"/>
    </DockPanel>
  </Grid>
'@
    $names = 'WsUrlBox', 'ConnectButton', 'DisconnectButton', 'SaveLogButton', 'LoadLogButton', 'ClearLogButton', 'WsStatusText', 'WsLogBox', 'SendButton', 'WsMessageBox'
    $dialog = New-DialogWindow -BodyXaml $body -ControlNames $names -Title 'WebSocket client' -Width 820 -Height 620
    $window = $dialog.Window; $controls = $dialog.Controls
    $script:ws = New-Object System.Net.WebSockets.ClientWebSocket
    $script:wsBuffer = New-Object byte[] 8192
    $script:wsReceiveTask = $null
    $script:wsConnectTask = $null
    $script:wsMessage = New-Object System.Text.StringBuilder
    $stamp = { Get-Date -Format 'HH:mm:ss' }

    $setConnected = {
        param([bool]$Connected)
        $controls['ConnectButton'].IsEnabled = -not $Connected; $controls['DisconnectButton'].IsEnabled = $Connected; $controls['SendButton'].IsEnabled = $Connected
        $controls['WsStatusText'].Text = if ($Connected) { 'Status: Connected' } else { 'Status: Disconnected' }
        $controls['WsStatusText'].Foreground = if ($Connected) { [System.Windows.Media.Brushes]::SeaGreen } else { [System.Windows.Media.Brushes]::Firebrick }
    }
    $disconnect = {
        try { if ($script:ws.State -eq 'Open') { [void]$script:ws.CloseAsync([System.Net.WebSockets.WebSocketCloseStatus]::NormalClosure, 'User disconnect', [System.Threading.CancellationToken]::None) } } catch { }
        $script:wsReceiveTask = $null
        Add-RichTextLine -Box $controls['WsLogBox'] -Text "[$(& $stamp)] Disconnected"
        & $setConnected $false
    }

    $timer = New-Object System.Windows.Threading.DispatcherTimer
    $timer.Interval = [TimeSpan]::FromMilliseconds(100)
    $timer.Add_Tick({
        if ($script:wsConnectTask) {
            if (-not $script:wsConnectTask.IsCompleted) { return }
            $connectTask = $script:wsConnectTask; $script:wsConnectTask = $null
            if ($connectTask.IsFaulted -or $script:ws.State -ne 'Open') {
                $reason = if ($connectTask.IsFaulted) { $connectTask.Exception.GetBaseException().Message } else { 'The connection was not opened.' }
                Add-RichTextLine -Box $controls['WsLogBox'] -Text "[$(& $stamp)] Error connecting: $reason" -Color '#B91C1C'
                & $setConnected $false
            } else {
                Add-RichTextLine -Box $controls['WsLogBox'] -Text "[$(& $stamp)] Connected to $($controls['WsUrlBox'].Text)"
                & $setConnected $true
            }
            return
        }
        if ($script:ws.State -ne 'Open') { return }
        if (-not $script:wsReceiveTask) {
            $script:wsReceiveTask = $script:ws.ReceiveAsync([System.ArraySegment[byte]]::new($script:wsBuffer), [System.Threading.CancellationToken]::None)
        } elseif ($script:wsReceiveTask.IsCompleted) {
            $receiveTask = $script:wsReceiveTask; $script:wsReceiveTask = $null
            if ($receiveTask.IsFaulted) { Add-RichTextLine -Box $controls['WsLogBox'] -Text "[$(& $stamp)] Error receiving: $($receiveTask.Exception.GetBaseException().Message)" -Color '#B91C1C'; & $disconnect; return }
            $received = $receiveTask.Result
            if ($received.MessageType -eq 'Close') { & $disconnect; return }
            [void]$script:wsMessage.Append([System.Text.Encoding]::UTF8.GetString($script:wsBuffer, 0, $received.Count))
            if ($received.EndOfMessage) {
                Add-RichTextLine -Box $controls['WsLogBox'] -Text "[$(& $stamp)] Received: $($script:wsMessage.ToString())" -Color '#15803D'
                [void]$script:wsMessage.Clear()
            }
        }
    })
    $timer.Start()

    $controls['ConnectButton'].Add_Click({
        try {
            if ($script:ws.State -ne 'None') { $script:ws.Dispose(); $script:ws = New-Object System.Net.WebSockets.ClientWebSocket }
            $script:wsConnectTask = $script:ws.ConnectAsync((New-Object System.Uri($controls['WsUrlBox'].Text)), [System.Threading.CancellationToken]::None)
            $controls['WsStatusText'].Text = 'Status: Connecting...'; $controls['WsStatusText'].Foreground = [System.Windows.Media.Brushes]::DarkOrange
            $controls['ConnectButton'].IsEnabled = $false
        } catch { Add-RichTextLine -Box $controls['WsLogBox'] -Text "Error connecting: $($_.Exception.Message)" -Color '#B91C1C'; $controls['ConnectButton'].IsEnabled = $true }
    })
    $controls['DisconnectButton'].Add_Click({ & $disconnect })
    $send = {
        if ($script:ws.State -ne 'Open' -or -not $controls['WsMessageBox'].Text) { return }
        $bytes = [System.Text.Encoding]::UTF8.GetBytes($controls['WsMessageBox'].Text)
        [void]$script:ws.SendAsync([System.ArraySegment[byte]]::new($bytes), [System.Net.WebSockets.WebSocketMessageType]::Text, $true, [System.Threading.CancellationToken]::None)
        Add-RichTextLine -Box $controls['WsLogBox'] -Text "[$(& $stamp)] Sent: $($controls['WsMessageBox'].Text)" -Color '#2563EB'
        $controls['WsMessageBox'].Text = ''
    }
    $controls['SendButton'].Add_Click($send)
    $controls['WsMessageBox'].Add_KeyDown({ param($sender, $keyArgs) if ($keyArgs.Key -eq [System.Windows.Input.Key]::Return) { & $send; $keyArgs.Handled = $true } })
    $controls['SaveLogButton'].Add_Click({
        $picker = New-Object Microsoft.Win32.SaveFileDialog; $picker.Filter = 'Text files (*.txt)|*.txt'; $picker.FileName = 'websocket_log.txt'
        if ($picker.ShowDialog($window) -eq $true) { Get-RichTextContent -Box $controls['WsLogBox'] | Set-Content -Path $picker.FileName }
    })
    $controls['LoadLogButton'].Add_Click({
        $picker = New-Object Microsoft.Win32.OpenFileDialog; $picker.Filter = 'Text files (*.txt)|*.txt'
        if ($picker.ShowDialog($window) -ne $true) { return }
        $controls['WsLogBox'].Document.Blocks.Clear()
        foreach ($line in (Get-Content -Path $picker.FileName)) { Add-RichTextLine -Box $controls['WsLogBox'] -Text $line }
    })
    $controls['ClearLogButton'].Add_Click({
        if ([System.Windows.MessageBox]::Show($window, 'Clear the WebSocket log?', 'Confirm', 'YesNo', 'Question') -eq 'Yes') { $controls['WsLogBox'].Document.Blocks.Clear() }
    })
    $window.Add_Closing({ $timer.Stop(); try { $script:ws.Dispose() } catch { } })
    [void](Show-WpfDialog -Window $window -OwnerForm (Get-MainWindow))
}

# ------------------------------------------------------------------------------------------------
# gRPC client (wraps grpcurl)
# ------------------------------------------------------------------------------------------------

function Show-GrpcDialog {
    Import-GrpcHistory
    $body = @'
  <Grid Margin="16,14,16,14">
    <Grid.ColumnDefinitions><ColumnDefinition Width="260"/><ColumnDefinition Width="12"/><ColumnDefinition Width="*"/></Grid.ColumnDefinitions>
    <Grid>
      <Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="*"/><RowDefinition Height="Auto"/></Grid.RowDefinitions>
      <TextBlock Style="{StaticResource SectionLabel}" Text="HISTORY"/>
      <ListBox x:Name="GrpcHistoryList" Grid.Row="1" Margin="0,6,0,8"/>
      <Button x:Name="GrpcClearHistoryButton" Grid.Row="2" Padding="12,5" Content="Clear history"/>
    </Grid>
    <Grid Grid.Column="2">
      <Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="Auto"/><RowDefinition Height="Auto"/><RowDefinition Height="1*"/><RowDefinition Height="1.4*"/><RowDefinition Height="Auto"/><RowDefinition Height="Auto"/><RowDefinition Height="1.6*"/></Grid.RowDefinitions>
      <Grid.ColumnDefinitions><ColumnDefinition Width="90"/><ColumnDefinition Width="*"/></Grid.ColumnDefinitions>
      <TextBlock Text="Host" VerticalAlignment="Center"/><TextBox x:Name="GrpcHostBox" Grid.Column="1" Height="28" VerticalContentAlignment="Center" Margin="0,3" Text="localhost:50051"/>
      <TextBlock Grid.Row="1" Text="Proto file" VerticalAlignment="Center"/>
      <DockPanel Grid.Row="1" Grid.Column="1" Margin="0,3"><Button x:Name="GrpcBrowseProtoButton" DockPanel.Dock="Right" Margin="6,0,0,0" Padding="12,3" Content="Browse"/><TextBox x:Name="GrpcProtoBox" Height="28" VerticalContentAlignment="Center" ToolTip="Optional: path to a .proto file"/></DockPanel>
      <TextBlock Grid.Row="2" Text="Method" VerticalAlignment="Center"/><TextBox x:Name="GrpcMethodBox" Grid.Row="2" Grid.Column="1" Height="28" VerticalContentAlignment="Center" Margin="0,3" Text="MyService/SayHello"/>
      <TextBlock Grid.Row="3" Text="Headers" Margin="0,6,0,0"/><TextBox x:Name="GrpcHeadersBox" Grid.Row="3" Grid.Column="1" Margin="0,3" AcceptsReturn="True" FontFamily="Consolas" VerticalScrollBarVisibility="Auto" ToolTip="Name: value, one per line"/>
      <TextBlock Grid.Row="4" Text="JSON body" Margin="0,6,0,0"/><TextBox x:Name="GrpcBodyBox" Grid.Row="4" Grid.Column="1" Margin="0,3" AcceptsReturn="True" FontFamily="Consolas" VerticalScrollBarVisibility="Auto"/>
      <CheckBox x:Name="GrpcPlaintextBox" Grid.Row="5" Grid.Column="1" Content="Use plaintext (no TLS)" IsChecked="True" Margin="0,6"/>
      <WrapPanel Grid.Row="6" Grid.ColumnSpan="2" Margin="0,4,0,6">
        <Button x:Name="GrpcExecuteButton" Style="{StaticResource PrimaryButton}" Padding="18,6" Margin="0,0,8,0" Content="Execute gRPC"/>
        <Button x:Name="GrpcBeautifyButton" Padding="14,6" Margin="0,0,8,0" Content="Beautify JSON"/>
        <Button x:Name="GrpcDownloadButton" Padding="14,6" Content="Download grpcurl"/>
      </WrapPanel>
      <TextBox x:Name="GrpcOutputBox" Grid.Row="7" Grid.ColumnSpan="2" IsReadOnly="True" FontFamily="Consolas" VerticalScrollBarVisibility="Auto" HorizontalScrollBarVisibility="Auto"/>
    </Grid>
  </Grid>
'@
    $names = 'GrpcHistoryList', 'GrpcClearHistoryButton', 'GrpcHostBox', 'GrpcBrowseProtoButton', 'GrpcProtoBox', 'GrpcMethodBox', 'GrpcHeadersBox', 'GrpcBodyBox', 'GrpcPlaintextBox', 'GrpcExecuteButton', 'GrpcBeautifyButton', 'GrpcDownloadButton', 'GrpcOutputBox'
    $dialog = New-DialogWindow -BodyXaml $body -ControlNames $names -Title 'gRPC client (via grpcurl)' -Width 1100 -Height 760
    $window = $dialog.Window; $controls = $dialog.Controls
    $controls['GrpcBodyBox'].Text = '{ "name": "World" }'

    $refreshHistory = {
        $controls['GrpcHistoryList'].Items.Clear()
        foreach ($entry in @($script:grpcHistory | Where-Object { $_ })) {
            $time = ConvertTo-HistoryTime -Timestamp $entry.Timestamp
            $item = New-Object System.Windows.Controls.ListBoxItem
            $item.Content = "$(if ($time) { $time.ToString('HH:mm:ss') } else { '??:??:??' }) | $($entry.Method)"
            $item.Tag = $entry
            [void]$controls['GrpcHistoryList'].Items.Add($item)
        }
    }
    & $refreshHistory
    $controls['GrpcHistoryList'].Add_SelectionChanged({
        $selected = $controls['GrpcHistoryList'].SelectedItem
        if (-not $selected) { return }
        $entry = $selected.Tag
        $controls['GrpcHostBox'].Text = [string]$entry.Host; $controls['GrpcMethodBox'].Text = [string]$entry.Method
        $controls['GrpcHeadersBox'].Text = [string]$entry.Headers; $controls['GrpcBodyBox'].Text = [string]$entry.Body; $controls['GrpcPlaintextBox'].IsChecked = [bool]$entry.Plaintext
    })
    $controls['GrpcClearHistoryButton'].Add_Click({
        if ([System.Windows.MessageBox]::Show($window, 'Clear gRPC history?', 'Confirm', 'YesNo', 'Question') -ne 'Yes') { return }
        $script:grpcHistory = @(); Save-GrpcHistory; & $refreshHistory
    })
    $controls['GrpcBrowseProtoButton'].Add_Click({
        $picker = New-Object Microsoft.Win32.OpenFileDialog; $picker.Filter = 'Proto files (*.proto)|*.proto|All files (*.*)|*.*'
        if ($picker.ShowDialog($window) -eq $true) { $controls['GrpcProtoBox'].Text = $picker.FileName }
    })
    $controls['GrpcBeautifyButton'].Add_Click({
        if ([string]::IsNullOrWhiteSpace($controls['GrpcOutputBox'].Text)) { return }
        try { $controls['GrpcOutputBox'].Text = Format-JsonText -Text $controls['GrpcOutputBox'].Text } catch { $controls['GrpcOutputBox'].Text += "`r`nInvalid JSON: $($_.Exception.Message)" }
    })

    $controls['GrpcDownloadButton'].Add_Click({
        try {
            $controls['GrpcOutputBox'].Text = 'Checking for the latest grpcurl release...'; Update-UiNow
            $latest = Invoke-RestMethod 'https://api.github.com/repos/fullstorydev/grpcurl/releases/latest'
            $asset = $latest.assets | Where-Object { $_.name -match 'windows_x86_64.zip' } | Select-Object -First 1
            if (-not $asset) { throw 'Could not find a Windows x64 asset in the latest release.' }
            $zipPath = Join-Path $env:TEMP $asset.name
            $controls['GrpcOutputBox'].AppendText("`r`nDownloading $($asset.browser_download_url)..."); Update-UiNow
            Invoke-WebRequest -Uri $asset.browser_download_url -OutFile $zipPath
            Expand-Archive -Path $zipPath -DestinationPath $scriptRoot -Force
            Remove-Item $zipPath -ErrorAction SilentlyContinue
            $controls['GrpcOutputBox'].AppendText("`r`nDone. grpcurl.exe was installed to $scriptRoot.")
        } catch { $controls['GrpcOutputBox'].AppendText("`r`nError: $($_.Exception.Message)") }
    })

    # Runs grpcurl without blocking the window: a timer waits for the process and its output readers.
    $script:grpcProcess = $null
    $grpcTimer = New-Object System.Windows.Threading.DispatcherTimer
    $grpcTimer.Interval = [TimeSpan]::FromMilliseconds(150)
    $grpcTimer.Add_Tick({
        if (-not $script:grpcProcess -or -not $script:grpcProcess.Process.HasExited) { return }
        $grpcTimer.Stop()
        $out = $script:grpcProcess.StdOut.Result; $err = $script:grpcProcess.StdErr.Result
        $script:grpcProcess = $null
        $controls['GrpcOutputBox'].Text = if ($err) { "STDERR:`r`n$err`r`nSTDOUT:`r`n$out" } else { $out }
        $controls['GrpcExecuteButton'].IsEnabled = $true
    })
    $controls['GrpcExecuteButton'].Add_Click({
        $hostAddress = $controls['GrpcHostBox'].Text; $method = $controls['GrpcMethodBox'].Text
        $historyItem = [PSCustomObject]@{ Timestamp = Get-Date; Host = $hostAddress; Method = $method; Headers = $controls['GrpcHeadersBox'].Text; Body = $controls['GrpcBodyBox'].Text; Plaintext = [bool]$controls['GrpcPlaintextBox'].IsChecked }
        $script:grpcHistory = @($historyItem) + @($script:grpcHistory | Where-Object { $_ })
        if ($script:grpcHistory.Count -gt 50) { $script:grpcHistory = @($script:grpcHistory[0..49]) }
        Save-GrpcHistory; & $refreshHistory

        $arguments = @()
        if ($controls['GrpcPlaintextBox'].IsChecked) { $arguments += '-plaintext' }
        $protoPath = $controls['GrpcProtoBox'].Text
        if (-not [string]::IsNullOrWhiteSpace($protoPath) -and (Test-Path $protoPath)) { $arguments += '-import-path', "`"$(Split-Path $protoPath)`"", '-proto', "`"$(Split-Path $protoPath -Leaf)`"" }
        foreach ($line in ($controls['GrpcHeadersBox'].Text -split "`r?`n")) { if ($line -match '^\s*(.+?):\s*(.+)$') { $arguments += '-H', "`"$($Matches[1]): $($Matches[2])`"" } }
        $arguments += '-d', "`"$($controls['GrpcBodyBox'].Text.Replace('"', '\"'))`"", $hostAddress, $method

        $executable = 'grpcurl'
        $localPath = Join-Path $scriptRoot 'grpcurl.exe'
        if (Test-Path $localPath) { $executable = $localPath }
        elseif (-not (Get-Command 'grpcurl' -ErrorAction SilentlyContinue -CommandType Application)) {
            $controls['GrpcOutputBox'].Text = "Error: 'grpcurl' was not found.`r`nUse 'Download grpcurl', or place grpcurl.exe in:`r`n$scriptRoot`r`nor add it to your PATH."
            return
        }
        try {
            $startInfo = New-Object System.Diagnostics.ProcessStartInfo
            $startInfo.FileName = $executable; $startInfo.Arguments = $arguments -join ' '
            $startInfo.RedirectStandardOutput = $true; $startInfo.RedirectStandardError = $true; $startInfo.UseShellExecute = $false; $startInfo.CreateNoWindow = $true
            $process = [System.Diagnostics.Process]::Start($startInfo)
            $script:grpcProcess = @{ Process = $process; StdOut = $process.StandardOutput.ReadToEndAsync(); StdErr = $process.StandardError.ReadToEndAsync() }
            $controls['GrpcOutputBox'].Text = 'Executing...'; $controls['GrpcExecuteButton'].IsEnabled = $false
            $grpcTimer.Start()
        } catch { $controls['GrpcOutputBox'].Text = "Error executing grpcurl: $($_.Exception.Message)" }
    })
    $window.Add_Closing({ $grpcTimer.Stop() })
    [void](Show-WpfDialog -Window $window -OwnerForm (Get-MainWindow))
}

# ------------------------------------------------------------------------------------------------
# Load tester (concurrent async requests driven by a UI timer - no runspaces needed)
# ------------------------------------------------------------------------------------------------

function Show-LoadTestDialog {
    param($RequestObject = $null)
    $body = @'
  <Grid Margin="16,14,16,14">
    <Grid.ColumnDefinitions><ColumnDefinition Width="300"/><ColumnDefinition Width="14"/><ColumnDefinition Width="*"/></Grid.ColumnDefinitions>
    <Grid.RowDefinitions><RowDefinition Height="*"/><RowDefinition Height="Auto"/></Grid.RowDefinitions>
    <ScrollViewer VerticalScrollBarVisibility="Auto"><StackPanel>
      <TextBlock Style="{StaticResource SectionLabel}" Text="URL"/><TextBox x:Name="LtUrlBox" Height="28" Margin="0,4,0,8" VerticalContentAlignment="Center"/>
      <TextBlock Style="{StaticResource SectionLabel}" Text="METHOD"/><ComboBox x:Name="LtMethodBox" Height="28" Margin="0,4,0,8" VerticalContentAlignment="Center"/>
      <TextBlock Style="{StaticResource SectionLabel}" Text="HEADERS"/><TextBox x:Name="LtHeadersBox" Height="70" Margin="0,4,0,8" AcceptsReturn="True" FontFamily="Consolas" VerticalScrollBarVisibility="Auto"/>
      <TextBlock Style="{StaticResource SectionLabel}" Text="BODY"/><TextBox x:Name="LtBodyBox" Height="70" Margin="0,4,0,8" AcceptsReturn="True" FontFamily="Consolas" VerticalScrollBarVisibility="Auto"/>
      <TextBlock Style="{StaticResource SectionLabel}" Text="CONCURRENT THREADS (1-100)"/><TextBox x:Name="LtThreadsBox" Height="28" Margin="0,4,0,8" VerticalContentAlignment="Center" Text="10"/>
      <TextBlock Style="{StaticResource SectionLabel}" Text="DURATION (SECONDS)"/><TextBox x:Name="LtDurationBox" Height="28" Margin="0,4,0,12" VerticalContentAlignment="Center" Text="5"/>
      <TextBlock x:Name="LtRequestsText" Text="Requests: 0"/><TextBlock x:Name="LtSuccessText" Text="Success: 0"/><TextBlock x:Name="LtFailedText" Text="Failed: 0"/><TextBlock x:Name="LtLatencyText" Text="Avg latency: 0 ms"/><TextBlock x:Name="LtMessageText" Margin="0,6,0,0" Foreground="#B91C1C" TextWrapping="Wrap"/>
    </StackPanel></ScrollViewer>
    <Border Grid.Column="2" Background="{StaticResource Surface}" BorderBrush="{StaticResource Border}" BorderThickness="1" CornerRadius="6"><Canvas x:Name="LtChart" ClipToBounds="True"/></Border>
    <StackPanel Grid.Row="1" Grid.ColumnSpan="3" Orientation="Horizontal" HorizontalAlignment="Right" Margin="0,12,0,0">
      <Button x:Name="LtStartButton" Style="{StaticResource PrimaryButton}" Width="120" Content="Start test"/>
      <Button x:Name="LtStopButton" Width="100" Margin="8,0,0,0" Content="Stop" IsEnabled="False"/>
      <Button x:Name="LtCloseButton" IsCancel="True" Width="90" Margin="8,0,0,0" Content="Close"/>
    </StackPanel>
  </Grid>
'@
    $names = 'LtUrlBox', 'LtMethodBox', 'LtHeadersBox', 'LtBodyBox', 'LtThreadsBox', 'LtDurationBox', 'LtRequestsText', 'LtSuccessText', 'LtFailedText', 'LtLatencyText', 'LtMessageText', 'LtChart', 'LtStartButton', 'LtStopButton', 'LtCloseButton'
    $dialog = New-DialogWindow -BodyXaml $body -ControlNames $names -Title 'Load tester' -Width 1000 -Height 640
    $window = $dialog.Window; $controls = $dialog.Controls
    foreach ($method in @('GET', 'POST', 'PUT', 'DELETE', 'PATCH')) { [void]$controls['LtMethodBox'].Items.Add($method) }
    $controls['LtUrlBox'].Text = if ($RequestObject -and $RequestObject.Url) { [string]$RequestObject.Url } else { 'https://httpbin.org/get' }
    $controls['LtMethodBox'].SelectedItem = if ($RequestObject -and $RequestObject.Method -and $controls['LtMethodBox'].Items.Contains([string]$RequestObject.Method)) { [string]$RequestObject.Method } else { 'GET' }
    if ($RequestObject -and $RequestObject.Headers) {
        $controls['LtHeadersBox'].Text = if ($RequestObject.Headers -is [string]) { $RequestObject.Headers } else { (@($RequestObject.Headers.GetEnumerator() | ForEach-Object { "$($_.Name): $($_.Value)" }) -join "`r`n") }
    }
    if ($RequestObject -and $RequestObject.Body) { $controls['LtBodyBox'].Text = [string]$RequestObject.Body }
    $controls['LtChart'].SetResourceReference([System.Windows.Controls.Panel]::BackgroundProperty, 'Surface')

    $script:loadTest = @{ Running = $false; Client = $null; InFlight = (New-Object System.Collections.ArrayList); Total = 0; Success = 0; Failed = 0; LatencySum = 0.0
        Start = $null; End = $null; Threads = 10; LastSample = [datetime]::MinValue; X = (New-Object System.Collections.ArrayList); Rps = (New-Object System.Collections.ArrayList); Lat = (New-Object System.Collections.ArrayList) }

    $drawChart = {
        Update-LineChart -Canvas $controls['LtChart'] -Series @(
            @{ Name = 'Requests/sec'; Color = '#3659C9'; X = @($script:loadTest.X); Y = @($script:loadTest.Rps); Axis = 'Left' },
            @{ Name = 'Latency (ms)'; Color = '#F97316'; X = @($script:loadTest.X); Y = @($script:loadTest.Lat); Axis = 'Right' }) -LeftTitle 'Requests/sec' -RightTitle 'Latency (ms)' -EmptyText 'Start a test to see throughput and latency.'
    }
    $controls['LtChart'].Add_SizeChanged({ & $drawChart })

    $newMessage = {
        $message = New-Object System.Net.Http.HttpRequestMessage([System.Net.Http.HttpMethod]::new($script:loadTest.Method), $script:loadTest.Url)
        $content = $null
        if ($script:loadTest.Body -and $script:loadTest.Method -in @('POST', 'PUT', 'PATCH', 'DELETE')) {
            $contentType = 'application/json'
            foreach ($entry in $script:loadTest.Headers) { if ($entry.Name -ieq 'Content-Type') { $contentType = ($entry.Value -split ';')[0].Trim() } }
            try { $content = New-Object System.Net.Http.StringContent($script:loadTest.Body, [System.Text.Encoding]::UTF8, $contentType) } catch { $content = New-Object System.Net.Http.StringContent($script:loadTest.Body) }
            $message.Content = $content
        }
        foreach ($entry in $script:loadTest.Headers) {
            if ($entry.Name -ieq 'Content-Type') { continue }
            if (-not $message.Headers.TryAddWithoutValidation($entry.Name, $entry.Value) -and $content) { [void]$content.Headers.TryAddWithoutValidation($entry.Name, $entry.Value) }
        }
        return $message
    }
    $updateStats = {
        $test = $script:loadTest
        $average = if ($test.Total -gt 0) { [Math]::Round($test.LatencySum / $test.Total, 2) } else { 0 }
        $controls['LtRequestsText'].Text = "Requests: $($test.Total)"; $controls['LtSuccessText'].Text = "Success: $($test.Success)"; $controls['LtFailedText'].Text = "Failed: $($test.Failed)"; $controls['LtLatencyText'].Text = "Avg latency: $average ms"
        return $average
    }
    $finish = {
        $script:loadTestTimer.Stop()
        foreach ($flight in $script:loadTest.InFlight) { try { $flight.Message.Dispose() } catch { } }
        $script:loadTest.InFlight.Clear()
        try { if ($script:loadTest.Client) { $script:loadTest.Client.Dispose() } } catch { }
        $script:loadTest.Running = $false
        $controls['LtStartButton'].IsEnabled = $true; $controls['LtStopButton'].IsEnabled = $false
        & $drawChart
    }

    $script:loadTestTimer = New-Object System.Windows.Threading.DispatcherTimer
    $script:loadTestTimer.Interval = [TimeSpan]::FromMilliseconds(40)
    $script:loadTestTimer.Add_Tick({
        $test = $script:loadTest
        if (-not $test.Running) { return }
        foreach ($flight in @($test.InFlight)) {
            if (-not $flight.Task.IsCompleted) { continue }
            [void]$test.InFlight.Remove($flight)
            $flight.Stopwatch.Stop()
            $test.Total++; $test.LatencySum += $flight.Stopwatch.ElapsedMilliseconds
            if (-not $flight.Task.IsFaulted -and -not $flight.Task.IsCanceled -and $flight.Task.Result.IsSuccessStatusCode) { $test.Success++ } else { $test.Failed++ }
            try { if ($flight.Task.Status -eq 'RanToCompletion') { $flight.Task.Result.Dispose() }; $flight.Message.Dispose() } catch { }
        }
        $now = [datetime]::Now
        if ($now -lt $test.End) {
            while ($test.InFlight.Count -lt $test.Threads) {
                $message = & $newMessage
                $stopwatch = [System.Diagnostics.Stopwatch]::StartNew()
                [void]$test.InFlight.Add(@{ Task = $test.Client.SendAsync($message); Message = $message; Stopwatch = $stopwatch })
            }
        }
        if (($now - $test.LastSample).TotalSeconds -ge 1) {
            $test.LastSample = $now
            $average = & $updateStats
            $elapsed = ($now - $test.Start).TotalSeconds
            [void]$test.X.Add($elapsed); [void]$test.Rps.Add($(if ($elapsed -gt 0) { [Math]::Round($test.Total / $elapsed, 2) } else { 0 })); [void]$test.Lat.Add($average)
            & $drawChart
        }
        if ($now -ge $test.End -and $test.InFlight.Count -eq 0) { [void](& $updateStats); & $finish }
    })

    $controls['LtStartButton'].Add_Click({
        $threads = 0; $duration = 0
        if (-not [int]::TryParse($controls['LtThreadsBox'].Text, [ref]$threads) -or $threads -lt 1 -or $threads -gt 100) { $controls['LtMessageText'].Text = 'Threads must be 1-100.'; return }
        if (-not [int]::TryParse($controls['LtDurationBox'].Text, [ref]$duration) -or $duration -lt 1 -or $duration -gt 3600) { $controls['LtMessageText'].Text = 'Duration must be 1-3600 seconds.'; return }
        if ([string]::IsNullOrWhiteSpace($controls['LtUrlBox'].Text)) { $controls['LtMessageText'].Text = 'Enter a URL.'; return }
        $controls['LtMessageText'].Text = ''
        Add-Type -AssemblyName System.Net.Http
        if ($script:settings.IgnoreSslErrors) { Enable-TrustAllCertificates }
        $client = New-Object System.Net.Http.HttpClient((New-Object System.Net.Http.HttpClientHandler))
        $client.Timeout = [TimeSpan]::FromSeconds(30)
        $url = (Expand-Variables -InputString $controls['LtUrlBox'].Text).Trim()
        if ($url -notmatch '^[a-zA-Z][a-zA-Z0-9+.-]*://') { $url = "https://$url" }
        $script:loadTest = @{ Running = $true; Client = $client; InFlight = (New-Object System.Collections.ArrayList); Total = 0; Success = 0; Failed = 0; LatencySum = 0.0
            Start = [datetime]::Now; End = [datetime]::Now.AddSeconds($duration); Threads = $threads; LastSample = [datetime]::Now; X = (New-Object System.Collections.ArrayList)
            Rps = (New-Object System.Collections.ArrayList); Lat = (New-Object System.Collections.ArrayList); Url = $url; Method = [string]$controls['LtMethodBox'].SelectedItem
            Headers = @(ConvertFrom-HeaderText -HeaderText (Expand-Variables -InputString $controls['LtHeadersBox'].Text)); Body = (Expand-Variables -InputString $controls['LtBodyBox'].Text) }
        $controls['LtStartButton'].IsEnabled = $false; $controls['LtStopButton'].IsEnabled = $true
        $script:loadTestTimer.Start()
    })
    # Stop: no new requests are started; the test finishes when the in-flight ones complete.
    $controls['LtStopButton'].Add_Click({ if ($script:loadTest.Running) { $script:loadTest.End = [datetime]::Now.AddSeconds(-1) } })
    $window.Add_Closing({ try { $script:loadTestTimer.Stop(); if ($script:loadTest.Client) { $script:loadTest.Client.Dispose() } } catch { } })
    [void](Show-WpfDialog -Window $window -OwnerForm (Get-MainWindow))
}
#endregion

#region XAML monitor UI (engine, manager, editor, email settings, dashboard, chart)

function Set-ObjectProperty {
    param($Object, [string]$Name, $Value)
    if ($Object -is [System.Collections.IDictionary]) { $Object[$Name] = $Value }
    else { $Object | Add-Member -MemberType NoteProperty -Name $Name -Value $Value -Force }
}

# ------------------------------------------------------------------------------------------------
# Background monitor service (-RunMonitors): runs the monitors with no window, only a tray icon.
# Only one runner is active at a time: while the service is running the app's own engine stays idle, and
# edits made in the Monitor Manager (start/stop/add/edit) are picked up by the service from the monitors file.
# ------------------------------------------------------------------------------------------------

$script:MonitorServiceMutexName = 'Global\APITester.MonitorService'
$script:MonitorServiceStopEventName = 'Global\APITester.MonitorService.Stop'
$script:monitorLastResult = @{}
$script:backgroundEmails = New-Object System.Collections.ArrayList

function Get-MonitorStatusFilePath { return (Join-Path $configDir 'api_tester_monitor_status.json') }

function Test-MonitorServiceRunning {
    param([switch]$NoCache)
    if ($script:isMonitorService) { return $false }
    $now = [datetime]::UtcNow
    if (-not $NoCache -and $script:serviceCheckTime -and ($now - $script:serviceCheckTime).TotalSeconds -lt 3) { return [bool]$script:serviceRunningCached }
    $script:serviceCheckTime = $now
    $mutex = $null
    $running = $false
    try { $running = [System.Threading.Mutex]::TryOpenExisting($script:MonitorServiceMutexName, [ref]$mutex) }
    catch [System.UnauthorizedAccessException] { $running = $true }   # exists but belongs to another account (scheduled task)
    catch { $running = $false }
    if ($mutex) { $mutex.Dispose() }
    $script:serviceRunningCached = $running
    return $running
}

function Get-MonitorServiceLaunch {
    $hostPath = (Get-Process -Id $PID).Path
    $arguments = "-NoProfile -STA -WindowStyle Hidden -ExecutionPolicy Bypass -File `"$PSCommandPath`" -RunMonitors"
    return @{ HostPath = $hostPath; Arguments = $arguments }
}

function Start-MonitorService {
    if (Test-MonitorServiceRunning -NoCache) { return $true }
    $launch = Get-MonitorServiceLaunch
    Start-Process -FilePath $launch.HostPath -ArgumentList $launch.Arguments -WindowStyle Hidden
    # Hand over immediately: stop anything the app is running so nothing is sent twice.
    foreach ($run in @($script:monitorRuns.Values)) { try { $run.State.Cancellation.Cancel() } catch { } }
    $script:monitorRuns = @{}
    $script:serviceRunningCached = $true; $script:serviceCheckTime = [datetime]::UtcNow
    Write-Log 'Background monitor service started.' -Level Info
    return $true
}

function Stop-MonitorService {
    $task = Get-MonitorScheduledTask
    if ($task -and $task.State -eq 'Running') { try { Stop-ScheduledTask -TaskName $script:MonitorTaskName -ErrorAction Stop } catch { Write-Log "Could not stop the scheduled task: $($_.Exception.Message)" -Level Info } }
    try {
        $stopEvent = $null
        if ([System.Threading.EventWaitHandle]::TryOpenExisting($script:MonitorServiceStopEventName, [ref]$stopEvent)) { [void]$stopEvent.Set(); $stopEvent.Dispose() }
    } catch { }
    $script:serviceRunningCached = $false; $script:serviceCheckTime = $null
    Write-Log 'Background monitor service stop requested.' -Level Info
}

# Windows sign-in auto-start, through a shortcut in the user's Startup folder (no admin rights needed).
function Get-MonitorAutoStartPath { return (Join-Path ([Environment]::GetFolderPath('Startup')) 'API Tester Monitors.lnk') }
function Test-MonitorAutoStart { return (Test-Path (Get-MonitorAutoStartPath)) }
function Set-MonitorAutoStart {
    param([bool]$Enabled)
    $shortcutPath = Get-MonitorAutoStartPath
    if (-not $Enabled) { Remove-Item $shortcutPath -Force -ErrorAction SilentlyContinue; return }
    $launch = Get-MonitorServiceLaunch
    $shell = New-Object -ComObject WScript.Shell
    $shortcut = $shell.CreateShortcut($shortcutPath)
    $shortcut.TargetPath = $launch.HostPath
    $shortcut.Arguments = $launch.Arguments
    $shortcut.WorkingDirectory = Split-Path $PSCommandPath
    $shortcut.WindowStyle = 7
    $shortcut.Description = 'Runs the API Tester monitors in the background'
    $shortcut.Save()
}

# Status written by the service so the Monitor Manager can show last run / last result.
function Save-MonitorStatus {
    param([switch]$Force)
    if (-not $Force -and $script:monitorStatusSaved -and ([datetime]::Now - $script:monitorStatusSaved).TotalSeconds -lt 5) { return }
    $script:monitorStatusSaved = [datetime]::Now
    try {
        $entries = @{}
        foreach ($monitor in @($script:monitors | Where-Object { $_ })) {
            $entries[[string]$monitor.Id] = @{ LastRun = $(if ($monitor.LastRun) { ([datetime]$monitor.LastRun).ToString('o') } else { '' }); LastResult = [string]$script:monitorLastResult[[string]$monitor.Id] }
        }
        @{ Updated = (Get-Date).ToString('o'); ProcessId = $PID; Monitors = $entries } | ConvertTo-Json -Depth 4 | Set-Content -Path (Get-MonitorStatusFilePath) -Encoding UTF8
    } catch { }
}

function Get-MonitorServiceStatus {
    try {
        $path = Get-MonitorStatusFilePath
        if (Test-Path $path) { return (ConvertFrom-JsonToHashtable -Json (Get-Content -Path $path -Raw)) }
    } catch { }
    return $null
}

# Reloads the monitors file (edited by the app) while keeping the in-memory last-run times.
function Update-MonitorsFromDisk {
    $lastRuns = @{}
    foreach ($monitor in @($script:monitors | Where-Object { $_ })) { $lastRuns[[string]$monitor.Id] = $monitor.LastRun }
    Import-Monitors
    foreach ($monitor in @($script:monitors | Where-Object { $_ })) {
        if ($lastRuns.ContainsKey([string]$monitor.Id) -and $lastRuns[[string]$monitor.Id]) { Set-ObjectProperty -Object $monitor -Name 'LastRun' -Value $lastRuns[[string]$monitor.Id] }
    }
}

function Invoke-MonitorService {
    $script:isMonitorService = $true
    Import-Settings; Import-Globals; Import-Environments; Import-Collections; Import-Monitors
    $createdNew = $false
    try { $mutex = New-Object System.Threading.Mutex($true, $script:MonitorServiceMutexName, [ref]$createdNew) }
    catch { $mutex = New-Object System.Threading.Mutex($true, ($script:MonitorServiceMutexName -replace '^Global', 'Local'), [ref]$createdNew) }
    if (-not $createdNew) { Write-Host 'The API Tester background monitor service is already running.'; $mutex.Dispose(); return }
    try { $stopEvent = New-Object System.Threading.EventWaitHandle($false, [System.Threading.EventResetMode]::ManualReset, $script:MonitorServiceStopEventName) }
    catch { $stopEvent = New-Object System.Threading.EventWaitHandle($false, [System.Threading.EventResetMode]::ManualReset, ($script:MonitorServiceStopEventName -replace '^Global', 'Local')) }
    $script:monitorRuns = @{}
    $script:monitorServiceStopRequested = $false

    Initialize-MonitorHistory
    Initialize-MonitorTray -Mode 'Service'
    $runningCount = @($script:monitors | Where-Object { $_ -and $_.Status -eq 'Running' }).Count
    Show-MonitorBalloon -Title 'API Tester monitors are running' -Message "$runningCount monitor(s) active in the background. Double-click the tray icon to open API Tester, right-click for monitors and options." -Kind 'Info'
    Write-Log "Background monitor service started ($runningCount active monitors)." -Level Info

    $monitorsStamp = if (Test-Path $monitorsFilePath) { (Get-Item $monitorsFilePath).LastWriteTimeUtc } else { $null }
    try {
        while (-not $script:monitorServiceStopRequested -and -not $stopEvent.WaitOne(0)) {
            [System.Windows.Forms.Application]::DoEvents()
            try {
                $stamp = if (Test-Path $monitorsFilePath) { (Get-Item $monitorsFilePath).LastWriteTimeUtc } else { $null }
                if ($stamp -ne $monitorsStamp) { $monitorsStamp = $stamp; Update-MonitorsFromDisk }
                Step-MonitorEngine
                Save-MonitorStatus
            } catch { Write-Log "Background monitor error: $($_.Exception.Message)" -Level Error }
            Start-Sleep -Milliseconds 250
        }
    } finally {
        foreach ($run in @($script:monitorRuns.Values)) { try { $run.State.Cancellation.Cancel() } catch { } }
        Save-MonitorStatus -Force
        Stop-MonitorWebServer
        try { $script:notifyIcon.Visible = $false; $script:notifyIcon.Dispose() } catch { }
        try { $stopEvent.Dispose() } catch { }
        try { $mutex.ReleaseMutex(); $mutex.Dispose() } catch { }
        Write-Log 'Background monitor service stopped.' -Level Info
    }
}

# Sends an alert email on a background runspace so a slow SMTP server never pauses the window or the service.
function Send-MonitorEmailInBackground {
    param([string]$To, [string]$Subject, [string]$Body)
    if ($script:settings.MonitorSmtpAuthMethod -eq 'OAuth2' -and $script:settings.MonitorSmtpRefreshToken -and $script:settings.MonitorSmtpTokenEndpoint) {
        $refresh = $false
        if ($script:settings.MonitorSmtpTokenExpiry) { if ([DateTime]::UtcNow -ge [DateTime]$script:settings.MonitorSmtpTokenExpiry) { $refresh = $true } }
        elseif (-not $script:settings.MonitorSmtpPass) { $refresh = $true }
        if ($refresh) { Update-SmtpToken }
    }
    $isHtml = [bool]($script:settings.MonitorAlertBodyForceHtml -or (Test-IsHtmlBody -Body $Body))
    $worker = [PowerShell]::Create()
    [void]$worker.AddScript({
        param($Settings, $To, $Subject, $Body, $IsHtml, $OAuthFunctionText)
        if ($Settings.MonitorSmtpAuthMethod -eq 'OAuth2') {
            . ([scriptblock]::Create("function Send-SmtpOAuth2 {`n$OAuthFunctionText`n}"))
            Send-SmtpOAuth2 -Server $Settings.MonitorSmtpServer -Port $Settings.MonitorSmtpPort -UseSsl $Settings.MonitorSmtpUseSsl -From $Settings.MonitorSmtpFrom -To $To -Subject $Subject -Body $Body -User $Settings.MonitorSmtpUser -AccessToken $Settings.MonitorSmtpPass -IsHtml:$IsHtml
        } else {
            $parameters = @{ SmtpServer = $Settings.MonitorSmtpServer; Port = $Settings.MonitorSmtpPort; UseSsl = [bool]$Settings.MonitorSmtpUseSsl; From = $Settings.MonitorSmtpFrom; To = $To; Subject = $Subject; Body = $Body; BodyAsHtml = $IsHtml }
            if ($Settings.MonitorSmtpUser) { $parameters.Credential = New-Object System.Management.Automation.PSCredential($Settings.MonitorSmtpUser, ($Settings.MonitorSmtpPass | ConvertTo-SecureString -AsPlainText -Force)) }
            Send-MailMessage @parameters -ErrorAction Stop
        }
    }).AddArgument($script:settings.Clone()).AddArgument($To).AddArgument($Subject).AddArgument($Body).AddArgument($isHtml).AddArgument([string]${function:Send-SmtpOAuth2})
    [void]$script:backgroundEmails.Add(@{ Worker = $worker; Handle = $worker.BeginInvoke(); To = $To })
}

function Update-BackgroundEmails {
    foreach ($job in @($script:backgroundEmails)) {
        if (-not $job.Handle.IsCompleted) { continue }
        try {
            [void]$job.Worker.EndInvoke($job.Handle)
            if ($job.Worker.HadErrors) { Write-Log "Failed to send email alert to $($job.To): $(@($job.Worker.Streams.Error)[0])" -Level Info }
        } catch { Write-Log "Failed to send email alert to $($job.To): $($_.Exception.Message)" -Level Info }
        finally { $job.Worker.Dispose(); [void]$script:backgroundEmails.Remove($job) }
    }
}

# ------------------------------------------------------------------------------------------------
# Live monitor dashboard in the browser (http://127.0.0.1:<port>/, loopback only)
# Served by whichever runner is active (the app or the background service). The HTTP server runs on its own
# runspace, so a slow or idle browser connection never blocks the window or the monitor loop; the runner only
# publishes a JSON snapshot into a synchronized table once per second.
# ------------------------------------------------------------------------------------------------

$script:monitorHistory = @{}

function Get-MonitorDashboardUrl {
    $port = if ([int]$script:settings.MonitorDashboardPort -gt 0) { [int]$script:settings.MonitorDashboardPort } else { 8765 }
    return "http://127.0.0.1:$port/"
}

function Add-MonitorHistorySample {
    param([string]$MonitorId, [datetime]$Time, [int]$TimeMs, [bool]$Ok)
    if (-not $script:monitorHistory.ContainsKey($MonitorId)) { $script:monitorHistory[$MonitorId] = New-Object System.Collections.ArrayList }
    $samples = $script:monitorHistory[$MonitorId]
    [void]$samples.Add(@{ t = $Time.ToString('o'); ms = $TimeMs; ok = $Ok })
    while ($samples.Count -gt 500) { $samples.RemoveAt(0) }
}

# Seeds the in-memory history from the end of the monitor log so the page has data straight away.
function Initialize-MonitorHistory {
    $script:monitorHistory = @{}
    if (-not (Test-Path $monitorLogFilePath)) { return }
    try {
        $header = Get-Content -Path $monitorLogFilePath -TotalCount 1
        $rows = @((@($header) + @(Get-Content -Path $monitorLogFilePath -Tail 3000)) | ConvertFrom-Csv | Where-Object { $_.Timestamp -and $_.Timestamp -ne 'Timestamp' })
        $idsByName = @{}
        foreach ($monitor in @($script:monitors | Where-Object { $_ })) { $idsByName[[string]$monitor.Name] = [string]$monitor.Id }
        foreach ($row in $rows) {
            if (-not $idsByName.ContainsKey([string]$row.MonitorName)) { continue }
            $time = [datetime]::MinValue
            if (-not [datetime]::TryParse([string]$row.Timestamp, [ref]$time)) { continue }
            Add-MonitorHistorySample -MonitorId $idsByName[[string]$row.MonitorName] -Time $time -TimeMs ([int]$row.TimeMs) -Ok ($row.Success -eq 'True')
        }
    } catch { Write-Log "Could not read the monitor log for the dashboard: $($_.Exception.Message)" -Level Info }
}

function Get-MonitorDashboardHtml {
    return @'
<!DOCTYPE html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
<title>API Tester - Monitors</title>
<style>
:root { --bg:#F4F7FC; --surface:#fff; --border:#D8E1EF; --text:#1F2937; --muted:#64748B; --primary:#3659C9; --ok:#107C10; --bad:#D93025; --warn:#B45309; }
@media (prefers-color-scheme: dark) { :root { --bg:#0F172A; --surface:#111B33; --border:#304264; --text:#DCE7FF; --muted:#94A3B8; --primary:#4C6FE0; } }
* { box-sizing:border-box } body { margin:0; font-family:"Segoe UI",system-ui,sans-serif; background:var(--bg); color:var(--text) }
header { background:linear-gradient(90deg,#3659C9,#243E9E); color:#fff; padding:18px 28px; display:flex; align-items:center; gap:18px; flex-wrap:wrap }
header h1 { margin:0; font-size:22px; font-weight:600 } header .meta { opacity:.85; font-size:13px } header .spacer { flex:1 }
main { padding:22px 28px; max-width:1400px; margin:0 auto }
.cards { display:grid; grid-template-columns:repeat(auto-fit,minmax(180px,1fr)); gap:14px; margin-bottom:20px }
.card { background:var(--surface); border:1px solid var(--border); border-radius:10px; padding:14px 16px }
.card .label { font-size:11px; font-weight:600; color:var(--muted); letter-spacing:.06em; text-transform:uppercase } .card .value { font-size:28px; font-weight:700; margin-top:6px }
table { width:100%; border-collapse:collapse; background:var(--surface); border:1px solid var(--border); border-radius:10px; overflow:hidden }
th, td { text-align:left; padding:10px 12px; border-bottom:1px solid var(--border); font-size:14px; vertical-align:middle }
th { font-size:11px; color:var(--muted); text-transform:uppercase; letter-spacing:.06em; font-weight:600 } tr:last-child td { border-bottom:none }
.pill { display:inline-block; padding:2px 10px; border-radius:999px; font-size:12px; font-weight:600; color:#fff }
.ok { background:var(--ok) } .bad { background:var(--bad) } .idle { background:#9AA7BD } .url { color:var(--muted); font-size:12px; word-break:break-all }
.num { font-variant-numeric:tabular-nums } .empty { padding:40px; text-align:center; color:var(--muted) } .error { color:var(--bad); padding:10px 0 }
</style></head>
<body>
<header><div><h1>API Tester monitors</h1><div class="meta" id="meta">Loading...</div></div><div class="spacer"></div><div class="meta">Refreshes every 3 seconds</div></header>
<main>
<div class="cards">
  <div class="card"><div class="label">Monitors running</div><div class="value num" id="running">-</div></div>
  <div class="card"><div class="label">Healthy now</div><div class="value num" id="healthy">-</div></div>
  <div class="card"><div class="label">Failing now</div><div class="value num" id="failing">-</div></div>
  <div class="card"><div class="label">Uptime (last 24 h)</div><div class="value num" id="uptime">-</div></div>
</div>
<div id="error" class="error"></div>
<table><thead><tr><th>Monitor</th><th>State</th><th>Last result</th><th>Last run</th><th>Uptime 24 h</th><th>Avg / p50 / p95 / p99 (ms)</th><th>Latency (last 60)</th></tr></thead><tbody id="rows"></tbody></table>
</main>
<script>
function esc(s){ return String(s == null ? '' : s).replace(/[&<>"]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c])); }
function spark(samples){
  if(!samples || !samples.length) return '<span class="url">no data</span>';
  const w=220,h=36,max=Math.max(...samples.map(s=>s.ms),1),step=samples.length>1?w/(samples.length-1):w;
  const pts=samples.map((s,i)=>`${(i*step).toFixed(1)},${(h-2-(s.ms/max)*(h-6)).toFixed(1)}`).join(' ');
  const dots=samples.map((s,i)=>s.ok?'':`<circle cx="${(i*step).toFixed(1)}" cy="${(h-2-(s.ms/max)*(h-6)).toFixed(1)}" r="2.6" fill="var(--bad)"/>`).join('');
  return `<svg width="${w}" height="${h}" viewBox="0 0 ${w} ${h}"><polyline fill="none" stroke="var(--primary)" stroke-width="1.8" points="${pts}"/>${dots}</svg>`;
}
async function refresh(){
  try{
    const r = await fetch('/api/status', {cache:'no-store'}); const d = await r.json();
    document.getElementById('error').textContent='';
    document.getElementById('meta').textContent = `Served by: ${d.runner} - updated ${new Date(d.generated).toLocaleTimeString()}`;
    const running = d.monitors.filter(m=>m.status==='Running');
    document.getElementById('running').textContent = running.length + ' / ' + d.monitors.length;
    document.getElementById('healthy').textContent = running.filter(m=>m.lastOk===true).length;
    document.getElementById('failing').textContent = running.filter(m=>m.lastOk===false).length;
    const all = d.monitors.filter(m=>m.checks24h>0); const total = all.reduce((a,m)=>a+m.checks24h,0), passed = all.reduce((a,m)=>a+m.passed24h,0);
    document.getElementById('uptime').textContent = total ? (100*passed/total).toFixed(2)+'%' : '-';
    const rows = d.monitors.map(m => {
      const state = m.status==='Running' ? (m.lastOk===false ? '<span class="pill bad">Failing</span>' : m.lastOk===true ? '<span class="pill ok">Healthy</span>' : '<span class="pill idle">Waiting</span>') : '<span class="pill idle">Stopped</span>';
      return `<tr><td><b>${esc(m.name)}</b><div class="url">${esc(m.method)} ${esc(m.url)} - every ${m.intervalSeconds}s</div></td><td>${state}</td><td>${esc(m.lastResult||'-')}</td>
        <td class="num">${m.lastRun ? new Date(m.lastRun).toLocaleString() : 'never'}</td><td class="num">${m.checks24h ? (100*m.passed24h/m.checks24h).toFixed(2)+'%' : '-'}</td>
        <td class="num">${m.avgMs!=null ? m.avgMs+' / '+m.p50Ms+' / '+m.p95Ms+' / '+m.p99Ms : '-'}</td><td>${spark(m.samples)}</td></tr>`;
    }).join('');
    document.getElementById('rows').innerHTML = rows || '<tr><td colspan="7" class="empty">No monitors yet. Add one in API Tester -> Monitor -> Monitor Manager.</td></tr>';
  } catch(e) { document.getElementById('error').textContent = 'API Tester is not serving the dashboard right now (the app and the background monitors are both closed?). Retrying...'; }
}
refresh(); setInterval(refresh, 3000);
</script></body></html>
'@
}

# Builds the JSON snapshot published to the web server.
function Get-MonitorDashboardStatusJson {
    $cutoff = [datetime]::Now.AddHours(-24)
    $entries = foreach ($monitor in @($script:monitors | Where-Object { $_ })) {
        $id = [string]$monitor.Id
        $samples = if ($script:monitorHistory.ContainsKey($id)) { @($script:monitorHistory[$id]) } else { @() }
        $recent = @($samples | Where-Object { [datetime]$_.t -ge $cutoff })
        $times = @($recent | ForEach-Object { [int]$_.ms } | Sort-Object)
        $last = if ($samples.Count -gt 0) { $samples[$samples.Count - 1] } else { $null }
        [ordered]@{
            id = $id; name = [string]$monitor.Name; method = [string]$monitor.Request.Method; url = [string]$monitor.Request.Url
            status = [string]$monitor.Status; intervalSeconds = [int]$monitor.IntervalSeconds
            lastRun = $(if ($monitor.LastRun) { ([datetime]$monitor.LastRun).ToString('o') } elseif ($last) { $last.t } else { $null })
            lastResult = [string]$script:monitorLastResult[$id]; lastOk = $(if ($last) { [bool]$last.ok } else { $null })
            checks24h = $recent.Count; passed24h = @($recent | Where-Object { $_.ok }).Count
            avgMs = $(if ($times.Count) { [int]($times | Measure-Object -Average).Average } else { $null })
            p50Ms = (Get-LatencyPercentile -SortedValues ([int[]]$times) -Fraction 0.5)
            p95Ms = (Get-LatencyPercentile -SortedValues ([int[]]$times) -Fraction 0.95)
            p99Ms = (Get-LatencyPercentile -SortedValues ([int[]]$times) -Fraction 0.99)
            samples = @($samples | Select-Object -Last 60)
        }
    }
    $snapshot = [ordered]@{ generated = (Get-Date).ToString('o'); runner = $(if ($script:isMonitorService) { 'Background service' } else { 'API Tester app' }); monitors = @($entries) }
    return (ConvertTo-Json -InputObject $snapshot -Depth 6 -Compress)
}

function Start-MonitorWebServer {
    if ($script:settings.EnableMonitorWebDashboard -eq $false) { return }
    if ($script:monitorWebServer) {
        $server = $script:monitorWebServer
        if (-not $server.Handle.IsCompleted) { return }
        # The previous attempt ended (for example the port was still in use); retry every 5 seconds.
        if (([datetime]::Now - $server.Started).TotalSeconds -lt 5) { return }
        try { $server.Worker.Dispose() } catch { }
        $script:monitorWebServer = $null
    }
    $port = if ([int]$script:settings.MonitorDashboardPort -gt 0) { [int]$script:settings.MonitorDashboardPort } else { 8765 }
    $shared = [hashtable]::Synchronized(@{ StatusJson = '{"monitors":[]}'; Html = (Get-MonitorDashboardHtml); Stop = $false; Error = $null; Listening = $false })
    $worker = [PowerShell]::Create()
    [void]$worker.AddScript({
        param($Shared, $Port)
        try { $listener = New-Object System.Net.Sockets.TcpListener([System.Net.IPAddress]::Loopback, $Port); $listener.Start(); $Shared.Listening = $true }
        catch { $Shared.Error = $_.Exception.Message; return }
        try {
            while (-not $Shared.Stop) {
                if (-not $listener.Pending()) { Start-Sleep -Milliseconds 100; continue }
                $client = $listener.AcceptTcpClient()
                try {
                    $client.ReceiveTimeout = 3000; $client.SendTimeout = 3000
                    $stream = $client.GetStream()
                    $reader = New-Object System.IO.StreamReader($stream, [System.Text.Encoding]::ASCII, $false, 4096, $true)
                    $requestLine = $reader.ReadLine()
                    while ($line = $reader.ReadLine()) { }
                    $path = if ($requestLine) { (($requestLine -split ' ')[1] -split '\?')[0] } else { '' }
                    $status = '200 OK'
                    if ($path -eq '/api/status') { $type = 'application/json'; $body = [string]$Shared.StatusJson }
                    elseif ($path -eq '/' -or $path -eq '/index.html') { $type = 'text/html'; $body = [string]$Shared.Html }
                    else { $status = '404 Not Found'; $type = 'text/plain'; $body = 'Not found' }
                    $bytes = [System.Text.Encoding]::UTF8.GetBytes($body)
                    $headerBytes = [System.Text.Encoding]::ASCII.GetBytes("HTTP/1.1 $status`r`nContent-Type: $type; charset=utf-8`r`nContent-Length: $($bytes.Length)`r`nCache-Control: no-store`r`nConnection: close`r`n`r`n")
                    $stream.Write($headerBytes, 0, $headerBytes.Length); $stream.Write($bytes, 0, $bytes.Length); $stream.Flush()
                } catch { } finally { $client.Close() }
            }
        } finally { $listener.Stop(); $Shared.Listening = $false }
    }).AddArgument($shared).AddArgument($port)
    $script:monitorWebServer = @{ Worker = $worker; Handle = $worker.BeginInvoke(); Shared = $shared; Port = $port; Started = [datetime]::Now }
}

function Stop-MonitorWebServer {
    if (-not $script:monitorWebServer) { return }
    $script:monitorWebServer.Shared.Stop = $true
    $server = $script:monitorWebServer
    $script:monitorWebServer = $null
    try { if ($server.Handle.AsyncWaitHandle.WaitOne(1000)) { $server.Worker.Dispose() } } catch { }
}

# Called by the active runner: keeps the server running and publishes the snapshot once per second.
function Update-MonitorWebServer {
    Start-MonitorWebServer
    if (-not $script:monitorWebServer) { return }
    if ($script:monitorWebPublished -and ([datetime]::Now - $script:monitorWebPublished).TotalMilliseconds -lt 1000) { return }
    $script:monitorWebPublished = [datetime]::Now
    try { $script:monitorWebServer.Shared.StatusJson = Get-MonitorDashboardStatusJson } catch { }
}

function Open-MonitorDashboardInBrowser {
    if (-not $script:isMonitorService -and -not (Test-MonitorServiceRunning -NoCache)) { Update-MonitorWebServer; Start-Sleep -Milliseconds 300 }
    if ($script:monitorWebServer -and $script:monitorWebServer.Shared.Error) {
        $message = "The monitor dashboard could not listen on port $($script:monitorWebServer.Port): $($script:monitorWebServer.Shared.Error)`n`nChange 'MonitorDashboardPort' in the settings file if another program uses this port."
        if ($script:MainWindowContext) { [void][System.Windows.MessageBox]::Show((Get-MainWindow), $message, 'Monitor dashboard', 'OK', 'Warning') } else { Write-Log $message -Level Warning }
        return
    }
    Start-Process (Get-MonitorDashboardUrl)
}

# ------------------------------------------------------------------------------------------------
# Tray icon (background service and open app)
# The icon is drawn at run time and its colour shows the state: green = all running monitors healthy,
# red = at least one failing, blue = running but no result yet, grey = no monitor running.
# Tooltip and menu list every monitor; clicking a monitor starts or stops it; double-click opens API Tester.
# ------------------------------------------------------------------------------------------------

function New-MonitorTrayIcon {
    param([string]$State = 'Idle')
    if (-not $script:trayIcons) { $script:trayIcons = @{} }
    if ($script:trayIcons.ContainsKey($State)) { return $script:trayIcons[$State] }
    $fill = switch ($State) { 'Healthy' { '#107C10' } 'Failing' { '#D93025' } 'Waiting' { '#3659C9' } default { '#64748B' } }
    $bitmap = New-Object System.Drawing.Bitmap 32, 32
    $graphics = [System.Drawing.Graphics]::FromImage($bitmap)
    $graphics.SmoothingMode = [System.Drawing.Drawing2D.SmoothingMode]::AntiAlias
    $graphics.Clear([System.Drawing.Color]::Transparent)
    $diameter = 14
    $shape = New-Object System.Drawing.Drawing2D.GraphicsPath
    $shape.AddArc(0, 0, $diameter, $diameter, 180, 90); $shape.AddArc(31 - $diameter, 0, $diameter, $diameter, 270, 90)
    $shape.AddArc(31 - $diameter, 31 - $diameter, $diameter, $diameter, 0, 90); $shape.AddArc(0, 31 - $diameter, $diameter, $diameter, 90, 90)
    $shape.CloseFigure()
    $brush = New-Object System.Drawing.SolidBrush ([System.Drawing.ColorTranslator]::FromHtml($fill))
    $graphics.FillPath($brush, $shape)
    $pen = New-Object System.Drawing.Pen ([System.Drawing.Color]::White), 3
    $pen.LineJoin = [System.Drawing.Drawing2D.LineJoin]::Round
    $pen.StartCap = [System.Drawing.Drawing2D.LineCap]::Round; $pen.EndCap = [System.Drawing.Drawing2D.LineCap]::Round
    $pulse = [System.Drawing.Point[]]@((New-Object System.Drawing.Point 5, 17), (New-Object System.Drawing.Point 11, 17), (New-Object System.Drawing.Point 14, 8),
        (New-Object System.Drawing.Point 18, 24), (New-Object System.Drawing.Point 21, 15), (New-Object System.Drawing.Point 27, 15))
    $graphics.DrawLines($pen, $pulse)
    $icon = [System.Drawing.Icon]::FromHandle($bitmap.GetHicon())
    $pen.Dispose(); $brush.Dispose(); $shape.Dispose(); $graphics.Dispose()
    $script:trayIcons[$State] = $icon
    return $icon
}

function Get-MonitorTraySummary {
    $running = @($script:monitors | Where-Object { $_ -and $_.Status -eq 'Running' })
    $failing = New-Object System.Collections.Generic.List[string]
    $healthy = 0; $waiting = 0
    foreach ($monitor in $running) {
        $samples = $script:monitorHistory[[string]$monitor.Id]
        if ($samples -and $samples.Count -gt 0) { if ($samples[$samples.Count - 1].ok) { $healthy++ } else { $failing.Add([string]$monitor.Name) } } else { $waiting++ }
    }
    $state = if ($running.Count -eq 0) { 'Idle' } elseif ($failing.Count -gt 0) { 'Failing' } elseif ($healthy -gt 0) { 'Healthy' } else { 'Waiting' }
    $long = if ($running.Count -eq 0) { 'API Tester - no monitor running' }
            elseif ($failing.Count -gt 0) { "API Tester - $($running.Count) running, $($failing.Count) failing: $($failing -join ', ')" }
            else { "API Tester - $($running.Count) monitor(s) running, all healthy" }
    $short = if ($long.Length -gt 63) { $long.Substring(0, 60) + '...' } else { $long }   # NotifyIcon.Text is limited to 63 characters
    return @{ Running = $running.Count; Failing = $failing.Count; Healthy = $healthy; Waiting = $waiting; State = $state; Text = $short; LongText = $long }
}

function Initialize-MonitorTray {
    param([ValidateSet('App', 'Service')][string]$Mode)
    $script:trayMode = $Mode
    try {
        $trayIcon = New-Object System.Windows.Forms.NotifyIcon
        $trayIcon.Icon = New-MonitorTrayIcon -State 'Idle'
        $trayIcon.Text = 'API Tester monitors'
        $menu = New-Object System.Windows.Forms.ContextMenuStrip
        $header = $menu.Items.Add('API Tester monitors')
        $header.Enabled = $false
        $header.Font = New-Object System.Drawing.Font($menu.Font, [System.Drawing.FontStyle]::Bold)
        $script:trayHeaderItem = $header
        $script:trayMonitorsItem = New-Object System.Windows.Forms.ToolStripMenuItem('Monitors')
        [void]$menu.Items.Add($script:trayMonitorsItem)
        [void]$menu.Items.Add('-')
        [void]$menu.Items.Add('Open API Tester', $null, { Open-ApiTesterFromTray })
        [void]$menu.Items.Add('Open monitor dashboard (browser)', $null, { Open-MonitorDashboardInBrowser })
        [void]$menu.Items.Add('Open monitor log', $null, { if (Test-Path $monitorLogFilePath) { Start-Process $monitorLogFilePath } })
        [void]$menu.Items.Add('-')
        if ($Mode -eq 'Service') {
            [void]$menu.Items.Add('Stop background monitors', $null, { $script:monitorServiceStopRequested = $true })
        } else {
            [void]$menu.Items.Add('Monitor Manager...', $null, { Invoke-UiGuard { Open-ApiTesterFromTray; Show-MonitorManagerWindow } 'Monitor manager' })
            [void]$menu.Items.Add('Keep running in the background (tray only)', $null, { Invoke-UiGuard { Save-Monitors; [void](Start-MonitorService); Update-MonitorTray -Force } 'Background monitors' })
        }
        $menu.Add_Opening({ Invoke-UiGuard { Update-MonitorTrayMenu } 'Tray menu' })
        $trayIcon.ContextMenuStrip = $menu
        $trayIcon.Add_DoubleClick({ Open-ApiTesterFromTray })
        $trayIcon.Add_BalloonTipClicked({ Open-ApiTesterFromTray })
        $script:notifyIcon = $trayIcon
        $script:trayState = 'Idle'
        $trayIcon.Visible = ($Mode -eq 'Service')
        Update-MonitorTray -Force
    } catch {
        $script:notifyIcon = $null
        Write-Log "No tray icon (no interactive desktop): $($_.Exception.Message)" -Level Info
    }
}

# Refreshes colour, tooltip and (for the app) visibility: the app shows its icon only while it is the one running
# monitors, so there is never more than one icon.
function Update-MonitorTray {
    param([switch]$Force)
    if (-not $script:notifyIcon) { return }
    if (-not $Force -and $script:trayUpdated -and ([datetime]::Now - $script:trayUpdated).TotalMilliseconds -lt 1000) { return }
    $script:trayUpdated = [datetime]::Now
    try {
        $summary = Get-MonitorTraySummary
        if ($summary.State -ne $script:trayState) { $script:notifyIcon.Icon = New-MonitorTrayIcon -State $summary.State; $script:trayState = $summary.State }
        if ($script:notifyIcon.Text -ne $summary.Text) { $script:notifyIcon.Text = $summary.Text }
        if ($script:trayMode -eq 'App') {
            $visible = ($summary.Running -gt 0) -and -not (Test-MonitorServiceRunning)
            if ($script:notifyIcon.Visible -ne $visible) { $script:notifyIcon.Visible = $visible }
        }
    } catch { }
}

function Update-MonitorTrayMenu {
    $summary = Get-MonitorTraySummary
    $script:trayHeaderItem.Text = $summary.LongText
    $entries = $script:trayMonitorsItem.DropDownItems
    $entries.Clear()
    $all = @($script:monitors | Where-Object { $_ })
    if ($all.Count -eq 0) { $none = $entries.Add('No monitors yet - add one in Monitor Manager'); $none.Enabled = $false; return }
    foreach ($monitor in $all) {
        $state = if ($monitor.Status -ne 'Running') { 'stopped' } elseif ($script:monitorLastResult[[string]$monitor.Id]) { [string]$script:monitorLastResult[[string]$monitor.Id] } else { 'waiting for the first check' }
        $label = "$($monitor.Name)  -  $state"
        if ($label.Length -gt 100) { $label = $label.Substring(0, 97) + '...' }
        $entry = New-Object System.Windows.Forms.ToolStripMenuItem($label)
        $entry.Checked = ($monitor.Status -eq 'Running')
        $entry.Tag = [string]$monitor.Id
        $entry.ToolTipText = 'Click to start or stop this monitor'
        $entry.Add_Click({ param($sender) Invoke-UiGuard { Switch-MonitorFromTray -MonitorId ([string]$sender.Tag) } 'Start/stop monitor' })
        [void]$entries.Add($entry)
    }
    [void]$entries.Add('-')
    [void]$entries.Add('Start all', $null, { Invoke-UiGuard { Set-AllMonitorsStatus -Status 'Running' } 'Start all' })
    [void]$entries.Add('Stop all', $null, { Invoke-UiGuard { Set-AllMonitorsStatus -Status 'Stopped' } 'Stop all' })
}

function Switch-MonitorFromTray {
    param([string]$MonitorId)
    $monitor = @($script:monitors | Where-Object { $_ -and [string]$_.Id -eq $MonitorId })[0]
    if (-not $monitor) { return }
    if ($monitor.Status -eq 'Running') {
        Set-ObjectProperty -Object $monitor -Name 'Status' -Value 'Stopped'
        if ($script:monitorRuns.ContainsKey($MonitorId)) { try { $script:monitorRuns[$MonitorId].State.Cancellation.Cancel() } catch { }; $script:monitorRuns.Remove($MonitorId) }
    } else {
        Set-ObjectProperty -Object $monitor -Name 'Status' -Value 'Running'
        Set-ObjectProperty -Object $monitor -Name 'LastRun' -Value $null
    }
    Save-Monitors
    Update-MonitorTray -Force
}

function Set-AllMonitorsStatus {
    param([string]$Status)
    foreach ($monitor in @($script:monitors | Where-Object { $_ })) {
        if ($monitor.Status -eq $Status) { continue }
        Set-ObjectProperty -Object $monitor -Name 'Status' -Value $Status
        if ($Status -eq 'Running') { Set-ObjectProperty -Object $monitor -Name 'LastRun' -Value $null }
    }
    if ($Status -eq 'Stopped') { foreach ($run in @($script:monitorRuns.Values)) { try { $run.State.Cancellation.Cancel() } catch { } }; $script:monitorRuns = @{} }
    Save-Monitors
    Update-MonitorTray -Force
}

# Double-click / "Open API Tester": brings the open window to the front, or starts the app from the service.
function Open-ApiTesterFromTray {
    if ($script:trayMode -eq 'App' -and $script:MainWindowContext) {
        $window = Get-MainWindow
        if ($window.WindowState -eq [System.Windows.WindowState]::Minimized) { $window.WindowState = [System.Windows.WindowState]::Normal }
        [void]$window.Activate(); $window.Topmost = $true; $window.Topmost = $false
        return
    }
    try { Start-Process -FilePath (Get-Process -Id $PID).Path -ArgumentList "-NoProfile -STA -ExecutionPolicy Bypass -File `"$PSCommandPath`"" } catch { }
}

# ------------------------------------------------------------------------------------------------
# Monitor engine: runs due monitors with async requests, logs to CSV, raises alerts
# ------------------------------------------------------------------------------------------------

function Start-MonitorEngine {
    if ($script:monitorEngineTimer) { return }
    $script:monitorRuns = @{}
    Initialize-MonitorHistory
    Initialize-MonitorTray -Mode 'App'
    $script:monitorEngineTimer = New-Object System.Windows.Threading.DispatcherTimer
    $script:monitorEngineTimer.Interval = [TimeSpan]::FromMilliseconds(500)
    $script:monitorEngineTimer.Add_Tick({ Invoke-UiGuard { Step-MonitorEngine } 'Monitors' })
    $script:monitorEngineTimer.Start()
}

function Stop-MonitorEngine {
    try { if ($script:monitorEngineTimer) { $script:monitorEngineTimer.Stop() } } catch { }
    Stop-MonitorWebServer
    $script:monitorEngineTimer = $null
    foreach ($run in @($script:monitorRuns.Values)) { try { $run.State.Cancellation.Cancel() } catch { } }
    $script:monitorRuns = @{}
    try { if ($script:notifyIcon) { $script:notifyIcon.Visible = $false; $script:notifyIcon.Dispose() } } catch { }
    $script:notifyIcon = $null
}

function Show-MonitorBalloon {
    param([string]$Title, [string]$Message, [string]$Kind = 'Error')
    try { if ($script:notifyIcon) { $script:notifyIcon.ShowBalloonTip(5000, $Title, $Message, [System.Windows.Forms.ToolTipIcon]::$Kind) } } catch { }
}

function Step-MonitorEngine {
    Update-BackgroundEmails
    Update-MonitorTray
    if (Test-MonitorServiceRunning) {
        if ($script:monitorRuns.Count -gt 0) { foreach ($run in @($script:monitorRuns.Values)) { try { $run.State.Cancellation.Cancel() } catch { } }; $script:monitorRuns = @{} }
        Stop-MonitorWebServer
        return
    }
    Update-MonitorWebServer
    $now = Get-Date
    foreach ($monitor in @($script:monitors)) {
        if (-not $monitor -or $monitor.Status -ne 'Running' -or $script:monitorRuns.ContainsKey($monitor.Id)) { continue }
        $lastRun = if ($monitor.LastRun) { [datetime]$monitor.LastRun } else { [datetime]::MinValue }
        if (($now - $lastRun).TotalSeconds -lt [int]$monitor.IntervalSeconds) { continue }
        Start-MonitorRun -Monitor $monitor
    }
    foreach ($id in @($script:monitorRuns.Keys)) {
        $run = $script:monitorRuns[$id]
        if (-not $run.State.Task.IsCompleted) { continue }
        $script:monitorRuns.Remove($id)
        $result = Get-HttpRequestResult -RequestState $run.State
        Complete-MonitorRun -Monitor $run.Monitor -Result $result
    }
}

function Start-MonitorRun {
    param($Monitor)
    Set-ObjectProperty -Object $Monitor -Name 'LastRun' -Value (Get-Date)
    $timeout = [int](Get-ObjectProperty $Monitor.Request 'RequestTimeoutSeconds' 30)
    try {
        $state = Start-HttpRequestFromObject -Request $Monitor.Request -TimeoutSeconds ([Math]::Max(1, $timeout))
        $script:monitorRuns[$Monitor.Id] = @{ State = $state; Monitor = $Monitor }
    } catch {
        Complete-MonitorRun -Monitor $Monitor -Result @{ Success = $false; ErrorMessage = $_.Exception.Message; ElapsedMs = 0 }
    }
}

function Complete-MonitorRun {
    param($Monitor, $Result)
    $id = [string]$Monitor.Id
    $alerts = $Monitor.Alerts
    $statusCode = if ($Result.Success) { [int]$Result.StatusCode } else { 0 }
    $succeeded = $Result.Success -and $statusCode -ge 200 -and $statusCode -lt 300
    $message = if (-not $Result.Success) { [string]$Result.ErrorMessage } elseif ($succeeded) { 'OK' } else { "HTTP $statusCode $($Result.ReasonPhrase)".Trim() }
    $timeMs = [int]$Result.ElapsedMs

    # Retry N times (5 seconds apart) before a failure is logged and alerted.
    if (-not $script:monitorRetryAttempts) { $script:monitorRetryAttempts = @{} }
    $retryLimit = [int](Get-ObjectProperty $alerts 'RetryCount' 0)
    if (-not $succeeded -and [int]$script:monitorRetryAttempts[$id] -lt $retryLimit) {
        $script:monitorRetryAttempts[$id] = [int]$script:monitorRetryAttempts[$id] + 1
        $script:monitorLastResult[$id] = "Retrying ($($script:monitorRetryAttempts[$id])/$retryLimit) - $message"
        Set-ObjectProperty -Object $Monitor -Name 'LastRun' -Value ((Get-Date).AddSeconds(5 - [int]$Monitor.IntervalSeconds))
        return
    }
    $retriesUsed = [int]$script:monitorRetryAttempts[$id]
    $script:monitorRetryAttempts[$id] = 0
    if ($retriesUsed -gt 0) { $message = "$message (after $retriesUsed retr$(if ($retriesUsed -eq 1) { 'y' } else { 'ies' }))" }

    $timestamp = Get-Date -Format 'yyyy-MM-dd HH:mm:ss'
    Add-MonitorHistorySample -MonitorId $id -Time (Get-Date) -TimeMs $timeMs -Ok $succeeded
    $script:monitorLastResult[$id] = "$(if ($succeeded) { 'OK' } else { 'FAIL' }) - $message ($timeMs ms)"
    try {
        [PSCustomObject]@{ Timestamp = $timestamp; MonitorName = $Monitor.Name; URL = $Monitor.Request.Url; Success = $succeeded; StatusCode = $statusCode; TimeMs = $timeMs; Message = $message } |
            Export-Csv -Path $monitorLogFilePath -Append -NoTypeInformation -Force
    } catch { Write-Log "Failed to write to monitor log: $($_.Exception.Message)" -Level Info }

    # Decide which alert (if any) this result raises.
    if (-not $script:monitorAlertState) { $script:monitorAlertState = @{} }
    $previous = if ($script:monitorAlertState.ContainsKey($id)) { $script:monitorAlertState[$id] } else { @{ Down = $false; Slow = $false } }
    $isSlow = $succeeded -and $alerts.OnSlow -and $timeMs -gt [int]$alerts.ThresholdMs
    $stateChangeOnly = [bool](Get-ObjectProperty $alerts 'OnStateChangeOnly' $false)
    $alertType = $null
    if ($alerts.OnFailure -and -not $succeeded) { if (-not $stateChangeOnly -or -not $previous.Down) { $alertType = 'Down' } }
    elseif ($alerts.OnFailure -and $succeeded -and $previous.Down) { $alertType = 'Recovered' }
    elseif ($isSlow) { if (-not $stateChangeOnly -or -not $previous.Slow) { $alertType = 'Slow' } }
    $script:monitorAlertState[$id] = @{ Down = (-not $succeeded); Slow = $isSlow }
    if (-not $alertType) { return }

    $alertMessage = switch ($alertType) { 'Down' { "$($Monitor.Name) failed: $message" } 'Recovered' { "$($Monitor.Name) recovered: $message ($timeMs ms)" } 'Slow' { "$($Monitor.Name) slow: $timeMs ms" } }
    if (Test-InQuietHours -Start (Get-ObjectProperty $alerts 'QuietHoursStart' '') -End (Get-ObjectProperty $alerts 'QuietHoursEnd' '')) {
        Write-Log "Alert suppressed (quiet hours): $alertMessage" -Level Info
        return
    }
    $kind = switch ($alertType) { 'Down' { 'Error' } 'Slow' { 'Warning' } default { 'Info' } }
    Show-MonitorBalloon -Title $(if ($alertType -eq 'Recovered') { 'API Monitor recovered' } elseif ($alertType -eq 'Slow') { 'API Monitor warning' } else { 'API Monitor alert' }) -Message $alertMessage -Kind $kind
    $alertData = @{ MonitorName = $Monitor.Name; Status = $(if ($alertType -eq 'Down') { 'Failure' } else { $alertType }); StatusCode = $statusCode; Url = $Monitor.Request.Url; TimeMs = $timeMs; Message = $message; Timestamp = $timestamp }
    if ($alerts.SendEmail -and $alerts.EmailTo -and $script:settings.MonitorSmtpServer) {
        try {
            $subjectTemplate = if ($script:settings.MonitorAlertSubjectTemplate) { $script:settings.MonitorAlertSubjectTemplate } else { 'API Alert: {MonitorName}' }
            $bodyTemplate = if ($script:settings.MonitorAlertBodyTemplate) { $script:settings.MonitorAlertBodyTemplate } else { $alertMessage }
            $emailSubject = Format-AlertTemplate -Template $subjectTemplate -Data $alertData
            $emailBody = Format-AlertTemplate -Template $bodyTemplate -Data $alertData
            if ([string]::IsNullOrWhiteSpace($emailSubject)) { $emailSubject = "API Alert: $($Monitor.Name)" }
            if ([string]::IsNullOrWhiteSpace($emailBody)) { $emailBody = $alertMessage }
            Send-MonitorEmailInBackground -To $alerts.EmailTo -Subject $emailSubject -Body $emailBody
        } catch { Write-Log "Failed to send email alert: $($_.Exception.Message)" -Level Info }
    }
    $webhookUrl = [string](Get-ObjectProperty $alerts 'WebhookUrl' '')
    if ($webhookUrl) { Send-MonitorWebhookAlert -Url $webhookUrl -Type ([string](Get-ObjectProperty $alerts 'WebhookType' 'Generic')) -Title "API Tester: $($Monitor.Name) $($alertType.ToLower())" -Data $alertData -Kind $alertType }
    if ($Monitor.AnalyticsUrl) {
        try {
            if (-not $script:analyticsClient) { Add-Type -AssemblyName System.Net.Http; $script:analyticsClient = New-Object System.Net.Http.HttpClient; $script:analyticsClient.Timeout = [TimeSpan]::FromSeconds(10) }
            $payload = @{ monitorName = $Monitor.Name; timestamp = $timestamp; success = $succeeded; statusCode = $statusCode; timeMs = $timeMs; message = $message } | ConvertTo-Json -Compress
            [void]$script:analyticsClient.PostAsync($Monitor.AnalyticsUrl, (New-Object System.Net.Http.StringContent($payload, [System.Text.Encoding]::UTF8, 'application/json')))
        } catch { Write-Log "Failed to send analytics for $($Monitor.Name): $($_.Exception.Message)" -Level Info }
    }
}

# Sends an email using the SMTP settings (Basic or OAuth2). Throws on failure.
function Send-MonitorEmail {
    param([string]$To, [string]$Subject, [string]$Body)
    $isHtml = $script:settings.MonitorAlertBodyForceHtml -or (Test-IsHtmlBody -Body $Body)
    if ($script:settings.MonitorSmtpAuthMethod -eq 'OAuth2') {
        if ($script:settings.MonitorSmtpRefreshToken -and $script:settings.MonitorSmtpTokenEndpoint) {
            $shouldRefresh = $false
            if ($script:settings.MonitorSmtpTokenExpiry) { if ([DateTime]::UtcNow -ge [DateTime]$script:settings.MonitorSmtpTokenExpiry) { $shouldRefresh = $true } }
            elseif (-not $script:settings.MonitorSmtpPass) { $shouldRefresh = $true }
            if ($shouldRefresh) { Update-SmtpToken }
        }
        Send-SmtpOAuth2 -Server $script:settings.MonitorSmtpServer -Port $script:settings.MonitorSmtpPort -UseSsl $script:settings.MonitorSmtpUseSsl -From $script:settings.MonitorSmtpFrom -To $To -Subject $Subject -Body $Body -User $script:settings.MonitorSmtpUser -AccessToken $script:settings.MonitorSmtpPass -IsHtml:$isHtml
        return
    }
    $parameters = @{ SmtpServer = $script:settings.MonitorSmtpServer; Port = $script:settings.MonitorSmtpPort; UseSsl = $script:settings.MonitorSmtpUseSsl; From = $script:settings.MonitorSmtpFrom; To = $To; Subject = $Subject; Body = $Body; BodyAsHtml = $isHtml }
    if ($script:settings.MonitorSmtpUser) {
        $parameters.Credential = New-Object System.Management.Automation.PSCredential($script:settings.MonitorSmtpUser, ($script:settings.MonitorSmtpPass | ConvertTo-SecureString -AsPlainText -Force))
    }
    Send-MailMessage @parameters -ErrorAction Stop
}

# ------------------------------------------------------------------------------------------------
# Scheduled task: runs the background monitors at system start-up under a chosen account, also while nobody is
# signed in. Registering a start-up task needs an elevated (Run as administrator) API Tester.
# ------------------------------------------------------------------------------------------------
$script:MonitorTaskName = 'API Tester Monitors'

function Get-MonitorScheduledTask {
    try { return (Get-ScheduledTask -TaskName $script:MonitorTaskName -ErrorAction Stop) } catch { return $null }
}

function Install-MonitorScheduledTask {
    param([Parameter(Mandatory = $true)][string]$UserName, [string]$Password)
    $hostPath = (Get-Process -Id $PID).Path
    $action = New-ScheduledTaskAction -Execute $hostPath -Argument "-NoProfile -NonInteractive -STA -WindowStyle Hidden -ExecutionPolicy Bypass -File `"$PSCommandPath`" -RunMonitors" -WorkingDirectory (Split-Path $PSCommandPath)
    $trigger = New-ScheduledTaskTrigger -AtStartup
    $taskSettings = New-ScheduledTaskSettingsSet -AllowStartIfOnBatteries -DontStopIfGoingOnBatteries -StartWhenAvailable -ExecutionTimeLimit ([TimeSpan]::Zero) -RestartCount 3 -RestartInterval (New-TimeSpan -Minutes 1)
    $arguments = @{ TaskName = $script:MonitorTaskName; Action = $action; Trigger = $trigger; Settings = $taskSettings; Description = 'Runs the API Tester monitors in the background, also while nobody is signed in.'; Force = $true }
    if ($UserName -match '^(?i)(NT AUTHORITY\\)?(SYSTEM|LOCAL SERVICE|NETWORK SERVICE)$') { $arguments.User = $UserName; $arguments.RunLevel = 'Highest' }
    else { $arguments.User = $UserName; $arguments.Password = $Password; $arguments.RunLevel = 'Limited' }
    Register-ScheduledTask @arguments | Out-Null
    Start-ScheduledTask -TaskName $script:MonitorTaskName
}

function Uninstall-MonitorScheduledTask {
    try { Stop-ScheduledTask -TaskName $script:MonitorTaskName -ErrorAction SilentlyContinue } catch { }
    Unregister-ScheduledTask -TaskName $script:MonitorTaskName -Confirm:$false -ErrorAction Stop
}

function Show-MonitorScheduledTaskDialog {
    param($Owner)
    $existing = Get-MonitorScheduledTask
    $body = @'
  <StackPanel Margin="22,18,22,18">
    <TextBlock Text="Run monitors as a scheduled task" FontSize="20" FontWeight="SemiBold" Foreground="{StaticResource Primary}"/>
    <TextBlock Margin="0,4,0,12" TextWrapping="Wrap" Foreground="{StaticResource Muted}" Text="The monitors start when Windows starts and keep running while nobody is signed in. Use an account that can read the API Tester folder. Installing needs API Tester to be run as administrator."/>
    <TextBlock x:Name="TaskStateText" Margin="0,0,0,10" FontWeight="SemiBold"/>
    <TextBlock Style="{StaticResource SectionLabel}" Text="ACCOUNT (DOMAIN\USER, OR SYSTEM)"/>
    <TextBox x:Name="TaskUserBox" Height="28" Margin="0,4,0,10" VerticalContentAlignment="Center"/>
    <TextBlock Style="{StaticResource SectionLabel}" Text="PASSWORD (NOT NEEDED FOR SYSTEM)"/>
    <PasswordBox x:Name="TaskPasswordBox" Height="28" Margin="0,4,0,10" VerticalContentAlignment="Center"/>
    <TextBlock x:Name="TaskMessageText" TextWrapping="Wrap" Margin="0,0,0,10"/>
    <StackPanel Orientation="Horizontal" HorizontalAlignment="Right">
      <Button x:Name="TaskRemoveButton" Width="120" Margin="0,0,8,0" Content="Remove task"/>
      <Button x:Name="TaskInstallButton" Style="{StaticResource PrimaryButton}" Width="140" Margin="0,0,8,0" Content="Install and start"/>
      <Button x:Name="TaskCloseButton" IsCancel="True" Width="90" Content="Close"/>
    </StackPanel>
  </StackPanel>
'@
    $dialog = New-DialogWindow -BodyXaml $body -ControlNames 'TaskStateText', 'TaskUserBox', 'TaskPasswordBox', 'TaskMessageText', 'TaskRemoveButton', 'TaskInstallButton', 'TaskCloseButton' -Title 'Scheduled task' -Width 560
    $window = $dialog.Window; $controls = $dialog.Controls
    $controls['TaskUserBox'].Text = "$env:USERDOMAIN\$env:USERNAME"
    $refreshState = {
        $task = Get-MonitorScheduledTask
        $controls['TaskStateText'].Text = if ($task) { "Installed - state: $($task.State) - runs as $($task.Principal.UserId)" } else { 'Not installed.' }
        $controls['TaskRemoveButton'].IsEnabled = [bool]$task
    }
    & $refreshState
    $controls['TaskInstallButton'].Add_Click({
        try {
            Save-Monitors
            Install-MonitorScheduledTask -UserName $controls['TaskUserBox'].Text.Trim() -Password $controls['TaskPasswordBox'].Password
            $controls['TaskMessageText'].Text = 'Installed and started. The monitors now run in the background at every start-up.'
            $controls['TaskMessageText'].Foreground = [System.Windows.Media.Brushes]::SeaGreen
        } catch {
            $controls['TaskMessageText'].Text = "Could not install the task: $($_.Exception.Message)`nRun API Tester as administrator and check the account and password."
            $controls['TaskMessageText'].Foreground = [System.Windows.Media.Brushes]::Firebrick
        }
        & $refreshState
    })
    $controls['TaskRemoveButton'].Add_Click({
        try { Uninstall-MonitorScheduledTask; $controls['TaskMessageText'].Text = 'The scheduled task was removed.'; $controls['TaskMessageText'].Foreground = [System.Windows.Media.Brushes]::SeaGreen }
        catch { $controls['TaskMessageText'].Text = "Could not remove the task: $($_.Exception.Message)"; $controls['TaskMessageText'].Foreground = [System.Windows.Media.Brushes]::Firebrick }
        & $refreshState
    })
    [void](Show-WpfDialog -Window $window -OwnerForm $Owner)
}

# ------------------------------------------------------------------------------------------------
# Monitor manager
# ------------------------------------------------------------------------------------------------

function Show-MonitorManagerWindow {
    $body = @'
  <Grid Margin="16,14,16,14">
    <Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="*"/><RowDefinition Height="Auto"/></Grid.RowDefinitions>
    <StackPanel>
      <TextBlock Text="API monitors" FontSize="20" FontWeight="SemiBold" Foreground="{StaticResource Primary}" Margin="0,0,0,8"/>
      <Border Background="{StaticResource Surface}" BorderBrush="{StaticResource Border}" BorderThickness="1" CornerRadius="8" Padding="12,8" Margin="0,0,0,10">
        <DockPanel>
          <StackPanel DockPanel.Dock="Right" Orientation="Horizontal" VerticalAlignment="Center">
            <CheckBox x:Name="AutoStartBox" Content="Start background monitors when I sign in to Windows" VerticalAlignment="Center" Margin="0,0,14,0"/>
            <Button x:Name="StartServiceButton" Style="{StaticResource PrimaryButton}" Padding="12,5" Margin="0,0,8,0" Content="Run in background"/>
            <Button x:Name="StopServiceButton" Padding="12,5" Margin="0,0,8,0" Content="Stop background"/>
            <Button x:Name="ScheduledTaskButton" Padding="12,5" Content="Scheduled task..."/>
          </StackPanel>
          <TextBlock x:Name="ServiceStatusText" VerticalAlignment="Center" TextWrapping="Wrap"/>
        </DockPanel>
      </Border>
    </StackPanel>
    <DataGrid x:Name="MonitorGrid" Grid.Row="1" AutoGenerateColumns="False" IsReadOnly="True" HeadersVisibility="Column" SelectionMode="Single" GridLinesVisibility="Horizontal" Background="Transparent" RowBackground="Transparent">
      <DataGrid.Columns>
        <DataGridTextColumn Header="Name" Binding="{Binding C1}" Width="180"/><DataGridTextColumn Header="URL" Binding="{Binding C2}" Width="*"/>
        <DataGridTextColumn Header="Interval (s)" Binding="{Binding C3}" Width="90"/><DataGridTextColumn Header="Status" Binding="{Binding C4}" Width="90"/>
        <DataGridTextColumn Header="Last run / result" Binding="{Binding C5}" Width="300"/>
      </DataGrid.Columns>
    </DataGrid>
    <WrapPanel Grid.Row="2" Margin="0,12,0,0" HorizontalAlignment="Center">
      <Button x:Name="BrowserButton" Style="{StaticResource PrimaryButton}" Padding="12,6" Margin="0,0,6,0" Content="Open in browser"/>
      <Button x:Name="VisualizeButton" Style="{StaticResource SmallButton}" Padding="12,6" Content="Visualize"/>
      <Button x:Name="OpenLogButton" Style="{StaticResource SmallButton}" Padding="12,6" Content="Open log"/>
      <Button x:Name="AddMonitorButton" Style="{StaticResource SmallButton}" Padding="12,6" Content="Add monitor..."/>
      <Button x:Name="EditMonitorButton" Style="{StaticResource SmallButton}" Padding="12,6" Content="Edit"/>
      <Button x:Name="ToggleMonitorButton" Style="{StaticResource SmallButton}" Padding="12,6" Content="Start / Stop"/>
      <Button x:Name="DeleteMonitorButton" Style="{StaticResource SmallButton}" Padding="12,6" Content="Delete"/>
      <Button x:Name="EmailConfigButton" Style="{StaticResource SmallButton}" Padding="12,6" Content="Email config"/>
      <Button x:Name="ClearLogButton" Style="{StaticResource SmallButton}" Padding="12,6" Content="Clear log"/>
      <Button x:Name="ArchiveLogButton" Style="{StaticResource SmallButton}" Padding="12,6" Content="Archive log"/>
    </WrapPanel>
  </Grid>
'@
    $names = 'AutoStartBox', 'StartServiceButton', 'StopServiceButton', 'ScheduledTaskButton', 'ServiceStatusText', 'MonitorGrid', 'BrowserButton', 'VisualizeButton', 'OpenLogButton', 'AddMonitorButton', 'EditMonitorButton', 'ToggleMonitorButton', 'DeleteMonitorButton', 'EmailConfigButton', 'ClearLogButton', 'ArchiveLogButton'
    $dialog = New-DialogWindow -BodyXaml $body -ControlNames $names -Title 'API monitor manager' -Width 1180 -Height 600
    $window = $dialog.Window; $controls = $dialog.Controls

    $refresh = {
        $serviceRunning = Test-MonitorServiceRunning
        $serviceStatus = if ($serviceRunning) { Get-MonitorServiceStatus } else { $null }
        $controls['ServiceStatusText'].Text = if ($serviceRunning) { 'Running in the background service (tray icon). Monitors keep running after you close API Tester; changes here are picked up within a second.' } else { 'Monitors run while API Tester is open. Use "Run in background" to keep them running after you close it.' }
        $controls['ServiceStatusText'].Foreground = if ($serviceRunning) { [System.Windows.Media.Brushes]::SeaGreen } else { ConvertTo-WpfBrush (ConvertTo-HexColor $script:Theme.MutedText) }
        $controls['StartServiceButton'].IsEnabled = -not $serviceRunning
        $controls['StopServiceButton'].IsEnabled = $serviceRunning
        $selectedId = if ($controls['MonitorGrid'].SelectedItem) { $controls['MonitorGrid'].SelectedItem.Item.Id } else { $null }
        $rows = New-Object 'System.Collections.ObjectModel.ObservableCollection[SimpleRow]'
        foreach ($monitor in @($script:monitors | Where-Object { $_ })) {
            $row = New-Object SimpleRow
            $row.C1 = [string]$monitor.Name; $row.C2 = [string]$monitor.Request.Url; $row.C3 = [string]$monitor.IntervalSeconds; $row.C4 = [string]$monitor.Status
            $lastRun = $monitor.LastRun; $lastResult = $script:monitorLastResult[[string]$monitor.Id]
            if ($serviceStatus -and $serviceStatus.Monitors -and $serviceStatus.Monitors.ContainsKey([string]$monitor.Id)) {
                $entry = $serviceStatus.Monitors[[string]$monitor.Id]
                if ($entry.LastRun) { $lastRun = $entry.LastRun }
                $lastResult = $entry.LastResult
            }
            $row.C5 = if ($lastRun) { ([datetime]$lastRun).ToString() + $(if ($lastResult) { "  |  $lastResult" } else { '' }) } else { 'Never' }
            $row.Item = $monitor
            $rows.Add($row)
        }
        $controls['MonitorGrid'].ItemsSource = $rows
        if ($selectedId) { $match = $rows | Where-Object { $_.Item.Id -eq $selectedId } | Select-Object -First 1; if ($match) { $controls['MonitorGrid'].SelectedItem = $match } }
    }
    $selected = { if ($controls['MonitorGrid'].SelectedItem) { return $controls['MonitorGrid'].SelectedItem.Item } else { [void][System.Windows.MessageBox]::Show($window, 'Please select a monitor first.', 'Selection required', 'OK', 'Warning'); return $null } }
    & $refresh

    $liveTimer = New-Object System.Windows.Threading.DispatcherTimer
    $liveTimer.Interval = [TimeSpan]::FromSeconds(2)
    $liveTimer.Add_Tick({ & $refresh })
    $liveTimer.Start()
    $window.Add_Closing({ $liveTimer.Stop() })

    $controls['AddMonitorButton'].Add_Click({
        $newMonitor = @{
            Id = [Guid]::NewGuid().ToString(); Name = 'New Monitor'; Status = 'Stopped'; IntervalSeconds = 60
            Request = @{ Method = 'GET'; Url = 'http://'; Headers = ''; Body = ''; BodyType = 'application/json'; RequestTimeoutSeconds = 30; Authentication = @{ Type = 'No Auth' } }
            Alerts = @{ OnFailure = $true; OnSlow = $false; ThresholdMs = 1000; SendEmail = $false; EmailTo = '' }; AnalyticsUrl = ''; LastRun = $null
        }
        if (Show-MonitorEditorDialog -Monitor $newMonitor -Owner $window) { $script:monitors = @($script:monitors) + $newMonitor; Save-Monitors; & $refresh }
    })
    $controls['EditMonitorButton'].Add_Click({
        $monitor = & $selected
        if (-not $monitor) { return }
        $copy = $monitor | ConvertTo-Json -Depth 20 | ConvertFrom-Json
        if (Show-MonitorEditorDialog -Monitor $copy -Owner $window) {
            for ($index = 0; $index -lt @($script:monitors).Count; $index++) { if ($script:monitors[$index].Id -eq $monitor.Id) { $script:monitors[$index] = $copy; break } }
            Save-Monitors; & $refresh
        }
    })
    $controls['ToggleMonitorButton'].Add_Click({
        $monitor = & $selected
        if (-not $monitor) { return }
        if ($monitor.Status -eq 'Running') { Set-ObjectProperty -Object $monitor -Name 'Status' -Value 'Stopped'; if ($script:monitorRuns.ContainsKey($monitor.Id)) { try { $script:monitorRuns[$monitor.Id].State.Cancellation.Cancel() } catch { }; $script:monitorRuns.Remove($monitor.Id) } }
        else { Set-ObjectProperty -Object $monitor -Name 'Status' -Value 'Running'; Set-ObjectProperty -Object $monitor -Name 'LastRun' -Value $null }
        Save-Monitors; & $refresh
    })
    $controls['DeleteMonitorButton'].Add_Click({
        $monitor = & $selected
        if (-not $monitor) { return }
        if ([System.Windows.MessageBox]::Show($window, "Delete monitor '$($monitor.Name)'?", 'Confirm delete', 'YesNo', 'Warning') -ne 'Yes') { return }
        if ($script:monitorRuns.ContainsKey($monitor.Id)) { try { $script:monitorRuns[$monitor.Id].State.Cancellation.Cancel() } catch { }; $script:monitorRuns.Remove($monitor.Id) }
        $script:monitors = @($script:monitors | Where-Object { $_.Id -ne $monitor.Id })
        Save-Monitors; & $refresh
    })
    $controls['OpenLogButton'].Add_Click({
        if (Test-Path $monitorLogFilePath) { try { Start-Process $monitorLogFilePath } catch { [void][System.Windows.MessageBox]::Show($window, "Failed to open the log: $($_.Exception.Message)", 'Error', 'OK', 'Error') } }
        else { [void][System.Windows.MessageBox]::Show($window, 'The log file does not exist yet.', 'Info', 'OK', 'Information') }
    })
    $controls['AutoStartBox'].IsChecked = Test-MonitorAutoStart
    $controls['AutoStartBox'].Add_Click({
        try { Set-MonitorAutoStart -Enabled ([bool]$controls['AutoStartBox'].IsChecked) }
        catch { [void][System.Windows.MessageBox]::Show($window, "Could not change the sign-in setting: $($_.Exception.Message)", 'Background monitors', 'OK', 'Error'); $controls['AutoStartBox'].IsChecked = Test-MonitorAutoStart }
    })
    $controls['StartServiceButton'].Add_Click({
        Save-Monitors
        [void](Start-MonitorService)
        & $refresh
    })
    $controls['StopServiceButton'].Add_Click({
        Stop-MonitorService
        Start-Sleep -Milliseconds 400
        & $refresh
    })
    $controls['BrowserButton'].Add_Click({ Open-MonitorDashboardInBrowser })
    $controls['ScheduledTaskButton'].Add_Click({ Show-MonitorScheduledTaskDialog -Owner $window; & $refresh })
    $controls['VisualizeButton'].Add_Click({ Show-MonitorChartDialog -Owner $window })
    $controls['EmailConfigButton'].Add_Click({ Show-MonitorEmailDialog -Owner $window })
    $controls['ClearLogButton'].Add_Click({
        if ([System.Windows.MessageBox]::Show($window, 'Clear the monitor log file?', 'Confirm', 'YesNo', 'Warning') -eq 'Yes') { Clear-Content $monitorLogFilePath -ErrorAction SilentlyContinue }
    })
    $controls['ArchiveLogButton'].Add_Click({
        if (-not (Test-Path $monitorLogFilePath)) { return }
        $archiveName = "$monitorLogFilePath.$((Get-Date).ToString('yyyyMMdd-HHmmss')).csv"
        Rename-Item $monitorLogFilePath $archiveName
        [void][System.Windows.MessageBox]::Show($window, "Log archived to:`n$archiveName", 'Archive log', 'OK', 'Information')
    })
    [void](Show-WpfDialog -Window $window -OwnerForm (Get-MainWindow))
}

# ------------------------------------------------------------------------------------------------
# Monitor editor. Returns $true when saved; $Monitor is modified in place.
# ------------------------------------------------------------------------------------------------

function Show-MonitorEditorDialog {
    param($Monitor, $Owner)
    $body = @'
  <Grid Margin="20,16,20,16">
    <Grid.RowDefinitions><RowDefinition Height="*"/><RowDefinition Height="Auto"/></Grid.RowDefinitions>
    <ScrollViewer VerticalScrollBarVisibility="Auto"><StackPanel Margin="0,0,10,0">
      <TextBlock Text="Edit monitor" FontSize="20" FontWeight="SemiBold" Foreground="{StaticResource Primary}" Margin="0,0,0,10"/>
      <WrapPanel>
        <StackPanel Margin="0,0,16,8"><TextBlock Style="{StaticResource SectionLabel}" Text="NAME"/><TextBox x:Name="MeNameBox" Width="320" Height="28" Margin="0,4,0,0" VerticalContentAlignment="Center"/></StackPanel>
        <StackPanel Margin="0,0,16,8"><TextBlock Style="{StaticResource SectionLabel}" Text="INTERVAL (SECONDS, 10-86400)"/><TextBox x:Name="MeIntervalBox" Width="120" Height="28" Margin="0,4,0,0" VerticalContentAlignment="Center"/></StackPanel>
      </WrapPanel>
      <TabControl Height="330" Background="{StaticResource Surface}" BorderBrush="{StaticResource Border}">
        <TabItem Header="General"><StackPanel Margin="12">
          <WrapPanel>
            <StackPanel Margin="0,0,16,8"><TextBlock Style="{StaticResource SectionLabel}" Text="METHOD"/><ComboBox x:Name="MeMethodBox" Width="120" Height="28" Margin="0,4,0,0" VerticalContentAlignment="Center"/></StackPanel>
            <StackPanel Margin="0,0,16,8"><TextBlock Style="{StaticResource SectionLabel}" Text="TIMEOUT (SECONDS, 1-300)"/><TextBox x:Name="MeTimeoutBox" Width="120" Height="28" Margin="0,4,0,0" VerticalContentAlignment="Center"/></StackPanel>
          </WrapPanel>
          <TextBlock Style="{StaticResource SectionLabel}" Text="URL"/><TextBox x:Name="MeUrlBox" Height="28" Margin="0,4,0,10" VerticalContentAlignment="Center"/>
          <Button x:Name="MeImportButton" HorizontalAlignment="Left" Padding="14,5" Content="Import from the current request"/>
        </StackPanel></TabItem>
        <TabItem Header="Headers"><TextBox x:Name="MeHeadersBox" Margin="10" AcceptsReturn="True" FontFamily="Consolas" VerticalScrollBarVisibility="Auto"/></TabItem>
        <TabItem Header="Body"><Grid Margin="10"><Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="*"/></Grid.RowDefinitions>
          <ComboBox x:Name="MeBodyTypeBox" Width="260" Height="28" HorizontalAlignment="Left" Margin="0,0,0,8" VerticalContentAlignment="Center"/>
          <TextBox x:Name="MeBodyBox" Grid.Row="1" AcceptsReturn="True" FontFamily="Consolas" VerticalScrollBarVisibility="Auto"/></Grid></TabItem>
        <TabItem Header="Auth"><StackPanel Margin="12">
          <ComboBox x:Name="MeAuthTypeBox" Width="220" Height="28" HorizontalAlignment="Left" VerticalContentAlignment="Center" Margin="0,0,0,8"/>
          <WrapPanel>
            <StackPanel x:Name="MeAuth1Panel" Margin="0,0,12,8"><TextBlock x:Name="MeAuthLabel1" Style="{StaticResource SectionLabel}"/><TextBox x:Name="MeAuth1Box" Width="260" Height="28" Margin="0,4,0,0" VerticalContentAlignment="Center"/></StackPanel>
            <StackPanel x:Name="MeAuth2Panel" Margin="0,0,12,8"><TextBlock x:Name="MeAuthLabel2" Style="{StaticResource SectionLabel}"/><TextBox x:Name="MeAuth2Box" Width="260" Height="28" Margin="0,4,0,0" VerticalContentAlignment="Center"/></StackPanel>
            <StackPanel x:Name="MeAuth3Panel" Margin="0,0,12,8"><TextBlock x:Name="MeAuthLabel3" Style="{StaticResource SectionLabel}"/><ComboBox x:Name="MeAuthAddToBox" Width="170" Height="28" Margin="0,4,0,0" VerticalContentAlignment="Center"/></StackPanel>
          </WrapPanel>
          <TextBlock x:Name="MeAuthNote" Foreground="{StaticResource Muted}" TextWrapping="Wrap"/>
        </StackPanel></TabItem>
      </TabControl>
      <Border Background="{StaticResource Surface}" BorderBrush="{StaticResource Border}" BorderThickness="1" CornerRadius="8" Padding="14,10" Margin="0,12,0,0"><StackPanel>
        <TextBlock Style="{StaticResource SectionLabel}" Text="ALERTING"/>
        <CheckBox x:Name="MeAlertFailBox" Content="Alert on HTTP failure (status is not 2xx)" Margin="0,8,0,3"/>
        <WrapPanel><CheckBox x:Name="MeAlertSlowBox" Content="Alert on slow response, threshold (ms):" VerticalAlignment="Center" Margin="0,3,8,3"/><TextBox x:Name="MeThresholdBox" Width="90" Height="26" VerticalContentAlignment="Center"/></WrapPanel>
        <CheckBox x:Name="MeStateChangeBox" Content="Only alert when the monitor goes down or recovers (not on every failed check)" Margin="0,3"/>
        <WrapPanel Margin="0,3">
          <TextBlock Text="Retry before alerting:" VerticalAlignment="Center" Margin="0,0,6,0"/><TextBox x:Name="MeRetryBox" Width="50" Height="26" VerticalContentAlignment="Center" ToolTip="Failed checks are retried this many times (5 seconds apart) before they count"/>
          <TextBlock Text="Quiet hours from" VerticalAlignment="Center" Margin="16,0,6,0"/><TextBox x:Name="MeQuietStartBox" Width="60" Height="26" VerticalContentAlignment="Center" ToolTip="HH:mm, e.g. 22:00 - alerts are suppressed (still logged)"/>
          <TextBlock Text="to" VerticalAlignment="Center" Margin="6,0,6,0"/><TextBox x:Name="MeQuietEndBox" Width="60" Height="26" VerticalContentAlignment="Center" ToolTip="HH:mm, e.g. 07:00"/>
        </WrapPanel>
        <WrapPanel Margin="0,3">
          <TextBlock Text="Webhook:" VerticalAlignment="Center" Margin="0,0,6,0"/><ComboBox x:Name="MeWebhookTypeBox" Width="110" Height="26" VerticalContentAlignment="Center" Margin="0,0,6,0"/>
          <TextBox x:Name="MeAlertWebhookBox" Width="420" Height="26" VerticalContentAlignment="Center" ToolTip="Microsoft Teams incoming webhook, Slack incoming webhook, or any URL that accepts JSON"/>
        </WrapPanel>
        <WrapPanel Margin="0,3"><CheckBox x:Name="MeAlertEmailBox" Content="Send email alert to:" VerticalAlignment="Center" Margin="0,3,8,3"/><TextBox x:Name="MeEmailToBox" Width="320" Height="26" VerticalContentAlignment="Center"/>
          <Button x:Name="MeSmtpButton" Style="{StaticResource SmallButton}" Margin="10,0,0,0" Content="SMTP settings..."/></WrapPanel>
      </StackPanel></Border>
      <TextBlock Style="{StaticResource SectionLabel}" Text="ANALYTICS WEBHOOK URL (OPTIONAL)" Margin="0,12,0,0"/><TextBox x:Name="MeWebhookBox" Height="28" Margin="0,4,0,0" VerticalContentAlignment="Center"/>
    </StackPanel></ScrollViewer>
    <DockPanel Grid.Row="1" Margin="0,12,0,0">
      <TextBlock x:Name="MeStatusText" DockPanel.Dock="Left" VerticalAlignment="Center" Foreground="#B91C1C" TextWrapping="Wrap" MaxWidth="460"/>
      <StackPanel Orientation="Horizontal" HorizontalAlignment="Right">
        <Button x:Name="MeTestButton" Width="130" Margin="0,0,8,0" Content="Test request"/>
        <Button x:Name="MeSaveButton" Style="{StaticResource PrimaryButton}" Width="100" Content="Save"/>
        <Button x:Name="MeCancelButton" IsCancel="True" Width="90" Margin="8,0,0,0" Content="Cancel"/>
      </StackPanel>
    </DockPanel>
  </Grid>
'@
    $names = 'MeNameBox', 'MeIntervalBox', 'MeMethodBox', 'MeTimeoutBox', 'MeUrlBox', 'MeImportButton', 'MeHeadersBox', 'MeBodyTypeBox', 'MeBodyBox', 'MeAuthTypeBox', 'MeAuth1Panel', 'MeAuthLabel1', 'MeAuth1Box',
        'MeAuth2Panel', 'MeAuthLabel2', 'MeAuth2Box', 'MeAuth3Panel', 'MeAuthLabel3', 'MeAuthAddToBox', 'MeAuthNote', 'MeAlertFailBox', 'MeAlertSlowBox', 'MeThresholdBox', 'MeStateChangeBox', 'MeRetryBox', 'MeQuietStartBox', 'MeQuietEndBox', 'MeWebhookTypeBox', 'MeAlertWebhookBox', 'MeAlertEmailBox', 'MeEmailToBox',
        'MeSmtpButton', 'MeWebhookBox', 'MeStatusText', 'MeTestButton', 'MeSaveButton', 'MeCancelButton'
    $dialog = New-DialogWindow -BodyXaml $body -ControlNames $names -Title 'Edit monitor' -Width 900 -Height 960
    $window = $dialog.Window; $controls = $dialog.Controls
    foreach ($method in @('GET', 'POST', 'PUT', 'DELETE', 'PATCH')) { [void]$controls['MeMethodBox'].Items.Add($method) }
    foreach ($type in @('multipart/form-data', 'application/json', 'application/xml', 'text/plain', 'application/x-www-form-urlencoded', 'GraphQL')) { [void]$controls['MeBodyTypeBox'].Items.Add($type) }
    foreach ($type in @('No Auth', 'API Key', 'Bearer Token', 'Basic Auth', 'Auth2', 'Client Certificate')) { [void]$controls['MeAuthTypeBox'].Items.Add($type) }
    foreach ($location in @('Header', 'Query Parameter')) { [void]$controls['MeAuthAddToBox'].Items.Add($location) }

    $request = $Monitor.Request; $alerts = $Monitor.Alerts
    $script:monitorAuthExtras = @{}
    $updateAuthFields = {
        $type = [string]$controls['MeAuthTypeBox'].SelectedItem
        $labels = switch ($type) { 'API Key' { @('KEY NAME', 'VALUE', 'ADD TO') } 'Bearer Token' { @('TOKEN', '', '') } 'Basic Auth' { @('USERNAME', 'PASSWORD', '') } default { @('', '', '') } }
        $controls['MeAuthLabel1'].Text = $labels[0]; $controls['MeAuthLabel2'].Text = $labels[1]; $controls['MeAuthLabel3'].Text = $labels[2]
        $controls['MeAuth1Panel'].Visibility = if ($labels[0]) { 'Visible' } else { 'Collapsed' }
        $controls['MeAuth2Panel'].Visibility = if ($labels[1]) { 'Visible' } else { 'Collapsed' }
        $controls['MeAuth3Panel'].Visibility = if ($labels[2]) { 'Visible' } else { 'Collapsed' }
        $controls['MeAuthNote'].Text = if ($type -in @('Auth2', 'Client Certificate')) { "$type settings are kept as they are. Use 'Import from the current request' to copy them from the request editor." } else { '' }
    }
    $loadAuth = {
        param($Auth)
        $script:monitorAuthExtras = @{}
        if ($Auth -is [System.Collections.IDictionary]) { foreach ($key in $Auth.Keys) { $script:monitorAuthExtras[$key] = $Auth[$key] } } elseif ($Auth) { foreach ($property in $Auth.PSObject.Properties) { $script:monitorAuthExtras[$property.Name] = $property.Value } }
        $type = [string](Get-ObjectProperty $Auth 'Type' 'No Auth')
        if (-not $controls['MeAuthTypeBox'].Items.Contains($type)) { $type = 'No Auth' }
        $controls['MeAuthTypeBox'].SelectedItem = $type
        & $updateAuthFields
        switch ($type) {
            'API Key'      { $controls['MeAuth1Box'].Text = [string]$script:monitorAuthExtras['Key']; $controls['MeAuth2Box'].Text = [string]$script:monitorAuthExtras['Value']; $controls['MeAuthAddToBox'].SelectedItem = if ($script:monitorAuthExtras['AddTo']) { [string]$script:monitorAuthExtras['AddTo'] } else { 'Header' } }
            'Bearer Token' { $controls['MeAuth1Box'].Text = [string]$script:monitorAuthExtras['Token']; $controls['MeAuth2Box'].Text = '' }
            'Basic Auth'   { $controls['MeAuth1Box'].Text = [string]$script:monitorAuthExtras['Username']; $controls['MeAuth2Box'].Text = [string]$script:monitorAuthExtras['Password'] }
            default        { $controls['MeAuth1Box'].Text = ''; $controls['MeAuth2Box'].Text = '' }
        }
    }
    $readAuth = {
        $type = [string]$controls['MeAuthTypeBox'].SelectedItem
        $auth = @{ Type = $type }
        switch ($type) {
            'API Key'      { $auth.Key = $controls['MeAuth1Box'].Text; $auth.Value = $controls['MeAuth2Box'].Text; $auth.AddTo = [string]$controls['MeAuthAddToBox'].SelectedItem }
            'Bearer Token' { $auth.Token = $controls['MeAuth1Box'].Text }
            'Basic Auth'   { $auth.Username = $controls['MeAuth1Box'].Text; $auth.Password = $controls['MeAuth2Box'].Text }
            { $_ -in @('Auth2', 'Client Certificate') } { foreach ($key in $script:monitorAuthExtras.Keys) { $auth[$key] = $script:monitorAuthExtras[$key] }; $auth.Type = $type }
        }
        return $auth
    }
    $controls['MeAuthTypeBox'].Add_SelectionChanged({ & $updateAuthFields })

    $controls['MeNameBox'].Text = [string]$Monitor.Name
    $controls['MeIntervalBox'].Text = [string]$Monitor.IntervalSeconds
    $controls['MeMethodBox'].SelectedItem = if ($request.Method -and $controls['MeMethodBox'].Items.Contains([string]$request.Method)) { [string]$request.Method } else { 'GET' }
    $controls['MeTimeoutBox'].Text = [string](Get-ObjectProperty $request 'RequestTimeoutSeconds' 30)
    $controls['MeUrlBox'].Text = [string]$request.Url
    $controls['MeHeadersBox'].Text = [string](Get-ObjectProperty $request 'Headers' '')
    $bodyType = ConvertTo-MimeBodyType -Name ([string](Get-ObjectProperty $request 'BodyType' 'application/json'))
    $controls['MeBodyTypeBox'].SelectedItem = if ($controls['MeBodyTypeBox'].Items.Contains($bodyType)) { $bodyType } else { 'application/json' }
    $controls['MeBodyBox'].Text = [string](Get-ObjectProperty $request 'Body' '')
    & $loadAuth (Get-ObjectProperty $request 'Authentication' @{ Type = 'No Auth' })
    $controls['MeAlertFailBox'].IsChecked = [bool](Get-ObjectProperty $alerts 'OnFailure' $true)
    $controls['MeAlertSlowBox'].IsChecked = [bool](Get-ObjectProperty $alerts 'OnSlow' $false)
    $controls['MeThresholdBox'].Text = [string](Get-ObjectProperty $alerts 'ThresholdMs' 1000)
    $controls['MeAlertEmailBox'].IsChecked = [bool](Get-ObjectProperty $alerts 'SendEmail' $false)
    $controls['MeEmailToBox'].Text = [string](Get-ObjectProperty $alerts 'EmailTo' '')
    $controls['MeWebhookBox'].Text = [string](Get-ObjectProperty $Monitor 'AnalyticsUrl' '')
    foreach ($type in @('Teams', 'Slack', 'Generic')) { [void]$controls['MeWebhookTypeBox'].Items.Add($type) }
    $controls['MeWebhookTypeBox'].SelectedItem = [string](Get-ObjectProperty $alerts 'WebhookType' 'Teams')
    if (-not $controls['MeWebhookTypeBox'].SelectedItem) { $controls['MeWebhookTypeBox'].SelectedIndex = 0 }
    $controls['MeAlertWebhookBox'].Text = [string](Get-ObjectProperty $alerts 'WebhookUrl' '')
    $controls['MeStateChangeBox'].IsChecked = [bool](Get-ObjectProperty $alerts 'OnStateChangeOnly' $false)
    $controls['MeRetryBox'].Text = [string][int](Get-ObjectProperty $alerts 'RetryCount' 0)
    $controls['MeQuietStartBox'].Text = [string](Get-ObjectProperty $alerts 'QuietHoursStart' '')
    $controls['MeQuietEndBox'].Text = [string](Get-ObjectProperty $alerts 'QuietHoursEnd' '')

    $controls['MeImportButton'].Add_Click({
        $state = Get-EditorState
        $controls['MeMethodBox'].SelectedItem = if ($controls['MeMethodBox'].Items.Contains($state.Method)) { $state.Method } else { 'GET' }
        $controls['MeUrlBox'].Text = $state.Url; $controls['MeHeadersBox'].Text = $state.Headers; $controls['MeBodyBox'].Text = $state.Body
        $controls['MeBodyTypeBox'].SelectedItem = $state.BodyType
        $authCopy = @{}
        foreach ($property in (Copy-RequestData $state.Authentication).PSObject.Properties) { $authCopy[$property.Name] = $property.Value }
        & $loadAuth $authCopy
        $controls['MeStatusText'].Text = ''
        [void][System.Windows.MessageBox]::Show($window, 'Request details imported from the main window.', 'Import complete', 'OK', 'Information')
    })
    $controls['MeSmtpButton'].Add_Click({ Show-MonitorEmailDialog -Owner $window })
    $controls['MeTestButton'].Add_Click({
        try {
            $testRequest = [PSCustomObject]@{ Method = [string]$controls['MeMethodBox'].SelectedItem; Url = $controls['MeUrlBox'].Text; Headers = $controls['MeHeadersBox'].Text; Body = $controls['MeBodyBox'].Text; BodyType = [string]$controls['MeBodyTypeBox'].SelectedItem; Authentication = (& $readAuth) }
            $timeout = 0; if (-not [int]::TryParse($controls['MeTimeoutBox'].Text, [ref]$timeout) -or $timeout -lt 1) { $timeout = 30 }
            $controls['MeStatusText'].Text = 'Testing...'; $controls['MeStatusText'].Foreground = [System.Windows.Media.Brushes]::DimGray; Update-UiNow
            $result = Invoke-HttpRequestSync -Request $testRequest -TimeoutSeconds $timeout
            if ($result.Success) { $controls['MeStatusText'].Text = "Success: HTTP $($result.StatusCode) in $($result.ElapsedMs) ms"; $controls['MeStatusText'].Foreground = if ($result.StatusCode -lt 400) { [System.Windows.Media.Brushes]::SeaGreen } else { [System.Windows.Media.Brushes]::DarkOrange } }
            else { $controls['MeStatusText'].Text = "Failed: $($result.ErrorMessage)"; $controls['MeStatusText'].Foreground = [System.Windows.Media.Brushes]::Firebrick }
        } catch { $controls['MeStatusText'].Text = "Failed: $($_.Exception.Message)"; $controls['MeStatusText'].Foreground = [System.Windows.Media.Brushes]::Firebrick }
    })
    $script:monitorEditorSaved = $false
    $controls['MeSaveButton'].Add_Click({
        $interval = 0; $timeout = 0; $threshold = 0
        $controls['MeStatusText'].Foreground = [System.Windows.Media.Brushes]::Firebrick
        if ([string]::IsNullOrWhiteSpace($controls['MeNameBox'].Text)) { $controls['MeStatusText'].Text = 'The monitor name cannot be empty.'; return }
        if ([string]::IsNullOrWhiteSpace($controls['MeUrlBox'].Text)) { $controls['MeStatusText'].Text = 'The request URL cannot be empty.'; return }
        if (-not [int]::TryParse($controls['MeIntervalBox'].Text, [ref]$interval) -or $interval -lt 10 -or $interval -gt 86400) { $controls['MeStatusText'].Text = 'The interval must be 10-86400 seconds.'; return }
        if (-not [int]::TryParse($controls['MeTimeoutBox'].Text, [ref]$timeout) -or $timeout -lt 1 -or $timeout -gt 300) { $controls['MeStatusText'].Text = 'The timeout must be 1-300 seconds.'; return }
        if (-not [int]::TryParse($controls['MeThresholdBox'].Text, [ref]$threshold) -or $threshold -lt 1) { $threshold = 1000 }
        Set-ObjectProperty -Object $Monitor -Name 'Name' -Value $controls['MeNameBox'].Text
        Set-ObjectProperty -Object $Monitor -Name 'IntervalSeconds' -Value $interval
        Set-ObjectProperty -Object $request -Name 'Method' -Value ([string]$controls['MeMethodBox'].SelectedItem)
        Set-ObjectProperty -Object $request -Name 'Url' -Value $controls['MeUrlBox'].Text
        Set-ObjectProperty -Object $request -Name 'RequestTimeoutSeconds' -Value $timeout
        Set-ObjectProperty -Object $request -Name 'Headers' -Value $controls['MeHeadersBox'].Text
        Set-ObjectProperty -Object $request -Name 'BodyType' -Value ([string]$controls['MeBodyTypeBox'].SelectedItem)
        Set-ObjectProperty -Object $request -Name 'Body' -Value $controls['MeBodyBox'].Text
        Set-ObjectProperty -Object $request -Name 'Authentication' -Value (& $readAuth)
        Set-ObjectProperty -Object $alerts -Name 'OnFailure' -Value ([bool]$controls['MeAlertFailBox'].IsChecked)
        Set-ObjectProperty -Object $alerts -Name 'OnSlow' -Value ([bool]$controls['MeAlertSlowBox'].IsChecked)
        Set-ObjectProperty -Object $alerts -Name 'ThresholdMs' -Value $threshold
        Set-ObjectProperty -Object $alerts -Name 'SendEmail' -Value ([bool]$controls['MeAlertEmailBox'].IsChecked)
        Set-ObjectProperty -Object $alerts -Name 'EmailTo' -Value $controls['MeEmailToBox'].Text
        Set-ObjectProperty -Object $Monitor -Name 'AnalyticsUrl' -Value $controls['MeWebhookBox'].Text
        $retryCount = 0; [void][int]::TryParse($controls['MeRetryBox'].Text, [ref]$retryCount)
        $quietStart = $controls['MeQuietStartBox'].Text.Trim(); $quietEnd = $controls['MeQuietEndBox'].Text.Trim(); $parsedTime = [TimeSpan]::Zero
        if (($quietStart -and -not [TimeSpan]::TryParse($quietStart, [ref]$parsedTime)) -or ($quietEnd -and -not [TimeSpan]::TryParse($quietEnd, [ref]$parsedTime))) { $controls['MeStatusText'].Text = 'Quiet hours must be HH:mm (for example 22:00).'; return }
        Set-ObjectProperty -Object $alerts -Name 'RetryCount' -Value ([Math]::Max(0, [Math]::Min(10, $retryCount)))
        Set-ObjectProperty -Object $alerts -Name 'OnStateChangeOnly' -Value ([bool]$controls['MeStateChangeBox'].IsChecked)
        Set-ObjectProperty -Object $alerts -Name 'QuietHoursStart' -Value $quietStart
        Set-ObjectProperty -Object $alerts -Name 'QuietHoursEnd' -Value $quietEnd
        Set-ObjectProperty -Object $alerts -Name 'WebhookType' -Value ([string]$controls['MeWebhookTypeBox'].SelectedItem)
        Set-ObjectProperty -Object $alerts -Name 'WebhookUrl' -Value $controls['MeAlertWebhookBox'].Text.Trim()
        $script:monitorEditorSaved = $true
        $window.DialogResult = $true
    })
    [void](Show-WpfDialog -Window $window -OwnerForm $Owner)
    return $script:monitorEditorSaved
}

# ------------------------------------------------------------------------------------------------
# SMTP / email alert settings
# ------------------------------------------------------------------------------------------------

function Show-MonitorEmailDialog {
    param($Owner)
    $body = @'
  <Grid Margin="20,16,20,16">
    <Grid.RowDefinitions><RowDefinition Height="*"/><RowDefinition Height="Auto"/></Grid.RowDefinitions>
    <ScrollViewer VerticalScrollBarVisibility="Auto"><StackPanel Margin="0,0,10,0">
      <TextBlock Text="Email alert configuration" FontSize="20" FontWeight="SemiBold" Foreground="{StaticResource Primary}" Margin="0,0,0,10"/>
      <WrapPanel>
        <StackPanel Margin="0,0,16,8"><TextBlock Style="{StaticResource SectionLabel}" Text="SMTP SERVER"/><TextBox x:Name="SmtpServerBox" Width="320" Height="28" Margin="0,4,0,0" VerticalContentAlignment="Center"/></StackPanel>
        <StackPanel Margin="0,0,16,8"><TextBlock Style="{StaticResource SectionLabel}" Text="PORT"/><TextBox x:Name="SmtpPortBox" Width="90" Height="28" Margin="0,4,0,0" VerticalContentAlignment="Center"/></StackPanel>
        <StackPanel Margin="0,0,16,8"><TextBlock Style="{StaticResource SectionLabel}" Text="AUTHENTICATION"/><ComboBox x:Name="SmtpAuthBox" Width="140" Height="28" Margin="0,4,0,0" VerticalContentAlignment="Center"/></StackPanel>
        <CheckBox x:Name="SmtpSslBox" Content="Use SSL/TLS" VerticalAlignment="Bottom" Margin="0,0,0,12"/>
      </WrapPanel>
      <WrapPanel>
        <StackPanel Margin="0,0,16,8"><TextBlock Style="{StaticResource SectionLabel}" Text="FROM ADDRESS"/><TextBox x:Name="SmtpFromBox" Width="320" Height="28" Margin="0,4,0,0" VerticalContentAlignment="Center"/></StackPanel>
        <StackPanel Margin="0,0,16,8"><TextBlock Style="{StaticResource SectionLabel}" Text="USERNAME"/><TextBox x:Name="SmtpUserBox" Width="300" Height="28" Margin="0,4,0,0" VerticalContentAlignment="Center"/></StackPanel>
      </WrapPanel>
      <StackPanel Margin="0,0,0,8"><TextBlock x:Name="SmtpPassLabel" Style="{StaticResource SectionLabel}" Text="PASSWORD"/><PasswordBox x:Name="SmtpPassBox" Width="640" HorizontalAlignment="Left" Height="28" Margin="0,4,0,0" VerticalContentAlignment="Center"/></StackPanel>
      <Border x:Name="OAuthSection" Visibility="Collapsed" Background="{StaticResource Surface}" BorderBrush="{StaticResource Border}" BorderThickness="1" CornerRadius="8" Padding="14,10" Margin="0,0,0,8"><StackPanel>
        <TextBlock Style="{StaticResource SectionLabel}" Text="OAUTH 2.0"/>
        <WrapPanel Margin="0,6,0,0">
          <StackPanel Margin="0,0,16,8"><TextBlock Text="Client ID"/><TextBox x:Name="SmtpClientIdBox" Width="300" Height="28" Margin="0,4,0,0" VerticalContentAlignment="Center"/></StackPanel>
          <StackPanel Margin="0,0,16,8"><TextBlock Text="Client secret"/><PasswordBox x:Name="SmtpClientSecretBox" Width="300" Height="28" Margin="0,4,0,0" VerticalContentAlignment="Center"/></StackPanel>
          <StackPanel Margin="0,0,16,8"><TextBlock Text="Token endpoint"/><TextBox x:Name="SmtpTokenEndpointBox" Width="300" Height="28" Margin="0,4,0,0" VerticalContentAlignment="Center"/></StackPanel>
          <StackPanel Margin="0,0,16,8"><TextBlock Text="Refresh token"/><PasswordBox x:Name="SmtpRefreshTokenBox" Width="300" Height="28" Margin="0,4,0,0" VerticalContentAlignment="Center"/></StackPanel>
        </WrapPanel>
        <Button x:Name="SmtpRefreshButton" HorizontalAlignment="Left" Padding="14,5" Content="Refresh access token now"/>
      </StackPanel></Border>
      <Border Background="{StaticResource Surface}" BorderBrush="{StaticResource Border}" BorderThickness="1" CornerRadius="8" Padding="14,10"><StackPanel>
        <TextBlock Style="{StaticResource SectionLabel}" Text="ALERT EMAIL TEMPLATE"/>
        <TextBlock Text="Subject" Margin="0,8,0,0"/><TextBox x:Name="AlertSubjectBox" Height="28" Margin="0,4,0,8" VerticalContentAlignment="Center"/>
        <TextBlock Text="Body"/><TextBox x:Name="AlertBodyBox" Height="120" Margin="0,4,0,8" AcceptsReturn="True" VerticalScrollBarVisibility="Auto"/>
        <CheckBox x:Name="ForceHtmlBox" Content="Force HTML email body"/>
        <TextBlock Margin="0,8,0,0" Foreground="{StaticResource Muted}" TextWrapping="Wrap" Text="Placeholders: {MonitorName} {Status} {StatusCode} {Url} {TimeMs} {Message} {Timestamp}"/>
      </StackPanel></Border>
    </StackPanel></ScrollViewer>
    <DockPanel Grid.Row="1" Margin="0,12,0,0">
      <TextBlock x:Name="SmtpStatusText" VerticalAlignment="Center" TextWrapping="Wrap" MaxWidth="420"/>
      <StackPanel Orientation="Horizontal" HorizontalAlignment="Right">
        <Button x:Name="SmtpTestButton" Width="150" Margin="0,0,8,0" Content="Test connection"/>
        <Button x:Name="SmtpSaveButton" Style="{StaticResource PrimaryButton}" Width="100" Content="Save"/>
        <Button x:Name="SmtpCancelButton" IsCancel="True" Width="90" Margin="8,0,0,0" Content="Close"/>
      </StackPanel>
    </DockPanel>
  </Grid>
'@
    $names = 'SmtpServerBox', 'SmtpPortBox', 'SmtpAuthBox', 'SmtpSslBox', 'SmtpFromBox', 'SmtpUserBox', 'SmtpPassLabel', 'SmtpPassBox', 'OAuthSection', 'SmtpClientIdBox', 'SmtpClientSecretBox', 'SmtpTokenEndpointBox',
        'SmtpRefreshTokenBox', 'SmtpRefreshButton', 'AlertSubjectBox', 'AlertBodyBox', 'ForceHtmlBox', 'SmtpStatusText', 'SmtpTestButton', 'SmtpSaveButton', 'SmtpCancelButton'
    $dialog = New-DialogWindow -BodyXaml $body -ControlNames $names -Title 'Email alert configuration' -Width 760 -Height 840
    $window = $dialog.Window; $controls = $dialog.Controls
    foreach ($method in @('Basic', 'OAuth2')) { [void]$controls['SmtpAuthBox'].Items.Add($method) }
    $currentSettings = $script:settings
    $controls['SmtpServerBox'].Text = [string]$currentSettings.MonitorSmtpServer; $controls['SmtpPortBox'].Text = [string]$currentSettings.MonitorSmtpPort
    $controls['SmtpAuthBox'].SelectedItem = if ($currentSettings.MonitorSmtpAuthMethod) { [string]$currentSettings.MonitorSmtpAuthMethod } else { 'Basic' }
    $controls['SmtpSslBox'].IsChecked = [bool]$currentSettings.MonitorSmtpUseSsl; $controls['SmtpFromBox'].Text = [string]$currentSettings.MonitorSmtpFrom; $controls['SmtpUserBox'].Text = [string]$currentSettings.MonitorSmtpUser
    $controls['SmtpPassBox'].Password = [string]$currentSettings.MonitorSmtpPass
    $controls['SmtpClientIdBox'].Text = [string]$currentSettings.MonitorSmtpClientId; $controls['SmtpClientSecretBox'].Password = [string]$currentSettings.MonitorSmtpClientSecret
    $controls['SmtpTokenEndpointBox'].Text = [string]$currentSettings.MonitorSmtpTokenEndpoint; $controls['SmtpRefreshTokenBox'].Password = [string]$currentSettings.MonitorSmtpRefreshToken
    $controls['AlertSubjectBox'].Text = [string]$currentSettings.MonitorAlertSubjectTemplate; $controls['AlertBodyBox'].Text = [string]$currentSettings.MonitorAlertBodyTemplate; $controls['ForceHtmlBox'].IsChecked = [bool]$currentSettings.MonitorAlertBodyForceHtml

    $updateAuth = {
        $isOAuth = ([string]$controls['SmtpAuthBox'].SelectedItem -eq 'OAuth2')
        $controls['SmtpPassLabel'].Text = if ($isOAuth) { 'ACCESS TOKEN' } else { 'PASSWORD' }
        $controls['OAuthSection'].Visibility = if ($isOAuth) { 'Visible' } else { 'Collapsed' }
    }
    $controls['SmtpAuthBox'].Add_SelectionChanged($updateAuth)
    & $updateAuth

    $applyToSettings = {
        $port = 0; [void][int]::TryParse($controls['SmtpPortBox'].Text, [ref]$port)
        $script:settings.MonitorSmtpServer = $controls['SmtpServerBox'].Text; $script:settings.MonitorSmtpPort = $port; $script:settings.MonitorSmtpUseSsl = [bool]$controls['SmtpSslBox'].IsChecked
        $script:settings.MonitorSmtpFrom = $controls['SmtpFromBox'].Text; $script:settings.MonitorSmtpUser = $controls['SmtpUserBox'].Text; $script:settings.MonitorSmtpPass = $controls['SmtpPassBox'].Password
        $script:settings.MonitorSmtpAuthMethod = [string]$controls['SmtpAuthBox'].SelectedItem
        $script:settings.MonitorSmtpClientId = $controls['SmtpClientIdBox'].Text; $script:settings.MonitorSmtpClientSecret = $controls['SmtpClientSecretBox'].Password
        $script:settings.MonitorSmtpTokenEndpoint = $controls['SmtpTokenEndpointBox'].Text; $script:settings.MonitorSmtpRefreshToken = $controls['SmtpRefreshTokenBox'].Password
        $script:settings.MonitorAlertSubjectTemplate = $controls['AlertSubjectBox'].Text; $script:settings.MonitorAlertBodyTemplate = $controls['AlertBodyBox'].Text; $script:settings.MonitorAlertBodyForceHtml = [bool]$controls['ForceHtmlBox'].IsChecked
    }
    $controls['SmtpRefreshButton'].Add_Click({
        & $applyToSettings
        try { Update-SmtpToken; $controls['SmtpPassBox'].Password = [string]$script:settings.MonitorSmtpPass; $controls['SmtpStatusText'].Text = 'Token refreshed.'; $controls['SmtpStatusText'].Foreground = [System.Windows.Media.Brushes]::SeaGreen }
        catch { $controls['SmtpStatusText'].Text = "Failed to refresh the token: $($_.Exception.Message)"; $controls['SmtpStatusText'].Foreground = [System.Windows.Media.Brushes]::Firebrick }
    })
    $controls['SmtpSaveButton'].Add_Click({ & $applyToSettings; Save-Settings; $window.DialogResult = $true })
    $controls['SmtpTestButton'].Add_Click({
        if (-not $controls['SmtpServerBox'].Text -or -not $controls['SmtpFromBox'].Text) { $controls['SmtpStatusText'].Text = 'Enter the SMTP server and the From address.'; $controls['SmtpStatusText'].Foreground = [System.Windows.Media.Brushes]::DarkOrange; return }
        $recipient = Show-InputBox -Prompt 'Recipient for the test email:' -Title 'Test email' -DefaultText $controls['SmtpFromBox'].Text
        if (-not $recipient) { return }
        & $applyToSettings
        $controls['SmtpStatusText'].Text = 'Sending...'; $controls['SmtpStatusText'].Foreground = [System.Windows.Media.Brushes]::DimGray; Update-UiNow
        try {
            Send-MonitorEmail -To $recipient -Subject 'API Tester SMTP test' -Body "This is a test email ($($script:settings.MonitorSmtpAuthMethod))."
            $controls['SmtpStatusText'].Text = "Test email sent to $recipient."; $controls['SmtpStatusText'].Foreground = [System.Windows.Media.Brushes]::SeaGreen
        } catch { $controls['SmtpStatusText'].Text = "Failed to send: $($_.Exception.Message)"; $controls['SmtpStatusText'].Foreground = [System.Windows.Media.Brushes]::Firebrick }
    })
    [void](Show-WpfDialog -Window $window -OwnerForm $Owner)
}

# ------------------------------------------------------------------------------------------------
# Dashboard + chart window
# ------------------------------------------------------------------------------------------------

function Get-MonitorLogData {
    if (-not (Test-Path $monitorLogFilePath)) { return @() }
    try { return @(Import-Csv $monitorLogFilePath) } catch { return @() }
}

function Show-MonitoringDashboardWindow {
    $body = @'
  <Grid Margin="16,14,16,14">
    <Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="Auto"/><RowDefinition Height="*"/></Grid.RowDefinitions>
    <WrapPanel>
      <TextBlock Text="Monitor" VerticalAlignment="Center" Margin="0,0,6,0"/><ComboBox x:Name="DbMonitorBox" Width="200" Height="28" VerticalContentAlignment="Center" Margin="0,0,12,0"/>
      <TextBlock Text="From" VerticalAlignment="Center" Margin="0,0,6,0"/><DatePicker x:Name="DbFromPicker" Width="130" Margin="0,0,10,0"/>
      <TextBlock Text="To" VerticalAlignment="Center" Margin="0,0,6,0"/><DatePicker x:Name="DbToPicker" Width="130" Margin="0,0,12,0"/>
      <Button x:Name="DbRefreshButton" Style="{StaticResource PrimaryButton}" Padding="14,5" Margin="0,0,8,0" Content="Refresh"/>
      <Button x:Name="DbExportButton" Style="{StaticResource SmallButton}" Padding="12,5" Content="Export data"/>
      <Button x:Name="DbSaveChartButton" Style="{StaticResource SmallButton}" Padding="12,5" Content="Save chart"/>
      <Button x:Name="DbBrowserButton" Style="{StaticResource SmallButton}" Padding="12,5" Content="Open live view in browser"/>
    </WrapPanel>
    <WrapPanel Grid.Row="1" Margin="0,12,0,12">
      <Border Width="180" Height="92" Margin="0,0,12,0" CornerRadius="8" Background="{StaticResource Surface}" BorderBrush="{StaticResource Border}" BorderThickness="1" Padding="12,8"><StackPanel><TextBlock Style="{StaticResource SectionLabel}" Text="UPTIME"/><TextBlock x:Name="DbUptimeText" FontSize="26" FontWeight="Bold" Text="..."/></StackPanel></Border>
      <Border Width="180" Height="92" Margin="0,0,12,0" CornerRadius="8" Background="{StaticResource Surface}" BorderBrush="{StaticResource Border}" BorderThickness="1" Padding="12,8"><StackPanel><TextBlock Style="{StaticResource SectionLabel}" Text="AVG. LATENCY"/><TextBlock x:Name="DbLatencyText" FontSize="26" FontWeight="Bold" Text="..."/></StackPanel></Border>
      <Border Width="180" Height="92" Margin="0,0,12,0" CornerRadius="8" Background="{StaticResource Surface}" BorderBrush="{StaticResource Border}" BorderThickness="1" Padding="12,8"><StackPanel><TextBlock Style="{StaticResource SectionLabel}" Text="TOTAL RUNS"/><TextBlock x:Name="DbTotalText" FontSize="26" FontWeight="Bold" Text="..."/></StackPanel></Border>
      <Border Width="180" Height="92" Margin="0,0,12,0" CornerRadius="8" Background="{StaticResource Surface}" BorderBrush="{StaticResource Border}" BorderThickness="1" Padding="12,8"><StackPanel><TextBlock Style="{StaticResource SectionLabel}" Text="PASSED"/><TextBlock x:Name="DbPassedText" FontSize="26" FontWeight="Bold" Text="..."/></StackPanel></Border>
      <Border Width="180" Height="92" Margin="0,0,12,0" CornerRadius="8" Background="{StaticResource Surface}" BorderBrush="{StaticResource Border}" BorderThickness="1" Padding="12,8"><StackPanel><TextBlock Style="{StaticResource SectionLabel}" Text="FAILED"/><TextBlock x:Name="DbFailedText" FontSize="26" FontWeight="Bold" Text="..."/></StackPanel></Border>
      <Border Width="240" Height="92" CornerRadius="8" Background="{StaticResource Surface}" BorderBrush="{StaticResource Border}" BorderThickness="1" Padding="12,8"><StackPanel><TextBlock Style="{StaticResource SectionLabel}" Text="P50 / P95 / P99 (MS)"/><TextBlock x:Name="DbPercentileText" FontSize="22" FontWeight="Bold" Text="..."/></StackPanel></Border>
    </WrapPanel>
    <Border Grid.Row="2" Background="{StaticResource Surface}" BorderBrush="{StaticResource Border}" BorderThickness="1" CornerRadius="6"><Canvas x:Name="DbChart" ClipToBounds="True"/></Border>
  </Grid>
'@
    $names = 'DbMonitorBox', 'DbFromPicker', 'DbToPicker', 'DbRefreshButton', 'DbExportButton', 'DbSaveChartButton', 'DbBrowserButton', 'DbUptimeText', 'DbLatencyText', 'DbTotalText', 'DbPassedText', 'DbFailedText', 'DbPercentileText', 'DbChart'
    $dialog = New-DialogWindow -BodyXaml $body -ControlNames $names -Title 'Monitoring dashboard' -Width 1060 -Height 720
    $window = $dialog.Window; $controls = $dialog.Controls
    $controls['DbChart'].SetResourceReference([System.Windows.Controls.Panel]::BackgroundProperty, 'Surface')
    $script:dashboardData = @()
    $script:dashboardRefreshing = $false

    $update = {
        if ($script:dashboardRefreshing) { return }
        $script:dashboardRefreshing = $true
        try {
            $all = @(Get-MonitorLogData)
            $current = [string]$controls['DbMonitorBox'].SelectedItem
            $controls['DbMonitorBox'].Items.Clear(); [void]$controls['DbMonitorBox'].Items.Add('All Monitors')
            foreach ($name in @($all | Select-Object -ExpandProperty MonitorName -Unique | Sort-Object)) { [void]$controls['DbMonitorBox'].Items.Add($name) }
            $controls['DbMonitorBox'].SelectedItem = if ($current -and $controls['DbMonitorBox'].Items.Contains($current)) { $current } else { 'All Monitors' }
            $data = $all
            if ($controls['DbMonitorBox'].SelectedItem -ne 'All Monitors') { $data = @($all | Where-Object { $_.MonitorName -eq $controls['DbMonitorBox'].SelectedItem }) }
            if ($controls['DbFromPicker'].SelectedDate) { $from = $controls['DbFromPicker'].SelectedDate.Value.Date; $data = @($data | Where-Object { ([datetime]$_.Timestamp) -ge $from }) }
            if ($controls['DbToPicker'].SelectedDate) { $to = $controls['DbToPicker'].SelectedDate.Value.Date.AddDays(1).AddTicks(-1); $data = @($data | Where-Object { ([datetime]$_.Timestamp) -le $to }) }
            $script:dashboardData = $data
            if ($data.Count -eq 0) {
                foreach ($key in @('DbUptimeText', 'DbLatencyText', 'DbTotalText', 'DbPassedText', 'DbFailedText', 'DbPercentileText')) { $controls[$key].Text = 'N/A' }
                Update-LineChart -Canvas $controls['DbChart'] -Series @() -EmptyText 'No data for the selected monitor and date range.'
                return
            }
            $passed = @($data | Where-Object { $_.Success -eq 'True' }).Count
            $uptime = $passed / $data.Count
            $controls['DbUptimeText'].Text = '{0:P2}' -f $uptime
            $controls['DbUptimeText'].Foreground = if ($uptime -ge 0.99) { [System.Windows.Media.Brushes]::SeaGreen } elseif ($uptime -ge 0.95) { [System.Windows.Media.Brushes]::DarkOrange } else { [System.Windows.Media.Brushes]::Firebrick }
            $controls['DbLatencyText'].Text = '{0:N0} ms' -f ($data | Measure-Object -Property TimeMs -Average).Average
            $controls['DbTotalText'].Text = [string]$data.Count; $controls['DbPassedText'].Text = [string]$passed; $controls['DbFailedText'].Text = [string]($data.Count - $passed)
            $sortedTimes = [int[]]@($data | ForEach-Object { [int]$_.TimeMs } | Sort-Object)
            $controls['DbPercentileText'].Text = "$(Get-LatencyPercentile -SortedValues $sortedTimes -Fraction 0.5) / $(Get-LatencyPercentile -SortedValues $sortedTimes -Fraction 0.95) / $(Get-LatencyPercentile -SortedValues $sortedTimes -Fraction 0.99)"
            $sorted = @($data | Sort-Object { [datetime]$_.Timestamp })
            $span = ([datetime]$sorted[-1].Timestamp) - ([datetime]$sorted[0].Timestamp)
            Update-LineChart -Canvas $controls['DbChart'] -Series @(@{ Name = 'Latency (ms)'; Color = '#3659C9'; X = @($sorted | ForEach-Object { [double]([datetime]$_.Timestamp).Ticks }); Y = @($sorted | ForEach-Object { [double]$_.TimeMs }); Axis = 'Left' }) `
                -LeftTitle 'Latency (ms)' -XAsTime -TimeFormat $(if ($span.TotalDays -gt 1) { 'MM-dd HH:mm' } else { 'HH:mm' })
        } catch {
            foreach ($key in @('DbUptimeText', 'DbLatencyText', 'DbTotalText', 'DbPassedText', 'DbFailedText', 'DbPercentileText')) { $controls[$key].Text = 'N/A' }
        } finally { $script:dashboardRefreshing = $false }
    }
    $controls['DbRefreshButton'].Add_Click({ & $update })
    $controls['DbBrowserButton'].Add_Click({ Open-MonitorDashboardInBrowser })
    $controls['DbMonitorBox'].Add_SelectionChanged({ & $update })
    $controls['DbFromPicker'].Add_SelectedDateChanged({ & $update })
    $controls['DbToPicker'].Add_SelectedDateChanged({ & $update })
    $controls['DbChart'].Add_SizeChanged({ & $update })
    $controls['DbExportButton'].Add_Click({
        if (@($script:dashboardData).Count -eq 0) { [void][System.Windows.MessageBox]::Show($window, 'There is no data to export.', 'Export', 'OK', 'Information'); return }
        $picker = New-Object Microsoft.Win32.SaveFileDialog; $picker.Filter = 'CSV file (*.csv)|*.csv'; $picker.FileName = "monitor_data_export_$((Get-Date).ToString('yyyyMMdd')).csv"
        if ($picker.ShowDialog($window) -eq $true) { $script:dashboardData | Export-Csv -Path $picker.FileName -NoTypeInformation -Encoding UTF8 }
    })
    $controls['DbSaveChartButton'].Add_Click({
        $picker = New-Object Microsoft.Win32.SaveFileDialog; $picker.Filter = 'PNG image (*.png)|*.png'; $picker.FileName = 'MonitorChart.png'
        if ($picker.ShowDialog($window) -eq $true) { try { Save-ElementAsPng -Element $controls['DbChart'] -Path $picker.FileName } catch { [void][System.Windows.MessageBox]::Show($window, "Failed to save the chart: $($_.Exception.Message)", 'Save chart', 'OK', 'Error') } }
    })
    [void](Show-WpfDialog -Window $window -OwnerForm (Get-MainWindow))
}

function Show-MonitorChartDialog {
    param($Owner)
    if (-not (Test-Path $monitorLogFilePath)) { [void][System.Windows.MessageBox]::Show($Owner, 'No monitor log file found.', 'Monitor analytics', 'OK', 'Information'); return }
    $body = @'
  <Grid Margin="16,14,16,14">
    <Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="*"/></Grid.RowDefinitions>
    <WrapPanel Margin="0,0,0,10"><TextBlock Text="Monitor" VerticalAlignment="Center" Margin="0,0,8,0"/><ComboBox x:Name="McMonitorBox" Width="240" Height="28" VerticalContentAlignment="Center" Margin="0,0,10,0"/><Button x:Name="McSaveButton" Style="{StaticResource SmallButton}" Padding="12,5" Content="Save image"/></WrapPanel>
    <Border Grid.Row="1" Background="{StaticResource Surface}" BorderBrush="{StaticResource Border}" BorderThickness="1" CornerRadius="6"><Canvas x:Name="McChart" ClipToBounds="True"/></Border>
  </Grid>
'@
    $dialog = New-DialogWindow -BodyXaml $body -ControlNames 'McMonitorBox', 'McSaveButton', 'McChart' -Title 'Monitor analytics' -Width 1000 -Height 680
    $window = $dialog.Window; $controls = $dialog.Controls
    $controls['McChart'].SetResourceReference([System.Windows.Controls.Panel]::BackgroundProperty, 'Surface')
    $data = @(Get-MonitorLogData | Select-Object @{ N = 'Time'; E = { [datetime]$_.Timestamp } }, MonitorName, @{ N = 'Ms'; E = { [int]$_.TimeMs } })
    foreach ($name in @($data | Select-Object -ExpandProperty MonitorName -Unique)) { [void]$controls['McMonitorBox'].Items.Add($name) }
    $draw = {
        $selected = [string]$controls['McMonitorBox'].SelectedItem
        $subset = @($data | Where-Object { $_.MonitorName -eq $selected } | Sort-Object Time)
        Update-LineChart -Canvas $controls['McChart'] -Series @(@{ Name = "$selected - response time (ms)"; Color = '#3659C9'; X = @($subset | ForEach-Object { [double]$_.Time.Ticks }); Y = @($subset | ForEach-Object { [double]$_.Ms }); Axis = 'Left' }) -LeftTitle 'ms' -XAsTime -TimeFormat 'HH:mm:ss' -EmptyText 'Select a monitor.'
    }
    $controls['McMonitorBox'].Add_SelectionChanged({ & $draw })
    $controls['McChart'].Add_SizeChanged({ & $draw })
    $controls['McSaveButton'].Add_Click({
        $picker = New-Object Microsoft.Win32.SaveFileDialog; $picker.Filter = 'PNG image (*.png)|*.png'; $picker.FileName = 'MonitorChart.png'
        if ($picker.ShowDialog($window) -eq $true) { Save-ElementAsPng -Element $controls['McChart'] -Path $picker.FileName }
    })
    if ($controls['McMonitorBox'].Items.Count -gt 0) { $controls['McMonitorBox'].SelectedIndex = 0 }
    [void](Show-WpfDialog -Window $window -OwnerForm $Owner)
}
#endregion

#region XAML Main Window
# New WPF/XAML main window, started with:  .\API-Tester.ps1 -NewUi
# It reads and writes the same files as the classic window (collections, history, environments, request tabs,
# templates, settings), so both UIs always show the same data.
#
#   NewMainWindow.ps1   - the XAML, startup and event wiring (this file)
#   NewRequestEditor.ps1 - request editor, request tabs, sending, response viewer
#   NewSidebar.ps1      - collections tree and history list
#   NewDialogs.ps1      - environments, templates, variables, save-to-collection, collection runner
#   NewMenuBar.ps1      - Menu / Tools / Monitor / Help
#   NewToolDialogs.ps1  - Settings, log viewer, cookie jar, JWT, About, diff viewer, report
#   NewNetworkDialogs.ps1 - WebSocket, gRPC, load tester
#   NewMonitorUi.ps1    - monitor engine, manager, editor, email settings, dashboard, charts
#   NewCharts.ps1       - line-chart renderer
#
# All handlers call top-level functions that read the controls from $script:ui, because event handlers run after
# the function that registered them has returned.

function Show-MainWindow {
    Import-Settings
    Import-Globals
    Import-Environments
    Import-Collections
    Import-Monitors
    Import-RequestTemplates
    if ($script:settings.EnableHistory) { Import-History }
    $script:monitorJobs = @{}
    if (-not $script:cookieJar) { $script:cookieJar = New-Object System.Collections.ArrayList }

    $themeName = if ($script:settings.AppTheme -and $script:Themes.ContainsKey($script:settings.AppTheme)) { $script:settings.AppTheme } else { 'Light' }
    $script:Theme = $script:Themes[$themeName]
    Initialize-NewUiTypes

    $xaml = @'
<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation" xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
        Title="API Tester" Height="900" Width="1440" MinHeight="480" MinWidth="760"
        WindowStartupLocation="CenterScreen" Background="@FORM@" Foreground="@TEXT@" FontFamily="Segoe UI">
  <Window.Resources>
    <!--APP_RESOURCES-->
    <Style x:Key="CodeBox" TargetType="TextBox" BasedOn="{StaticResource {x:Type TextBox}}">
      <Setter Property="FontFamily" Value="Consolas"/><Setter Property="FontSize" Value="13"/>
      <Setter Property="AcceptsReturn" Value="True"/><Setter Property="AcceptsTab" Value="True"/>
      <Setter Property="VerticalScrollBarVisibility" Value="Auto"/><Setter Property="HorizontalScrollBarVisibility" Value="Auto"/>
    </Style>
    <Style x:Key="TabCloseButton" TargetType="Button">
      <Setter Property="Width" Value="18"/><Setter Property="Height" Value="18"/><Setter Property="Margin" Value="10,0,0,0"/><Setter Property="Cursor" Value="Hand"/>
      <Setter Property="Foreground" Value="{Binding Foreground, RelativeSource={RelativeSource AncestorType=ListBoxItem}}"/>
      <Setter Property="Template"><Setter.Value>
        <ControlTemplate TargetType="Button">
          <Border x:Name="Bd" Background="Transparent" CornerRadius="9"><TextBlock Text="&#x2715;" FontSize="10" HorizontalAlignment="Center" VerticalAlignment="Center" Foreground="{TemplateBinding Foreground}"/></Border>
          <ControlTemplate.Triggers><Trigger Property="IsMouseOver" Value="True"><Setter TargetName="Bd" Property="Background" Value="#40808080"/></Trigger></ControlTemplate.Triggers>
        </ControlTemplate>
      </Setter.Value></Setter>
    </Style>
    <Style x:Key="RequestTabItem" TargetType="ListBoxItem">
      <Setter Property="Padding" Value="14,7"/><Setter Property="Margin" Value="0,0,4,0"/><Setter Property="Cursor" Value="Hand"/>
      <Setter Property="Foreground" Value="{StaticResource SoftText}"/><Setter Property="Background" Value="{StaticResource Soft}"/>
      <Setter Property="Template"><Setter.Value>
        <ControlTemplate TargetType="ListBoxItem">
          <Border x:Name="TabBorder" Background="{TemplateBinding Background}" CornerRadius="6,6,0,0" Padding="{TemplateBinding Padding}">
            <ContentPresenter TextElement.Foreground="{TemplateBinding Foreground}"/>
          </Border>
          <ControlTemplate.Triggers>
            <Trigger Property="IsSelected" Value="True"><Setter TargetName="TabBorder" Property="Background" Value="{StaticResource Primary}"/><Setter Property="Foreground" Value="White"/></Trigger>
          </ControlTemplate.Triggers>
        </ControlTemplate>
      </Setter.Value></Setter>
    </Style>
  </Window.Resources>
  <Grid>
    <Grid.RowDefinitions><RowDefinition Height="72"/><RowDefinition Height="Auto"/><RowDefinition Height="Auto"/><RowDefinition Height="Auto"/><RowDefinition Height="*"/></Grid.RowDefinitions>

    <!-- Header -->
    <Border Grid.Row="0">
      <Border.Background><LinearGradientBrush StartPoint="0,0" EndPoint="1,0"><GradientStop Color="#3659C9" Offset="0"/><GradientStop Color="#243E9E" Offset="1"/></LinearGradientBrush></Border.Background>
      <Grid Margin="24,0">
        <Grid.ColumnDefinitions><ColumnDefinition Width="Auto"/><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions>
        <StackPanel VerticalAlignment="Center">
          <TextBlock Text="API Tester" FontSize="24" FontWeight="SemiBold" Foreground="White"/>
          <TextBlock Text="Request workspace" Margin="2,2,0,0" Foreground="#DCE7FF"/>
        </StackPanel>
        <Border Grid.Column="1" Height="34" Margin="30,0" Padding="16,0" HorizontalAlignment="Center" VerticalAlignment="Center" CornerRadius="17" Background="#22FFFFFF" MaxWidth="560">
          <TextBlock x:Name="StatusText" VerticalAlignment="Center" TextTrimming="CharacterEllipsis" Foreground="#DCE7FF" Text="Ready"/>
        </Border>
        <StackPanel x:Name="EnvironmentPanel" Grid.Column="2" Orientation="Horizontal" VerticalAlignment="Center">
          <TextBlock Text="Environment" Foreground="#DCE7FF" VerticalAlignment="Center" Margin="0,0,8,0"/>
          <ComboBox x:Name="EnvironmentBox" Width="190" Height="34" VerticalContentAlignment="Center"/>
          <Button x:Name="ManageEnvironmentsButton" Height="34" Margin="8,0,0,0" Padding="14,0" Content="Manage..." ToolTip="Add, edit and remove environments"/>
          <Button x:Name="SettingsButton" Height="34" Margin="8,0,0,0" Padding="14,0" Content="&#x2699; Settings" ToolTip="Application settings"/>
        </StackPanel>
      </Grid>
    </Border>

    <!-- Menu bar -->
    <Border Grid.Row="1" Background="{StaticResource Surface}" BorderBrush="{StaticResource Border}" BorderThickness="0,0,0,1">
      <Menu x:Name="MainMenu" Background="Transparent" Padding="14,3" FontSize="13">
        <MenuItem Header="_Menu" Foreground="{StaticResource Text}">
          <MenuItem x:Name="MenuImportCurl" Header="Import _cURL..."/>
          <MenuItem x:Name="MenuImportPostman" Header="Import _Postman / Insomnia / HAR / OpenAPI..."/>
          <MenuItem x:Name="MenuImportWorkspace" Header="Import _Workspace..."/>
          <MenuItem x:Name="MenuExportWorkspace" Header="_Export Workspace..."/>
          <Separator/>
          <MenuItem x:Name="MenuResetLayout" Header="Reset _Layout"/>
          <MenuItem x:Name="MenuSettings" Header="_Settings..."/>
          <Separator/>
          <MenuItem x:Name="MenuExit" Header="E_xit" InputGestureText="Alt+F4"/>
        </MenuItem>
        <MenuItem Header="_Tools" Foreground="{StaticResource Text}">
          <MenuItem x:Name="MenuEnvironments" Header="Manage _Environments..."/>
          <MenuItem x:Name="MenuGlobalVariables" Header="_Global Variables..."/>
          <MenuItem x:Name="MenuTemplates" Header="Request _Templates..."/>
          <Separator/>
          <MenuItem x:Name="MenuProxy" Header="_Proxy Configuration..."/>
          <MenuItem x:Name="MenuCookieJar" Header="_Cookie Jar..."/>
          <MenuItem x:Name="MenuJwt" Header="_JWT Utility..."/>
          <MenuItem x:Name="MenuReport" Header="Generate _Report..."/>
          <MenuItem x:Name="MenuWebSocket" Header="_WebSocket Client..."/>
          <MenuItem x:Name="MenuGrpc" Header="g_RPC Client..."/>
          <MenuItem x:Name="MenuLoadTester" Header="_Load Tester..."/>
        </MenuItem>
        <MenuItem Header="_Monitor" Foreground="{StaticResource Text}">
          <MenuItem x:Name="MenuMonitorManager" Header="Monitor _Manager..."/>
          <MenuItem x:Name="MenuMonitorDashboard" Header="Monitoring _Dashboard..."/>
          <MenuItem x:Name="MenuMonitorBrowser" Header="Open Monitors in _Browser"/>
        </MenuItem>
        <MenuItem Header="_Help" Foreground="{StaticResource Text}">
          <MenuItem x:Name="MenuAbout" Header="_About API Tester..."/>
          <MenuItem x:Name="MenuShortcuts" Header="_Keyboard Shortcuts..."/>
        </MenuItem>
      </Menu>
    </Border>

    <!-- Request tabs strip -->
    <Border Grid.Row="2" Background="{StaticResource Surface}" BorderBrush="{StaticResource Border}" BorderThickness="0,0,0,1" Padding="14,8,14,0">
      <ScrollViewer HorizontalScrollBarVisibility="Auto" VerticalScrollBarVisibility="Disabled">
        <StackPanel Orientation="Horizontal">
          <ListBox x:Name="RequestTabsStrip" BorderThickness="0" Background="Transparent" ItemContainerStyle="{StaticResource RequestTabItem}" ScrollViewer.HorizontalScrollBarVisibility="Disabled">
            <ListBox.ItemsPanel><ItemsPanelTemplate><StackPanel Orientation="Horizontal"/></ItemsPanelTemplate></ListBox.ItemsPanel>
          </ListBox>
          <Button x:Name="NewTabButton" Content="+" Width="34" Height="32" Padding="0" Margin="2,0,0,2" FontSize="17" VerticalAlignment="Bottom" ToolTip="New request tab (Ctrl+T)"/>
        </StackPanel>
      </ScrollViewer>
    </Border>

    <!-- Request bar -->
    <Border Grid.Row="3" Margin="14,12,14,0" Background="{StaticResource Surface}" BorderBrush="{StaticResource Border}" BorderThickness="1" CornerRadius="8" Padding="12">
      <Grid>
        <Grid.ColumnDefinitions><ColumnDefinition Width="Auto"/><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions>
        <ComboBox x:Name="MethodBox" Width="120" Height="36" VerticalContentAlignment="Center" FontWeight="SemiBold"/>
        <Border x:Name="UrlEditorHost" Grid.Column="1" Margin="10,0,10,0" Height="36" Background="{StaticResource Input}" BorderBrush="{StaticResource Border}" BorderThickness="1" CornerRadius="6">
          <ScrollViewer x:Name="UrlScroll" HorizontalScrollBarVisibility="Hidden" VerticalScrollBarVisibility="Disabled" Padding="8,0">
            <Grid MinWidth="{Binding ViewportWidth, ElementName=UrlScroll}" Background="Transparent"><TextBlock x:Name="UrlHighlight" FontFamily="Segoe UI" FontSize="14" Margin="2,0,0,0" TextWrapping="NoWrap" IsHitTestVisible="False" VerticalAlignment="Center"/><TextBox x:Name="UrlBox" FontFamily="Segoe UI" FontSize="14" Background="Transparent" BorderThickness="0" Padding="0" VerticalScrollBarVisibility="Disabled" HorizontalScrollBarVisibility="Disabled" TextWrapping="NoWrap" VerticalAlignment="Center"/></Grid>
          </ScrollViewer>
        </Border>
        <StackPanel Grid.Column="2" Orientation="Horizontal">
          <Button x:Name="SendButton" Style="{StaticResource PrimaryButton}" Width="100" Height="36" Content="Send"/>
          <Button x:Name="StopButton" Width="90" Height="36" Margin="8,0,0,0" Content="Cancel" IsEnabled="False"/>
          <Button x:Name="RepeatButton" Width="90" Height="36" Margin="8,0,0,0" Content="Repeat..." Visibility="Collapsed" ToolTip="Send the request several times"/>
          <Button x:Name="SaveRequestButton" Width="80" Height="36" Margin="8,0,0,0" Content="Save" ToolTip="Save to the selected collection (or update the request this tab was loaded from)"/>
          <Button x:Name="TemplatesButton" Width="100" Height="36" Margin="8,0,0,0" Content="Templates..."/>
        </StackPanel>
      </Grid>
    </Border>

    <!-- Main area -->
    <Grid Grid.Row="4" Margin="14,10,14,12">
      <Grid.ColumnDefinitions><ColumnDefinition x:Name="SidebarColumn" Width="310"/><ColumnDefinition x:Name="SidebarSplitterColumn" Width="6"/><ColumnDefinition Width="*"/></Grid.ColumnDefinitions>

      <!-- Sidebar -->
      <TabControl x:Name="SidebarTabs" Grid.Column="0" ToolTip="Right-click a tab header to undock this panel" Background="{StaticResource Surface}" BorderBrush="{StaticResource Border}">
        <TabItem x:Name="TabCollections" Header="Collections">
          <Grid>
            <Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="*"/><RowDefinition Height="Auto"/></Grid.RowDefinitions>
            <TextBox x:Name="CollectionFilterBox" Margin="8,8,8,4" Height="28" VerticalContentAlignment="Center" ToolTip="Filter requests by name or URL"/>
            <TreeView x:Name="CollectionsTree" Grid.Row="1" BorderThickness="0" Background="Transparent" Margin="2"/>
            <WrapPanel Grid.Row="2" Margin="8,4,8,8">
              <Button x:Name="NewCollectionButton" Style="{StaticResource SmallButton}" Content="New"/>
              <Button x:Name="ImportCollectionsButton" Style="{StaticResource SmallButton}" Content="Import..."/>
              <Button x:Name="ExportCollectionsButton" Style="{StaticResource SmallButton}" Content="Export..."/>
            </WrapPanel>
          </Grid>
        </TabItem>
        <TabItem x:Name="TabHistory" Header="History">
          <Grid>
            <Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="*"/><RowDefinition Height="Auto"/></Grid.RowDefinitions>
            <StackPanel Margin="8,8,8,4">
              <TextBox x:Name="HistoryFilterBox" Height="28" VerticalContentAlignment="Center" ToolTip="Search by method or URL"/>
              <ComboBox x:Name="HistoryEnvironmentBox" Margin="0,6,0,0" Height="28" VerticalContentAlignment="Center" ToolTip="Filter history by environment"/>
            </StackPanel>
            <ListBox x:Name="HistoryList" Grid.Row="1" BorderThickness="0" Background="Transparent" SelectionMode="Extended" Margin="2"/>
            <WrapPanel Grid.Row="2" Margin="8,4,8,8">
              <Button x:Name="ClearHistoryButton" Style="{StaticResource SmallButton}" Content="Clear"/>
              <Button x:Name="ExportHistoryButton" Style="{StaticResource SmallButton}" Content="Export..."/>
            </WrapPanel>
          </Grid>
        </TabItem>
      </TabControl>
      <GridSplitter x:Name="SidebarSplitter" Grid.Column="1" HorizontalAlignment="Stretch" Background="Transparent"/>

      <!-- Workspace: editor + response -->
      <Grid x:Name="WorkspaceGrid" Grid.Column="2">
        <Grid.RowDefinitions><RowDefinition Height="*" MinHeight="140"/><RowDefinition Height="6"/><RowDefinition Height="1.4*" MinHeight="160"/></Grid.RowDefinitions>
        <Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="0"/><ColumnDefinition Width="0"/></Grid.ColumnDefinitions>

        <!-- Request editor -->
        <TabControl x:Name="RequestTabs" Grid.Row="0" Grid.Column="0" Grid.ColumnSpan="3" Background="{StaticResource Surface}" BorderBrush="{StaticResource Border}">
          <TabItem x:Name="TabParams" Header="Params">
            <Grid Margin="10"><Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="*"/></Grid.RowDefinitions>
              <WrapPanel Margin="0,0,0,6">
                <Button x:Name="AddParamButton" Style="{StaticResource SmallButton}" Content="+ Add parameter"/>
                <Button x:Name="RemoveParamButton" Style="{StaticResource SmallButton}" Content="Remove selected"/>
                <TextBlock Style="{StaticResource SectionLabel}" VerticalAlignment="Center" Text="Query parameters - edits here update the URL, and the other way round."/>
              </WrapPanel>
              <DataGrid x:Name="ParamsGrid" Grid.Row="1" AutoGenerateColumns="False" CanUserAddRows="False" HeadersVisibility="Column" SelectionMode="Extended" GridLinesVisibility="Horizontal" Background="Transparent" RowBackground="Transparent">
                <DataGrid.Columns>
                  <DataGridTextColumn Header="Key" Binding="{Binding Key, UpdateSourceTrigger=PropertyChanged}" Width="220"/>
                  <DataGridTextColumn Header="Value" Binding="{Binding Value, UpdateSourceTrigger=PropertyChanged}" Width="*"/>
                </DataGrid.Columns>
              </DataGrid>
            </Grid>
          </TabItem>
          <TabItem x:Name="TabHeaders" Header="Headers">
            <Grid Margin="10"><Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="*"/></Grid.RowDefinitions>
              <TextBlock Style="{StaticResource SectionLabel}" Text="ONE HEADER PER LINE  -  Name: value"/>
              <Border x:Name="HeadersEditorHost" Grid.Row="1" Margin="0,8,0,0" Background="{StaticResource Input}" BorderBrush="{StaticResource Border}" BorderThickness="1" CornerRadius="6">
                <ScrollViewer x:Name="HeadersScroll" HorizontalScrollBarVisibility="Auto" VerticalScrollBarVisibility="Auto" Padding="4,4,6,4">
                  <Grid MinWidth="{Binding ViewportWidth, ElementName=HeadersScroll}" MinHeight="{Binding ViewportHeight, ElementName=HeadersScroll}" Background="Transparent"><TextBlock x:Name="HeadersHighlight" FontFamily="Consolas" FontSize="13" Margin="2,0,0,0" TextWrapping="NoWrap" IsHitTestVisible="False"/><TextBox x:Name="HeadersBox" FontFamily="Consolas" FontSize="13" Background="Transparent" BorderThickness="0" Padding="0" VerticalScrollBarVisibility="Disabled" HorizontalScrollBarVisibility="Disabled" TextWrapping="NoWrap" AcceptsReturn="True" AcceptsTab="True"/></Grid>
                </ScrollViewer>
              </Border>
            </Grid>
          </TabItem>
          <TabItem x:Name="TabBody" Header="Body">
            <Grid Margin="10">
              <Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="*"/></Grid.RowDefinitions>
              <Grid>
                <Grid.ColumnDefinitions><ColumnDefinition Width="Auto"/><ColumnDefinition Width="Auto"/><ColumnDefinition Width="*"/></Grid.ColumnDefinitions>
                <ComboBox x:Name="BodyTypeBox" Grid.Column="0" Width="250" Height="30" VerticalContentAlignment="Center" VerticalAlignment="Center"/>
                <Button x:Name="BeautifyButton" Grid.Column="1" Style="{StaticResource SmallButton}" Height="30" Margin="10,0,0,0" VerticalAlignment="Center" Content="Beautify" ToolTip="Pretty-print JSON or XML"/>
                <TextBlock x:Name="BodyOptionsHint" Grid.Column="2" Margin="14,0,0,0" VerticalAlignment="Center" TextTrimming="CharacterEllipsis" Foreground="{StaticResource Muted}" Visibility="Collapsed"
                           Text="File name / content-type options and Save to file: Options tab" ToolTip="Options tab: multipart options, output format field and where to save the response"/>
              </Grid>
              <Grid Grid.Row="1" Margin="0,10,0,0">
                <Border x:Name="BodyEditorHost"  Background="{StaticResource Input}" BorderBrush="{StaticResource Border}" BorderThickness="1" CornerRadius="6">
                  <Grid>
                    <Grid.ColumnDefinitions><ColumnDefinition Width="Auto"/><ColumnDefinition Width="*"/></Grid.ColumnDefinitions>
                    <ScrollViewer x:Name="BodyGutterScroll" VerticalScrollBarVisibility="Hidden" HorizontalScrollBarVisibility="Disabled" IsHitTestVisible="False" Padding="0,4,0,4" Background="{StaticResource Surface}"><TextBlock x:Name="BodyGutter" FontFamily="Consolas" FontSize="13" Foreground="{StaticResource Muted}" TextAlignment="Right" MinWidth="26" Margin="8,0,8,0"/></ScrollViewer>
                    <ScrollViewer x:Name="BodyScroll" Grid.Column="1" HorizontalScrollBarVisibility="Auto" VerticalScrollBarVisibility="Auto" Padding="4,4,6,4">
                      <Grid MinWidth="{Binding ViewportWidth, ElementName=BodyScroll}" MinHeight="{Binding ViewportHeight, ElementName=BodyScroll}" Background="Transparent"><TextBlock x:Name="BodyHighlight" FontFamily="Consolas" FontSize="13" Margin="2,0,0,0" TextWrapping="NoWrap" IsHitTestVisible="False"/><TextBox x:Name="BodyBox" FontFamily="Consolas" FontSize="13" Background="Transparent" BorderThickness="0" Padding="0" VerticalScrollBarVisibility="Disabled" HorizontalScrollBarVisibility="Disabled" TextWrapping="NoWrap" AcceptsReturn="True" AcceptsTab="True"/></Grid>
                    </ScrollViewer>
                  </Grid>
                </Border>
                <Grid x:Name="MultipartPanel" Visibility="Collapsed" AllowDrop="True">
                  <Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="*"/></Grid.RowDefinitions>
                  <WrapPanel Margin="0,0,0,6">
                    <Button x:Name="AddFieldButton" Style="{StaticResource SmallButton}" Content="+ Text field"/>
                    <Button x:Name="AddFileButton" Style="{StaticResource SmallButton}" Content="+ Attach file(s)..."/>
                    <Button x:Name="RemoveRowButton" Style="{StaticResource SmallButton}" Content="Remove selected"/>
                    <Button x:Name="ClearRowsButton" Style="{StaticResource SmallButton}" Content="Clear all"/>
                    <TextBlock Style="{StaticResource SectionLabel}" VerticalAlignment="Center" TextWrapping="Wrap" Text="Set a row's Type to File to choose a file for that key (or use its Browse button). Files can also be dropped onto a row or onto the grid."/>
                  </WrapPanel>
                  <DataGrid x:Name="MultipartGrid" Grid.Row="1" AutoGenerateColumns="False" CanUserAddRows="False" CanUserReorderColumns="False" CanUserSortColumns="False" HeadersVisibility="Column" SelectionMode="Extended" SelectionUnit="FullRow" GridLinesVisibility="Horizontal" Background="Transparent" RowBackground="Transparent" AllowDrop="True">
                    <DataGrid.Columns>
                      <DataGridTemplateColumn Header="Key" Width="150">
                        <DataGridTemplateColumn.CellTemplate><DataTemplate><TextBox Text="{Binding Key, UpdateSourceTrigger=PropertyChanged}" BorderThickness="0" Background="Transparent" Padding="2,0" VerticalContentAlignment="Center" MinHeight="24"/></DataTemplate></DataGridTemplateColumn.CellTemplate>
                      </DataGridTemplateColumn>
                      <DataGridTemplateColumn Header="Type" Width="100">
                        <DataGridTemplateColumn.CellTemplate><DataTemplate><ComboBox ItemsSource="{Binding KindChoices}" SelectedItem="{Binding Kind, UpdateSourceTrigger=PropertyChanged}" Height="26" Padding="8,2,26,2" VerticalContentAlignment="Center" ToolTip="Text value or file upload"/></DataTemplate></DataGridTemplateColumn.CellTemplate>
                      </DataGridTemplateColumn>
                      <DataGridTemplateColumn Header="Value" Width="*">
                        <DataGridTemplateColumn.CellTemplate>
                          <DataTemplate>
                            <Grid>
                              <TextBox x:Name="TextValueBox" Text="{Binding Value, UpdateSourceTrigger=PropertyChanged}" BorderThickness="0" Background="Transparent" Padding="2,0" VerticalContentAlignment="Center" MinHeight="24" ToolTip="Text value (supports {{variables}})"/>
                              <DockPanel x:Name="FileValuePanel" Visibility="Collapsed">
                                <Button DockPanel.Dock="Right" Tag="BrowseFile" Content="Browse..." Padding="10,1" Margin="6,1,2,1" ToolTip="Choose the file to upload"/>
                                <TextBlock x:Name="FileLabelText" Text="{Binding FileLabel}" ToolTip="{Binding Value}" VerticalAlignment="Center" TextTrimming="CharacterEllipsis" Margin="2,0"/>
                              </DockPanel>
                            </Grid>
                            <DataTemplate.Triggers>
                              <DataTrigger Binding="{Binding IsFile}" Value="True">
                                <Setter TargetName="TextValueBox" Property="Visibility" Value="Collapsed"/>
                                <Setter TargetName="FileValuePanel" Property="Visibility" Value="Visible"/>
                              </DataTrigger>
                              <DataTrigger Binding="{Binding HasValue}" Value="False">
                                <Setter TargetName="FileLabelText" Property="Foreground" Value="{StaticResource Muted}"/>
                                <Setter TargetName="FileLabelText" Property="FontStyle" Value="Italic"/>
                              </DataTrigger>
                            </DataTemplate.Triggers>
                          </DataTemplate>
                        </DataGridTemplateColumn.CellTemplate>
                      </DataGridTemplateColumn>
                      <DataGridTemplateColumn Header="File name" Width="150">
                        <DataGridTemplateColumn.CellTemplate>
                          <DataTemplate>
                            <Grid>
                              <TextBlock x:Name="FileNameDash" Text="&#x2013;" Foreground="{StaticResource Muted}" VerticalAlignment="Center" Margin="4,0" ToolTip="Only used for file uploads"/>
                              <TextBox x:Name="FileNameBox" Text="{Binding FileName, UpdateSourceTrigger=PropertyChanged}" BorderThickness="0" Background="Transparent" Padding="2,0" VerticalContentAlignment="Center" MinHeight="24" Visibility="Collapsed" ToolTip="File name sent to the server"/>
                            </Grid>
                            <DataTemplate.Triggers>
                              <DataTrigger Binding="{Binding IsFile}" Value="True"><Setter TargetName="FileNameBox" Property="Visibility" Value="Visible"/><Setter TargetName="FileNameDash" Property="Visibility" Value="Collapsed"/></DataTrigger>
                            </DataTemplate.Triggers>
                          </DataTemplate>
                        </DataGridTemplateColumn.CellTemplate>
                      </DataGridTemplateColumn>
                      <DataGridTemplateColumn Header="Content type" Width="170">
                        <DataGridTemplateColumn.CellTemplate>
                          <DataTemplate>
                            <Grid>
                              <TextBlock x:Name="ContentTypeDash" Text="&#x2013;" Foreground="{StaticResource Muted}" VerticalAlignment="Center" Margin="4,0" ToolTip="Only used for file uploads"/>
                              <TextBox x:Name="ContentTypeBox" Text="{Binding ContentType, UpdateSourceTrigger=PropertyChanged}" BorderThickness="0" Background="Transparent" Padding="2,0" VerticalContentAlignment="Center" MinHeight="24" Visibility="Collapsed" ToolTip="MIME type of the file (filled in automatically)"/>
                            </Grid>
                            <DataTemplate.Triggers>
                              <DataTrigger Binding="{Binding IsFile}" Value="True"><Setter TargetName="ContentTypeBox" Property="Visibility" Value="Visible"/><Setter TargetName="ContentTypeDash" Property="Visibility" Value="Collapsed"/></DataTrigger>
                            </DataTemplate.Triggers>
                          </DataTemplate>
                        </DataGridTemplateColumn.CellTemplate>
                      </DataGridTemplateColumn>
                    </DataGrid.Columns>
                  </DataGrid>
                </Grid>
                <Grid x:Name="GraphQLPanel" Visibility="Collapsed">
                  <Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="10"/><ColumnDefinition Width="0.6*"/></Grid.ColumnDefinitions>
                  <Grid><Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="*"/></Grid.RowDefinitions>
                    <TextBlock Style="{StaticResource SectionLabel}" Text="QUERY"/><TextBox x:Name="GqlQueryBox" Grid.Row="1" Margin="0,6,0,0" Style="{StaticResource CodeBox}"/></Grid>
                  <Grid Grid.Column="2"><Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="*"/></Grid.RowDefinitions>
                    <TextBlock Style="{StaticResource SectionLabel}" Text="VARIABLES (JSON)"/><TextBox x:Name="GqlVarsBox" Grid.Row="1" Margin="0,6,0,0" Style="{StaticResource CodeBox}"/></Grid>
                </Grid>
              </Grid>
            </Grid>
          </TabItem>
          <TabItem x:Name="TabAuth" Header="Auth">
            <ScrollViewer VerticalScrollBarVisibility="Auto">
              <StackPanel Margin="14">
                <ComboBox x:Name="AuthTypeBox" Width="240" Height="30" HorizontalAlignment="Left" VerticalContentAlignment="Center"/>
                <TextBlock x:Name="InheritNote" Margin="0,12,0,0" TextWrapping="Wrap" Foreground="{StaticResource Muted}" Visibility="Collapsed" Text="Uses the auth set on the parent folder or collection (Collections panel: right-click a folder or collection, then Settings). Requests that are not saved in a collection send no auth."/>
                <StackPanel x:Name="BearerPanel" Margin="0,12,0,0" Visibility="Collapsed">
                  <TextBlock Style="{StaticResource SectionLabel}" Text="TOKEN"/>
                  <TextBox x:Name="BearerTokenBox" Margin="0,6,0,0" Height="30" VerticalContentAlignment="Center"/>
                </StackPanel>
                <Grid x:Name="BasicPanel" Margin="0,12,0,0" Visibility="Collapsed">
                  <Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="14"/><ColumnDefinition Width="*"/></Grid.ColumnDefinitions>
                  <StackPanel><TextBlock Style="{StaticResource SectionLabel}" Text="USERNAME"/><TextBox x:Name="BasicUserBox" Margin="0,6,0,0" Height="30" VerticalContentAlignment="Center"/></StackPanel>
                  <StackPanel Grid.Column="2"><TextBlock Style="{StaticResource SectionLabel}" Text="PASSWORD"/><PasswordBox x:Name="BasicPasswordBox" Margin="0,6,0,0" Height="30" VerticalContentAlignment="Center"/></StackPanel>
                </Grid>
                <Grid x:Name="ApiKeyPanel" Margin="0,12,0,0" Visibility="Collapsed">
                  <Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="14"/><ColumnDefinition Width="*"/><ColumnDefinition Width="14"/><ColumnDefinition Width="170"/></Grid.ColumnDefinitions>
                  <StackPanel><TextBlock Style="{StaticResource SectionLabel}" Text="KEY NAME"/><TextBox x:Name="ApiKeyNameBox" Margin="0,6,0,0" Height="30" VerticalContentAlignment="Center"/></StackPanel>
                  <StackPanel Grid.Column="2"><TextBlock Style="{StaticResource SectionLabel}" Text="VALUE"/><TextBox x:Name="ApiKeyValueBox" Margin="0,6,0,0" Height="30" VerticalContentAlignment="Center"/></StackPanel>
                  <StackPanel Grid.Column="4"><TextBlock Style="{StaticResource SectionLabel}" Text="ADD TO"/><ComboBox x:Name="ApiKeyLocationBox" Margin="0,6,0,0" Height="30" VerticalContentAlignment="Center"/></StackPanel>
                </Grid>
                <Grid x:Name="OAuthPanel" Margin="0,12,0,0" Visibility="Collapsed">
                  <Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="14"/><ColumnDefinition Width="*"/></Grid.ColumnDefinitions>
                  <Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="Auto"/><RowDefinition Height="Auto"/><RowDefinition Height="Auto"/><RowDefinition Height="Auto"/><RowDefinition Height="Auto"/></Grid.RowDefinitions>
                  <StackPanel><TextBlock Style="{StaticResource SectionLabel}" Text="CLIENT ID"/><TextBox x:Name="OAuthClientIdBox" Margin="0,6,0,10" Height="28" VerticalContentAlignment="Center"/></StackPanel>
                  <StackPanel Grid.Column="2"><TextBlock Style="{StaticResource SectionLabel}" Text="CLIENT SECRET"/><TextBox x:Name="OAuthClientSecretBox" Margin="0,6,0,10" Height="28" VerticalContentAlignment="Center"/></StackPanel>
                  <StackPanel Grid.Row="1"><TextBlock Style="{StaticResource SectionLabel}" Text="AUTHORIZATION ENDPOINT"/><TextBox x:Name="OAuthAuthEndpointBox" Margin="0,6,0,10" Height="28" VerticalContentAlignment="Center"/></StackPanel>
                  <StackPanel Grid.Row="1" Grid.Column="2"><TextBlock Style="{StaticResource SectionLabel}" Text="TOKEN ENDPOINT"/><TextBox x:Name="OAuthTokenEndpointBox" Margin="0,6,0,10" Height="28" VerticalContentAlignment="Center"/></StackPanel>
                  <StackPanel Grid.Row="2"><TextBlock Style="{StaticResource SectionLabel}" Text="REDIRECT URI"/><TextBox x:Name="OAuthRedirectUriBox" Margin="0,6,0,10" Height="28" VerticalContentAlignment="Center"/></StackPanel>
                  <StackPanel Grid.Row="2" Grid.Column="2"><TextBlock Style="{StaticResource SectionLabel}" Text="SCOPE"/><TextBox x:Name="OAuthScopeBox" Margin="0,6,0,10" Height="28" VerticalContentAlignment="Center"/></StackPanel>
                  <StackPanel Grid.Row="3" Grid.ColumnSpan="3"><TextBlock Style="{StaticResource SectionLabel}" Text="ACCESS TOKEN"/><TextBox x:Name="OAuthAccessTokenBox" Margin="0,6,0,10" Height="28" VerticalContentAlignment="Center"/></StackPanel>
                  <StackPanel Grid.Row="4"><TextBlock Style="{StaticResource SectionLabel}" Text="REFRESH TOKEN"/><TextBox x:Name="OAuthRefreshTokenBox" Margin="0,6,0,10" Height="28" VerticalContentAlignment="Center"/></StackPanel>
                  <StackPanel Grid.Row="4" Grid.Column="2"><TextBlock Style="{StaticResource SectionLabel}" Text="EXPIRES IN (SECONDS)"/><TextBox x:Name="OAuthExpiresInBox" Margin="0,6,0,10" Height="28" VerticalContentAlignment="Center"/></StackPanel>
                  <WrapPanel Grid.Row="5" Grid.ColumnSpan="3">
                    <Button x:Name="OAuthClientCredentialsButton" Style="{StaticResource SmallButton}" Content="Get token (client credentials)"/>
                    <Button x:Name="OAuthAuthorizationCodeButton" Style="{StaticResource SmallButton}" Content="Get token (authorization code)..."/>
                    <Button x:Name="OAuthRefreshButton" Style="{StaticResource SmallButton}" Content="Refresh token"/>
                    <TextBlock x:Name="OAuthStatusText" VerticalAlignment="Center" Foreground="{StaticResource Muted}"/>
                  </WrapPanel>
                </Grid>
                <Grid x:Name="CertPanel" Margin="0,12,0,0" Visibility="Collapsed">
                  <Grid.ColumnDefinitions><ColumnDefinition Width="170"/><ColumnDefinition Width="14"/><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions>
                  <Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="Auto"/></Grid.RowDefinitions>
                  <StackPanel><TextBlock Style="{StaticResource SectionLabel}" Text="SOURCE"/><ComboBox x:Name="CertSourceBox" Margin="0,6,0,10" Height="28" VerticalContentAlignment="Center"/></StackPanel>
                  <StackPanel x:Name="CertPathPanel" Grid.Column="2"><TextBlock Style="{StaticResource SectionLabel}" Text="PFX FILE"/><TextBox x:Name="CertPathBox" Margin="0,6,0,10" Height="28" VerticalContentAlignment="Center"/></StackPanel>
                  <Button x:Name="CertBrowseButton" Grid.Column="3" Margin="8,22,0,10" Padding="12,3" Content="Browse..."/>
                  <StackPanel x:Name="CertPasswordPanel" Grid.Row="1" Grid.Column="2"><TextBlock Style="{StaticResource SectionLabel}" Text="PFX PASSWORD"/><PasswordBox x:Name="CertPasswordBox" Margin="0,6,0,10" Height="28" VerticalContentAlignment="Center"/></StackPanel>
                  <StackPanel x:Name="CertThumbPanel" Grid.Column="2" Visibility="Collapsed"><TextBlock Style="{StaticResource SectionLabel}" Text="THUMBPRINT (CURRENT USER STORE)"/><TextBox x:Name="CertThumbBox" Margin="0,6,0,10" Height="28" VerticalContentAlignment="Center"/></StackPanel>
                </Grid>
              </StackPanel>
            </ScrollViewer>
          </TabItem>
          <TabItem x:Name="TabPreRequest" Header="Pre-request">
            <Grid Margin="10"><Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="*"/></Grid.RowDefinitions>
              <TextBlock Style="{StaticResource SectionLabel}" TextWrapping="Wrap" Text="POWERSHELL RUN BEFORE SENDING  -  $ApiRequest (Method, Url, Headers, Body) and $Environment are available and may be changed"/>
              <TextBox x:Name="PreRequestBox" Grid.Row="1" Margin="0,8,0,0" Style="{StaticResource CodeBox}"/>
            </Grid>
          </TabItem>
          <TabItem x:Name="TabTests" Header="Tests">
            <Grid Margin="10"><Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="*"/></Grid.RowDefinitions>
              <DockPanel>
                <Button x:Name="TestSnippetsButton" DockPanel.Dock="Right" Style="{StaticResource SmallButton}" Margin="8,0,0,0" Content="Insert snippet &#x25BE;"/>
                <TextBlock Style="{StaticResource SectionLabel}" TextWrapping="Wrap" VerticalAlignment="Center" Text="POWERSHELL RUN AFTER THE RESPONSE  -  $statusCode, $headers, $body, $jsonBody, $responseTimeMs and Assert-Equal / Assert-Contains / Assert-StatusIs / Assert-True"/>
              </DockPanel>
              <TextBox x:Name="TestsBox" Grid.Row="1" Margin="0,8,0,0" Style="{StaticResource CodeBox}"/>
            </Grid>
          </TabItem>
          <TabItem x:Name="TabOptions" Header="Options">
            <ScrollViewer VerticalScrollBarVisibility="Auto" HorizontalScrollBarVisibility="Disabled">
              <StackPanel Margin="14,12,14,12" MaxWidth="820" HorizontalAlignment="Stretch">
                <Border Background="{StaticResource Surface}" BorderBrush="{StaticResource Border}" BorderThickness="1" CornerRadius="8" Padding="16,12" Margin="0,0,0,12">
                  <StackPanel>
                    <TextBlock Style="{StaticResource SectionLabel}" Text="SAVE RESPONSE TO FILE"/>
                    <TextBlock Margin="0,4,0,10" TextWrapping="Wrap" Foreground="{StaticResource Muted}" Text="Binary and attachment responses (for example a generated document) are written to this file after each send. When Auto-save is switched on in Settings, files go to the auto-save folder instead."/>
                    <Grid>
                      <Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions>
                      <TextBox x:Name="OutputFileBox" Height="30" VerticalContentAlignment="Center" ToolTip="Full path of the file to write, for example C:\Temp\result.docx"/>
                      <Button x:Name="OutputFileBrowseButton" Grid.Column="1" Style="{StaticResource SmallButton}" Height="30" Margin="8,0,6,0" Content="Browse..."/>
                      <Button x:Name="OutputFileClearButton" Grid.Column="2" Style="{StaticResource SmallButton}" Height="30" Margin="0" Content="Clear"/>
                    </Grid>
                  </StackPanel>
                </Border>
                <Border x:Name="MultipartOptionsPanel" Background="{StaticResource Surface}" BorderBrush="{StaticResource Border}" BorderThickness="1" CornerRadius="8" Padding="16,12">
                  <StackPanel>
                    <TextBlock Style="{StaticResource SectionLabel}" Text="MULTIPART / FORM-DATA"/>
                    <TextBlock x:Name="MultipartOptionsNote" Margin="0,4,0,10" TextWrapping="Wrap" Foreground="{StaticResource Muted}" Text="Only used when the body type is multipart/form-data."/>
                    <CheckBox x:Name="IncludeFilenameBox" Content="Send the file name with each file (filename=...)" IsChecked="True" Margin="0,2,0,4"/>
                    <CheckBox x:Name="IncludeContentTypeBox" Content="Send the content type with each file (Content-Type)" IsChecked="True" Margin="0,2,0,4"/>
                    <TextBlock Style="{StaticResource SectionLabel}" Text="OUTPUT FORMAT FIELD" Margin="0,12,0,4"/>
                    <TextBox x:Name="OutputFormatBox" Height="30" VerticalContentAlignment="Center" ToolTip="Extra form field, for example outputFormat=TrackChanges"/>
                    <TextBlock Margin="0,4,0,0" TextWrapping="Wrap" Foreground="{StaticResource Muted}" Text="Optional extra form field added to the request as name=value, for example outputFormat=TrackChanges. Leave empty if the API does not need it."/>
                  </StackPanel>
                </Border>
              </StackPanel>
            </ScrollViewer>
          </TabItem>
        </TabControl>

        <GridSplitter x:Name="WorkspaceSplitter" Grid.Row="1" Grid.Column="0" Grid.ColumnSpan="3" HorizontalAlignment="Stretch" VerticalAlignment="Center" Height="4" Background="{StaticResource Border}"/>

        <!-- Response -->
        <Border x:Name="ResponsePanel" Grid.Row="2" Grid.Column="0" Grid.ColumnSpan="3" Background="{StaticResource Surface}" BorderBrush="{StaticResource Border}" BorderThickness="1" CornerRadius="6" ToolTip="Right-click the toolbar for docking options">
          <Grid>
            <Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="Auto"/><RowDefinition Height="*"/></Grid.RowDefinitions>
            <WrapPanel x:Name="ResponseToolbar" Margin="12,8,12,4" Background="Transparent">
              <TextBlock Style="{StaticResource SectionLabel}" Text="RESPONSE" VerticalAlignment="Center" Margin="0,0,12,0"/>
              <Border x:Name="StatusBadge" CornerRadius="10" Padding="10,2" Background="#9AA7BD" Visibility="Collapsed" Margin="0,0,12,0">
                <TextBlock x:Name="ResponseStatusText" Foreground="White" FontWeight="SemiBold"/>
              </Border>
              <TextBlock x:Name="ResponseTimeText" VerticalAlignment="Center" Foreground="{StaticResource Muted}" Margin="0,0,12,0"/>
              <TextBlock x:Name="ResponseSizeText" VerticalAlignment="Center" Foreground="{StaticResource Muted}" Margin="0,0,16,0"/>
              <Button x:Name="PrettifyButton" Style="{StaticResource SmallButton}" Content="Prettify"/>
              <Button x:Name="SaveResponseButton" Style="{StaticResource SmallButton}" Content="Save..."/>
              <Button x:Name="CopyResponseButton" Style="{StaticResource SmallButton}" Content="Copy"/>
              <Button x:Name="GoToLineButton" Style="{StaticResource SmallButton}" Content="Go to line..."/>
              <Button x:Name="FindButton" Style="{StaticResource SmallButton}" Content="Find"/>
              <Button x:Name="ExtractButton" Style="{StaticResource SmallButton}" Content="Extract variable"/>
              <CheckBox x:Name="WrapBox" Content="Wrap" VerticalAlignment="Center" Margin="4,0,12,0"/>
            </WrapPanel>
            <Grid x:Name="FindBar" Grid.Row="1" Margin="12,0,12,6" Visibility="Collapsed">
              <Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions>
              <TextBox x:Name="FindBox" Height="28" VerticalContentAlignment="Center" ToolTip="Enter = next, Shift+Enter = previous, Esc = close"/>
              <StackPanel Grid.Column="1" Orientation="Horizontal" Margin="8,0,0,0">
                <Button x:Name="FindPrevButton" Style="{StaticResource SmallButton}" Content="&#x25B2;"/>
                <Button x:Name="FindNextButton" Style="{StaticResource SmallButton}" Content="&#x25BC;"/>
                <TextBlock x:Name="FindCountText" VerticalAlignment="Center" Foreground="{StaticResource Muted}" Margin="4,0,8,0"/>
                <Button x:Name="FindCloseButton" Style="{StaticResource SmallButton}" Margin="0" Content="&#x2715;"/>
              </StackPanel>
            </Grid>
            <TabControl x:Name="ResponseTabs" Grid.Row="2" BorderThickness="0,1,0,0" BorderBrush="{StaticResource Border}" Background="Transparent">
              <TabItem x:Name="TabResponse" Header="Response">
                <Grid>
                  <Grid.RowDefinitions><RowDefinition Height="*"/><RowDefinition Height="Auto"/></Grid.RowDefinitions>
                  <Border x:Name="ResponseBodyEditorHost" Margin="4" BorderThickness="0" Background="{StaticResource Input}" BorderBrush="{StaticResource Border}" CornerRadius="6">
                    <Grid>
                      <Grid.ColumnDefinitions><ColumnDefinition Width="Auto"/><ColumnDefinition Width="*"/></Grid.ColumnDefinitions>
                      <ScrollViewer x:Name="ResponseBodyGutterScroll" VerticalScrollBarVisibility="Hidden" HorizontalScrollBarVisibility="Disabled" IsHitTestVisible="False" Padding="0,4,0,4" Background="{StaticResource Surface}"><TextBlock x:Name="ResponseBodyGutter" FontFamily="Consolas" FontSize="13" Foreground="{StaticResource Muted}" TextAlignment="Right" MinWidth="26" Margin="8,0,8,0"/></ScrollViewer>
                      <ScrollViewer x:Name="ResponseBodyScroll" Grid.Column="1" HorizontalScrollBarVisibility="Auto" VerticalScrollBarVisibility="Auto" Padding="4,4,6,4">
                        <Grid MinWidth="{Binding ViewportWidth, ElementName=ResponseBodyScroll}" MinHeight="{Binding ViewportHeight, ElementName=ResponseBodyScroll}" Background="Transparent"><TextBlock x:Name="ResponseBodyHighlight" FontFamily="Consolas" FontSize="13" Margin="2,0,0,0" TextWrapping="NoWrap" IsHitTestVisible="False"/><TextBox x:Name="ResponseBodyBox" FontFamily="Consolas" FontSize="13" Background="Transparent" BorderThickness="0" Padding="0" VerticalScrollBarVisibility="Disabled" HorizontalScrollBarVisibility="Disabled" TextWrapping="NoWrap" IsReadOnly="True" IsReadOnlyCaretVisible="True" IsUndoEnabled="False" IsInactiveSelectionHighlightEnabled="True"/></Grid>
                      </ScrollViewer>
                    </Grid>
                  </Border>
                  <Border x:Name="ExtractPanel" Grid.Row="1" Visibility="Collapsed" Background="{StaticResource Surface}" BorderBrush="{StaticResource Border}" BorderThickness="0,1,0,0" Padding="10,8">
                    <WrapPanel>
                      <TextBlock Style="{StaticResource SectionLabel}" Text="EXTRACT" VerticalAlignment="Center" Margin="0,0,8,0"/>
                      <ComboBox x:Name="ExtractSourceBox" Width="80" Height="26" Margin="0,0,6,0" VerticalContentAlignment="Center"/>
                      <ComboBox x:Name="ExtractModeBox" Width="90" Height="26" Margin="0,0,6,0" VerticalContentAlignment="Center"/>
                      <TextBox x:Name="ExtractPathBox" Width="200" Height="26" Margin="0,0,6,0" VerticalContentAlignment="Center" ToolTip="JSON path (data.items[0].id) or a regex (first group is used)"/>
                      <TextBlock Text="to" VerticalAlignment="Center" Margin="0,0,6,0"/>
                      <TextBox x:Name="ExtractNameBox" Width="130" Height="26" Margin="0,0,6,0" VerticalContentAlignment="Center" ToolTip="Variable name"/>
                      <ComboBox x:Name="ExtractScopeBox" Width="110" Height="26" Margin="0,0,6,0" VerticalContentAlignment="Center"/>
                      <ComboBox x:Name="ExtractExistingBox" Width="130" Height="26" Margin="0,0,6,0" VerticalContentAlignment="Center" ToolTip="Existing variables in this scope"/>
                      <Button x:Name="ExtractRunButton" Style="{StaticResource PrimaryButton}" Padding="12,3" Content="Extract"/>
                      <TextBlock x:Name="ExtractStatusText" VerticalAlignment="Center" Margin="10,0,0,0" Foreground="{StaticResource Muted}"/>
                    </WrapPanel>
                  </Border>
                </Grid>
              </TabItem>
              <TabItem x:Name="TabResponseHeaders" Header="Response Headers"><TextBox x:Name="ResponseHeadersBox" Style="{StaticResource CodeBox}" IsReadOnly="True" IsReadOnlyCaretVisible="True" BorderThickness="0" Margin="4"/></TabItem>
              <TabItem x:Name="TabJsonTree" Header="JSON Tree">
                <Grid Margin="4">
                  <Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="*"/></Grid.RowDefinitions>
                  <WrapPanel Margin="4,4,4,6">
                    <TextBox x:Name="JsonSearchBox" Width="220" Height="26" VerticalContentAlignment="Center" Margin="0,0,6,0" ToolTip="Search keys and values (Enter = next)"/>
                    <Button x:Name="JsonSearchNextButton" Style="{StaticResource SmallButton}" Content="Find next"/>
                    <Button x:Name="JsonExpandButton" Style="{StaticResource SmallButton}" Content="Expand all"/>
                    <Button x:Name="JsonCollapseButton" Style="{StaticResource SmallButton}" Content="Collapse all"/>
                    <Button x:Name="JsonCopyPathButton" Style="{StaticResource SmallButton}" Content="Copy path"/>
                    <TextBlock x:Name="JsonStatusText" VerticalAlignment="Center" Foreground="{StaticResource Muted}"/>
                  </WrapPanel>
                  <TreeView x:Name="JsonTree" Grid.Row="1" BorderThickness="0" Background="Transparent" FontFamily="Consolas"/>
                </Grid>
              </TabItem>
              <TabItem x:Name="TabCode" Header="Code Snippets">
                <Grid Margin="4"><Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="*"/></Grid.RowDefinitions>
                  <StackPanel Orientation="Horizontal" Margin="4,4,4,6">
                    <ComboBox x:Name="CodeLanguageBox" Width="150" Height="26" VerticalContentAlignment="Center" Margin="0,0,8,0"/>
                    <Button x:Name="CodeRefreshButton" Style="{StaticResource SmallButton}" Content="Refresh"/>
                    <Button x:Name="CodeCopyButton" Style="{StaticResource SmallButton}" Content="Copy"/>
                  </StackPanel>
                  <TextBox x:Name="CodeBox" Grid.Row="1" Style="{StaticResource CodeBox}" IsReadOnly="True" BorderThickness="0"/>
                </Grid>
              </TabItem>
              <TabItem x:Name="TabConsole" Header="Console">
                <Grid Margin="4"><Grid.RowDefinitions><RowDefinition Height="*"/><RowDefinition Height="Auto"/></Grid.RowDefinitions>
                  <TextBox x:Name="ConsoleOutputBox" Style="{StaticResource CodeBox}" IsReadOnly="True" Background="Black" Foreground="White" FontSize="12"/>
                  <DockPanel Grid.Row="1" Margin="0,6,0,0">
                    <StackPanel DockPanel.Dock="Right" Orientation="Horizontal" Margin="8,0,0,0">
                      <Button x:Name="ConsoleRunButton" Style="{StaticResource PrimaryButton}" Padding="14,4" Margin="0,0,6,0" Content="Run"/>
                      <Button x:Name="ConsoleClearButton" Padding="14,4" Content="Clear"/>
                    </StackPanel>
                    <TextBox x:Name="ConsoleInputBox" Height="64" Style="{StaticResource CodeBox}" ToolTip="Ctrl+Enter or Shift+Enter runs. Prefix: python: js: php: ruby: go: bat: bash:"/>
                  </DockPanel>
                </Grid>
              </TabItem>
              <TabItem x:Name="TabPreview" Header="Preview" Visibility="Collapsed">
                <Grid><Image x:Name="PreviewImage" Stretch="Uniform" Visibility="Collapsed" Margin="8"/><WebBrowser x:Name="PreviewBrowser" Visibility="Collapsed"/></Grid>
              </TabItem>
              <TabItem x:Name="TabTestResults" Header="Test Results">
                <ListBox x:Name="TestResultsList" BorderThickness="0" Background="Transparent" Margin="4"/>
              </TabItem>
            </TabControl>
          </Grid>
        </Border>
      </Grid>
    </Grid>
  </Grid>
</Window>
'@
    $controlNames = @(
    'StatusText', 'EnvironmentPanel', 'EnvironmentBox', 'ManageEnvironmentsButton', 'SettingsButton', 'MainMenu', 'MenuImportCurl',
    'MenuImportPostman', 'MenuImportWorkspace', 'MenuExportWorkspace', 'MenuResetLayout', 'MenuSettings', 'MenuExit', 'MenuEnvironments',
    'MenuGlobalVariables', 'MenuTemplates', 'MenuProxy', 'MenuCookieJar', 'MenuJwt', 'MenuReport', 'MenuWebSocket', 'MenuGrpc', 'MenuLoadTester',
    'MenuMonitorManager', 'MenuMonitorDashboard', 'MenuMonitorBrowser', 'MenuAbout', 'MenuShortcuts', 'RequestTabsStrip', 'NewTabButton',
    'MethodBox', 'UrlEditorHost', 'UrlScroll', 'UrlHighlight', 'UrlBox', 'SendButton', 'StopButton', 'RepeatButton', 'SaveRequestButton',
    'TemplatesButton', 'SidebarColumn', 'SidebarSplitterColumn', 'SidebarTabs', 'TabCollections', 'CollectionFilterBox', 'CollectionsTree',
    'NewCollectionButton', 'ImportCollectionsButton', 'ExportCollectionsButton', 'TabHistory', 'HistoryFilterBox', 'HistoryEnvironmentBox',
    'HistoryList', 'ClearHistoryButton', 'ExportHistoryButton', 'SidebarSplitter', 'WorkspaceGrid', 'RequestTabs', 'TabParams', 'AddParamButton',
    'RemoveParamButton', 'ParamsGrid', 'TabHeaders', 'HeadersEditorHost', 'HeadersScroll', 'HeadersHighlight', 'HeadersBox', 'TabBody',
    'BodyTypeBox', 'BeautifyButton', 'BodyOptionsHint', 'BodyEditorHost', 'BodyGutterScroll', 'BodyGutter', 'BodyScroll', 'BodyHighlight', 'BodyBox',
    'MultipartPanel', 'AddFieldButton', 'AddFileButton', 'RemoveRowButton', 'ClearRowsButton', 'MultipartGrid', 'GraphQLPanel', 'GqlQueryBox',
    'GqlVarsBox', 'TabAuth', 'AuthTypeBox', 'InheritNote', 'BearerPanel', 'BearerTokenBox', 'BasicPanel', 'BasicUserBox', 'BasicPasswordBox',
    'ApiKeyPanel', 'ApiKeyNameBox', 'ApiKeyValueBox', 'ApiKeyLocationBox', 'OAuthPanel', 'OAuthClientIdBox', 'OAuthClientSecretBox',
    'OAuthAuthEndpointBox', 'OAuthTokenEndpointBox', 'OAuthRedirectUriBox', 'OAuthScopeBox', 'OAuthAccessTokenBox', 'OAuthRefreshTokenBox',
    'OAuthExpiresInBox', 'OAuthClientCredentialsButton', 'OAuthAuthorizationCodeButton', 'OAuthRefreshButton', 'OAuthStatusText', 'CertPanel',
    'CertSourceBox', 'CertPathPanel', 'CertPathBox', 'CertBrowseButton', 'CertPasswordPanel', 'CertPasswordBox', 'CertThumbPanel', 'CertThumbBox',
    'TabPreRequest', 'PreRequestBox', 'TabTests', 'TestSnippetsButton', 'TestsBox', 'TabOptions', 'OutputFileBox', 'OutputFileBrowseButton',
    'OutputFileClearButton', 'MultipartOptionsPanel', 'MultipartOptionsNote', 'IncludeFilenameBox', 'IncludeContentTypeBox', 'OutputFormatBox',
    'WorkspaceSplitter', 'ResponsePanel', 'ResponseToolbar', 'StatusBadge', 'ResponseStatusText', 'ResponseTimeText', 'ResponseSizeText',
    'PrettifyButton', 'SaveResponseButton', 'CopyResponseButton', 'GoToLineButton', 'FindButton', 'ExtractButton', 'WrapBox', 'FindBar', 'FindBox',
    'FindPrevButton', 'FindNextButton', 'FindCountText', 'FindCloseButton', 'ResponseTabs', 'TabResponse', 'ResponseBodyEditorHost',
    'ResponseBodyGutterScroll', 'ResponseBodyGutter', 'ResponseBodyScroll', 'ResponseBodyHighlight', 'ResponseBodyBox', 'ExtractPanel',
    'ExtractSourceBox', 'ExtractModeBox', 'ExtractPathBox', 'ExtractNameBox', 'ExtractScopeBox', 'ExtractExistingBox', 'ExtractRunButton',
    'ExtractStatusText', 'TabResponseHeaders', 'ResponseHeadersBox', 'TabJsonTree', 'JsonSearchBox', 'JsonSearchNextButton', 'JsonExpandButton',
    'JsonCollapseButton', 'JsonCopyPathButton', 'JsonStatusText', 'JsonTree', 'TabCode', 'CodeLanguageBox', 'CodeRefreshButton', 'CodeCopyButton',
    'CodeBox', 'TabConsole', 'ConsoleOutputBox', 'ConsoleRunButton', 'ConsoleClearButton', 'ConsoleInputBox', 'TabPreview', 'PreviewImage',
    'PreviewBrowser', 'TabTestResults', 'TestResultsList'
    )
    $uiBundle = New-WpfWindowFromXaml -Xaml $xaml -ControlNames $controlNames
    $window = $uiBundle.Window
    $script:ui = $uiBundle.Controls
    $script:MainWindowContext = @{ Window = $window; Controls = $script:ui }
    $window.Title = "API Tester v$($script:AppVersion)"

    Initialize-MainWindowControls
    Register-MainWindowHandlers
    Register-SidebarHandlers
    Register-MainMenuHandlers -Controls $script:ui

    Import-RequestTabs
    if ($OpenRequestFile) {
        # Secondary window ("Open in new window"): just this request; it does not run monitors or save the main tabs.
        $script:isSecondaryWindow = $true
        try {
            $opened = Get-Content -Path $OpenRequestFile -Raw | ConvertFrom-Json
            Initialize-RequestTabDefaults -TabState $opened
            $script:requestTabs = @($opened); $script:activeRequestTabId = $opened.Id
            Remove-Item -Path $OpenRequestFile -Force -ErrorAction SilentlyContinue
            $window.Title = "API Tester - $($opened.Name)"
        } catch { Write-Log "Could not open the request file: $($_.Exception.Message)" -Level Error }
    } elseif (-not $script:settings.RestoreRequestTabs) {
        # The tabs file is shared with the classic window; by default the new window starts with a single fresh tab.
        $script:requestTabs = @(New-RequestTabState -Name 'Request 1' -Method 'GET' -BodyType 'application/json' -IncludeFilename ([bool]$script:settings.IncludeFilename) -IncludeContentType ([bool]$script:settings.IncludeContentType))
        $script:activeRequestTabId = $script:requestTabs[0].Id
    }
    if (-not $script:isSecondaryWindow) { Restore-DraftSession }
    Update-RequestTabsStrip
    Set-EditorState -State (Get-ActiveRequestTab)
    Update-CollectionsTree
    Update-HistoryList
    Update-UiFromSettings
    Set-UiStatus 'Ready'
    if (-not $script:isSecondaryWindow) { Start-MonitorEngine }

    $autoSaveTimer = New-Object System.Windows.Threading.DispatcherTimer
    $autoSaveTimer.Interval = [TimeSpan]::FromSeconds(2)
    $autoSaveTimer.Add_Tick({ Invoke-UiGuard { if ($script:editorDirty) { $script:editorDirty = $false; Save-ActiveRequestTab; Save-DraftState } } 'Auto-save' })
    $autoSaveTimer.Start()
    $script:autoSaveTimer = $autoSaveTimer

    # Any error escaping an event handler is reported instead of closing the window.
    $window.Dispatcher.Add_UnhandledException({
        param($sender, $exceptionArgs)
        $exceptionArgs.Handled = $true
        try {
            $errorRecord = $exceptionArgs.Exception
            Write-Log "Unhandled UI error: $($errorRecord.ToString())" -Level Error
            Set-UiStatus "Error: $($errorRecord.Message)"
        } catch { }
    })

    $window.Add_Closing({
        param($sender, $closingArgs)
        $runningCount = @($script:pendingRequests.Keys).Count
        if ($runningCount -gt 0) {
            $answer = [System.Windows.MessageBox]::Show($sender, "$runningCount request(s) are still running. Close the application and cancel them?", 'Requests running', 'YesNo', 'Warning')
            if ($answer -ne 'Yes') { $closingArgs.Cancel = $true; return }
        }
        $script:startMonitorServiceOnExit = $false
        $activeMonitors = @($script:monitors | Where-Object { $_ -and $_.Status -eq 'Running' }).Count
        if (-not $script:isSecondaryWindow -and $activeMonitors -gt 0 -and -not (Test-MonitorServiceRunning -NoCache)) {
            $answer = [System.Windows.MessageBox]::Show($sender, "$activeMonitors monitor(s) are running.`n`nKeep them running in the background after API Tester closes?`n`nYes - keep running (tray icon)`nNo - stop them`nCancel - don't close", 'Monitors', 'YesNoCancel', 'Question')
            if ($answer -eq 'Cancel') { $closingArgs.Cancel = $true; return }
            $script:startMonitorServiceOnExit = ($answer -eq 'Yes')
        }
        try { $script:autoSaveTimer.Stop() } catch { }
        try { Stop-MonitorEngine } catch { }
        if ($script:startMonitorServiceOnExit) { try { Save-Monitors; [void](Start-MonitorService) } catch { Write-Log "Could not start background monitors: $($_.Exception.Message)" -Level Error } }
        try { if ($script:requestPollTimer) { $script:requestPollTimer.Stop() } } catch { }
        foreach ($pending in @($script:pendingRequests.Values)) { try { $pending.State.Cancellation.Cancel() } catch { } }
        try { Save-ActiveRequestTab; Save-RequestTabs } catch { }
        if (-not $script:isSecondaryWindow) { try { if (Test-Path $draftsFilePath) { Remove-Item $draftsFilePath -Force -ErrorAction SilentlyContinue } } catch { } }
        try { Close-FloatingPanels } catch { }
        if (-not $script:isSecondaryWindow) { try { Save-MainWindowBounds -Window $sender } catch { } }
        try { Save-Settings } catch { }
    })
    $window.Add_ContentRendered({
        $script:ui.UrlBox.Focus() | Out-Null
        if ($script:startupDockState -eq 'Undocked') { Invoke-UiGuard { Set-ResponseDock -Dock 'Undocked' } 'Undock' }
        if ($script:settings.HistoryUndocked) { Invoke-UiGuard { Set-SidebarDocked -Docked $false } 'Undock' }
        if (-not $script:isSecondaryWindow) { Invoke-UiGuard { Start-StartupUpdateCheck } 'Update check' }
    })

    Set-MainWindowInitialBounds -Window $window
    [void]$window.ShowDialog()
    $script:MainWindowContext = $null
    $script:ui = $null
}

function Initialize-MainWindowControls {
    $controls = $script:ui
    $methods = @('GET', 'POST', 'PUT', 'PATCH', 'DELETE', 'HEAD', 'OPTIONS')
    if ($script:settings.EnableAllMethods) { $methods += @('TRACE', 'CONNECT') }
    foreach ($method in $methods) { [void]$controls.MethodBox.Items.Add($method) }
    foreach ($bodyType in @('multipart/form-data', 'application/json', 'application/xml', 'text/plain', 'application/x-www-form-urlencoded', 'GraphQL')) { [void]$controls.BodyTypeBox.Items.Add($bodyType) }
    foreach ($authType in @('Inherit', 'No Auth', 'API Key', 'Bearer Token', 'Basic Auth', 'Auth2', 'Client Certificate')) { [void]$controls.AuthTypeBox.Items.Add($authType) }
    foreach ($location in @('Header', 'Query Parameter')) { [void]$controls.ApiKeyLocationBox.Items.Add($location) }
    foreach ($source in @('PFX File', 'User Store')) { [void]$controls.CertSourceBox.Items.Add($source) }
    foreach ($language in @('cURL', 'PowerShell', 'Python', 'C#', 'JavaScript', 'JavaScript (axios)', 'Go', 'Java')) { [void]$controls.CodeLanguageBox.Items.Add($language) }
    foreach ($source in @('Body', 'Headers')) { [void]$controls.ExtractSourceBox.Items.Add($source) }
    foreach ($mode in @('JSON Path', 'Regex')) { [void]$controls.ExtractModeBox.Items.Add($mode) }
    foreach ($scope in @('Global', 'Collection', 'Environment')) { [void]$controls.ExtractScopeBox.Items.Add($scope) }
    $controls.MethodBox.SelectedIndex = 0
    $controls.BodyTypeBox.SelectedItem = 'application/json'
    $controls.AuthTypeBox.SelectedItem = 'No Auth'
    $controls.ApiKeyLocationBox.SelectedIndex = 0
    $controls.CertSourceBox.SelectedIndex = 0
    $controls.CodeLanguageBox.SelectedIndex = 0
    $controls.ExtractSourceBox.SelectedIndex = 0
    $controls.ExtractModeBox.SelectedIndex = 0
    $controls.ExtractScopeBox.SelectedIndex = 0
    $dockState = if ($script:settings.ResponseDockState -in @('Bottom', 'Right', 'Left', 'Undocked')) { $script:settings.ResponseDockState } else { 'Right' }

    $script:multipartRows = New-Object 'System.Collections.ObjectModel.ObservableCollection[MultipartRow]'
    $controls.MultipartGrid.ItemsSource = $script:multipartRows
    $script:paramRows = New-Object 'System.Collections.ObjectModel.ObservableCollection[ParamRow]'
    $controls.ParamsGrid.ItemsSource = $script:paramRows
    $controls.TestSnippetsButton.ContextMenu = New-TestSnippetMenu
    Register-CodeEditor -Name 'Url' -LanguageHint { 'text' }
    Register-CodeEditor -Name 'Headers' -LanguageHint { 'text' }
    Register-CodeEditor -Name 'Body' -LanguageHint { [string]$script:ui.BodyTypeBox.SelectedItem }
    Register-CodeEditor -Name 'ResponseBody' -LanguageHint { if ($script:lastResult) { [string]$script:lastResult.ContentType } else { '' } }
    $script:editorDirty = $false
    $script:isSwitchingRequestTab = $false
    $script:pendingRequests = @{}
    $script:lastResult = $null

    Update-EnvironmentChoices
    $startEnvironment = $script:settings.LastActiveEnvironment
    if ($startEnvironment -and $controls.EnvironmentBox.Items.Contains($startEnvironment)) { $controls.EnvironmentBox.SelectedItem = $startEnvironment }
    $script:activeEnvironment = [string]$controls.EnvironmentBox.SelectedItem
    $controls.ConsoleOutputBox.Text = "Welcome to API Tester Console.`r`nDefault language: $(if ($script:settings.DefaultConsoleLanguage) { $script:settings.DefaultConsoleLanguage } else { 'PowerShell' }).`r`nPrefix commands with 'python:', 'js:', 'php:', 'ruby:', 'go:', 'bat:', 'bash:' to switch languages.`r`nExample: python: print('Hello')`r`n`r`n"
    # An undocked panel needs the main window on screen first, so it is opened after ContentRendered.
    Set-ResponseDock -Dock $(if ($dockState -eq 'Undocked') { 'Right' } else { $dockState })
    $script:startupDockState = $dockState
}

function Register-MainWindowHandlers {
    $controls = $script:ui

    # --- header / environments ---
    $controls.EnvironmentBox.Add_SelectionChanged({ Invoke-UiGuard { Select-Environment } 'Environment' })
    $controls.ManageEnvironmentsButton.Add_Click({ Invoke-UiGuard { Show-EnvironmentManager } 'Environments' })
    $controls.SettingsButton.Add_Click({ Invoke-UiGuard { Invoke-MenuSettings } 'Settings' })

    # --- request tabs strip ---
    $controls.RequestTabsStrip.Add_SelectionChanged({ Invoke-UiGuard { Switch-RequestTabFromStrip } 'Switch tab' })
    $controls.NewTabButton.Add_Click({ Invoke-UiGuard { [void](Add-RequestTab) } 'New tab' })

    # --- request bar ---
    $controls.SendButton.Add_Click({ Invoke-UiGuard { Invoke-SendRequest } 'Send' })
    $controls.StopButton.Add_Click({ Invoke-UiGuard { Stop-SendRequest } 'Cancel' })
    $controls.RepeatButton.Add_Click({ Invoke-UiGuard { Invoke-RepeatRequest } 'Repeat' })
    $controls.SaveRequestButton.Add_Click({ Invoke-UiGuard { Save-CurrentRequest } 'Save request' })
    $controls.TemplatesButton.Add_Click({ Invoke-UiGuard { Show-RequestTemplatesDialog } 'Templates' })

    # --- editor: body ---
    $controls.BodyTypeBox.Add_SelectionChanged({ Invoke-UiGuard { Set-BodyEditorMode } 'Body type' })
    $controls.BeautifyButton.Add_Click({ Invoke-UiGuard { Format-BodyEditor } 'Beautify' })
    $controls.AddFieldButton.Add_Click({ Invoke-UiGuard { Add-MultipartRow -Kind 'Text' } 'Add field' })
    $controls.AddFileButton.Add_Click({ Invoke-UiGuard { Add-MultipartFiles } 'Attach files' })
    $controls.RemoveRowButton.Add_Click({ Invoke-UiGuard { Remove-MultipartRows } 'Remove rows' })
    $controls.ClearRowsButton.Add_Click({ Invoke-UiGuard { $script:multipartRows.Clear(); $script:editorDirty = $true } 'Clear rows' })
    $controls.MultipartPanel.Add_DragOver({
        param($sender, $dragArgs)
        $dragArgs.Effects = if ($dragArgs.Data.GetDataPresent([System.Windows.DataFormats]::FileDrop)) { [System.Windows.DragDropEffects]::Copy } else { [System.Windows.DragDropEffects]::None }
        $dragArgs.Handled = $true
    })
    $controls.MultipartPanel.Add_Drop({
        param($sender, $dropArgs)
        $dropArgs.Handled = $true
        $paths = @($dropArgs.Data.GetData([System.Windows.DataFormats]::FileDrop))
        # Dropped onto a row: attach to that key; otherwise new rows.
        $targetRow = $null
        try {
            $source = $dropArgs.OriginalSource -as [System.Windows.DependencyObject]
            while ($source -and $source -isnot [System.Windows.Controls.DataGridRow]) { $source = [System.Windows.Media.VisualTreeHelper]::GetParent($source) }
            if ($source) { $targetRow = $source.Item }
        } catch { }
        Invoke-UiGuard { Add-MultipartFiles -Paths $paths -TargetRow $targetRow } 'Drop files'
    })
    # The Browse button inside each Value cell.
    $controls.MultipartGrid.AddHandler([System.Windows.Controls.Primitives.ButtonBase]::ClickEvent, [System.Windows.RoutedEventHandler]{
        param($sender, $clickArgs)
        $button = $clickArgs.OriginalSource
        if ($button -is [System.Windows.Controls.Button] -and [string]$button.Tag -eq 'BrowseFile') {
            $clickArgs.Handled = $true
            $row = $button.DataContext
            Invoke-UiGuard { Add-MultipartFiles -TargetRow $row -SingleFile } 'Attach file'
        }
    })
    $controls.MultipartGrid.Add_PreviewGotKeyboardFocus({
        param($sender, $focusArgs)
        $modifiers = [System.Windows.Input.Keyboard]::Modifiers
        if ($modifiers -band ([System.Windows.Input.ModifierKeys]::Control -bor [System.Windows.Input.ModifierKeys]::Shift)) { return }
        $element = $focusArgs.NewFocus -as [System.Windows.DependencyObject]
        while ($element -and $element -isnot [System.Windows.Controls.DataGridRow]) { $element = [System.Windows.Media.VisualTreeHelper]::GetParent($element) }
        if ($element -and -not $element.IsSelected) { $sender.SelectedItem = $element.Item }
    })
    $controls.IncludeFilenameBox.Add_Click({ $script:editorDirty = $true })
    $controls.IncludeContentTypeBox.Add_Click({ $script:editorDirty = $true })

    # --- editor: auth ---
    $controls.AuthTypeBox.Add_SelectionChanged({ Invoke-UiGuard { Update-AuthPanels } 'Auth type' })
    $controls.CertSourceBox.Add_SelectionChanged({ Invoke-UiGuard { Update-AuthPanels } 'Certificate source' })
    $controls.CertBrowseButton.Add_Click({
        Invoke-UiGuard {
            $dialog = New-Object Microsoft.Win32.OpenFileDialog
            $dialog.Filter = 'Certificates (*.pfx;*.p12)|*.pfx;*.p12|All files (*.*)|*.*'
            if ($dialog.ShowDialog((Get-MainWindow)) -eq $true) { $script:ui.CertPathBox.Text = $dialog.FileName }
        } 'Browse certificate'
    })
    $controls.OAuthClientCredentialsButton.Add_Click({ Invoke-UiGuard { Invoke-OAuthClientCredentials } 'OAuth token' })
    $controls.OAuthAuthorizationCodeButton.Add_Click({ Invoke-UiGuard { Invoke-OAuthAuthorizationCode } 'OAuth authorization code' })
    $controls.OAuthRefreshButton.Add_Click({ Invoke-UiGuard { Invoke-OAuthRefresh } 'OAuth refresh' })

    # --- mark the editor dirty on any change so the active tab is saved automatically ---
    foreach ($textBox in @($controls.UrlBox, $controls.HeadersBox, $controls.BodyBox, $controls.OutputFormatBox, $controls.GqlQueryBox, $controls.GqlVarsBox, $controls.PreRequestBox, $controls.TestsBox,
            $controls.BearerTokenBox, $controls.BasicUserBox, $controls.ApiKeyNameBox, $controls.ApiKeyValueBox, $controls.OAuthClientIdBox, $controls.OAuthClientSecretBox,
            $controls.OAuthAuthEndpointBox, $controls.OAuthTokenEndpointBox, $controls.OAuthRedirectUriBox, $controls.OAuthScopeBox, $controls.OAuthAccessTokenBox,
            $controls.OAuthRefreshTokenBox, $controls.OAuthExpiresInBox, $controls.CertPathBox, $controls.CertThumbBox)) {
        $textBox.Add_TextChanged({ $script:editorDirty = $true })
    }
    $controls.MethodBox.Add_SelectionChanged({ $script:editorDirty = $true })
    $controls.BasicPasswordBox.Add_PasswordChanged({ $script:editorDirty = $true })
    $controls.CertPasswordBox.Add_PasswordChanged({ $script:editorDirty = $true })
    $controls.UrlBox.Add_TextChanged({ Invoke-UiGuard { Update-ActiveTabCaption; if (-not $script:isSyncingParams) { Update-ParamsFromUrl } } 'Tab caption' })
    $controls.AddParamButton.Add_Click({ Invoke-UiGuard { Add-ParamRow } 'Add parameter' })
    $controls.RemoveParamButton.Add_Click({ Invoke-UiGuard { Remove-ParamRows } 'Remove parameters' })
    $controls.TestSnippetsButton.Add_Click({ param($sender) $sender.ContextMenu.PlacementTarget = $sender; $sender.ContextMenu.IsOpen = $true })

    # --- response toolbar ---
    $controls.PrettifyButton.Add_Click({ Invoke-UiGuard { Format-ResponseBody } 'Prettify' })
    $controls.SaveResponseButton.Add_Click({ Invoke-UiGuard { Save-ResponseToFile } 'Save response' })
    $controls.CopyResponseButton.Add_Click({ Invoke-UiGuard { Copy-ResponseToClipboard } 'Copy response' })
    $controls.GoToLineButton.Add_Click({ Invoke-UiGuard { Move-ResponseToLine } 'Go to line' })
    $controls.FindButton.Add_Click({ Invoke-UiGuard { Show-FindBar } 'Find' })
    $controls.ExtractButton.Add_Click({
        Invoke-UiGuard {
        $panel = $script:ui.ExtractPanel
        $panel.Visibility = if ($panel.Visibility -eq 'Visible') { 'Collapsed' } else { 'Visible' }
        if ($panel.Visibility -eq 'Visible') { $script:ui.ResponseTabs.SelectedItem = $script:ui.TabResponse; Update-ExtractVariableChoices }
        } 'Extract'
    })
    $controls.WrapBox.Add_Checked({ Set-ResponseWrap -Wrap $true })
    $controls.WrapBox.Add_Unchecked({ Set-ResponseWrap -Wrap $false })
    $controls.OutputFileClearButton.Add_Click({ $script:ui.OutputFileBox.Text = '' })
    $controls.OutputFileBox.Add_TextChanged({ Update-OptionsTabHeader })
    $controls.OutputFormatBox.Add_TextChanged({ Update-OptionsTabHeader })
    $controls.OutputFileBrowseButton.Add_Click({
        Invoke-UiGuard {
            $picker = New-Object Microsoft.Win32.SaveFileDialog
            $picker.Filter = 'All files (*.*)|*.*'
            if ($picker.ShowDialog((Get-MainWindow)) -eq $true) { $script:ui.OutputFileBox.Text = $picker.FileName }
        } 'Output file'
    })

    # --- docking (classic-style right-click menus) ---
    $controls.ResponseToolbar.ContextMenu = New-DockingContextMenu
    $controls.SidebarTabs.ContextMenu = New-SidebarDockingMenu

    # --- find bar ---
    $controls.FindBox.Add_TextChanged({ Invoke-UiGuard { Update-FindMatches } 'Find' })
    $controls.FindNextButton.Add_Click({ Invoke-UiGuard { Step-FindMatch -Forward $true } 'Find next' })
    $controls.FindPrevButton.Add_Click({ Invoke-UiGuard { Step-FindMatch -Forward $false } 'Find previous' })
    $controls.FindCloseButton.Add_Click({ Hide-FindBar })
    $controls.FindBox.Add_KeyDown({
        param($sender, $keyArgs)
        if ($keyArgs.Key -eq [System.Windows.Input.Key]::Return) {
            $shift = [System.Windows.Input.Keyboard]::Modifiers -band [System.Windows.Input.ModifierKeys]::Shift
            Invoke-UiGuard { Step-FindMatch -Forward (-not $shift) } 'Find'
            $keyArgs.Handled = $true
        } elseif ($keyArgs.Key -eq [System.Windows.Input.Key]::Escape) { Hide-FindBar; $keyArgs.Handled = $true }
    })

    # --- extract variable ---
    $controls.ExtractModeBox.Add_SelectionChanged({ $script:ui.ExtractSourceBox.IsEnabled = $true })
    $controls.ExtractScopeBox.Add_SelectionChanged({ Update-ExtractVariableChoices })
    $controls.ExtractExistingBox.Add_SelectionChanged({ if ($script:ui.ExtractExistingBox.SelectedItem) { $script:ui.ExtractNameBox.Text = [string]$script:ui.ExtractExistingBox.SelectedItem } })
    $controls.ExtractRunButton.Add_Click({ Invoke-UiGuard { Invoke-ExtractVariable } 'Extract variable' })

    # --- JSON tree ---
    $controls.JsonSearchNextButton.Add_Click({ Invoke-UiGuard { Step-JsonTreeSearch } 'JSON search' })
    $controls.JsonSearchBox.Add_KeyDown({ param($sender, $keyArgs) if ($keyArgs.Key -eq [System.Windows.Input.Key]::Return) { Invoke-UiGuard { Step-JsonTreeSearch } 'JSON search'; $keyArgs.Handled = $true } })
    $controls.JsonSearchBox.Add_TextChanged({ $script:jsonSearchIndex = -1 })
    $controls.JsonExpandButton.Add_Click({ Set-JsonTreeExpanded -Expanded $true })
    $controls.JsonCollapseButton.Add_Click({ Set-JsonTreeExpanded -Expanded $false })
    $controls.JsonCopyPathButton.Add_Click({ Copy-JsonTreePath })

    # --- code snippets ---
    $controls.CodeLanguageBox.Add_SelectionChanged({ Invoke-UiGuard { Update-CodeSnippet } 'Code snippet' })
    $controls.CodeRefreshButton.Add_Click({ Invoke-UiGuard { Update-CodeSnippet } 'Code snippet' })
    $controls.CodeCopyButton.Add_Click({ if ($script:ui.CodeBox.Text) { [System.Windows.Clipboard]::SetText($script:ui.CodeBox.Text); Set-UiStatus 'Code snippet copied.' } })
    $controls.ResponseTabs.Add_SelectionChanged({
        param($sender, $selectionArgs)
        if ($selectionArgs.OriginalSource -eq $script:ui.ResponseTabs -and $script:ui.ResponseTabs.SelectedItem -eq $script:ui.TabCode) { Invoke-UiGuard { Update-CodeSnippet } 'Code snippet' }
    })

    # --- console ---
    $controls.ConsoleRunButton.Add_Click({ Invoke-UiGuard { Invoke-ConsoleRun } 'Console' })
    $controls.ConsoleClearButton.Add_Click({ $script:ui.ConsoleOutputBox.Clear() })
    $controls.ConsoleInputBox.Add_PreviewKeyDown({
        param($sender, $keyArgs)
        $modifiers = [System.Windows.Input.Keyboard]::Modifiers
        $runChord = ($modifiers -band [System.Windows.Input.ModifierKeys]::Control) -or ($modifiers -band [System.Windows.Input.ModifierKeys]::Shift)
        if ($keyArgs.Key -eq [System.Windows.Input.Key]::Return -and $runChord) { $keyArgs.Handled = $true; Invoke-UiGuard { Invoke-ConsoleRun } 'Console' }
    })

    # --- window-level shortcuts ---
    $script:MainWindowContext.Window.Add_PreviewKeyDown({
        param($sender, $keyArgs)
        $ctrl = [System.Windows.Input.Keyboard]::Modifiers -band [System.Windows.Input.ModifierKeys]::Control
        $shift = [System.Windows.Input.Keyboard]::Modifiers -band [System.Windows.Input.ModifierKeys]::Shift
        if (-not $ctrl) { return }
        $key = $keyArgs.Key
        if ($key -eq [System.Windows.Input.Key]::Return -and $shift) { $keyArgs.Handled = $true; $script:ui.ResponseTabs.SelectedItem = $script:ui.TabConsole; Invoke-UiGuard { Invoke-ConsoleRun } 'Console' }
        elseif ($key -eq [System.Windows.Input.Key]::Return -and $keyArgs.OriginalSource -ne $script:ui.ConsoleInputBox) { $keyArgs.Handled = $true; Invoke-UiGuard { Invoke-SendRequest } 'Send' }
        elseif ($key -eq [System.Windows.Input.Key]::T) { $keyArgs.Handled = $true; Invoke-UiGuard { [void](Add-RequestTab) } 'New tab' }
        elseif ($key -eq [System.Windows.Input.Key]::W) { $keyArgs.Handled = $true; Invoke-UiGuard { Remove-ActiveRequestTab } 'Close tab' }
        elseif ($key -eq [System.Windows.Input.Key]::F) { $keyArgs.Handled = $true; Invoke-UiGuard { Show-FindBar } 'Find' }
    })
}

# Sizes the main window for the screen. First launch: up to 1440 x 900, never larger than the work area (and maximised
# on small screens, where the sidebar is narrowed and the response is docked below the editor). Later launches restore
# the size and position saved on exit, as long as they are still on a connected screen.
function Set-MainWindowInitialBounds {
    param($Window)
    $area = [System.Windows.SystemParameters]::WorkArea
    $Window.MinWidth = [Math]::Min(1000, $area.Width - 20)
    $Window.MinHeight = [Math]::Min(640, $area.Height - 20)
    $Window.WindowStartupLocation = [System.Windows.WindowStartupLocation]::Manual
    $saved = $script:settings.WindowBounds
    $left = [double](Get-ObjectProperty $saved 'Left' ([double]::NaN)); $top = [double](Get-ObjectProperty $saved 'Top' ([double]::NaN))
    $width = [double](Get-ObjectProperty $saved 'Width' 0); $height = [double](Get-ObjectProperty $saved 'Height' 0)
    $virtualScreen = [System.Windows.Rect]::new([System.Windows.SystemParameters]::VirtualScreenLeft, [System.Windows.SystemParameters]::VirtualScreenTop,
        [System.Windows.SystemParameters]::VirtualScreenWidth, [System.Windows.SystemParameters]::VirtualScreenHeight)
    $savedIsUsable = $saved -and -not [double]::IsNaN($left) -and -not [double]::IsNaN($top) -and $width -ge 400 -and $height -ge 300 -and
        $virtualScreen.IntersectsWith([System.Windows.Rect]::new($left + 40, $top + 10, [Math]::Max(1, $width - 80), 60))
    if ($savedIsUsable) {
        $Window.Width = [Math]::Min($width, $virtualScreen.Width); $Window.Height = [Math]::Min($height, $virtualScreen.Height)
        $Window.Left = $left; $Window.Top = $top
        if ([bool](Get-ObjectProperty $saved 'Maximized' $false)) { $Window.Add_SourceInitialized({ param($sender) $sender.WindowState = [System.Windows.WindowState]::Maximized }) }
        $Window.Add_Loaded({ param($sender) Move-WindowIntoWorkArea -Window $sender })
        return
    }
    $Window.Width = [Math]::Min(1440, $area.Width - 24)
    $Window.Height = [Math]::Min(900, $area.Height - 24)
    $Window.Left = $area.Left + ($area.Width - $Window.Width) / 2
    $Window.Top = $area.Top + ($area.Height - $Window.Height) / 2
    if ($area.Width -lt 1280 -or $area.Height -lt 760) {
        $Window.Add_SourceInitialized({ param($sender) $sender.WindowState = [System.Windows.WindowState]::Maximized })
        $script:ui.SidebarColumn.Width = [System.Windows.GridLength]::new(250)
        if ($area.Width -lt 1280 -and $script:settings.ResponseDockState -in @('Right', 'Left')) { Set-ResponseDock -Dock 'Bottom'; $script:startupDockState = 'Bottom' }
    }
}

function Save-MainWindowBounds {
    param($Window)
    $bounds = if ($Window.WindowState -eq [System.Windows.WindowState]::Normal) { [System.Windows.Rect]::new($Window.Left, $Window.Top, $Window.ActualWidth, $Window.ActualHeight) } else { $Window.RestoreBounds }
    if ($bounds.IsEmpty -or $bounds.Width -lt 400) { return }
    $script:settings.WindowBounds = @{ Left = [Math]::Round($bounds.Left); Top = [Math]::Round($bounds.Top); Width = [Math]::Round($bounds.Width); Height = [Math]::Round($bounds.Height)
        Maximized = ($Window.WindowState -eq [System.Windows.WindowState]::Maximized) }
}

# Runs an action; any error is shown in the header pill and written to the application log instead of crashing the window.
function Invoke-UiGuard {
    param([scriptblock]$Action, [string]$What = 'Action')
    try { & $Action }
    catch {
        Write-Log "$What failed: $($_.Exception.Message)" -Level Info
        Set-UiStatus "$What failed: $($_.Exception.Message)"
    }
}
#endregion

function New-ApiForm {

    $script:lastResponseContentType = $null # Store the content type of the last response
    $script:lastResponseText = ""
    $script:lastResponseHeadersText = ""
    $script:lastResponseHeadersNormalized = @{}
    $script:currentPowerShell = $null
    $script:currentAsyncResult = $null
    
    $script:isCollectionRunning = $false
    $script:collectionRunQueue = New-Object System.Collections.Queue
    $script:collectionRunnerForm = $null
    $script:collectionRunnerGrid = $null
    $script:collectionRunnerProgress = $null
    $script:collectionRunnerSummaryLabel = $null
    $script:collectionRunnerBtnStart = $null
    $script:collectionRunnerBtnRetry = $null
    $script:collectionRunnerBtnStop = $null
    $script:collectionRunnerParentForm = $null
    $script:collectionRunTotal = 0
    # Initialize RunspacePool for background requests (Min 1, Max 5 concurrent tasks)
    $script:requestRunspacePool = [System.Management.Automation.Runspaces.RunspaceFactory]::CreateRunspacePool(1, 5)
    $script:requestRunspacePool.Open()
    Write-Log "Runspace pool created." -Level Debug

    $script:collectionRunCompleted = 0
    $script:collectionRunDelay = 0
    $script:collectionRunStopOnFail = $false
    $script:collectionRunnerCurrentRow = $null
    $script:collectionRunStopRequested = $false
    $script:collectionRunDelayTimer = $null
    $script:cookieJar = New-Object System.Collections.ArrayList

    function Complete-CollectionRun {
        param(
            [string]$Summary = "Run Complete.",
            [bool]$EnableRetry = $true,
            [string]$PendingReason = $null
        )

        $script:isCollectionRunning = $false
        $script:collectionRunStopRequested = $false
        $script:collectionRunnerCurrentRow = $null

        if ($script:collectionRunDelayTimer) {
            try { $script:collectionRunDelayTimer.Stop() } catch {}
            try { $script:collectionRunDelayTimer.Dispose() } catch {}
            $script:collectionRunDelayTimer = $null
        }

        if ($script:collectionRunQueue) {
            if ($PendingReason) {
                foreach ($queuedRow in $script:collectionRunQueue) {
                    if ($queuedRow.Cells["Status"].Value -eq "Queued") {
                        $queuedRow.Cells["Status"].Value = "Stopped"
                        $queuedRow.Cells["Result"].Value = $PendingReason
                        $queuedRow.DefaultCellStyle.BackColor = [System.Drawing.ColorTranslator]::FromHtml("#e2e3e5")
                    }
                }
            }
            $script:collectionRunQueue.Clear()
        }

        if ($script:collectionRunnerSummaryLabel) { $script:collectionRunnerSummaryLabel.Text = $Summary }
        if ($script:collectionRunnerBtnStart) { $script:collectionRunnerBtnStart.Enabled = $true; $script:collectionRunnerBtnStart.Text = "Start Run" }
        if ($script:collectionRunnerBtnRetry) { $script:collectionRunnerBtnRetry.Enabled = $EnableRetry }
        if ($script:collectionRunnerBtnStop) { $script:collectionRunnerBtnStop.Enabled = $false }

        if ($script:collectionRunnerParentForm -and $script:collectionRunnerParentForm.Tag) {
            $script:collectionRunnerParentForm.Tag.btnSubmit.Enabled = $true
            $script:collectionRunnerParentForm.Tag.btnCancel.Enabled = $false
            $script:collectionRunnerParentForm.Tag.btnRepeat.Enabled = $true
        }
    }

    function Request-CollectionRunStop {
        param([string]$Summary = "Stopping run...")

        if (-not $script:isCollectionRunning) { return }

        $script:collectionRunStopRequested = $true
        if ($script:collectionRunnerSummaryLabel) { $script:collectionRunnerSummaryLabel.Text = $Summary }
        if ($script:collectionRunnerBtnStop) { $script:collectionRunnerBtnStop.Enabled = $false }

        if ($script:collectionRunDelayTimer) {
            try { $script:collectionRunDelayTimer.Stop() } catch {}
            try { $script:collectionRunDelayTimer.Dispose() } catch {}
            $script:collectionRunDelayTimer = $null
            Complete-CollectionRun -Summary "Collection run stopped." -PendingReason "Skipped after manual stop"
            return
        }

        if ($script:currentPowerShell -and $script:currentAsyncResult -and -not $script:currentAsyncResult.IsCompleted) {
            Write-Log "Collection run stop requested. Cancelling active request."
            try { $script:currentPowerShell.Stop() } catch {}
            return
        }

        Complete-CollectionRun -Summary "Collection run stopped." -PendingReason "Skipped after manual stop"
    }

    function Invoke-CollectionRunnerFormClosing {
        param(
            [object]$sender,
            [System.Windows.Forms.FormClosingEventArgs]$e
        )

        if ($e.CloseReason -in @(
            [System.Windows.Forms.CloseReason]::FormOwnerClosing,
            [System.Windows.Forms.CloseReason]::ApplicationExitCall,
            [System.Windows.Forms.CloseReason]::TaskManagerClosing,
            [System.Windows.Forms.CloseReason]::WindowsShutDown
        )) { return }

        if (-not $script:isCollectionRunning) { return }
        if ($script:collectionRunnerForm -ne $sender) { return }

        $e.Cancel = $true
        Request-CollectionRunStop -Summary "Stopping collection run..."
        if ($script:collectionRunnerSummaryLabel) {
            $script:collectionRunnerSummaryLabel.Text = "Stopping collection run... Window will stay open until the active request ends."
        }
    }

    # Create the single, persistent timer for polling request status.
    $script:requestTimer = New-Object System.Windows.Forms.Timer
    $script:requestTimer.Interval = 100 # Check every 100ms

    $script:requestTimer.Add_Tick({
        if ($script:currentAsyncResult -and $script:currentAsyncResult.IsCompleted) {
            $script:requestTimer.Stop()
            
            $jobResult = $null
            try {
                $output = $script:currentPowerShell.EndInvoke($script:currentAsyncResult)
                # Extract the result hashtable.
                $jobResult = $output | Where-Object { $_ -is [hashtable] -and $_.ContainsKey('Success') } | Select-Object -First 1
            } catch {
                 $jobResult = @{ Success = $false; ErrorMessage = "Runspace Error: $($_.Exception.Message)" }
                 $statusStrip.BackColor = [System.Drawing.ColorTranslator]::FromHtml("#dc3545") # Red
            }

            # Check if it was stopped/cancelled (InvocationStateInfo might be Stopping/Stopped)
            $requestWasCancelled = $script:currentPowerShell.InvocationStateInfo.State -eq 'Stopped'
            if ($requestWasCancelled) {
                 $statusLabelStatus.Text = "Request Cancelled"
                 $statusStrip.BackColor = [System.Drawing.ColorTranslator]::FromHtml("#ffc107") # Yellow/Orange
                 $richTextResponse.Text = "The request was cancelled by the user."
            }
            elseif ($jobResult) {
                if ($jobResult.Success) {
                    $res = $jobResult.Data
                    if ($script:isRepeating) { $script:repeatSuccessCount++ }
                    # Color code the status bar based on the response code
                    $statusCode = $res.StatusCode
                    if ($statusCode -ge 200 -and $statusCode -le 299) {
                        $statusStrip.BackColor = [System.Drawing.ColorTranslator]::FromHtml("#28a745") # Green
                    }
                    elseif ($statusCode -ge 300 -and $statusCode -le 399) {
                        $statusStrip.BackColor = [System.Drawing.ColorTranslator]::FromHtml("#ffc107") # Yellow
                    }
                    else { # 4xx, 5xx, etc.
                        $statusStrip.BackColor = [System.Drawing.ColorTranslator]::FromHtml("#dc3545") # Red
                    }
                    $statusLabelStatus.Text = "$($res.StatusCode) $($res.StatusDescription)"
                    $statusLabelTime.Text = "Time: $($res.ElapsedTime) ms"
                    $statusLabelSize.Text = "Size: $(if ($res.RawContentLength -gt 0) { Format-Bytes -bytes $res.RawContentLength } else { (if ($res.Content) { Format-Bytes -bytes $res.Content.Length } else { '0 bytes' }) })"
                    Write-Log "Response: $($res.StatusCode) $($res.StatusDescription)"

                    $headersBuilder = New-Object System.Text.StringBuilder
                    foreach ($key in $res.Headers.Keys) { $headersBuilder.AppendLine("${key}: $($res.Headers[$key])") | Out-Null }
                    $responseHeadersText = $headersBuilder.ToString()
                    $richTextResponseHeaders.Text = $responseHeadersText
                    $script:lastResponseHeadersText = $responseHeadersText

                    # Normalize response headers to lowercase keys for consistent lookups.
                    $headersNormalized = @{}
                    foreach ($k in $res.Headers.Keys) { $headersNormalized[$k.ToLower()] = $res.Headers[$k] }
                    $script:lastResponseHeadersNormalized = $headersNormalized

                    $contentType = ""
                    $script:lastResponseContentType = $null # Reset content type
                    if ($headersNormalized.ContainsKey('content-type')) { $contentType = $headersNormalized['content-type'].Split(';')[0].Trim() }
                    $script:lastResponseContentType = $contentType

                    if ($script:settings.LogLevel -eq 'Debug') {
                        # Log Cookies
                        if ($jobResult.Cookies) {
                            $cookieLog = "Received Cookies:`r`n"
                            foreach ($c in $jobResult.Cookies) {
                                $cookieLog += "$($c.Name)=$($c.Value) (Domain: $($c.Domain))`r`n"
                            }
                            Write-Log $cookieLog
                        }

                        Write-Log "Response Headers:`r`n$responseHeadersText"
                        $shouldLogBody = $true
                        if ($contentType -match 'text|rtf|json|html|xml') { $shouldLogBody = $false }
                        if ($shouldLogBody -and $res.Content) {
                            $debugBody = [System.Text.Encoding]::UTF8.GetString($res.Content)
                            if ($debugBody.Length -gt 10000) { $debugBody = $debugBody.Substring(0, 10000) + "... (truncated)" }
                            Write-Log "Response Body:`r`n$debugBody"
                        }
                    }

                    # Update Cookie Jar
                    if ($jobResult.Cookies) {
                        foreach ($newCookie in $jobResult.Cookies) {
                            # Remove existing cookie with same name/domain/path
                            $existing = $null
                            foreach ($c in $script:cookieJar) {
                                if ($c.Name -eq $newCookie.Name -and $c.Domain -eq $newCookie.Domain -and $c.Path -eq $newCookie.Path) {
                                    $existing = $c
                                    break
                                }
                            }
                            if ($existing) { $script:cookieJar.Remove($existing) }
                            
                            # Add if not expired
                            if (-not $newCookie.Expired) {
                                [void]$script:cookieJar.Add($newCookie)
                            }
                        }
                    }

                    $isAttachmentHeader = $headersNormalized.ContainsKey('content-disposition') -and $headersNormalized['content-disposition'] -like 'attachment*'
                    
                    # Determine if the content is something we can render as text.
                    $isRenderable = $contentType -like 'text/*' -or 
                                    $contentType -like 'application/json*' -or 
                                    $contentType -like 'application/xml*' -or
                                    $contentType -like 'application/xml*' -or 
                                    $contentType -like 'application/rtf*' -or
                                    $contentType -like 'image/*' -or
                                    $contentType -like 'text/html*'

                    # Store the content type for the prettify button
                    $script:lastResponseContentType = $contentType
                    $script:btnExportResponse.Enabled = $isRenderable
                    $script:btnPrettifyResponse.Enabled = $isRenderable

                    $finalSavePath = $null

                    $isBinaryResponse = (-not $isRenderable -and $res.Content.Length -gt 0)
                    if ($isBinaryResponse -or $isAttachmentHeader) { # Check if we should try to save the file
                        if ($script:settings.AutoSaveToFile -and [System.IO.Directory]::Exists($script:settings.AutoSavePath)) { # Auto-save is enabled
                            # Auto-Save is enabled.
                            $targetFolder = $script:settings.AutoSavePath
                            $fileNameFromHeader = $null
                            if ($headersNormalized.ContainsKey('content-disposition') -and $headersNormalized['content-disposition'] -match 'filename="?([^"]+)"?') {
                                $fileNameFromHeader = $matches[1] # Extract filename from header
                            }
                            
                            if ($fileNameFromHeader) {
                                $outputFileName = $fileNameFromHeader # Start with filename from header
                                # Apply auto-rename logic if enabled.
                                if ($script:settings.AutoRenameFile) {
                                    # Find all keys in the form body that correspond to file uploads.
                                    $fileUploads = @($script:formBody.GetEnumerator() | Where-Object { $_.Value -is [hashtable] -and $_.Value.ContainsKey('_Path') })

                                    $prefix = if ($script:settings.EnableAutoRenamePrefix) { $script:settings.AutoRenamePrefix } else { "" }
                                    $ext = [System.IO.Path]::GetExtension($outputFileName)

                                    if ($fileUploads.Count -eq 1) {
                                        $file = $fileUploads[0].Value
                                        $name = [System.IO.Path]::GetFileNameWithoutExtension($file.Name)
                                        $outputFileName = "$prefix$name$ext"
                                    } elseif ($fileUploads.Count -ge 2) {
                                        $file1 = $fileUploads[0].Value
                                        $file2 = $fileUploads[1].Value
                                        $name1 = [System.IO.Path]::GetFileNameWithoutExtension($file1.Name)
                                        $name2 = [System.IO.Path]::GetFileNameWithoutExtension($file2.Name)
                                        $outputFileName = "$prefix$name1 and $name2$ext"
                                    }
                                }
                                $finalSavePath = Join-Path -Path $targetFolder -ChildPath $outputFileName
                            } else {
                                $richTextResponse.Text = "Auto-save is enabled, but the server response did not include a 'filename' in the Content-Disposition header. Cannot save the file."
                            }
                        } elseif (-not [string]::IsNullOrWhiteSpace($script:textOutputFile.Text)) {
                            # Manual output file is specified.
                            $finalSavePath = $script:textOutputFile.Text
                        }
                    }
                    if ($finalSavePath) { # If a save path was determined, write the file
                        try {
                            $parentDir = [System.IO.Path]::GetDirectoryName($finalSavePath)
                            if (-not (Test-Path $parentDir)) { [System.IO.Directory]::CreateDirectory($parentDir) | Out-Null }
                            [System.IO.File]::WriteAllBytes($finalSavePath, $res.Content)
                            Write-Log "Saved file to $finalSavePath"
                            $uri = New-Object System.Uri $finalSavePath
                            $richTextResponse.Text = "Binary response successfully saved to:`n$($uri.AbsoluteUri)"
                            $script:lastResponseText = ""
                        } catch {
                            $richTextResponse.Text = "Error saving file to '$finalSavePath':`n$($_.Exception.Message)"
                            Write-Log "Error saving file: $($_.Exception.Message)" -Level Info
                            $script:lastResponseText = ""
                        }
                    } elseif ($isRenderable -or $res.Content.Length -eq 0) { # If not saving, try to render it
                        $responseContent = if ($res.Content) { [System.Text.Encoding]::UTF8.GetString($res.Content) } else { "" }
                        $script:lastResponseText = $responseContent
                        $tabControlResponse.TabPages.Remove($tabPreview) # Remove preview tab by default
                        $webBrowserPreview.Visible = $false
                        $pictureBoxPreview.Visible = $false

                        try {
                        if ($contentType -like 'application/rtf*') {
                            $richTextResponse.Rtf = $responseContent
                            Write-Log "Rendering response as RTF."
                        } elseif ($contentType -like 'application/json*') {
                            $jsonObj = $responseContent | ConvertFrom-Json # Validate JSON
                            Update-JsonTreeView -JsonData $jsonObj -NodesCollection $treeViewJson.Nodes
                            $richTextResponse.Rtf = Format-JsonAsRtf -JsonString $responseContent -FontSize $script:settings.ResponseFontSize
                            Write-Log "Rendering response as formatted JSON."
                        } elseif ($contentType -like 'application/xml*' -or $contentType -like 'text/xml*') {
                        # Check if the JSON is a redline document
                        if ($jsonBodyForTest -and $jsonBodyForTest._type -eq 'redlinedocument') {
                            $richTextResponse.Rtf = Format-RedlineAsRtf -RedlineJson $jsonBodyForTest -FontSize $script:settings.ResponseFontSize
                            Write-Log "Rendering response as a formatted Redline Document."
                        }
                            $richTextResponse.Text = ([xml]$responseContent).OuterXml # Format XML
                            Write-Log "Rendering response as formatted XML."
                        } elseif ($contentType -like 'text/html*') {
                                $webBrowserPreview.Visible = $true
                                $webBrowserPreview.DocumentText = $responseContent
                                $tabControlResponse.TabPages.Add($tabPreview) # Add preview tab
                                $richTextResponse.Text = $responseContent # Also show raw text
                                Write-Log "Rendering response as HTML."
                            } elseif ($contentType -like 'image/*') {
                                $ms = New-Object System.IO.MemoryStream(,$res.Content)
                                $pictureBoxPreview.Image = [System.Drawing.Image]::FromStream($ms)
                                $pictureBoxPreview.Visible = $true
                                $tabControlResponse.TabPages.Add($tabPreview)
                                $richTextResponse.Text = "[Binary Image Data: $contentType]"
                                Write-Log "Rendering response as Image."
                            } else {
                                # Fallback for other text-based types
                                $richTextResponse.Text = $responseContent
                            }
                        }
                        catch { 
                            $richTextResponse.Text = $responseContent 
                            Write-Log "Failed to render rich content, showing as plain text."
                        }
                        # Execute user-defined tests against the response.
                        if (-not [string]::IsNullOrWhiteSpace($testsRaw)) {
                            $script:testResults.Clear()
                            $testScriptBlock = [scriptblock]::Create($testsRaw)

                            $jsonBodyForTest = $null
                            try {
                                if (-not $finalSavePath) {
                                    $jsonBodyForTest = [System.Text.Encoding]::UTF8.GetString($res.Content) | ConvertFrom-Json -ErrorAction Stop
                                }
                            } catch {
                                # If JSON parsing fails, $jsonBodyForTest will remain $null.
                            }

                            $testScopeVars = @{
                                statusCode = $res.StatusCode
                                headers    = $res.Headers
                                body       = if ($finalSavePath) { "[Binary content saved to file]" } else { [System.Text.Encoding]::UTF8.GetString($res.Content) }
                                jsonBody   = $jsonBodyForTest
                            }

                            try {
                            # Define the functions within the scope of the Invoke-Command
                            $fullTestScript = @"
                            $(Get-Command Assert-Equal | Select-Object -ExpandProperty Definition)
                            $(Get-Command Assert-Contains | Select-Object -ExpandProperty Definition)
                            $(Get-Command Assert-StatusIs | Select-Object -ExpandProperty Definition)
                            $testsRaw
"@
                            Invoke-Command -ScriptBlock ([scriptblock]::Create($fullTestScript)) -ArgumentList $testScopeVars -NoNewScope -ErrorAction Stop
                            } catch {
                                $script:testResults.Add([PSCustomObject]@{ Status = 'ERROR'; Message = "Test script failed to execute: $($_.Exception.Message)"}) | Out-Null
                            }

                            $richTextTestResults.Rtf = Format-TestResultsAsRtf -Results $script:testResults -FontSize $script:settings.ResponseFontSize
                            $tabControlResponse.SelectedTab = $tabTestResults
                        }
                    } else { # This is now the case for unrenderable binary content with no save path
                        $richTextResponse.Text = "Cannot render binary response in the UI.`n`nContent-Type: $contentType`nSize: $(Format-Bytes -bytes $res.Content.Length)`n`nTo save this response, specify an 'Output File' or enable 'Auto-Save' and send the request again."
                        $script:lastResponseText = ""
                    }
                }
                elseif ($jobResult) { # This handles the case where the job did not succeed
                    # Job failed but we might still have error data
                    if ($script:isRepeating) { $script:repeatFailCount++ }
                    $res = $jobResult.Data
                    if ($res -and $res.errorBody) {
                        $statusStrip.BackColor = [System.Drawing.ColorTranslator]::FromHtml("#dc3545") # Red
                        if ($res.StatusCode) {
                            $statusLabelStatus.Text = "$($res.StatusCode) $($res.StatusDescription)"
                        } else {
                            $statusLabelStatus.Text = "Request Failed"
                        }
                        $statusLabelTime.Text = "Time: $($res.ElapsedTime) ms" # Display elapsed time even on error
                        $statusLabelSize.Text = "Size: $(if (($res.RawContentLength -as [int64]) -gt 0) { Format-Bytes -bytes ([int64]$res.RawContentLength) } else { if ($res.errorBody) { Format-Bytes -bytes ([System.Text.Encoding]::UTF8.GetByteCount($res.errorBody)) } else { '0 bytes' } })"

                        $headersBuilder = New-Object System.Text.StringBuilder
                        $headersNormalized = @{}
                        if ($res.Headers) {
                            foreach ($key in $res.Headers.Keys) {
                                $headersBuilder.AppendLine("${key}: $($res.Headers[$key])") | Out-Null
                                $headersNormalized[$key.ToLower()] = $res.Headers[$key]
                            }
                        }
                        $responseHeadersText = $headersBuilder.ToString()
                        $richTextResponseHeaders.Text = $responseHeadersText
                        $script:lastResponseHeadersText = $responseHeadersText
                        $script:lastResponseHeadersNormalized = $headersNormalized

                        $contentType = ""
                        if ($headersNormalized.ContainsKey('content-type')) { $contentType = $headersNormalized['content-type'].Split(';')[0].Trim() }
                        $script:lastResponseContentType = $contentType

                        try {
                            $null = $res.errorBody | ConvertFrom-Json
                            $richTextResponse.Rtf = Format-JsonAsRtf -JsonString $res.errorBody -FontSize $script:settings.ResponseFontSize
                        } catch {
                            $richTextResponse.Text = $res.errorBody
                        }
                        $script:lastResponseText = $res.errorBody
                    } else {
                        $statusStrip.BackColor = [System.Drawing.ColorTranslator]::FromHtml("#dc3545") # Red
                        $statusLabelStatus.Text = "Request Failed"
                        $richTextResponseHeaders.Text = ""
                        $script:lastResponseHeadersText = ""
                        $script:lastResponseHeadersNormalized = @{}
                        $richTextResponse.Text = $jobResult.ErrorMessage # Display generic job error message
                        $script:lastResponseText = $jobResult.ErrorMessage
                    }
                }

            }
            
            # Cleanup Runspace
            if ($script:currentPowerShell) { $script:currentPowerShell.Dispose() }
            $script:currentPowerShell = $null
            $script:currentAsyncResult = $null
            
            # --- Collection Runner Logic ---
            if ($script:isCollectionRunning) {
                $script:collectionRunCompleted++
                if ($script:collectionRunnerProgress) { $script:collectionRunnerProgress.Value = $script:collectionRunCompleted }
                if ($script:collectionRunnerSummaryLabel) { $script:collectionRunnerSummaryLabel.Text = "Progress: $($script:collectionRunCompleted)/$($script:collectionRunTotal)" }

                # Update Grid Status
                if ($script:collectionRunnerCurrentRow) {
                    $row = $script:collectionRunnerCurrentRow
                    if ($requestWasCancelled -and $script:collectionRunStopRequested) {
                        $row.Cells["Status"].Value = "Stopped"
                        $row.Cells["Result"].Value = "Cancelled by user"
                        $row.DefaultCellStyle.BackColor = [System.Drawing.ColorTranslator]::FromHtml("#e2e3e5")
                    } elseif ($jobResult.Success) {
                        $row.Cells["Status"].Value = "PASS"
                        $row.Cells["Result"].Value = "$($jobResult.Data.StatusCode) $($jobResult.Data.StatusDescription)"
                        $row.Cells["Time"].Value = $jobResult.Data.ElapsedTime
                        $row.DefaultCellStyle.BackColor = [System.Drawing.ColorTranslator]::FromHtml("#d4edda")
                    } else {
                        $row.Cells["Status"].Value = "FAIL"
                        $row.Cells["Result"].Value = if ($jobResult.Data) { "$($jobResult.Data.StatusCode) $($jobResult.Data.StatusDescription)" } else { $jobResult.ErrorMessage }
                        $row.DefaultCellStyle.BackColor = [System.Drawing.ColorTranslator]::FromHtml("#f8d7da")
                    }
                    # Test Summary
                    if ($script:testResults) {
                        $passCount = ($script:testResults | Where-Object { $_.Status -eq 'PASS' }).Count
                        $failCount = ($script:testResults | Where-Object { $_.Status -ne 'PASS' }).Count
                        $row.Cells["Tests"].Value = "$passCount passed, $failCount failed"
                    }
                }

                if ($script:collectionRunStopRequested) {
                    Complete-CollectionRun -Summary "Collection run stopped." -PendingReason "Skipped after manual stop"
                    return
                }

                # Stop on Failure Check
                $isFailure = (-not $jobResult.Success) -or ($jobResult.Data.StatusCode -ge 400)
                if ($script:collectionRunStopOnFail -and $isFailure) {
                    Complete-CollectionRun -Summary "Stopped due to failure." -EnableRetry $true -PendingReason "Skipped after failure"
                    return
                }

                if ($script:collectionRunQueue.Count -gt 0) {
                    $nextRow = $script:collectionRunQueue.Dequeue()
                    $script:collectionRunnerCurrentRow = $nextRow
                    $nextRow.Cells["Status"].Value = "Running..."
                    
                    # Delay Logic
                    $delay = [Math]::Max(50, $script:collectionRunDelay)
                    $script:collectionRunDelayTimer = New-Object System.Windows.Forms.Timer
                    $script:collectionRunDelayTimer.Interval = $delay
                    $script:collectionRunDelayTimer.Add_Tick({
                        param($s, $ev)
                        $s.Stop(); $s.Dispose()
                        $script:collectionRunDelayTimer = $null
                        if ($script:collectionRunStopRequested) {
                            Complete-CollectionRun -Summary "Collection run stopped." -PendingReason "Skipped after manual stop"
                            return
                        }
                        $currentRow = $script:collectionRunnerCurrentRow
                        $requestObject = if ($currentRow) { Get-RequestObjectFromItem -Item $currentRow.Tag } else { $null }
                        if (-not $requestObject) {
                            if ($currentRow) {
                                $currentRow.Cells["Status"].Value = "ERROR"
                                $currentRow.Cells["Result"].Value = "Missing request data"
                                $currentRow.DefaultCellStyle.BackColor = [System.Drawing.ColorTranslator]::FromHtml("#f8d7da")
                            }
                            Complete-CollectionRun -Summary "Run stopped because a request entry is missing request data." -EnableRetry $true -PendingReason "Skipped after missing request data"
                            return
                        }
                        Import-RequestFromObject -RequestObject $requestObject
                        Invoke-RequestExecution
                    })
                    $script:collectionRunDelayTimer.Start()
                    return # Exit tick to wait for delay
                } else {
                    if ($script:collectionRunData -and $script:collectionRunData.Count -gt 0 -and $script:collectionRunDataIndex -lt ($script:collectionRunData.Count - 1)) {
                        $script:collectionRunDataIndex++
                        $script:activeCollectionVariables = @{}
                        $nextDataRow = $script:collectionRunData[$script:collectionRunDataIndex]
                        foreach ($prop in $nextDataRow.PSObject.Properties) {
                            $script:activeCollectionVariables[$prop.Name] = $prop.Value
                        }
                        
                        # Re-enqueue rows
                        foreach ($row in $script:collectionRunnerGrid.Rows) {
                            if ($row.Cells["Run"].Value -and $row.Cells["Status"].Value -ne "Invalid") {
                                $script:collectionRunQueue.Enqueue($row)
                                $row.Cells["Status"].Value = "Queued"
                            }
                        }
                        
                        $script:collectionRunTotal += $script:collectionRunQueue.Count
                        $script:collectionRunnerProgress.Maximum = [Math]::Max(1, $script:collectionRunTotal)
                        
                        # Trigger the next loop
                        Process-NextCollectionRequest -IsSuccess $true
                    } else {
                        Complete-CollectionRun -Summary "Run Complete." -EnableRetry $true
                    }
                }
            }

            # Handle repeat requests *after* cleaning up the completed runspace.
            if ($script:isRepeating -eq $true) {
                $script:currentRepeatIteration++
                if ($script:currentRepeatIteration -lt $script:repeatCount) {
                    Write-Log "Repeat Request: Iteration $($script:currentRepeatIteration) of $($script:repeatCount) completed. Sending next request..." -Level Debug
                    $statusLabelStatus.Text = "Repeating Request ($($script:currentRepeatIteration + 1)/$($script:repeatCount))... (Success: $($script:repeatSuccessCount), Fail: $($script:repeatFailCount))"
                    
                    $repeatDelayTimer = New-Object System.Windows.Forms.Timer
                    $repeatDelayTimer.Interval = 200 # A small delay to allow UI to update
                    $repeatDelayBlock = { 
                        param($sender, $e) # Use param block to get the timer object that fired the event
                        Invoke-RequestExecution # Call the core logic directly, bypassing the button click
                        $sender.Stop() # Stop and dispose the timer using the sender parameter
                        $sender.Dispose()
                    }
                    $repeatDelayTimer.Add_Tick($repeatDelayBlock)
                    $repeatDelayTimer.Start()
                    return # Exit the main timer tick; the delay timer will fire the next request.
                } else {
                    # All repeats are done
                    $finalStatus = "Repeat Request Completed ($($script:repeatCount) iterations). Success: $($script:repeatSuccessCount), Fail: $($script:repeatFailCount)."
                    Write-Log $finalStatus -Level Info
                    $statusLabelStatus.Text = $finalStatus
                    $script:isRepeating = $false
                }
            }
            
            # This code runs if not repeating, or if the last repeat has just finished.
            if (-not $script:isCollectionRunning) {
                $btnSubmit.Enabled = $true; $btnSubmit.BackColor = $script:Theme.PrimaryButton
                $btnCancel.Enabled = $false
                $btnRepeat.Enabled = $true
            }
        }
    })

# This function contains the core logic for preparing and executing an API request.
# It's separated from the UI button's click event to allow for programmatic re-triggering (e.g., for repeating requests).
function Invoke-RequestExecution {
    $missingUiControls = @(
        @{ Name = 'comboMethod'; Control = $script:comboMethod }
        @{ Name = 'comboBodyType'; Control = $script:comboBodyType }
        @{ Name = 'comboEnvironment'; Control = $script:comboEnvironment }
        @{ Name = 'textUrl'; Control = $script:textUrl }
        @{ Name = 'textHeaders'; Control = $script:textHeaders }
        @{ Name = 'textBody'; Control = $script:textBody }
        @{ Name = 'textTests'; Control = $script:textTests }
    ) | Where-Object { -not $_.Control } | ForEach-Object { $_.Name }

    if ($missingUiControls.Count -gt 0) {
        $missingList = $missingUiControls -join ', '
        Write-Log "Invoke-RequestExecution skipped because UI is not ready. Missing controls: $missingList"
        if ($statusLabelStatus) { $statusLabelStatus.Text = "Request UI is still loading." }
        return
    }

    # Clear previous response and test results.
    $richTextResponse.Text = ""
    $richTextResponseHeaders.Text = ""
    $richTextCode.Text = ""
    $treeViewJson.Nodes.Clear()
    $script:btnExportResponse.Enabled = $false # Disable export button for new request
    $script:btnPrettifyResponse.Enabled = $false # Disable prettify button for new request
    $richTextTestResults.Text = ""
    $script:lastResponseText = ""
    $script:lastResponseHeadersText = ""
    $script:lastResponseHeadersNormalized = @{}

    # Reset the status bar for the new request.
    if (-not $script:isCollectionRunning) {
        $statusStrip.BackColor = $script:Theme.PrimaryButton
    }
    $statusLabelStatus.Text = "Sending request..."
    $statusLabelTime.Text = "Time: ..."
    $statusLabelSize.Text = "Size: ..."
    $form.Refresh() # Force UI update
    Write-Log "Request execution started."
    
    # Substitute environment variables into all relevant fields.
    $script:activeEnvironment = $script:comboEnvironment.SelectedItem

    $ApiRequest = @{
        Method = if ($script:comboMethod.SelectedItem) { [string]$script:comboMethod.SelectedItem } else { "GET" }
        Url = $script:textUrl.Text
        Headers = $script:textHeaders.Text
        Body = $script:textBody.Text
    }

    # --- Pre-request Script Execution ---
    if ($script:textPreRequest -and -not [string]::IsNullOrWhiteSpace($script:textPreRequest.Text)) {
        try {
            Write-Log "Executing Pre-request script..."
            if ($script:activeEnvironment -ne "No Environment" -and $script:environments.ContainsKey($script:activeEnvironment)) {
                $Environment = $script:environments[$script:activeEnvironment]
            } else { $Environment = @{} }
            
            # Expose $ApiRequest to the script block. It runs in the current scope (-NoNewScope)
            Invoke-Command -ScriptBlock ([scriptblock]::Create($script:textPreRequest.Text)) -NoNewScope
            
            # Map any modifications back to the UI
            if ($script:comboMethod.Items.Contains($ApiRequest.Method)) { $script:comboMethod.SelectedItem = $ApiRequest.Method }
            $script:textUrl.Text = $ApiRequest.Url
            $script:textHeaders.Text = $ApiRequest.Headers
            $script:textBody.Text = $ApiRequest.Body

            Write-Log "Pre-request script executed successfully."
        } catch {
            Write-Log "Pre-request script failed: $($_.Exception.Message)"
            [System.Windows.Forms.MessageBox]::Show("Pre-request script failed:`n$($_.Exception.Message)", "Error", "OK", "Error")
            # Re-enable buttons on script failure
            $btnSubmit.Enabled = $true; $btnCancel.Enabled = $false; $btnRepeat.Enabled = $true; return
        }
    }

    $selectedMethod = if ($script:comboMethod.SelectedItem) { [string]$script:comboMethod.SelectedItem } else { "GET" }
    $selectedBodyType = if ($script:comboBodyType.SelectedItem) { [string]$script:comboBodyType.SelectedItem } else { "text/plain" }
    $method = (Expand-Variables -InputString $selectedMethod)
    $url = (Expand-Variables -InputString $script:textUrl.Text)
    $headersRaw = (Expand-Variables -InputString $script:textHeaders.Text)
    $bodyRaw = (Expand-Variables -InputString $script:textBody.Text)
    $testsRaw = $script:textTests.Text

    # --- GraphQL Logic ---
    if ($selectedBodyType -eq "GraphQL") {
        $gqlQuery = (Expand-Variables -InputString $script:txtGqlQuery.Text)
        $gqlVars = (Expand-Variables -InputString $script:txtGqlVars.Text)
        $payload = @{ query = $gqlQuery }
        if (-not [string]::IsNullOrWhiteSpace($gqlVars)) {
            try { $payload['variables'] = $gqlVars | ConvertFrom-Json } catch { Write-Log "Invalid GraphQL Variables JSON" }
        }
        $bodyRaw = $payload | ConvertTo-Json -Depth 10
        $bodyType = "application/json" # Send as JSON
        $method = "POST" # GraphQL is typically POST
    }

    $outputFormat = if ($script:textOutputFormat) { [string]$script:textOutputFormat.Text } else { "" }
    $outputFormat = $outputFormat.Trim()
    $outputFormatKey = "outputFormat"
    $outputFormatValue = $outputFormat
    if ($outputFormat -match '^\s*([^=]+?)\s*=\s*(.+)\s*$') {
        $outputFormatKey = $matches[1].Trim()
        $outputFormatValue = $matches[2].Trim()
    }
    if ($selectedBodyType -ne "GraphQL") { 
        $bodyType = $selectedBodyType
    }
    # Determine the correct output path based on whether Auto-Save is enabled.
    if ($script:settings.AutoSaveToFile) {
        $outputFile = $script:settings.AutoSavePath # Use the path from settings
    } else {
        $outputFile = $script:textOutputFile.Text
    }
    
    $includeFilename = $checkIncludeFilename.Checked
    $includeContentType = $checkIncludeContentType.Checked
    
    $ignoreSsl = $script:settings.IgnoreSslErrors
    $timeoutSeconds = $script:settings.RequestTimeoutSeconds
    
    # Store request state for code generation
    $script:lastRequestState = [PSCustomObject]@{
        Method = $method
        Url = $url
        Headers = $headersRaw
        Body = $bodyRaw
        BodyType = $bodyType
    }

    Write-Log "URL: $url"
    Write-Log "Headers: $headersRaw"
    Write-Log "Method: $method"
    Write-Log "Request Body: $bodyRaw" -Level Info
    Write-Log "Output Format: $outputFormat"

    if ($outputFile) {
        if ($script:settings.AutoSaveToFile) { Write-Log "Auto-Save Folder specified: $outputFile" }
        else { Write-Log "Output File specified: $outputFile" }
    }

    if (-not $url) {
    Write-Log "URL is empty. Showing message box."
    [System.Windows.Forms.MessageBox]::Show("Please enter a valid URL.")
    return
    }

    # Only add to history on the first request of a repeat sequence, or for a normal request.
    if ($script:settings.EnableHistory -and -not $script:isRepeating -and -not $script:isCollectionRunning) {
        # Create and save a history entry for the current request.
        $historyEntry = [PSCustomObject]@{
            Timestamp = Get-Date
            Method    = $method
            Url       = $url
            Headers   = $headersRaw
            Body      = $bodyRaw
            BodyType  = $bodyType
            OutputFormat = $outputFormat
            Tests     = $testsRaw
            PreRequestScript = $script:textPreRequest.Text
            Environment = $script:comboEnvironment.SelectedItem
            Authentication = (& $script:authPanel.GetAuthData) # Use the helper to get auth data
        }
        $script:history = @($historyEntry) + $script:history
        if ($script:history.Count -gt 50) { $script:history = $script:history[0..49] }
        
        $listHistory.Items.Insert(0, "$($historyEntry.Timestamp.ToString('HH:mm:ss')) | $($historyEntry.Method) | $($historyEntry.Url)")
        if ($listHistory.Items.Count -gt 50) { $listHistory.Items.RemoveAt(50) }

        Save-History
    }

    # Parse user-provided headers from the textbox into a hashtable.
    $headers = @{}
    foreach ($line in $headersRaw -split "`n") {
    if ($line -match "^\s*(.+?):\s*(.+)$") {
        $headers[$matches[1]] = $matches[2]
    }
    }

    # Apply authentication details to the request headers or URL.
    $authHeader = $null
    $currentAuth = & $script:authPanel.GetAuthData
    switch ($currentAuth.Type) {
        "Auth2" {
            # Pre-flight check for token expiry
            $tokenIsExpired = $false
            if ($currentAuth.TokenExpiryTimestamp) {
                try {
                    $expiryTime = [datetime]$currentAuth.TokenExpiryTimestamp
                    if ([DateTime]::UtcNow -ge $expiryTime) {
                        $tokenIsExpired = $true
                    }
                } catch {
                    Write-Log "Could not parse Auth2 TokenExpiryTimestamp: $($currentAuth.TokenExpiryTimestamp)" -Level Info
                }
            }

            if ($tokenIsExpired -and -not [string]::IsNullOrWhiteSpace($currentAuth.RefreshToken)) {
                Write-Log "Auth2 access token expired. Attempting to refresh..." -Level Info
                try {
                    $refreshBody = @{
                        grant_type    = 'refresh_token'
                        refresh_token = $currentAuth.RefreshToken
                        client_id     = $currentAuth.ClientId
                        client_secret = $currentAuth.ClientSecret # Some providers require this
                    }
                    $tokenResponse = Invoke-RestMethod -Uri $currentAuth.TokenEndpoint -Method Post -Body $refreshBody -ContentType "application/x-www-form-urlencoded" -ErrorAction Stop
                    
                    # Update UI and current auth data with the new token
                    $currentAuth.AccessToken = $tokenResponse.access_token
                    $script:authPanel.TextAuth2AccessToken.Text = $tokenResponse.access_token
                    
                    if ($tokenResponse.PSObject.Properties.Name -contains 'refresh_token') {
                        $currentAuth.RefreshToken = $tokenResponse.refresh_token
                        $script:authPanel.TextAuth2RefreshToken.Text = $tokenResponse.refresh_token
                    }
                    
                    $currentAuth.TokenExpiryTimestamp = ([DateTime]::UtcNow).AddSeconds([int]$tokenResponse.expires_in)
                    $script:authPanel.TextAuth2AccessToken.Tag = $currentAuth.TokenExpiryTimestamp
                    
                    Write-Log "Auth2 token successfully refreshed." -Level Info
                } catch {
                    [System.Windows.Forms.MessageBox]::Show("Failed to automatically refresh access token. Please get a new token manually.`n`nError: $($_.Exception.Message)", "Token Refresh Failed", "OK", "Error")
                  # Stop the request by re-enabling the submit button and returning #FIX: Corrected comment
                  $btnSubmit.Enabled = $true; $btnCancel.Enabled = $false; $btnRepeat.Enabled = $true; return
                }
            }
        }
        "API Key" {
            if (-not ([string]::IsNullOrWhiteSpace($currentAuth.Key) -or [string]::IsNullOrWhiteSpace($currentAuth.Value))) { #FIX: Corrected condition
                if ($currentAuth.AddTo -eq "Header") {
                    $headers[$currentAuth.Key] = $currentAuth.Value
                } else { # Query Params
                    $separator = if ($url -like '*?*') { '&' } else { '?' }
                    $url += "$separator$([uri]::EscapeDataString($currentAuth.Key))=$([uri]::EscapeDataString($currentAuth.Value))"
                }
            }
        }
        "Bearer Token" {
            if (-not [string]::IsNullOrWhiteSpace($currentAuth.Token)) { # Only add if token is not empty
                $authHeader = "Bearer $($currentAuth.Token)"
            }
        }
        "Basic Auth" {
            if (-not ([string]::IsNullOrWhiteSpace($currentAuth.Username))) { # Only add if username is not empty
                $credentials = [System.Text.Encoding]::UTF8.GetBytes("$($currentAuth.Username):$($currentAuth.Password)")
                $authHeader = "Basic $([System.Convert]::ToBase64String($credentials))"
            }
        }
    } # End of switch ($currentAuth.Type)
    
    # Client Certificate Logic (Prepare data for job)
    $clientCertData = $null
    if ($currentAuth.Type -eq "Client Certificate") {
        $clientCertData = @{
            Source = $currentAuth.Source
            Path = $currentAuth.Path
            Password = $currentAuth.Password
            Thumbprint = $currentAuth.Thumbprint
        }
    }

    if ($authHeader) { $headers["Authorization"] = $authHeader }
    
    # Construct the request body
    $script:formBody = @{}
    $script:formBody.Clear() # Clear any data from a previous request
    if ($bodyType -eq "multipart/form-data") {
        Write-Log "Parsing Body as multipart/form-data..."
        foreach ($line in $bodyRaw -split "`n" | Where-Object { $_ -match '\S' }) { # Process non-empty lines
            if ($line -match '^\s*([^=]+?)\s*=\s*@("([^"]+)"|([^;`\r`n]+))((?:;[^=]+=[^;]+)*)\s*$') {
                $key = $matches[1].Trim()
                $filePath = if ($matches[3]) { $matches[3] } else { $matches[4] } # Correctly get path if quoted (group 3) or not (group 4)
                $attributesRaw = $matches[5]

                if (Test-Path $filePath) {
                    # Pass a simple hashtable with path/name/metadata so it serializes safely across Start-Job.
                    $fileObject = @{
                        _Path = $filePath
                        Name  = ([System.IO.Path]::GetFileName($filePath))
                        IncludeFilename = $false # Default to false, check attributes
                        IncludeContentType = $false # Default to false, check attributes
                    }
                    if ($attributesRaw -match 'filename=([^;`\r`n]+)') {
                        $fileObject.Name = $matches[1].Trim() # Override filename from attribute
                        $fileObject.IncludeFilename = $true
                    }
                    if ($attributesRaw -match 'type=([^;`\r`n]+)') {
                        $fileObject.ContentType = $matches[1].Trim() # Override content type from attribute
                        $fileObject.IncludeContentType = $true
                    }
                    # If the global checkbox is checked but no type attribute was specified, get it now.
                    if ($includeContentType -and -not $fileObject.ContainsKey('ContentType')) {
                        $fileObject.ContentType = Get-MimeType -filePath $filePath
                    }
                    
                    $script:formBody[$key] = $fileObject
                    Write-Log "Adding file to form: '$filePath' as key '$key'"
                } else {
                    Write-Log "File not found, skipping: '$filePath'"
                }
            } elseif ($line -match '^\s*([^=]+?)\s*=\s*(.*)') { # Regular key-value (allow empty values)
                $key = $matches[1].Trim()
                $value = $matches[2].Trim()
                $script:formBody[$key] = $value
                Write-Log "Adding form value: '$key' = '$value'"
            }
        }
    if ($outputFormatValue) {
        $script:formBody[$outputFormatKey] = $outputFormatValue
    }
    }

    # Generate Code Snippet
    $selectedLang = if ($script:comboCodeLanguage.SelectedItem) { $script:comboCodeLanguage.SelectedItem } else { "cURL" }
    $richTextCode.Text = New-CodeSnippet -RequestItem $script:lastRequestState -Language $selectedLang

    if ($script:settings.LogLevel -eq 'Debug') {
        $debugCurl = New-CodeSnippet -RequestItem $script:lastRequestState -Language "cURL"
        Write-Log "Generated cURL:`r`n$debugCurl"
    }

    # --- Build multipart body bytes on the main thread to avoid Start-Job serialization issues ---
    $multipartBytes = $null # Initialize
    $multipartContentType = $null # Initialize
    if ($bodyType -eq "multipart/form-data") {
        $boundary = "---------------------------" + [System.Guid]::NewGuid().ToString("N")
        $encoding = [System.Text.Encoding]::GetEncoding("iso-8859-1")
        function Write-StreamText { param([System.IO.MemoryStream]$s, [string]$t) $b = $encoding.GetBytes($t); $s.Write($b,0,$b.Length) }
        $ms = New-Object System.IO.MemoryStream
        foreach ($key in $script:formBody.Keys) {
            $val = $script:formBody[$key]
            Write-StreamText -s $ms -t "--$boundary`r`n"
            if ($val -is [hashtable] -and $val.ContainsKey('_Path')) {
                $fp = $val._Path
                $fn = if ($val.ContainsKey('Name')) { $val.Name } else { [System.IO.Path]::GetFileName($fp) }
                $ctype = if ($val.ContainsKey('ContentType')) { $val.ContentType } else { 'application/octet-stream' }
                $disp = "Content-Disposition: form-data; name=`"$key`"; filename=`"$fn`"`r`n"
                Write-StreamText -s $ms -t $disp
                Write-StreamText -s $ms -t "Content-Type: $ctype`r`n`r`n"
                $fb = [System.IO.File]::ReadAllBytes($fp)
                $ms.Write($fb,0,$fb.Length)
                Write-StreamText -s $ms -t "`r`n"
            } else {
                $field = [string]$val
                Write-StreamText -s $ms -t "Content-Disposition: form-data; name=`"$key`"`r`n`r`n$field`r`n"
            }
        } # End of foreach ($key in $script:formBody.Keys)
        Write-StreamText -s $ms -t "--$boundary--`r`n"
        $ms.Seek(0,'Begin') | Out-Null
        $multipartBytes = $ms.ToArray()
        $multipartContentType = "multipart/form-data; boundary=$boundary"
        $ms.Close()
    }

    # Prepare Cookies for Job
    $inputCookies = @()
    if ($script:cookieJar.Count -gt 0) {
        $uri = New-Object System.Uri($url)
        foreach ($c in $script:cookieJar) {
            # Simple domain matching
            if ($uri.Host.EndsWith($c.Domain.TrimStart('.')) -or $c.Domain.TrimStart('.') -eq $uri.Host) {
                $inputCookies += $c
            }
        }
    }
    $proxySettings = @{ Mode=$script:settings.ProxyMode; Address=$script:settings.ProxyAddress; Port=$script:settings.ProxyPort; User=$script:settings.ProxyUser; Pass=$script:settings.ProxyPass }
    
    # This script block is executed in a background job to keep the UI responsive.
    $scriptBlock = { #region Start-Job ScriptBlock 
        param($url, $method, $headers, $bodyRaw, $bodyType, $formBody, $outputFile, $includeFilename, $includeContentType, $outputFormat, $multipartBytes, $multipartContentType, $ignoreSsl, $timeoutSeconds, $proxySettings, $clientCertData, $inputCookies)

        function Format-Bytes {
            param([long]$bytes)
            if ($bytes -lt 0) { return "N/A" }
            $units = @("B", "KB", "MB", "GB", "TB")
            $i = 0
            $size = [double]$bytes
            while ($size -ge 1024 -and $i -lt ($units.Length - 1)) {
                $size /= 1024
                $i++
            }
            return "{0:N2} {1}" -f $size, $units[$i]
        }
        $result = @{ Success = $false; Data = $null; ErrorMessage = "" }
        try {
            $stopwatch = [System.Diagnostics.Stopwatch]::StartNew()
          function Write-JobLog { param([string]$Message) Write-Verbose "JOB: $Message" } # Use Verbose to avoid polluting output
            Write-JobLog "Starting request to $url"

            if ($ignoreSsl) {
                [System.Net.ServicePointManager]::ServerCertificateValidationCallback = { $true }
            }

          $req = [System.Net.HttpWebRequest]::Create($url)
            $req.Method = $method
            $req.Timeout = $timeoutSeconds * 1000
            
            # Proxy Configuration
            if ($proxySettings.Mode -eq 'Custom') {
                $proxy = New-Object System.Net.WebProxy($proxySettings.Address, $proxySettings.Port)
                if ($proxySettings.User) {
                    $proxy.Credentials = New-Object System.Net.NetworkCredential($proxySettings.User, $proxySettings.Pass)
                }
                $req.Proxy = $proxy
            } elseif ($proxySettings.Mode -eq 'None') {
                $req.Proxy = [System.Net.GlobalProxySelection]::GetEmptyWebProxy()
            } else {
                $req.Proxy = [System.Net.WebRequest]::GetSystemWebProxy()
                $req.Proxy.Credentials = [System.Net.CredentialCache]::DefaultCredentials
            }

            # Client Certificates
            if ($clientCertData) {
                if ($clientCertData.Source -eq "PFX File" -and (Test-Path $clientCertData.Path)) {
                    $cert = New-Object System.Security.Cryptography.X509Certificates.X509Certificate2($clientCertData.Path, $clientCertData.Password)
                    [void]$req.ClientCertificates.Add($cert)
                } elseif ($clientCertData.Source -eq "User Store") {
                    $store = New-Object System.Security.Cryptography.X509Certificates.X509Store("My", "CurrentUser")
                    $store.Open("ReadOnly")
                    $certs = $store.Certificates.Find("FindByThumbprint", $clientCertData.Thumbprint, $false)
                    if ($certs.Count -gt 0) { [void]$req.ClientCertificates.Add($certs[0]) }
                    $store.Close()
                }
            }

            # Cookies
            $req.CookieContainer = New-Object System.Net.CookieContainer
            if ($inputCookies) {
                foreach ($c in $inputCookies) {
                    # Reconstruct cookie to ensure it attaches to container
                    $req.CookieContainer.Add($c)
                }
            }

            # Restricted headers cannot go through Headers.Add(); they must be set via HttpWebRequest properties.
            foreach ($key in $headers.Keys) {
                $val = [string]$headers[$key]
                try {
                    switch -Regex ($key.ToLowerInvariant()) {
                        '^content-type$'      { } # Set automatically alongside the body, avoid double-setting
                        '^content-length$'    { } # Computed automatically from the body
                        '^accept$'            { $req.Accept = $val }
                        '^user-agent$'        { $req.UserAgent = $val }
                        '^referer$'           { $req.Referer = $val }
                        '^expect$'            { $req.Expect = $val }
                        '^connection$'        {
                            if ($val -match 'keep-alive') { $req.KeepAlive = $true }
                            elseif ($val -match 'close')  { $req.KeepAlive = $false }
                            else { $req.Connection = $val }
                        }
                        '^transfer-encoding$' { $req.SendChunked = $true; $req.TransferEncoding = $val }
                        '^date$'              { $req.Date = [datetime]::Parse($val) }
                        '^if-modified-since$' { $req.IfModifiedSince = [datetime]::Parse($val) }
                        '^host$'              {
                            # Known limitation: Host override is not supported on every runtime.
                            try { $req.Host = $val } catch { Write-Verbose "JOB: Host header override not supported on this runtime: $($_.Exception.Message)" }
                        }
                        '^range$'             {
                            if ($val -match '^\s*bytes\s*=\s*(\d*)\s*-\s*(\d*)\s*$') {
                                if ($Matches[1] -ne '' -and $Matches[2] -ne '') { $req.AddRange([long]$Matches[1], [long]$Matches[2]) }
                                elseif ($Matches[1] -ne '')                     { $req.AddRange([long]$Matches[1]) }
                                elseif ($Matches[2] -ne '')                     { $req.AddRange(-[long]$Matches[2]) }
                            } else { Write-Verbose "JOB: Unsupported Range header value '$val' skipped" }
                        }
                        default               { $req.Headers.Add($key, $val) }
                    }
                } catch {
                    Write-Verbose "JOB: Could not apply header '$key': $($_.Exception.Message)"
                }
            }

            # Only attempt to write a request body for methods that support it.
            if ($method -in @('POST', 'PUT', 'PATCH')) {
                if ($bodyType -eq "multipart/form-data" -and $multipartBytes) {
                    $req.ContentType = $multipartContentType
                    $req.ContentLength = $multipartBytes.Length
                    Write-JobLog "Writing prebuilt multipart body, $($multipartBytes.Length) bytes"
                    $rs = $req.GetRequestStream()
                    $rs.Write($multipartBytes, 0, $multipartBytes.Length)
                    $rs.Close()
                } elseif ($bodyType -eq "multipart/form-data") {
                    Write-JobLog "Multipart Form-Data Logic: No bytes"
                } else {
                    if (-not [string]::IsNullOrEmpty($bodyRaw)) {
                        $bodyBytes = [System.Text.Encoding]::UTF8.GetBytes($bodyRaw)
                        $req.ContentLength = $bodyBytes.Length
                        $req.ContentType = if ($headers.ContainsKey('Content-Type')) { $headers['Content-Type'] } else { $bodyType }
                        Write-JobLog "Request ContentLength (raw) = $($req.ContentLength) bytes"
                        $requestStream = $req.GetRequestStream()
                        $requestStream.Write($bodyBytes, 0, $bodyBytes.Length)
                        $requestStream.Close()
                    }
                } # End of if (-not [string]::IsNullOrEmpty($bodyRaw))
            } # End of body-writing logic

            $response = $req.GetResponse()
            $stopwatch.Stop()

            $responseStream = $response.GetResponseStream()
            $memStream = New-Object System.IO.MemoryStream
            $responseStream.Close()
          $responseHeaders = @{}
          foreach ($key in $response.Headers.AllKeys) { $responseHeaders[$key] = $response.Headers[$key] }
          
          $resCookies = $req.CookieContainer.GetCookies($req.RequestUri)
            $memStream.Close()
            $responseHeaders = @{}
            foreach ($key in $response.Headers.AllKeys) { $responseHeaders[$key] = $response.Headers[$key] }
            
            $resCookies = $req.CookieContainer.GetCookies($req.RequestUri)
            $result.Success = $true
            $result.Data = @{
                StatusCode        = [int]$response.StatusCode
                StatusDescription = $response.StatusDescription
                ElapsedTime       = $stopwatch.ElapsedMilliseconds
                Headers           = $responseHeaders
                Content           = $responseBytes
                Cookies           = $resCookies
                RawContentLength  = $response.ContentLength
            }
        } # End of try
        catch {
            $stopwatch.Stop()
            $result.ErrorMessage = $_.Exception.Message
            if ($_.Exception.Response) {
                $errorBody = ""
                $errorHeaders = @{}
                foreach ($key in $_.Exception.Response.Headers.AllKeys) { $errorHeaders[$key] = $_.Exception.Response.Headers[$key] }
                if ($errorStream = $_.Exception.Response.GetResponseStream()) {
                    $reader = New-Object System.IO.StreamReader($errorStream)
                    $errorBody = $reader.ReadToEnd()
                    $reader.Close()
                    $errorStream.Close()
                }
                $result.Data = @{
                    StatusCode        = [int]$_.Exception.Response.StatusCode
                    StatusDescription = $_.Exception.Response.StatusDescription
                    ElapsedTime       = $stopwatch.ElapsedMilliseconds
                    Headers           = $errorHeaders
                    RawContentLength  = $_.Exception.Response.ContentLength
                    errorBody         = $errorBody
                }
            } else {
                $result.Data = @{ ElapsedTime = $stopwatch.ElapsedMilliseconds }
            }
        } # End of catch
        return $result
    } #endregion

    # Use Runspace (PowerShell instance) instead of Start-Job for better performance
    if ($script:currentPowerShell) { $script:currentPowerShell.Dispose(); $script:currentPowerShell = $null }
    $script:currentPowerShell = [PowerShell]::Create()
    $script:currentPowerShell.AddScript($scriptBlock).AddArgument($url).AddArgument($method).AddArgument($headers).AddArgument($bodyRaw).AddArgument($bodyType).AddArgument($formBody).AddArgument($outputFile).AddArgument($includeFilename).AddArgument($includeContentType).AddArgument($outputFormat).AddArgument($multipartBytes).AddArgument($multipartContentType).AddArgument($ignoreSsl).AddArgument($timeoutSeconds).AddArgument($proxySettings).AddArgument($clientCertData).AddArgument($inputCookies) | Out-Null
    
    $script:currentAsyncResult = $script:currentPowerShell.BeginInvoke()

    $script:requestTimer.Start()
}

    # --- Collection Runner Window ---
    function Show-CollectionRunnerWindow {
        param(
            [PSCustomObject]$Item,
            [System.Windows.Forms.Form]$parentForm
        )

        $runnerForm = New-Object System.Windows.Forms.Form -Property @{
            Text          = "Collection Runner: $($Item.Name)"
            Size          = New-Object System.Drawing.Size(900, 700)
            StartPosition = "CenterParent"
            BackColor     = $script:Theme.FormBackground
        }

        # --- Layout ---
        $mainLayout = New-Object System.Windows.Forms.TableLayoutPanel -Property @{
            Dock        = 'Fill'
            ColumnCount = 1
            RowCount    = 3
            Padding     = [System.Windows.Forms.Padding]::new(10)
        }
        $mainLayout.RowStyles.Add((New-Object System.Windows.Forms.RowStyle([System.Windows.Forms.SizeType]::AutoSize))) | Out-Null
        $mainLayout.RowStyles.Add((New-Object System.Windows.Forms.RowStyle([System.Windows.Forms.SizeType]::Percent, 100))) | Out-Null
        $mainLayout.RowStyles.Add((New-Object System.Windows.Forms.RowStyle([System.Windows.Forms.SizeType]::AutoSize))) | Out-Null

        # --- Top Panel (Summary & Progress) ---
        $topPanel = New-Object System.Windows.Forms.TableLayoutPanel -Property @{ Dock = 'Fill'; AutoSize = $true; ColumnCount = 2; RowCount = 2 }
        $topPanel.ColumnStyles.Add((New-Object System.Windows.Forms.ColumnStyle([System.Windows.Forms.SizeType]::Percent, 100))) | Out-Null
        $topPanel.ColumnStyles.Add((New-Object System.Windows.Forms.ColumnStyle([System.Windows.Forms.SizeType]::AutoSize))) | Out-Null

        $summaryLabel = New-Label -Text "Ready to run." -Property @{ Dock = 'Fill'; Font = New-Object System.Drawing.Font("Segoe UI", 10); TextAlign = 'MiddleLeft' }
        $progress = New-Object System.Windows.Forms.ProgressBar -Property @{ Dock = 'Fill'; Margin = [System.Windows.Forms.Padding]::new(0, 5, 0, 5) }
        
        # Settings Panel
        $settingsPanel = New-Object System.Windows.Forms.FlowLayoutPanel -Property @{ Dock = 'Fill'; AutoSize = $true; FlowDirection = 'LeftToRight'; WrapContents = $false }
        $lblDelay = New-Label -Text "Delay (ms):" -Property @{ AutoSize = $true; Margin = [System.Windows.Forms.Padding]::new(0, 5, 5, 0) }
        $numDelay = New-Object System.Windows.Forms.NumericUpDown -Property @{ Minimum = 0; Maximum = 60000; Value = 0; Width = 60 }
        if ($script:settings -and $script:settings['CollectionRunnerDelay']) { $numDelay.Value = $script:settings['CollectionRunnerDelay'] }
        $chkStopOnFail = New-Object System.Windows.Forms.CheckBox -Property @{ Text = "Stop on Failure"; AutoSize = $true; Margin = [System.Windows.Forms.Padding]::new(15, 3, 0, 0) }
        if ($script:settings -and $script:settings['CollectionRunnerStopOnFail']) { $chkStopOnFail.Checked = $script:settings['CollectionRunnerStopOnFail'] }
        $chkSelectAll = New-Object System.Windows.Forms.CheckBox -Property @{ Text = "Select All"; Checked = $true; AutoSize = $true; Margin = [System.Windows.Forms.Padding]::new(15, 3, 0, 0) }
        
        $btnDataFile = New-Button -Text "Data File..." -Property @{ Width = 90; Margin = [System.Windows.Forms.Padding]::new(15, 0, 0, 0) }
        $txtDataFile = New-TextBox -Property @{ Width = 150; ReadOnly = $true; Margin = [System.Windows.Forms.Padding]::new(5, 3, 0, 0) }
        $btnDataFile.Add_Click({
            $ofd = New-Object System.Windows.Forms.OpenFileDialog
            $ofd.Filter = "Data Files (*.csv;*.json)|*.csv;*.json|All Files (*.*)|*.*"
            if ($ofd.ShowDialog() -eq [System.Windows.Forms.DialogResult]::OK) {
                $txtDataFile.Text = $ofd.FileName
            }
        })

        $settingsPanel.Controls.AddRange(@($lblDelay, $numDelay, $chkStopOnFail, $chkSelectAll, $btnDataFile, $txtDataFile))

        $topPanel.Controls.Add($summaryLabel, 0, 0)
        $topPanel.Controls.Add($settingsPanel, 1, 0)
        $topPanel.Controls.Add($progress, 0, 1); $topPanel.SetColumnSpan($progress, 2)

        # --- Grid ---
        $grid = New-Object System.Windows.Forms.DataGridView -Property @{
            Dock               = 'Fill'
            ReadOnly           = $true
            AllowUserToAddRows = $false
            RowHeadersVisible  = $false
            SelectionMode      = 'FullRowSelect'
            BackgroundColor    = $script:Theme.GroupBackground
            BorderStyle        = 'None'
        }
        $colCheck = New-Object System.Windows.Forms.DataGridViewCheckBoxColumn
        $colCheck.HeaderText = ""
        $colCheck.Name = "Run"
        $colCheck.Width = 30
        $grid.Columns.Add($colCheck) | Out-Null
        
        $grid.Columns.Add("Name", "Request") | Out-Null
        $grid.Columns.Add("Status", "Status") | Out-Null
        $grid.Columns.Add("Result", "Result") | Out-Null
        $grid.Columns.Add("Time", "Time (ms)") | Out-Null
        $grid.Columns.Add("Tests", "Tests") | Out-Null
        $grid.Columns["Name"].AutoSizeMode = 'Fill'
        $grid.Columns["Result"].Width = 200

        # --- Bottom Panel (Buttons) ---
        $bottomPanel = New-Object System.Windows.Forms.FlowLayoutPanel -Property @{ FlowDirection = 'RightToLeft'; Dock = 'Fill'; AutoSize = $true }
        $btnStart = New-Button -Text "Start Run" -Style 'Primary' -Property @{ Width = 120; Height = 35 }
        $btnClose = New-Button -Text "Close" -Style 'Secondary' -Property @{ Width = 100; Height = 35 } -OnClick { $this.FindForm().Close() }
        $btnStop = New-Button -Text "Stop Run" -Style 'Danger' -Property @{ Width = 120; Height = 35; Margin = [System.Windows.Forms.Padding]::new(0,0,5,0); Enabled = $false } -OnClick {
            Request-CollectionRunStop
        }
        $btnRetry = New-Button -Text "Retry Failed" -Style 'Secondary' -Property @{ Width = 120; Height = 35; Margin = [System.Windows.Forms.Padding]::new(0,0,5,0); Enabled = $false }
        $btnExport = New-Button -Text "Export CSV" -Style 'Secondary' -Property @{ Width = 100; Height = 35; Margin = [System.Windows.Forms.Padding]::new(0,0,5,0) }
        $bottomPanel.Controls.AddRange(@($btnStart, $btnClose, $btnExport, $btnRetry, $btnStop))

        $runnerState = [PSCustomObject]@{
            form = $runnerForm
            parentForm = $parentForm
            grid = $grid
            progress = $progress
            summaryLabel = $summaryLabel
            btnStart = $btnStart
            btnRetry = $btnRetry
            btnStop = $btnStop
            btnExport = $btnExport
            numDelay = $numDelay
            chkStopOnFail = $chkStopOnFail
            chkSelectAll = $chkSelectAll
            txtDataFile = $txtDataFile
        }
        $btnStart.Tag = $runnerState
        $btnRetry.Tag = $runnerState
        $btnExport.Tag = $runnerState
        $chkSelectAll.Tag = $runnerState

        $btnRetry.Add_Click({
            $state = $this.Tag
            $failedRows = @()
            foreach ($row in $state.grid.Rows) {
                if ($row.Cells["Status"].Value -in @("FAIL", "ERROR")) { $failedRows += $row }
            }

            if ($failedRows.Count -eq 0) {
                [System.Windows.Forms.MessageBox]::Show("No failed requests to retry.", "Info", "OK", "Information")
                return
            }

            if ($script:collectionRunQueue -eq $null) { $script:collectionRunQueue = New-Object System.Collections.Queue }
            $script:collectionRunQueue.Clear()
            foreach ($row in $failedRows) {
                $script:collectionRunQueue.Enqueue($row)
                $row.Cells["Status"].Value = "Queued"
                $row.Cells["Result"].Value = ""
                $row.Cells["Time"].Value = ""
                $row.Cells["Tests"].Value = ""
                $row.DefaultCellStyle.BackColor = [System.Drawing.Color]::Empty
            }

            if ($script:settings) {
                $script:settings.CollectionRunnerDelay = [int]$state.numDelay.Value
                $script:settings.CollectionRunnerStopOnFail = $state.chkStopOnFail.Checked
                Save-Settings
            }

            $script:isCollectionRunning = $true
            $script:collectionRunDelay = [int]$state.numDelay.Value
            $script:collectionRunStopOnFail = $state.chkStopOnFail.Checked
            $script:collectionRunnerForm = $state.form
            $script:collectionRunnerGrid = $state.grid
            $script:collectionRunnerProgress = $state.progress
            $script:collectionRunnerSummaryLabel = $state.summaryLabel
            $script:collectionRunnerBtnStart = $state.btnStart
            $script:collectionRunnerBtnRetry = $state.btnRetry
            $script:collectionRunnerBtnStop = $state.btnStop
            $script:collectionRunnerParentForm = $state.parentForm
            $script:collectionRunTotal = $script:collectionRunQueue.Count
            $script:collectionRunCompleted = 0
            $script:collectionRunPassed = 0
            $script:collectionRunFailed = 0
            $script:collectionRunStopRequested = $false

            $script:collectionRunnerProgress.Maximum = [Math]::Max(1, $script:collectionRunTotal)
            $script:collectionRunnerProgress.Value = 0
            $script:collectionRunnerSummaryLabel.Text = "Retrying $($script:collectionRunTotal) failed requests..."
            $script:collectionRunnerBtnStart.Enabled = $false
            $script:collectionRunnerBtnRetry.Enabled = $false
            $script:collectionRunnerBtnStop.Enabled = $true

            if ($script:collectionRunQueue.Count -gt 0) {
                $firstRow = $script:collectionRunQueue.Dequeue()
                $script:collectionRunnerCurrentRow = $firstRow
                $firstRow.Cells["Status"].Value = "Running..."
                $requestObject = Get-RequestObjectFromItem -Item $firstRow.Tag
                if (-not $requestObject) {
                    $firstRow.Cells["Status"].Value = "ERROR"
                    $firstRow.Cells["Result"].Value = "Missing request data"
                    $firstRow.DefaultCellStyle.BackColor = [System.Drawing.ColorTranslator]::FromHtml("#f8d7da")
                    Complete-CollectionRun -Summary "Unable to retry one or more requests because request data is missing." -EnableRetry $true
                    return
                }
                Import-RequestFromObject -RequestObject $requestObject
                $state.parentForm.Tag.btnSubmit.Enabled = $false
                $state.parentForm.Tag.btnCancel.Enabled = $true
                $state.parentForm.Tag.btnRepeat.Enabled = $false
                Invoke-RequestExecution
            }
        })

        $btnExport.Add_Click({
            $state = $this.Tag
            $sfd = New-Object System.Windows.Forms.SaveFileDialog
            $sfd.Filter = "CSV Files (*.csv)|*.csv"
            $sfd.FileName = "collection_run_results.csv"
            if ($sfd.ShowDialog() -eq [System.Windows.Forms.DialogResult]::OK) {
                $results = @()
                foreach ($row in $state.grid.Rows) {
                    $results += [PSCustomObject]@{
                        Request = $row.Cells["Name"].Value
                        Status  = $row.Cells["Status"].Value
                        Result  = $row.Cells["Result"].Value
                        TimeMs  = $row.Cells["Time"].Value
                        Tests   = $row.Cells["Tests"].Value
                    }
                }
                $results | Export-Csv -Path $sfd.FileName -NoTypeInformation -Encoding UTF8
                [System.Windows.Forms.MessageBox]::Show("Export successful.", "Export", "OK", "Information")
            }
        })

        $chkSelectAll.Add_CheckedChanged({
            $state = $this.Tag
            foreach ($row in $state.grid.Rows) { $row.Cells["Run"].Value = $this.Checked }
        })

        # --- Logic ---
        function Get-RequestsRecursive {
            param($NodeItem)
            $requests = @()
            if ($NodeItem.Type -eq "Request") {
                $requests += $NodeItem
            } elseif ($NodeItem.Items) {
                foreach ($child in $NodeItem.Items) {
                    $requests += Get-RequestsRecursive -NodeItem $child
                }
            }
            return $requests
        }
        $allRequests = Get-RequestsRecursive -NodeItem $Item

        # Populate Grid
        $grid.Rows.Clear()
        foreach ($req in $allRequests) {
            $rowIndex = $grid.Rows.Add(@($true, $req.Name, "Queued", "", "", ""))
            $grid.Rows[$rowIndex].Tag = $req
        }

        $btnStart.Add_Click({
            $state = $this.Tag
            # Reset state
            if ($script:collectionRunQueue -eq $null) { $script:collectionRunQueue = New-Object System.Collections.Queue }
            $script:collectionRunQueue.Clear()

            $script:collectionRunData = @()
            $script:collectionRunDataIndex = 0
            if ($state.txtDataFile -and $state.txtDataFile.Text -and (Test-Path $state.txtDataFile.Text)) {
                try {
                    if ($state.txtDataFile.Text -match '\.json$') {
                        $script:collectionRunData = Get-Content $state.txtDataFile.Text -Raw | ConvertFrom-Json
                    } elseif ($state.txtDataFile.Text -match '\.csv$') {
                        $script:collectionRunData = Import-Csv $state.txtDataFile.Text
                    }
                    if ($script:collectionRunData.Count -gt 0) {
                        $script:activeCollectionVariables = @{}
                        $firstRow = $script:collectionRunData[0]
                        foreach ($prop in $firstRow.PSObject.Properties) {
                            $script:activeCollectionVariables[$prop.Name] = $prop.Value
                        }
                    }
                } catch {
                    [System.Windows.Forms.MessageBox]::Show("Failed to load Data File: $($_.Exception.Message)", "Data Error", "OK", "Warning")
                }
            }
            
            foreach ($row in $state.grid.Rows) {
                $requestObject = Get-RequestObjectFromItem -Item $row.Tag
                if ($row.Cells["Run"].Value -and $requestObject) {
                    $script:collectionRunQueue.Enqueue($row)
                    $row.Cells["Status"].Value = "Queued"
                    $row.DefaultCellStyle.BackColor = [System.Drawing.Color]::Empty
                } elseif ($row.Cells["Run"].Value) {
                    $row.Cells["Status"].Value = "Invalid"
                    $row.Cells["Result"].Value = "Missing request data"
                    $row.DefaultCellStyle.BackColor = [System.Drawing.ColorTranslator]::FromHtml("#fff3cd")
                } else {
                    $row.Cells["Status"].Value = "Skipped"
                    $row.DefaultCellStyle.BackColor = [System.Drawing.Color]::LightGray
                }
                if ($row.Cells["Status"].Value -ne "Invalid") { $row.Cells["Result"].Value = "" }
                $row.Cells["Time"].Value = ""
                $row.Cells["Tests"].Value = ""
            }

            if ($script:settings) {
                $script:settings.CollectionRunnerDelay = [int]$state.numDelay.Value
                $script:settings.CollectionRunnerStopOnFail = $state.chkStopOnFail.Checked
                Save-Settings
            }

            $script:isCollectionRunning = $true
            $script:collectionRunDelay = [int]$state.numDelay.Value
            $script:collectionRunStopOnFail = $state.chkStopOnFail.Checked
            
            $script:collectionRunnerForm = $state.form
            $script:collectionRunnerGrid = $state.grid
            $script:collectionRunnerProgress = $state.progress
            $script:collectionRunnerSummaryLabel = $state.summaryLabel
            $script:collectionRunnerBtnStart = $state.btnStart
            $script:collectionRunnerBtnRetry = $state.btnRetry
            $script:collectionRunnerBtnStop = $state.btnStop
            $script:collectionRunnerParentForm = $state.parentForm
            $script:collectionRunTotal = $script:collectionRunQueue.Count
            $script:collectionRunCompleted = 0
            $script:collectionRunPassed = 0
            $script:collectionRunFailed = 0
            $script:collectionRunStopRequested = $false

            # Reset UI
            $script:collectionRunnerProgress.Maximum = [Math]::Max(1, $script:collectionRunTotal)
            $script:collectionRunnerProgress.Value = 0
            $script:collectionRunnerSummaryLabel.Text = "Starting run..."

            # Disable button
            $this.Enabled = $false
            $script:collectionRunnerBtnRetry.Enabled = $false
            $script:collectionRunnerBtnStop.Enabled = $true
            $this.Text = "Running..."

            # Dequeue and run the first request
            if ($script:collectionRunQueue.Count -gt 0) {
                $firstRow = $script:collectionRunQueue.Dequeue()
                $script:collectionRunnerCurrentRow = $firstRow
                $firstRow.Cells["Status"].Value = "Running..."
                $requestObject = Get-RequestObjectFromItem -Item $firstRow.Tag
                if (-not $requestObject) {
                    $firstRow.Cells["Status"].Value = "ERROR"
                    $firstRow.Cells["Result"].Value = "Missing request data"
                    $firstRow.DefaultCellStyle.BackColor = [System.Drawing.ColorTranslator]::FromHtml("#f8d7da")
                    Complete-CollectionRun -Summary "Unable to start one or more requests because request data is missing." -EnableRetry $true
                    return
                }
                Import-RequestFromObject -RequestObject $requestObject
                
                # Control main form buttons
                $state.parentForm.Tag.btnSubmit.Enabled = $false
                $state.parentForm.Tag.btnCancel.Enabled = $true
                $state.parentForm.Tag.btnRepeat.Enabled = $false
                
                Invoke-RequestExecution
            } else {
                # No requests to run
                Complete-CollectionRun -Summary "No runnable requests found in this collection/folder." -EnableRetry $true
            }
        })

        # Assemble form
        $mainLayout.Controls.Add($topPanel, 0, 0)
        $mainLayout.Controls.Add($grid, 0, 1)
        $mainLayout.Controls.Add($bottomPanel, 0, 2)
        $runnerForm.Controls.Add($mainLayout)
        $runnerForm.Add_FormClosing({ param($sender, $e) Invoke-CollectionRunnerFormClosing -sender $sender -e $e })

        $runnerForm.Show($parentForm) # Show non-modally
    }

    $script:monitorPool = $null
    $script:isHistoryUndocked = $false
    $script:lastDockState = 'Bottom' # Initialize the last known dock state
    $script:responseForm = $null # Initialize the undocked response form variable
    $script:isMainFormClosing = $false # New flag to indicate if the main form is closing
    if ($script:settings.EnableHistory) {
        Import-History
    } #FIX: Corrected Import-History call
    Import-Settings
    Import-RequestTemplates
    Import-RequestTabs
    $drafts = Import-DraftState
    if ($drafts) {
        $msgResult = [System.Windows.Forms.MessageBox]::Show("An unsaved session (draft) was found. Would you like to restore it?", "Restore Session", 'YesNo', 'Question')
        if ($msgResult -eq 'Yes') {
            $script:requestTabs = $drafts
            $script:activeRequestTabId = $script:requestTabs[0].Id
        }
        if (Test-Path $draftsFilePath) { Remove-Item $draftsFilePath -Force }
    }
    Import-Globals
    Import-Environments
    Import-Monitors
    Import-Collections

    # Initialize dock state from loaded settings, ensuring it's a valid state
    $script:responseDockState = $script:settings.ResponseDockState

    # Create Form
    $form = New-Object System.Windows.Forms.Form -Property @{
        Text               = "PowerShell API Tester v$($script:AppVersion)"
        Size               = New-Object System.Drawing.Size(1200, 1000)
        StartPosition      = "CenterScreen"
        MinimumSize        = New-Object System.Drawing.Size(900, 800)
        FormBorderStyle    = [System.Windows.Forms.FormBorderStyle]::Sizable
        KeyPreview         = $true
        BackColor          = $script:Theme.FormBackground
    }

    $toolTip = New-Object System.Windows.Forms.ToolTip
    $script:monitorJobs = @{} # Hash to store running monitor jobs

    $statusStrip = New-Object System.Windows.Forms.StatusStrip
    $statusLabelStatus = New-Object System.Windows.Forms.ToolStripStatusLabel -Property @{
        Spring      = $true
        Text        = "Ready"
        TextAlign   = [System.Drawing.ContentAlignment]::MiddleLeft
    }
    $statusLabelTime = New-Object System.Windows.Forms.ToolStripStatusLabel -Property @{
        Text = "Time: N/A"
    }
    $statusLabelSize = New-Object System.Windows.Forms.ToolStripStatusLabel -Property @{
        Text = "Size: N/A"
    }
    $statusStrip.BackColor = $script:Theme.PrimaryButton
    $statusLabelStatus.ForeColor = $statusLabelTime.ForeColor = $statusLabelSize.ForeColor = $script:Theme.PrimaryButtonText

    $statusStrip.Items.AddRange(@($statusLabelStatus, $statusLabelTime, $statusLabelSize))

    # --- Menu Strip and File Menu ---
    $menuStrip = New-Object System.Windows.Forms.MenuStrip
    $fileMenu = New-Object System.Windows.Forms.ToolStripMenuItem("&Menu")
    $toolsMenu = New-Object System.Windows.Forms.ToolStripMenuItem("&Tools")
    $monitorMenu = New-Object System.Windows.Forms.ToolStripMenuItem("&Monitor")
    $menuStrip.BackColor = $script:Theme.GroupBackground
    $menuStrip.ForeColor = $script:Theme.TextColor


    # Initialize RunspacePool for background monitoring (Min 1, Max 5 concurrent tasks)
    $script:monitorPool = [System.Management.Automation.Runspaces.RunspaceFactory]::CreateRunspacePool(1, 5)
    $script:monitorPool.Open()

    # --- Monitoring System ---
    $notifyIcon = New-Object System.Windows.Forms.NotifyIcon
    $notifyIcon.Icon = [System.Drawing.SystemIcons]::Application
    $notifyIcon.Visible = $true
    $notifyIcon.Text = "API Tester Monitor"

    $script:autoSaveTimer = New-Object System.Windows.Forms.Timer
    $script:autoSaveTimer.Interval = 30000 # Save every 30 seconds
    $script:autoSaveTimer.Add_Tick({ Save-DraftState })

    $monitorTimer = New-Object System.Windows.Forms.Timer
    $monitorTimer.Interval = 1000 # Tick every second
    $monitorTimer.Add_Tick({
        $now = Get-Date
        foreach ($m in $script:monitors) {
            if ($m.Status -eq 'Running') {
                $lastRun = if ($m.LastRun) { [DateTime]$m.LastRun } else { [DateTime]::MinValue }
                
                # Check if it's time to run (and not currently running)
                if (($now - $lastRun).TotalSeconds -ge $m.IntervalSeconds -and -not $script:monitorJobs.ContainsKey($m.Id)) {
                    
                    # Start Monitor Job
                    $m.LastRun = $now
                    
                    # Simplified job script block for monitoring
                    $jobBlock = {
                        param($url, $method, $headers, $body, $bodyType, $timeout) #FIX: Corrected parameter definition
                        try {
                            $sw = [System.Diagnostics.Stopwatch]::StartNew()
                            $req = [System.Net.HttpWebRequest]::Create($url)
                            $req.Method = $method
                            $req.Timeout = $timeout * 1000
                            # Add headers/body logic here (simplified for brevity)
                            $resp = $req.GetResponse()
                            $sw.Stop()
                            return @{ Success=$true; StatusCode=[int]$resp.StatusCode; Time=$sw.ElapsedMilliseconds; Msg="OK" }
                        } catch {
                            return @{ Success=$false; StatusCode=0; Time=0; Msg=$_.Exception.Message }
                        }
                    }
                    
                    $ps = [PowerShell]::Create()
                    $ps.RunspacePool = $script:monitorPool
                    $ps.AddScript($jobBlock).AddArgument($m.Request.Url).AddArgument($m.Request.Method).AddArgument($m.Request.Headers).AddArgument($m.Request.Body).AddArgument($m.Request.BodyType).AddArgument($m.Request.RequestTimeoutSeconds) | Out-Null #FIX: Corrected argument list
                    $script:monitorJobs[$m.Id] = @{ PS = $ps; AR = $ps.BeginInvoke() }
                }
            }
        }

        # Check running jobs
        $ids = @($script:monitorJobs.Keys)
        foreach ($id in $ids) {
            $entry = $script:monitorJobs[$id]
            if ($entry.AR.IsCompleted) {
                $res = $entry.PS.EndInvoke($entry.AR) | Select-Object -First 1
                $entry.PS.Dispose()
                $script:monitorJobs.Remove($id)
                
                # Alerting Logic
                $mon = ($script:monitors | Where-Object {$_.Id -eq $id})
                if ($mon) {
                    # Log to CSV
                    try {
                        $logEntry = [PSCustomObject]@{
                            Timestamp   = Get-Date -Format "yyyy-MM-dd HH:mm:ss"
                            MonitorName = $mon.Name
                            URL         = $mon.Request.Url
                            Success     = $res.Success
                            StatusCode  = $res.StatusCode
                            TimeMs      = $res.Time
                            Message     = $res.Msg
                        }
                        $logEntry | Export-Csv -Path $monitorLogFilePath -Append -NoTypeInformation -Force
                    } catch { Write-Log "Failed to write to monitor log: $($_.Exception.Message)" -Level Info }

                    $alertMsg = $null
                    $alertType = $null
                    if ($mon.Alerts.OnFailure -and (-not $res.Success -or $res.StatusCode -ne 200)) {
                        $alertMsg = "$($mon.Name) Failed: $($res.Msg)"
                        $alertType = "Failure"
                        $notifyIcon.ShowBalloonTip(5000, "API Monitor Alert", $alertMsg, [System.Windows.Forms.ToolTipIcon]::Error)
                    } elseif ($mon.Alerts.OnSlow -and $res.Time -gt $mon.Alerts.ThresholdMs) {
                        $alertMsg = "$($mon.Name) Slow: $($res.Time)ms"
                        $alertType = "Slow"
                        $notifyIcon.ShowBalloonTip(5000, "API Monitor Warning", $alertMsg, [System.Windows.Forms.ToolTipIcon]::Warning)
                    }

                    # Email Alert
                    if ($alertMsg -and $mon.Alerts.SendEmail -and $mon.Alerts.EmailTo -and $script:settings.MonitorSmtpServer) {
                        try {
                            $alertData = @{
                                MonitorName = $mon.Name
                                Status = $alertType
                                StatusCode = $res.StatusCode
                                Url = $mon.Request.Url
                                TimeMs = $res.Time
                                Message = $res.Msg
                                Timestamp = $logEntry.Timestamp
                            }
                            $subjectTemplate = if ($script:settings.MonitorAlertSubjectTemplate) { $script:settings.MonitorAlertSubjectTemplate } else { "API Alert: {MonitorName}" }
                            $bodyTemplate = if ($script:settings.MonitorAlertBodyTemplate) { $script:settings.MonitorAlertBodyTemplate } else { $alertMsg }
                            $emailSubject = Format-AlertTemplate -Template $subjectTemplate -Data $alertData
                            $emailBody = Format-AlertTemplate -Template $bodyTemplate -Data $alertData
                            if ([string]::IsNullOrWhiteSpace($emailSubject)) { $emailSubject = "API Alert: $($mon.Name)" }
                            if ([string]::IsNullOrWhiteSpace($emailBody)) { $emailBody = $alertMsg }

                            if ($script:settings.MonitorSmtpAuthMethod -eq "OAuth2") {
                                # Check for refresh
                                if ($script:settings.MonitorSmtpRefreshToken -and $script:settings.MonitorSmtpTokenEndpoint) {
                                     $shouldRefresh = $false
                                     if ($script:settings.MonitorSmtpTokenExpiry) {
                                         if ([DateTime]::UtcNow -ge [DateTime]$script:settings.MonitorSmtpTokenExpiry) { $shouldRefresh = $true }
                                     } elseif (-not $script:settings.MonitorSmtpPass) { $shouldRefresh = $true }
                                     if ($shouldRefresh) { Update-SmtpToken }
                                }
                                $isHtml = $script:settings.MonitorAlertBodyForceHtml -or (Test-IsHtmlBody -Body $emailBody)
                                Send-SmtpOAuth2 -Server $script:settings.MonitorSmtpServer -Port $script:settings.MonitorSmtpPort -UseSsl $script:settings.MonitorSmtpUseSsl -From $script:settings.MonitorSmtpFrom -To $mon.Alerts.EmailTo -Subject $emailSubject -Body $emailBody -User $script:settings.MonitorSmtpUser -AccessToken $script:settings.MonitorSmtpPass -IsHtml:$isHtml
                            } else {
                                $smtpParams = @{
                                    SmtpServer = $script:settings.MonitorSmtpServer
                                    Port = $script:settings.MonitorSmtpPort
                                    UseSsl = $script:settings.MonitorSmtpUseSsl
                                    From = $script:settings.MonitorSmtpFrom
                                    To = $mon.Alerts.EmailTo
                                    Subject = $emailSubject
                                    Body = $emailBody
                                    IsBodyHtml = ($script:settings.MonitorAlertBodyForceHtml -or (Test-IsHtmlBody -Body $emailBody))
                                }
                                if ($script:settings.MonitorSmtpUser) {
                                    $pass = $script:settings.MonitorSmtpPass | ConvertTo-SecureString -AsPlainText -Force
                                    $smtpParams.Credential = New-Object System.Management.Automation.PSCredential($script:settings.MonitorSmtpUser, $pass)
                                }
                                Send-MailMessage @smtpParams -ErrorAction Stop
                            }
                        } catch { Write-Log "Failed to send email alert: $($_.Exception.Message)" -Level Info }
                    }

                    # Analytics Webhook
                    if ($mon.AnalyticsUrl) {
                        try {
                            $payload = @{
                                monitorName = $mon.Name
                                timestamp = $logEntry.Timestamp
                                success = $res.Success
                                statusCode = $res.StatusCode
                                timeMs = $res.Time
                                message = $res.Msg
                            } | ConvertTo-Json -Compress
                            Invoke-RestMethod -Uri $mon.AnalyticsUrl -Method Post -Body $payload -ContentType "application/json" -ErrorAction Stop
                        } catch { Write-Log "Failed to send analytics for $($mon.Name): $($_.Exception.Message)" -Level Info }
                    }
                }
            }
        }
    })
    $monitorTimer.Start()
    $script:autoSaveTimer.Start()

    # --- Import/Export Workspace ---
    $importCurlMenuItem = New-Object System.Windows.Forms.ToolStripMenuItem("Import cURL...", $null, {
        $curlForm = New-Object System.Windows.Forms.Form -Property @{
            Text = "Import cURL"
            Size = New-Object System.Drawing.Size(600, 450)
            StartPosition = [System.Windows.Forms.FormStartPosition]::CenterParent
        }
        $labelCurl = New-Label -Text "Paste cURL command here:" -Property @{ Dock = "Top"; Height = 25; Padding = [System.Windows.Forms.Padding]::new(5) }
        $txtCurl = New-TextBox -Multiline $true -Property @{ Dock = "Fill"; ScrollBars = "Vertical"; Font = New-Object System.Drawing.Font("Courier New", 9) }
        
        $panelBtn = New-Object System.Windows.Forms.Panel -Property @{ Dock = "Bottom"; Height = 40; Padding = [System.Windows.Forms.Padding]::new(5) }
        $btnImport = New-Button -Text "Import" -Property @{ Dock = "Right"; Width = 100 } -OnClick {
            $raw = $txtCurl.Text
            if ([string]::IsNullOrWhiteSpace($raw)) { return }

            # Basic parsing logic for standard cURL commands
            $url = ""
            $method = "GET"
            $headers = @{}
            $body = ""

            # Regex to find URL (http/https) inside quotes or whitespace
            if ($raw -match "['`"](https?://[^'`"]+)['`"]") { $url = $matches[1] }
            elseif ($raw -match "(https?://\S+)") { $url = $matches[1] }

            # Method
            if ($raw -match "-X\s+([A-Z]+)") { $method = $matches[1] }
            
            # Headers (-H "Key: Value")
            # Regex matches -H, space, quote (group 1), content (group 2), matching quote (backreference 1)
            $hMatches = [regex]::Matches($raw, '-H\s+([''"])(.*?)\1')
            foreach ($m in $hMatches) {
                $headerContent = $m.Groups[2].Value
                if ($headerContent -match "^(.*?):\s*(.*)$") {
                    $k = $matches[1]; $v = $matches[2]
                    if ($k -ne "Content-Type") { $headers[$k] = $v }
                }
            }

            # Body (--data, -d, --data-raw)
            if ($raw -match "(?:--data|--data-raw|-d)\s+(['`"])(.*?)\1") {
                $body = $matches[2]
                if ($method -eq "GET") { $method = "POST" }
            }

            # Apply to UI
            if ($url) { $script:textUrl.Text = $url }
            $script:comboMethod.SelectedItem = $method
            
            $headerText = ""
            foreach ($k in $headers.Keys) { $headerText += "${k}: $($headers[$k])`r`n" }
            $script:textHeaders.Text = $headerText
            
            $script:textBody.Text = $body
            if ($body.Trim().StartsWith("{") -or $body.Trim().StartsWith("[")) { $script:comboBodyType.SelectedItem = "application/json" }

            $curlForm.DialogResult = [System.Windows.Forms.DialogResult]::OK
            $curlForm.Close()
        }
        $btnCancel = New-Button -Text "Cancel" -Property @{ Dock = "Right"; Width = 100 } -OnClick { $curlForm.Close() }
        
        $panelBtn.Controls.AddRange(@($btnCancel, $btnImport))
        $curlForm.Controls.AddRange(@($txtCurl, $labelCurl, $panelBtn))
        $curlForm.ShowDialog($form)
    })    
    $importCurlMenuItem.Visible = $script:settings.EnableCurlImport

    $importPostmanMenuItem = New-Object System.Windows.Forms.ToolStripMenuItem("Import Postman Collection...", $null, {
        $openFileDialog = New-Object System.Windows.Forms.OpenFileDialog -Property @{
            Filter = "Postman Collection (*.json)|*.json"
            Title  = "Import Postman Collection"
        }
        if ($openFileDialog.ShowDialog() -eq [System.Windows.Forms.DialogResult]::OK) {
            try {
                $jsonContent = Get-Content -Path $openFileDialog.FileName -Raw | ConvertFrom-Json
                
                $newCollection = Convert-PostmanCollection -PostmanJson $jsonContent
                $script:collections += $newCollection
                Update-CollectionsTreeView -nodes $treeViewCollections.Nodes -items $script:collections
                Save-Collections
                [System.Windows.Forms.MessageBox]::Show("Postman collection imported successfully.", "Import Complete", "OK", "Information")
            } catch {
                [System.Windows.Forms.MessageBox]::Show("Failed to import Postman collection: $($_.Exception.Message)", "Import Error", "OK", "Error")
            }
        }
    })
    $importPostmanMenuItem.Visible = $script:settings.EnablePostmanImport

    $importWorkspaceMenuItem = New-Object System.Windows.Forms.ToolStripMenuItem("Import Workspace...", $null, {
        $openFileDialog = New-Object System.Windows.Forms.OpenFileDialog -Property @{
            Filter = "API Tester Workspace (*.apw)|*.apw"
            Title  = "Import Workspace"
            InitialDirectory = $configDir
        }
        if ($openFileDialog.ShowDialog() -eq [System.Windows.Forms.DialogResult]::OK) {
            try {
                $workspace = Get-Content -Path $openFileDialog.FileName -Raw | ConvertFrom-Json
                if ($workspace.PSObject.Properties.Name -contains 'Settings') { #FIX: Corrected condition
                    # Create an import options form
                    $importOptionsForm = New-Object System.Windows.Forms.Form -Property @{
                        Text = "Import Options" #FIX: Corrected form size
                        Size = New-Object System.Drawing.Size(320, 260)
                        StartPosition = [System.Windows.Forms.FormStartPosition]::CenterParent
                        FormBorderStyle = [System.Windows.Forms.FormBorderStyle]::FixedDialog
                        MaximizeBox = $false; MinimizeBox = $false
                    }
                    $labelInfo = New-Label -Text "Select components to import from workspace." -Location (New-Object System.Drawing.Point(15, 15)) -Size (New-Object System.Drawing.Size(280, 20))
                    $checkImportEnvironments = New-Object System.Windows.Forms.CheckBox -Property @{ Text = "Import Environments"; Location = (New-Object System.Drawing.Point(18, 45)); AutoSize = $true }
                    $checkImportHistory = New-Object System.Windows.Forms.CheckBox -Property @{ Text = "Import History"; Location = (New-Object System.Drawing.Point(18, 75)); AutoSize = $true }
                    $checkImportGlobals = New-Object System.Windows.Forms.CheckBox -Property @{ Text = "Import Globals"; Location = (New-Object System.Drawing.Point(18, 105)); AutoSize = $true }
                    $checkImportCollections = New-Object System.Windows.Forms.CheckBox -Property @{ Text = "Import Collections"; Location = (New-Object System.Drawing.Point(18, 135)); AutoSize = $true }

                    # Enable/disable checkboxes based on what's in the file
                    $checkImportEnvironments.Enabled = $workspace.PSObject.Properties.Name -contains 'Environments'
                    $checkImportHistory.Enabled = $workspace.PSObject.Properties.Name -contains 'History'
                    $checkImportGlobals.Enabled = $workspace.PSObject.Properties.Name -contains 'Globals'
                    $checkImportCollections.Enabled = $workspace.PSObject.Properties.Name -contains 'Collections'
                    $checkImportEnvironments.Checked = $checkImportEnvironments.Enabled
                    $checkImportHistory.Checked = $checkImportHistory.Enabled
                    $checkImportGlobals.Checked = $checkImportGlobals.Enabled
                    $checkImportCollections.Checked = $checkImportCollections.Enabled

                    $btnContinueImport = New-Button -Text "Import" -Location (New-Object System.Drawing.Point(190, 180)) -Size (New-Object System.Drawing.Size(100, 30)) -OnClick {
                        # Always import settings
                        $workspace.Settings | ConvertTo-Json -Depth 5 | Set-Content -Path $settingsFilePath
                        Write-Log "Imported Settings from workspace." -Level Debug

                        if ($checkImportEnvironments.Checked) {
                            $workspace.Environments | ConvertTo-Json -Depth 5 | Set-Content -Path $environmentsFilePath -ErrorAction Stop
                            Write-Log "Imported Environments from workspace." -Level Debug
                        }
                        if ($checkImportHistory.Checked) {
                            $workspace.History | ConvertTo-Json -Depth 5 | Set-Content -Path $historyFilePath -ErrorAction Stop
                            Write-Log "Imported History from workspace." -Level Debug
                        }
                        if ($checkImportGlobals.Checked) {
                            $workspace.Globals | ConvertTo-Json -Depth 5 | Set-Content -Path $globalsFilePath -ErrorAction Stop
                            Write-Log "Imported Globals from workspace." -Level Debug
                        }
                        if ($checkImportCollections.Checked) {
                            $workspace.Collections | ConvertTo-Json -Depth 10 | Set-Content -Path $collectionsFilePath -ErrorAction Stop
                            Write-Log "Imported Collections from workspace." -Level Debug
                        }

                        # Reload everything into the current session
                        Write-Log "Workspace import complete. Reloading UI."
                        Import-Settings
                        Import-Globals
                        Import-Environments
                        Import-Collections
                        if ($script:settings.EnableHistory) { Import-History }
                        Update-EnvironmentDropdown
                        Update-CollectionsTreeView -nodes $treeViewCollections.Nodes -items $script:collections
                        $script:activeCollectionNode = $null
                        $script:activeCollectionVariables = @{}
                        Update-Layout
                        Update-HistoryListView
                        [System.Windows.Forms.MessageBox]::Show("Workspace components successfully imported. The application will now reflect the changes.", "Import Successful", "OK", "Information")
                        $importOptionsForm.Close()
                    }
                    $btnCancelImport = New-Button -Text "Cancel" -Location (New-Object System.Drawing.Point(80, 180)) -Size (New-Object System.Drawing.Size(100, 30)) -OnClick { $importOptionsForm.Close() }
                    
                    $importOptionsForm.Controls.AddRange(@($labelInfo, $checkImportEnvironments, $checkImportHistory, $checkImportGlobals, $checkImportCollections, $btnContinueImport, $btnCancelImport))
                    $importOptionsForm.ShowDialog($form)
                } else {
                    [System.Windows.Forms.MessageBox]::Show("The selected file is not a valid workspace file.", "Import Error", "OK", "Error")
                }
            } catch {
                [System.Windows.Forms.MessageBox]::Show("Failed to import workspace: $($_.Exception.Message)", "Import Error", "OK", "Error")
                Write-Log "Error importing workspace file '$($openFileDialog.FileName)': $($_.Exception.Message)" -Level Info
            }
        }
    })
    $exportWorkspaceMenuItem = New-Object System.Windows.Forms.ToolStripMenuItem("Export Workspace...", $null, {
        # Create a small form to ask about including history
        $exportOptionsForm = New-Object System.Windows.Forms.Form -Property @{
            Text = "Export Options"
            Size = New-Object System.Drawing.Size(450, 340) # Increased height for better button spacing
            StartPosition = [System.Windows.Forms.FormStartPosition]::CenterParent
            FormBorderStyle = [System.Windows.Forms.FormBorderStyle]::FixedDialog
            MaximizeBox = $false
            MinimizeBox = $false
        }
        $labelInfo = New-Label -Text "Select options for your workspace export." -Location (New-Object System.Drawing.Point(15, 15)) -Size (New-Object System.Drawing.Size(410, 25))
        $checkIncludeEnvironments = New-Object System.Windows.Forms.CheckBox -Property @{
            Text = "Include environments in export"
            Location = New-Object System.Drawing.Point(18, 50)
            AutoSize = $true
        }
        $checkIncludeHistory = New-Object System.Windows.Forms.CheckBox -Property @{
            Text = "Include request history in export"
            Location = New-Object System.Drawing.Point(18, 85) # Moved down
            AutoSize = $true
        }
        $checkIncludeGlobals = New-Object System.Windows.Forms.CheckBox -Property @{
            Text = "Include global variables in export"
            Location = New-Object System.Drawing.Point(18, 120)
            AutoSize = $true
        }
        $checkIncludeCollections = New-Object System.Windows.Forms.CheckBox -Property @{
            Text = "Include collections in export"
            Location = New-Object System.Drawing.Point(18, 155)
            AutoSize = $true
        }
        # Disable checkboxes if there is no data to export
        $checkIncludeEnvironments.Enabled = ($null -ne $script:environments -and $script:environments.Count -gt 0)
        $checkIncludeHistory.Enabled = ($null -ne $script:history -and $script:history.Count -gt 0)
        $checkIncludeGlobals.Enabled = ($null -ne $script:globals -and $script:globals.Count -gt 0)
        $checkIncludeCollections.Enabled = ($null -ne $script:collections -and $script:collections.Count -gt 0)
        $checkIncludeEnvironments.Checked = $checkIncludeEnvironments.Enabled
        $checkIncludeHistory.Checked = $checkIncludeHistory.Enabled
        $checkIncludeGlobals.Checked = $checkIncludeGlobals.Enabled
        $checkIncludeCollections.Checked = $checkIncludeCollections.Enabled

        $btnContinueExport = New-Button -Text "Export..." -Location (New-Object System.Drawing.Point(310, 300)) -Size (New-Object System.Drawing.Size(110, 40)) -OnClick {
            $exportOptionsForm.Close() # Close the options form first
            $saveFileDialog = New-Object System.Windows.Forms.SaveFileDialog -Property @{
                Filter = "API Tester Workspace (*.apw)|*.apw"
                DefaultExt = "apw"
                FileName = "api_tester_workspace.apw"
                Title = "Export Workspace"
                InitialDirectory = $configDir
            }
            if ($saveFileDialog.ShowDialog() -eq [System.Windows.Forms.DialogResult]::OK) {
                $workspace = [PSCustomObject]@{
                    # Settings are always included in a workspace export.
                    Settings = $script:settings
                }
                if ($checkIncludeEnvironments.Checked) {
                    $workspace | Add-Member -MemberType NoteProperty -Name "Environments" -Value $script:environments
                }
                if ($checkIncludeHistory.Checked) {
                    $workspace | Add-Member -MemberType NoteProperty -Name "History" -Value $script:history
                }
                if ($checkIncludeGlobals.Checked) {
                    $workspace | Add-Member -MemberType NoteProperty -Name "Globals" -Value $script:globals
                }
                if ($checkIncludeCollections.Checked) {
                    $workspace | Add-Member -MemberType NoteProperty -Name "Collections" -Value $script:collections
                }
                try {
                    $workspace | ConvertTo-Json -Depth 10 | Set-Content -Path $saveFileDialog.FileName -ErrorAction Stop
                    [System.Windows.Forms.MessageBox]::Show("Workspace successfully exported.", "Export Complete", "OK", "Information")
                } catch {
                    Write-Log "Error exporting workspace: $($_.Exception.Message)" -Level Info
                    [System.Windows.Forms.MessageBox]::Show("Failed to export workspace: $($_.Exception.Message)", "Export Error", "OK", "Error")
                }
            }
        }
        $btnCancelExport = New-Button -Text "Cancel" -Location (New-Object System.Drawing.Point(200, 300)) -Size (New-Object System.Drawing.Size(100, 40)) -OnClick {
            $exportOptionsForm.Close()
        }
        $exportOptionsForm.Controls.AddRange(@($labelInfo, $checkIncludeEnvironments, $checkIncludeHistory, $checkIncludeGlobals, $checkIncludeCollections, $btnContinueExport, $btnCancelExport))
        $exportOptionsForm.ShowDialog($form)
    })

