    $editCollectionVarsMenuItem = New-Object System.Windows.Forms.ToolStripMenuItem("Edit Variables...", $null, {
        $selectedNode = $treeViewCollections.SelectedNode
        if ($selectedNode -and $selectedNode.Tag.Type -eq "Collection") {
