                $parent = $selectedNode.Parent
                if ($parent) {
                    $parent.Tag.Items = @($parent.Tag.Items | Where-Object { $_ -ne $selectedNode.Tag })
                } else { # Top-level collection
                    $script:collections = @($script:collections | Where-Object { $_ -ne $selectedNode.Tag })
                }
                $selectedNode.Remove()
